      module real(wp) function phaseq ( ctx, et, target, illmn, obsrvr, abcorr )
      use pepper_kinds, only: ip, wp
      use pepper_strings, only: ljucrs
      use pepper_inc_zzabcorr
      use pepper_inc_zzctr
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      real(wp), intent(in) :: et  !! Ephemeris seconds past J2000 TDB.
      character(*), intent(in) :: target  !! Target body name.
      character(*), intent(in) :: illmn  !! Illuminating body name.
      character(*), intent(in) :: obsrvr  !! Observer body.
      character(*), intent(in) :: abcorr  !! Aberration correction flag.
      integer(ip) :: targ
      integer(ip) :: illum
      integer(ip) :: obs
      logical :: attblk ( nabcor )
      logical :: fnd
      character(32) :: xbcorr
      if ( .not. allocated ( ctx%phaseq_state ) ) allocate ( ctx%phaseq_state )
      associate ( svctr1 => ctx%phaseq_state%svctr1, &
                  svtarg => ctx%phaseq_state%svtarg, &
                  svtgid => ctx%phaseq_state%svtgid, &
                  svfnd1 => ctx%phaseq_state%svfnd1, &
                  svctr2 => ctx%phaseq_state%svctr2, &
                  svilmn => ctx%phaseq_state%svilmn, &
                  svicde => ctx%phaseq_state%svicde, &
                  svfnd2 => ctx%phaseq_state%svfnd2, &
                  svctr3 => ctx%phaseq_state%svctr3, &
                  svobsr => ctx%phaseq_state%svobsr, &
                  svobsn => ctx%phaseq_state%svobsn, &
                  svfnd3 => ctx%phaseq_state%svfnd3, &
                  first => ctx%phaseq_state%first )
      phaseq = 0.0_wp

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Initialization.
!
      if ( first ) then

!
!        Initialize counters.
!
         call zzctruin( ctx, svctr1 )
         call zzctruin( ctx, svctr2 )
         call zzctruin( ctx, svctr3 )

         first = .false.

      end if

!
!     Obtain integer codes for the target, illuminator, and observer.
!
      call zzbods2c ( ctx, svctr1, svtarg, svtgid, svfnd1, &
                      target, targ, fnd    )

      if ( .not. fnd ) then

         call ctx%setmsg ( 'The target, ' &
         //            '''#'', is not a recognized name for an ' &
         //            'ephemeris object. The cause of this ' &
         //            'problem may be that you need an updated ' &
         //            'version of the SPICE Toolkit. '           )
         call ctx%errch  ( '#', target                                )
         call ctx%sigerr ( 'SPICE(IDCODENOTFOUND)'                    )
         return

      end if

      call zzbods2c ( ctx, svctr2, svilmn, svicde, svfnd2, &
                      illmn, illum, fnd    )

      if ( .not. fnd ) then

         call ctx%setmsg ( 'The illuminator, ' &
         //            '''#'', is not a recognized name for an ' &
         //            'ephemeris object. The cause of this ' &
         //            'problem may be that you need an updated ' &
         //            'version of the SPICE Toolkit. '           )
         call ctx%errch  ( '#', illmn                                )
         call ctx%sigerr ( 'SPICE(IDCODENOTFOUND)'                    )
         return

      end if

      call zzbods2c ( ctx, svctr3, svobsr, svobsn, svfnd3, &
                      obsrvr, obs, fnd    )

      if ( .not. fnd ) then

         call ctx%setmsg ( 'The observer, ' &
         //            '''#'', is not a recognized name for an ' &
         //            'ephemeris object. The cause of this ' &
         //            'problem may be that you need an updated ' &
         //            'version of the SPICE Toolkit. '           )
         call ctx%errch  ( '#', obsrvr                                )
         call ctx%sigerr ( 'SPICE(IDCODENOTFOUND)'                    )
         return

      end if

!
!     Squeeze all blanks out of the aberration correction
!     string; ensure the string is in upper case.
!
      call ljucrs ( 0, abcorr, xbcorr )

!
!     Check the aberration correction. If SPKEZR can't handle it,
!     neither can we.
!
      call zzvalcor ( ctx, xbcorr, attblk )

      if ( ctx%failed() ) return

!
!     Restrict correction to reception cases. The attribute block ID
!     for transmit corrections is XMTIDX.
!
      if( attblk(xmtidx) ) then

         call ctx%setmsg ( 'Invalid aberration correction ''#''. ' &
         //            'Phase angle geometry calculations currently ' &
         //            'restricted to reception cases.')
         call ctx%errch  ( '#', abcorr )
         call ctx%sigerr ( 'SPICE(INVALIDOPTION)' )
         return

      end if

!
!     Make sure the observer, illuminator, and target are distinct.
!
      if ( (targ == obs  )   .or. &
           (targ == illum)   .or. &
           (obs  == illum)      ) then

         call ctx%setmsg ( 'The observer, illuminator, and ' &
         //            'target must be distinct objects, but ' &
         //            'are not: OBSRVR = #, TARGET = #, ' &
         //            'are not: ILLMN= #.' )
         call ctx%errch  ( '#', obsrvr                         )
         call ctx%errch  ( '#', target                         )
         call ctx%errch  ( '#', illmn                          )
         call ctx%sigerr ( 'SPICE(BODIESNOTDISTINCT)'          )
         return

      end if

!
!     Call the routine to calculate the phase angle
!
      call zzgfpaq ( ctx, et, targ, illum, obs, xbcorr, phaseq )

!
!     All done.
!
      return
      end associate
      end function phaseq

      !> Return a state vector used to define coordinates referenced in a
      !> GF search.
      !>
      !> SPICE private routine intended solely for the support of SPICE
      !> routines. Users should not call this routine directly due to the
      !> volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     VECDEF     States computed by this routine consist of a an
      !>                underlying vector and the vector's velocity. VECDEF is
      !>                a short string describing the means by which the
      !>                vector of interest is defined. Only parameters from
      !>                the Fortran INCLUDE file zzgf.inc should be used.
      !>                Parameter names and meanings are:
      !>
      !>                   POSDEF               Vector is position of
      !>                                        target relative to observer.
      !>
      !>                   SOBDEF               Vector is sub-observer
      !>                                        point on target body.  Vector
      !>                                        points from target body
      !>                                        center to sub-observer point.
      !>                                        The target must be an extended
      !>                                        body modeled as a triaxial
      !>                                        ellipsoid.
      !>
      !>                   SINDEF               Vector is ray-surface intercept
      !>                                        point on target body. Vector
      !>                                        points from target body
      !>                                        center to sub-observer point.
      !>                                        The target must be an extended
      !>                                        body modeled as a triaxial
      !>                                        ellipsoid.
      !>
      !>                Case, leading and trailing blanks ARE significant
      !>                in the string VECDEF.
      !>
      !>     METHOD     is a string specifying the computational method
      !>                applicable to the vector of interest. When VECDEF
      !>                is the parameter
      !>
      !>                   SOBDEF
      !>
      !>                METHOD should be set to one of the values accepted
      !>                by the SPICELIB routine SUBPNT.
      !>
      !>                When VECDEF is the parameter
      !>
      !>                   SINDEF
      !>
      !>                METHOD should be set to one of the values accepted
      !>                by the SPICELIB routine SINCPT.
      !>
      !>                METHOD is ignored if VECDEF is set to
      !>
      !>                   POSDEF
      !>
      !>                Case, leading and trailing blanks are not significant
      !>                in the string METHOD.
      !>
      !>     TRGID      is the NAIF ID code of the target object.
      !>
      !>     ET         is the time, expressed as ephemeris seconds past J2000
      !>                TDB, at which the specified state is to be computed.
      !>
      !>     REF        is the name of the reference frame relative to which
      !>                the state of interest is specified.
      !>
      !>                Case, leading and trailing blanks are not significant
      !>                in the string REF.
      !>
      !>     ABCORR     indicates the aberration corrections to be applied to
      !>                the state of the target body to account for one-way
      !>                light time and stellar aberration.  The orientation
      !>                of the target body will also be corrected for one-way
      !>                light time when light time corrections are requested.
      !>
      !>                Supported aberration correction options for
      !>                observation (case where radiation is received by
      !>                observer at ET) are:
      !>
      !>                   NONE           No correction.
      !>                   LT             Light time only.
      !>                   LT+S           Light time and stellar aberration.
      !>                   CN             Converged Newtonian (CN) light time.
      !>                   CN+S           CN light time and stellar aberration.
      !>
      !>                Supported aberration correction options for
      !>                transmission (case where radiation is emitted from
      !>                observer at ET) are:
      !>
      !>                   XLT            Light time only.
      !>                   XLT+S          Light time and stellar aberration.
      !>                   XCN            Converged Newtonian (CN) light time.
      !>                   XCN+S          CN light time and stellar aberration.
      !>
      !>                For detailed information, see the geometry finder
      !>                required reading, gf.req.  Also see the header of
      !>                SPKEZR, which contains a detailed discussion of
      !>                aberration corrections.
      !>
      !>                Case, leading and trailing blanks are not significant
      !>                in the string ABCORR.
      !>
      !>     OBSID      is the NAIF ID code of the observer.
      !>
      !>     DREF       is the name of the reference frame relative to which a
      !>                ray's direction vector is expressed. This may be any
      !>                frame supported by the SPICE system, including
      !>                built-in frames (documented in the Frames Required
      !>                Reading) and frames defined by a loaded frame kernel
      !>                (FK). The string DREF is case-insensitive, and leading
      !>                and trailing blanks in DREF are not significant.
      !>
      !>                When DREF designates a non-inertial frame, the
      !>                orientation of the frame is evaluated at an epoch
      !>                dependent on the frame's center and, if the center is
      !>                not the observer, on the selected aberration
      !>                correction. See the description of the direction
      !>                vector DVEC for details.
      !>
      !>     DCTR       is the ID code of the object at which the frame
      !>                designated by DREF is centered. Although DCTR
      !>                can be derived from DREF, in the interest of
      !>                efficiency, DCTR is obtained by the caller,
      !>                normally during search initialization.
      !>
      !>     DVEC       Ray direction vector emanating from the observer. The
      !>                intercept with the target body's surface of the ray
      !>                defined by the observer and DVEC is sought.
      !>
      !>                DVEC is specified relative to the reference frame
      !>                designated by DREF.
      !>
      !>                Non-inertial reference frames are treated as follows:
      !>                if the center of the frame is at the observer's
      !>                location, the frame is evaluated at ET. If the frame's
      !>                center is located elsewhere, then letting LTCENT be
      !>                the one-way light time between the observer and the
      !>                central body associated with the frame, the
      !>                orientation of the frame is evaluated at ET-LTCENT,
      !>                ET+LTCENT, or ET depending on whether the requested
      !>                aberration correction is, respectively, for received
      !>                radiation, transmitted radiation, or is omitted.
      !>                LTCENT is computed using the method indicated by
      !>                ABCORR.
      !>
      !>     RADII      is a double precision array containing the three
      !>                radii of a reference ellipsoid associated with
      !>                the target body.
      !>
      !>                RADII is ignored if the input vector definition
      !>                is POSDEF; in this case the caller may set the
      !>                elements of RADII to zero.
      !>
      !>## Detailed Output
      !>
      !>     STATE      is the specified state vector, evaluated at the epoch
      !>                ET. The position component of STATE is the vector
      !>                defined by VECDEF and the other inputs. The velocity
      !>                component of STATE is the derivative with respect to
      !>                time of the position component. Units are km and km/s.
      !>
      !>                STATE is defined if and only if the output argument
      !>                FOUND is set to .TRUE.
      !>
      !>     FOUND      is a logical flag indicating whether the requested
      !>                state could be computed. FOUND is set to .FALSE. if
      !>                and only if the vector definition is SINDEF and either
      !>
      !>                - the surface intercept is not found
      !>
      !>                - the surface intercept velocity is not computable
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If the vector definition VECDEF is not recognized,
      !>         the error SPICE(NOTSUPPORTED) is signaled.
      !>
      !>     2)  If the computation method METHOD is not recognized,
      !>         the error will be diagnosed by routines in the call tree
      !>         of this routine.
      !>
      !>     3)  If the aberration correction ABCORR is not recognized,
      !>         the error will be diagnosed by routines in the call tree
      !>         of this routine.
      !>
      !>     4)  If the frame REF is not recognized by the frames subsystem,
      !>         the error will be diagnosed by routines in the call tree
      !>         of this routine.
      !>
      !>     5)  If VECDEF calls for a computation involving a target surface
      !>         point and the name and ID code of the frame associated with
      !>         the target body is not available from the frame subsystem,
      !>         the error SPICE(NOFRAME) is signaled.
      !>
      !>     6)  If VECDEF calls for a computation involving a target surface
      !>         point and ID codes of target and observer can't be converted
      !>         to names, the error  will be diagnosed by routines in the
      !>         call tree of this routine.
      !>
      !>     7)  If ephemeris data are required but not available to compute
      !>         the state of the target, the coordinate frame REF's center,
      !>         or the input ray's frame DREF's center relative to the
      !>         observer, the error will be diagnosed by routines in the call
      !>         tree of this routine.
      !>
      !>     8)  If orientation data for the frame REF are not available,
      !>         the error will be diagnosed by routines in the call tree
      !>         of this routine.
      !>
      !>     9)  If orientation data for the frame DREF are required but
      !>         not available, the error will be diagnosed by routines in the
      !>         call tree of this routine.
      !>
      !>     10) If the input radii don't define a valid triaxial ellipsoid,
      !>         the error will be diagnosed by routines in the call tree of
      !>         this routine.
      !>
      !>## Files
      !>
      !>     This routine doesn't directly participate in SPICE kernel loading
      !>     or unloading.  However, a variety of SPICE kernels must be loaded
      !>     in order for this routine to work:
      !>
      !>        - SPK files providing ephemeris data enabling computation of
      !>          the specified state vector are required.
      !>
      !>        - If non-inertial reference frames are used, then PCK
      !>          files, frame kernels, C-kernels, and SCLK kernels may be
      !>          needed.
      !>
      !>        - If the state of interest is defined in terms of a target
      !>          surface point, then (currently) a PCK providing radii for a
      !>          triaxial shape model must be loaded.
      !>
      !>     See the Files section of GFEVNT's header for further information.
      !>
      !>## Particulars
      !>
      !>     This routine is used by the GF coordinate utility routines in
      !>     order to solve for time windows on which specified mathematical
      !>     conditions involving coordinates are satisfied. The role of
      !>     this routine is to provide Cartesian state vectors enabling
      !>     the GF coordinate utilities to determine the signs of the
      !>     derivatives with respect to time of coordinates of interest.
      !>
      !>     This routine has a secondary purpose: enabling the GF system
      !>     to determine, via a binary state search, the window over
      !>     which a coordinate of interest is computable. This "computability
      !>     window" must be found before any search involving a constraint
      !>     on a coordinate of a surface intercept point can be performed.
      !>
      !>## Examples
      !>
      !>     See ZZGFCOU.
      !>
      !>## Restrictions
      !>
      !>     1)  The interface and functionality of this set of routines may
      !>         change without notice.  These routines should be called only
      !>         by SPICELIB routines.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.0 05-MAR-2009 (NJB)
      module subroutine zzgfcost ( ctx, vecdef, method, trgid, et, ref, abcorr, obsid, dref, dctr, dvec, radii, state, found )
      use pepper_kinds, only: ip, wp
      use pepper_inc_gf
      use pepper_inc_zzgf
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      character(*), intent(in) :: vecdef  !! Vector definition.
      character(*), intent(in) :: method  !! Computation method.
      integer(ip), intent(in) :: trgid  !! Target ID code.
      real(wp), intent(in) :: et  !! Computation epoch.
      character(*), intent(in) :: ref  !! Reference frame name.
      character(*), intent(in) :: abcorr  !! Aberration correction.
      integer(ip), intent(in) :: obsid  !! Observer ID code.
      character(*), intent(in) :: dref  !! Reference frame of ray's direction vector.
      integer(ip), intent(in) :: dctr  !! ID code of ray frame's center.
      real(wp), intent(in) :: dvec   ( 3 )  !! Ray's direction vector.
      real(wp), intent(in) :: radii  ( 3 )  !! Radii of reference ellipsoid.
      real(wp), intent(out) :: state  ( 6 )  !! State used to define coordinates.
      logical, intent(out) :: found  !! Flag indicating if state was computed.

      real(wp) :: lt

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     No result was found yet.
!
      found = .false.

      if ( vecdef == posdef  ) then
!
!        Find the observer-target state vector.
!
         call spkez ( ctx, trgid, et, ref, abcorr, obsid, state, lt )

         found = .true.

      else if ( vecdef == sobdef ) then
!
!        The caller has requested the state of a sub-observer point.
!
         call zzgfssob ( ctx, method, trgid, et,    ref, &
                         abcorr, obsid, radii, state )

         found = .true.

      else if ( vecdef == sindef ) then
!
!        The caller has requested the state of a surface intercept
!        point.
!
         call zzgfssin ( ctx, method, trgid, et,   ref,   abcorr, obsid, &
                         dref,   dctr,  dvec, radii, state,  found )

      else

         call ctx%setmsg ( 'The coordinate quantity # is not recognized.' )
         call ctx%errch  ( '#',  vecdef                                   )
         call ctx%sigerr ( 'SPICE(NOTSUPPORTED)'                          )
         return

      end if

!
!     At this point, one of the following is true:
!
!        - the state vector was found and
!          FOUND is .TRUE.
!
!        - FOUND is .FALSE.
!
!        - a SPICE error occurred
!

      return
      end subroutine zzgfcost

      !> Initialize the GF distance constraint search utilities.
      !>
      !>## Detailed Input
      !>
      !>     TARGET     is the name of a target body. Optionally, you may
      !>                supply the integer ID code for the object as
      !>                an integer string. For example both 'MOON' and
      !>                '301' are legitimate strings that indicate the
      !>                moon is the target body.
      !>
      !>                The target and observer define a position vector
      !>                which points from the observer to the target.
      !>
      !>                Case and leading or trailing blanks are not
      !>                significant in the string TARGET.
      !>
      !>     ABCORR     indicates the aberration corrections to be applied
      !>                when computing the target's position and orientation.
      !>                Any value accepted by SPKEZR may be used.
      !>
      !>                See the header of the SPICE routine SPKEZR for a
      !>                detailed description of the aberration correction
      !>                options.
      !>
      !>                Case and embedded blanks are not significant in
      !>                ABCORR.
      !>
      !>     OBSRVR     is the name of the body from which the occultation is
      !>                observed. Optionally, you may supply the integer NAIF
      !>                ID code for the body as a string.
      !>
      !>                Case and leading or trailing blanks are not
      !>                significant in the string OBSRVR.
      !>
      !>## Detailed Output
      !>
      !>     None.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If name of the target or the observer cannot be translated
      !>         to a NAIF ID code, the error SPICE(IDCODENOTFOUND) is
      !>         signaled.
      !>
      !>     2)  If  target body coincides with the observer body OBSRVR, the
      !>         error SPICE(BODIESNOTDISTINCT) will be signaled.
      !>
      !>     3)  If the aberration correction string is invalid, the error
      !>         will be diagnosed by a routine in the call tree of this
      !>         routine.
      !>
      !>## Files
      !>
      !>     See the header of the umbrella routine ZZGFDIU.
      !>
      !>## Particulars
      !>
      !>     This routine must be called once before each GF search for
      !>     distance events.
      !>
      !>## Examples
      !>
      !>     See GFEVNT.
      !>
      !>## Restrictions
      !>
      !>     This is a SPICELIB private routine; it should not be called by
      !>     user applications.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>     L.S. Elson     (JPL)
      !>     W.L. Taber     (JPL)
      !>     I.M. Underwood (JPL)
      !>     E.D. Wright    (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB version 2.0.0 18-FEB-2011 (EDW)
      !>
      !>        REFVAL removed from routine argument list due to use
      !>        of ZZGFRELX to calculate the events.
      !>
      !>-    SPICELIB Version 1.0.0 05-MAR-2009 (NJB) (LSE) (WLT) (IMU) (EDW)
      module subroutine zzgfdiin ( ctx, target, abcorr, obsrvr )
      use pepper_kinds, only: ip, wp
      use pepper_strings, only: cmprss, ucase_inplace
      use pepper_inc_zzabcorr
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      character(*), intent(in) :: target  !! Target body name.
      character(*), intent(in) :: abcorr  !! Aberration correction specifier.
      character(*), intent(in) :: obsrvr  !! Observer name.
      real(wp) :: lt
      real(wp) :: state  ( 6 )
      logical :: attblk ( nabcor )
      logical :: found
      if ( .not. allocated ( ctx%zzgfdiu_state ) ) allocate ( ctx%zzgfdiu_state )
      associate ( svcorr => ctx%zzgfdiu_state%svcorr, &
                  svobs => ctx%zzgfdiu_state%svobs, &
                  svtarg => ctx%zzgfdiu_state%svtarg )
      if ( ctx%failed() ) return

!
!     Find NAIF IDs for TARGET and OBSRVR.
!
      call bods2c ( ctx, target, svtarg, found )

      if ( .not. found ) then

         call ctx%setmsg ( 'The target object, ' &
         //            '''#'', is not a recognized name for an ' &
         //            'ephemeris object. The cause of this ' &
         //            'problem may be that you need an updated ' &
         //            'version of the SPICE Toolkit. '           )
         call ctx%errch  ( '#', target                                )
         call ctx%sigerr ( 'SPICE(IDCODENOTFOUND)'                    )
         return

      end if

      call bods2c ( ctx, obsrvr, svobs, found )

      if ( .not. found ) then

         call ctx%setmsg ( 'The observer, ' &
         //            '''#'', is not a recognized name for an ' &
         //            'ephemeris object. The cause of this ' &
         //            'problem may be that you need an updated ' &
         //            'version of the SPICE toolkit. '           )
         call ctx%errch  ( '#', obsrvr                                )
         call ctx%sigerr ( 'SPICE(IDCODENOTFOUND)'                    )
         return

      end if

!
!     Make sure the observer and target are distinct.
!
      if ( svtarg == svobs ) then

         call ctx%setmsg ( 'The observer and target must be ' &
         //            'distinct objects, but are not: ' &
         //            'OBSRVR = #; TARGET = #.'           )
         call ctx%errch  ( '#', obsrvr                         )
         call ctx%errch  ( '#', target                         )
         call ctx%sigerr ( 'SPICE(BODIESNOTDISTINCT)'          )
         return

      end if

!
!     Squeeze all blanks out of the aberration correction
!     string; ensure the string is in upper case.
!
      call cmprss ( ' ', 0, abcorr, svcorr )
      call ucase_inplace ( svcorr )

!
!     Check the aberration correction. If SPKEZR can't handle it,
!     neither can we.
!
      call zzvalcor ( ctx, svcorr, attblk )

      if ( ctx%failed() ) return

      return
      end associate
      end subroutine zzgfdiin

      !> Indicate whether the observer-target distance is decreasing at a
      !> specified time.
      !>
      !>## Detailed Input
      !>
      !>     ET         is the time, expressed as seconds past J2000 TDB, at
      !>                which to determine whether or not the distance between
      !>                the observer and target is decreasing.
      !>
      !>## Detailed Output
      !>
      !>     DECRES     is a logical flag that indicates whether the
      !>                observer-target distance is decreasing at ET. The
      !>                observer, target, and aberration correction used to
      !>                compute the distance are defined by the latest call to
      !>                the initialization entry point ZZGFDIIN.
      !>
      !>                DECRES is .TRUE. if and only if the observer-target
      !>                distance is decreasing at ET.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1) If the state of the target relative to the observer
      !>        at ET can not be found due to an SPK lookup failure,
      !>        the error will be diagnosed by routines in the call
      !>        tree of this routine.
      !>
      !>## Files
      !>
      !>     See the header of the umbrella routine ZZGFDIU.
      !>
      !>## Particulars
      !>
      !>     A function f(x) is strictly decreasing at x0 if and only if there
      !>     exists some delta > 0 such that for all dx satisfying
      !>
      !>        0  <  dx  < delta
      !>
      !>     we have
      !>
      !>        f(x0)       <  f(x0 + dx)
      !>
      !>     and
      !>
      !>        f(x0 - dx)  <  f(x)
      !>
      !>     Note that a strictly decreasing function need not be
      !>     differentiable in a neighborhood of x0; it can have jump
      !>     discontinuities in any neighborhood of x0 and even at x0.
      !>
      !>## Examples
      !>
      !>     See GFREL.
      !>
      !>## Restrictions
      !>
      !>     This is a SPICELIB private routine; it should not be called by
      !>     user applications.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>     L.S. Elson     (JPL)
      !>     W.L. Taber     (JPL)
      !>     I.M. Underwood (JPL)
      !>     E.D. Wright    (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB version 2.0.0 18-FEB-2011 (EDW)
      !>
      !>        Added UDFUNC to argument list for use of ZZGFRELX when
      !>        calculating the events.
      !>
      !>-    SPICELIB Version 1.0.0 05-MAR-2009 (NJB) (LSE) (WLT) (IMU) (EDW)
      module subroutine zzgfdidc ( ctx, udfunc, et, decres )
      use pepper_kinds, only: ip, wp
      use pepper_math, only: vdot
      use pepper_inc_zzabcorr
      implicit none
      real(wp) :: lt
      real(wp) :: state  ( 6 )
      logical :: attblk ( nabcor )
      logical :: found
      class(pepper_context), intent(inout) :: ctx  !! the context
      real(wp), intent(in) :: et  !! Ephemeris seconds past J2000 TDB.
      logical, intent(out) :: decres  !! Flag indicating whether distance is decreasing.
      procedure(gf_scalar) :: udfunc  !! the [[gf_scalar]] routine
      if ( .not. allocated ( ctx%zzgfdiu_state ) ) allocate ( ctx%zzgfdiu_state )
      associate ( svcorr => ctx%zzgfdiu_state%svcorr, &
                  svobs => ctx%zzgfdiu_state%svobs, &
                  svtarg => ctx%zzgfdiu_state%svtarg )
      if ( ctx%failed() ) return

      call spkez ( ctx, svtarg, et, 'J2000', svcorr, svobs, state, lt )

      if (  ctx%failed() ) return

!
!     The observer-target distance is decreasing if and only
!     if the dot product of the velocity and position is
!     negative.
!
      decres  =  vdot( state, state(4) )  <  0.0_wp

      return
      end associate
      end subroutine zzgfdidc

      !> Return the distance between the target and observer
      !> at a specified epoch.
      !>
      !>## Detailed Input
      !>
      !>     ET         is the time, expressed as seconds past J2000 TDB, at
      !>                which the distance between the observer and target is
      !>                to be computed.
      !>
      !>## Detailed Output
      !>
      !>     DIST       is the distance between the observer and target as
      !>                seen by the observer at time ET. The observer, target,
      !>                and aberration correction used to compute the distance
      !>                are defined by the latest call to the initialization
      !>                entry point ZZGFDIIN.
      !>
      !>                Units are km.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1) If the position of the target relative to the observer
      !>        at ET can not be found due to an SPK lookup failure,
      !>        the error will be diagnosed by routines in the call
      !>        tree of this routine.
      !>
      !>## Files
      !>
      !>     See the header of the umbrella routine ZZGFDIU.
      !>
      !>## Particulars
      !>
      !>     This routine determines the apparent distance between the target
      !>     and observer as seen from the observer at time ET. This
      !>     functionality supports GFREL's comparisons of relative extrema in
      !>     order to determine absolute extrema.
      !>
      !>## Examples
      !>
      !>     See GFREL.
      !>
      !>## Restrictions
      !>
      !>     This is a SPICELIB private routine; it should not be called by
      !>     user applications.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>     L.S. Elson     (JPL)
      !>     W.L. Taber     (JPL)
      !>     I.M. Underwood (JPL)
      !>     E.D. Wright    (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.0 05-MAR-2009 (NJB) (LSE) (WLT) (IMU) (EDW)
      module subroutine zzgfdigq ( ctx, et, dist )
      use pepper_kinds, only: ip, wp
      use pepper_inc_zzabcorr
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      real(wp), intent(in) :: et  !! Ephemeris seconds past J2000 TDB.
      real(wp), intent(out) :: dist  !! Distance at time ET.
      real(wp) :: lt
      real(wp) :: state  ( 6 )
      logical :: attblk ( nabcor )
      logical :: found
      if ( .not. allocated ( ctx%zzgfdiu_state ) ) allocate ( ctx%zzgfdiu_state )
      associate ( svcorr => ctx%zzgfdiu_state%svcorr, &
                  svobs => ctx%zzgfdiu_state%svobs, &
                  svtarg => ctx%zzgfdiu_state%svtarg )
      if ( ctx%failed() ) return

      call zzgfdiq ( ctx, svtarg, et, svcorr, svobs, dist )

      return
      end associate
      end subroutine zzgfdigq

      !> This is the initialization entry point used for describing
      !> the event that is to be solved for by [[zzgfsolv]].
      !>
      !>## Detailed Input
      !>
      !>     TARGET   the string name of a target body.  Optionally, you may
      !>              supply the integer ID code for the object as an
      !>              integer string.  For example both 'MOON' and '301'
      !>              are legitimate strings that indicate the moon is the
      !>              target body.
      !>
      !>              Case and leading or trailing blanks are not significant
      !>              in the string TARGET.
      !>
      !>     ILLMN    the string name of the illuminating body. This will
      !>              normally be 'SUN' but the algorithm can use any
      !>              ephemeris object
      !>
      !>              Case and leading or trailing blanks are not significant
      !>              in the string ILLMN.
      !>
      !>     ABCORR   the string description of the aberration corrections to
      !>              apply to the state evaluations to account for one-way
      !>              light time and stellar aberration.
      !>
      !>              Any aberration correction accepted by the SPICE
      !>              routine SPKEZR is accepted here. See the header
      !>              of SPKEZR for a detailed description of the
      !>              aberration correction options. For convenience,
      !>              the options are listed below:
      !>
      !>                 'NONE'     Apply no correction. Returns the "true"
      !>                            geometric state.
      !>
      !>                 'LT'       "Reception" case:  correct for
      !>                            one-way light time using a Newtonian
      !>                            formulation.
      !>
      !>                 'LT+S'     "Reception" case:  correct for
      !>                            one-way light time and stellar
      !>                            aberration using a Newtonian
      !>                            formulation.
      !>
      !>                 'CN'       "Reception" case:  converged
      !>                            Newtonian light time correction.
      !>
      !>                'CN+S'     "Reception" case:  converged
      !>                            Newtonian light time and stellar
      !>                            aberration corrections.
      !>
      !>              Note that this routine accepts only reception mode
      !>              aberration corrections.
      !>
      !>              The ABCORR string lacks sensitivity to case, leading
      !>              and trailing blanks.
      !>
      !>     OBSRVR   the string name of an observing body.  Optionally, you
      !>              may supply the ID code of the object as an integer
      !>              string. For example, both 'EARTH' and '399' are
      !>              legitimate strings to indicate the observer as Earth.
      !>
      !>              Case and leading or trailing blanks are not significant
      !>              in the string OBSRVR.
      !>
      !>## Detailed Output
      !>
      !>     None.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1) SPICE(IDCODENOTFOUND) signals if the object name for the
      !>        target, TARGET, is not a recognized name.
      !>
      !>     2) SPICE(IDCODENOTFOUND) signals if the object name for the
      !>        illuminator, ILLMN, is not a recognized name.
      !>
      !>     3) SPICE(IDCODENOTFOUND) signals if the object name for the
      !>        observer, OBSRVR, is not a recognized name.
      !>
      !>     4) SPICE(BODIESNOTDISTINCT) signals if the three objects
      !>        associated with a PHASE ANGLE search are not distinct.
      !>
      !>     5) SPICE(INVALIDOPTION) signals for any transmit mode aberration
      !>        correction.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     None.
      !>
      !>## Examples
      !>
      !>     None.
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>     E.D. Wright    (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB version 1.0.0 19-OCT-2010 (EDW)(NJB)
      module subroutine zzgfpain ( ctx, target, illmn, abcorr, obsrvr )
      use pepper_kinds, only: ip, wp
      use pepper_strings, only: cmprss, ucase_inplace
      use pepper_inc_zzabcorr
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      character(*), intent(in) :: target  !! Name of the target body.
      character(*), intent(in) :: illmn  !! Name of the illuminating body.
      character(*), intent(in) :: abcorr  !! Aberration correction flag.
      character(*), intent(in) :: obsrvr  !! Name of the observing body.
      real(wp) :: dsep
      real(wp) :: lt
      real(wp) :: dlt
      real(wp) :: s1   (6)
      real(wp) :: s2   (6)
      real(wp) :: uvec (3)
      integer(ip) :: i
      logical :: found
      if ( .not. allocated ( ctx%zzgfpau_state ) ) allocate ( ctx%zzgfpau_state )
      associate ( svablk => ctx%zzgfpau_state%svablk, &
                  svabco => ctx%zzgfpau_state%svabco, &
                  svtarg => ctx%zzgfpau_state%svtarg, &
                  svobs => ctx%zzgfpau_state%svobs, &
                  svillm => ctx%zzgfpau_state%svillm )
      if ( ctx%failed() ) return

!
!     Find NAIF IDs for TARGET, ILLMN, and OBSRVR.
!
      call bods2c ( ctx, target, svtarg, found )

      if ( .not. found ) then

         call ctx%setmsg ( 'The target object, ' &
         //            '''#'', is not a recognized name for an ' &
         //            'ephemeris object. The cause of this ' &
         //            'problem may be that you need an updated ' &
         //            'version of the SPICE Toolkit. '           )
         call ctx%errch  ( '#', target                                )
         call ctx%sigerr ( 'SPICE(IDCODENOTFOUND)'                    )
         return

      end if

      call bods2c ( ctx, illmn, svillm, found )

      if ( .not. found ) then

         call ctx%setmsg ( 'The illuminator object, ' &
         //            '''#'', is not a recognized name for an ' &
         //            'ephemeris object. The cause of this ' &
         //            'problem may be that you need an updated ' &
         //            'version of the SPICE toolkit. '           )
         call ctx%errch  ( '#', obsrvr                                )
         call ctx%sigerr ( 'SPICE(IDCODENOTFOUND)'                    )
         return

      end if

      call bods2c ( ctx, obsrvr, svobs, found )

      if ( .not. found ) then

         call ctx%setmsg ( 'The observer object, ' &
         //            '''#'', is not a recognized name for an ' &
         //            'ephemeris object. The cause of this ' &
         //            'problem may be that you need an updated ' &
         //            'version of the SPICE toolkit. '           )
         call ctx%errch  ( '#', obsrvr                                )
         call ctx%sigerr ( 'SPICE(IDCODENOTFOUND)'                    )
         return

      end if

!
!     Make sure the observer, illuminator, and target are distinct.
!
      if ( (svtarg == svobs)   .or. &
           (svtarg == svillm) .or. &
           (svobs  == svillm)      ) then

         call ctx%setmsg ( 'The observer, illuminator, and ' &
         //            'target must be distinct objects, but ' &
         //            'are not: OBSRVR = #, TARGET = #, ' &
         //            'are not: ILLMN= #.' )
         call ctx%errch  ( '#', obsrvr                         )
         call ctx%errch  ( '#', target                         )
         call ctx%errch  ( '#', illmn                          )
         call ctx%sigerr ( 'SPICE(BODIESNOTDISTINCT)'          )
         return

      end if

!
!     Squeeze all blanks out of the aberration correction
!     string; ensure the string is in upper case.
!
      call cmprss ( ' ', 0, abcorr, svabco )
      call ucase_inplace ( svabco )

!
!     Check the aberration correction. If SPKEZR can't handle it,
!     neither can we.
!
      call zzvalcor ( ctx, svabco, svablk )

      if ( ctx%failed() ) return

!
!     Restrict correction to reception cases.
!

      if( svablk(xmtidx) ) then

         call ctx%setmsg ( 'Invalid aberration correction ''#''. ' &
         //            'Phase angle geometry calculations currently ' &
         //            'restricted to reception cases.')
         call ctx%errch  ( '#', abcorr )
         call ctx%sigerr ( 'SPICE(INVALIDOPTION)' )
         return

      end if

      return
      end associate
      end subroutine zzgfpain

      !> Computes whether or not the phase angle between the observer
      !> and the target is decreasing at time ET.
      !>
      !>## Detailed Input
      !>
      !>     ET         the time in ephemeris seconds past J2000 TDB at which
      !>                to determine whether the phase angle between SVTARG
      !>                and SVILLMN as seen from SVOBS is decreasing.
      !>
      !>## Detailed Output
      !>
      !>     DECRES     is .TRUE. if the phase angle is decreasing at ET.
      !>                Otherwise it is .FALSE..
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     None.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     A function f(x) is strictly decreasing at x0 if and only if there
      !>     exists some delta > 0 such that for all dx satisfying
      !>
      !>        0  <  dx  < delta
      !>
      !>     we have
      !>
      !>        f(x0)       <  f(x0 + dx)
      !>
      !>     and
      !>
      !>        f(x0 - dx)  <  f(x)
      !>
      !>     Note that a strictly decreasing function need not be
      !>     differentiable in a neighborhood of x0; it can have jump
      !>     discontinuities in any neighborhood of x0 and even at x0.
      !>
      !>## Examples
      !>
      !>     None.
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>     E.D. Wright    (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB version 1.0.0 10-JAN-2012 (EDW)
      module subroutine zzgfpadc ( ctx, udfunc, et, decres )
      use pepper_kinds, only: ip, wp
      use pepper_constants, only: clight
      use pepper_math, only: vdot, vhat
      use pepper_inc_zzabcorr
      implicit none
      character(*), parameter :: ref = 'J2000'
      real(wp) :: dsep
      real(wp) :: lt
      real(wp) :: dlt
      real(wp) :: s1   (6)
      real(wp) :: s2   (6)
      real(wp) :: uvec (3)
      integer(ip) :: i
      logical :: found
      class(pepper_context), intent(inout) :: ctx  !! the context
      real(wp), intent(in) :: et  !! Ephemeris seconds past J2000 TDB.
      logical, intent(out) :: decres  !! .TRUE. if phase angle is decreasing, .FALSE. otherwise.
      procedure(gf_scalar) :: udfunc  !! the [[gf_scalar]] routine
      if ( .not. allocated ( ctx%zzgfpau_state ) ) allocate ( ctx%zzgfpau_state )
      associate ( svablk => ctx%zzgfpau_state%svablk, &
                  svabco => ctx%zzgfpau_state%svabco, &
                  svtarg => ctx%zzgfpau_state%svtarg, &
                  svobs => ctx%zzgfpau_state%svobs, &
                  svillm => ctx%zzgfpau_state%svillm )
      if ( ctx%failed() ) return

!
!     Get the state of the TARG object relative to OBS at ET.
!
      call spkez ( ctx, svtarg, et, ref, svabco, svobs, s1, lt )

      if (  ctx%failed() ) return

!
!     Get the state of the ILLMN object relative to TARG at ET
!     for no aberration correction, or ET - LT otherwise.
!
      if ( svablk(geoidx) ) then

!
!        No correction, geometric.
!
         call spkez ( ctx, svillm, et,      ref, svabco, svtarg, s2, lt )

      else

         call spkez ( ctx, svillm, et - lt, ref, svabco, svtarg, s2, lt )

         if (  ctx%failed() ) return

!
!        Correct velocity for time derivative of the observer target
!        light-time. We need to do this since the SPK evaluation occurs
!        at ET - LT.
!
!        d( ET - LT ) = (1 - d LT )
!        ------------        ----
!        dt                  dt
!
!        LT = ||R||
!             -----
!               C
!                                     ^
!        d LT    = 1   d ||R||  = 1 < R, V >
!        ----      -   -------    -
!        dt        C   dt         C
!
         call vhat ( s1, uvec )

         dlt = vdot ( uvec, s1(4) ) / clight

!
!        Apply the correction to the velocity vector components.
!
         s2(4:6) = (1.0_wp - dlt)*s2(4:6)

      end if

      if (  ctx%failed() ) return

!
!                       ILLMN      OBS
!       ILLMN as seen      *       /
!       from TARG at       |      /
!       ET - LT.           |     /
!                         >|..../< phase angle
!                          |   /
!                        . |  /
!                      .   | /
!                     .     *     TARG as seen from OBS
!               SEP   .   TARG    at ET
!                      .  /
!                        /
!                       *
!
!     Calculate the derivative of the angle separating the vectors
!     relative to TARG.
!
!        PI = SEP + PHASE
!
!        dPHASE     dSEP
!        ------ = - ----
!         dt         dt
!
      dsep   = dvsep( ctx, s1, s2 )

      decres = -dsep < 0.0_wp

      return
      end associate
      end subroutine zzgfpadc

      !> Determine the phase angle between the centers of the two
      !> bodies.
      !>
      !>## Detailed Input
      !>
      !>     ET         the time in ephemeris seconds past J2000 TDB at which
      !>                to compute the phase angle.
      !>
