      real(wp) :: s1   (6)
      real(wp) :: s2   (6)
      real(wp) :: uvec (3)
      integer(ip) :: i
      logical :: found
      if ( .not. allocated ( ctx%zzgfpau_state ) ) allocate ( ctx%zzgfpau_state )
      associate ( svabco => ctx%zzgfpau_state%svabco, &
                  svtarg => ctx%zzgfpau_state%svtarg, &
                  svobs => ctx%zzgfpau_state%svobs, &
                  svillm => ctx%zzgfpau_state%svillm )
      call zzgfpaq ( ctx, et, svtarg, svillm, svobs, svabco, rvl )

      return
      end associate
      end subroutine zzgfpagq

      !> Retrieve values set in [[zzgfpain]].
