      !>     W.L. Taber     (JPL)
      !>     I.M. Underwood (JPL)
      !>     L.S. Elson     (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB version 1.0.0 09-JUN-2009 (LSE)(EDW)
      module subroutine zzgfrrgq ( ctx, et, rvl )
      use pepper_kinds, only: ip, wp
      use pepper_inc_zzabcorr
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      real(wp), intent(in) :: et  !! Ephemeris seconds past J2000 TDB.
      real(wp), intent(out) :: rvl  !! Range rate at time ET.
      logical :: return
      real(wp) :: lt
      real(wp) :: drvel
      real(wp) :: srhat  ( 6 )
      real(wp) :: state  ( 6 )
      real(wp) :: dfdt   ( 6 )
      real(wp) :: states ( 6, 2 )
      integer(ip) :: n
      logical :: attblk ( nabcor )
      logical :: found
      if ( .not. allocated ( ctx%zzgfrru_state ) ) allocate ( ctx%zzgfrru_state )
      associate ( svabco => ctx%zzgfrru_state%svabco, &
                  svtarg => ctx%zzgfrru_state%svtarg, &
                  svobs => ctx%zzgfrru_state%svobs )
      call zzgfrrq ( ctx, et, svtarg, svobs, svabco, rvl )

      return
      end associate
      end subroutine zzgfrrgq

      !> Retrieve values set in [[zzgfrrin]].
      !>
      !>## Detailed Input
      !>
      !>     None.
      !>
      !>## Detailed Output
      !>
      !>     XTARG    SPICE ID value for the target body initialized
      !>              via ZZGFRRIN.
      !>
      !>     XABCOR   String value for the aberration correction initialized
      !>              via ZZGFRRIN.
      !>
      !>     XOBS     SPICE ID value for the observing body initialized
      !>              via ZZGFRRIN.
      !>
      !>     XDT      Saved value for DT.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     None.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     None.
      !>
      !>## Examples
      !>
      !>     None.
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>     E.D. Wright    (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB version 1.0.0 16-SEP-2012 (EDW)
      module subroutine zzgfrrx ( ctx, xtarg, xabcor, xobs, xdt )
      use pepper_kinds, only: ip, wp
      use pepper_inc_zzabcorr
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(out) :: xtarg  !! Saved value for the target body.
      character(*), intent(out) :: xabcor  !! Saved value for the aberration correction.
      integer(ip), intent(out) :: xobs  !! Saved value for the observing body.
      real(wp), intent(out) :: xdt  !! Saved value for DT.
      logical :: return
      real(wp) :: lt
      real(wp) :: drvel
      real(wp) :: srhat  ( 6 )
      real(wp) :: state  ( 6 )
      real(wp) :: dfdt   ( 6 )
      real(wp) :: states ( 6, 2 )
      integer(ip) :: n
      logical :: attblk ( nabcor )
      logical :: found
      if ( .not. allocated ( ctx%zzgfrru_state ) ) allocate ( ctx%zzgfrru_state )
      associate ( svabco => ctx%zzgfrru_state%svabco, &
                  svtarg => ctx%zzgfrru_state%svtarg, &
                  svobs => ctx%zzgfrru_state%svobs, &
                  svdt => ctx%zzgfrru_state%svdt )
         xtarg  = svtarg
         xabcor = svabco
         xobs   = svobs
         xdt    = svdt

      return
      end associate
      end subroutine zzgfrrx

      !> Routine to determine time intervals when a user defined boolean
      !> function returns true. Report progress and handle interrupts
      !> if so commanded.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines.  Users should not call this routine directly due
      !> to the volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     UDFUNS     the routine that returns the value of the scalar
      !>                quantity of interest at time ET. The calling sequence
      !>                for UDFUNC is:
      !>
      !>                   CALL UDFUNS ( ET, VALUE )
      !>
      !>                where:
      !>
      !>                   ET      a double precision value representing
      !>                           ephemeris time, expressed as seconds past
      !>                           J2000 TDB at which to determine the scalar
      !>                           value.
      !>
      !>                   VALUE   is the value of the scalar quantity
      !>                           at ET.
      !>
      !>     UDFUNB     the user defined routine returning a boolean value
      !>                for an epoch ET.
      !>
      !>                The calling sequence:
      !>
      !>                   CALL UDFUNB ( UDFUNS, ET, BOOL )
      !>
      !>                where:
      !>
      !>                   UDFUNS   a scalar function as previously defined.
      !>
      !>                   ET       a double precision value representing
      !>                            ephemeris time, expressed as seconds past
      !>                            J2000 TDB, at which to evaluate UDFUNB.
      !>
      !>                   BOOL     the boolean value at ET.
      !>
      !>     TOL        is a tolerance value used to determine convergence of
      !>                root-finding operations. TOL is measured in TDB seconds
      !>                and must be greater than zero.
      !>
      !>     UDSTEP     is an externally specified routine that computes a
      !>                time step used to find transitions of the state being
      !>                considered. A state transition occurs where the state
      !>                changes from being "in state" to being "not in
      !>                state" or vice versa.
      !>
      !>                This routine relies on UDSTEP returning step sizes
      !>                small enough so that state transitions within the
      !>                confinement window are not overlooked.
      !>
      !>                The calling sequence for UDSTEP is:
      !>
      !>                   CALL UDSTEP ( ET, STEP )
      !>
      !>                where:
      !>
      !>                   ET      is the input start time from which the
      !>                           algorithm is to search forward for a state
      !>                           transition. ET is expressed as seconds past
      !>                           J2000 TDB. ET is a DOUBLE PRECISION number.
      !>
      !>                   STEP    is the output step size.  STEP indicates
      !>                           how far to advance ET so that ET and
      !>                           ET+STEP may bracket a state transition and
      !>                           definitely do not bracket more than one
      !>                           state transition. STEP is a DOUBLE
      !>                           PRECISION number. Units are TDB seconds.
      !>
      !>                If a constant step size is desired, the routine GFSTEP
      !>                may be used. If GFSTEP is used, the step size must be
      !>                set by calling GFSSTP prior to calling this routine.
      !>
      !>     UDREFN     is the name of the externally specified routine that
      !>                refines the times that bracket a transition point. In
      !>                other words, once a pair of times, T1 and T2, that
      !>                bracket a state transition have been found, UDREFN
      !>                computes an intermediate time T such that either
      !>                [T1, T] or [T, T2] contains the time of the state
      !>                transition. The calling sequence for UDREFN is:
      !>
      !>                   CALL UDREFN ( T1, T2, S1, S2, T )
      !>
      !>                where the inputs are:
      !>
      !>                   T1    is a time when the visibility state is S1. T1
      !>                         is expressed as seconds past J2000 TDB.
      !>
      !>                   T2    is a time when the visibility state is S2. T2
      !>                         is expressed as seconds past J2000 TDB. and
      !>                         is assumed to be larger than T1.
      !>
      !>                   S1    is the visibility state at time T1. S1 is a
      !>                         LOGICAL value.
      !>
      !>                   S2    is the visibility state at time T2. S2 is a
      !>                         LOGICAL value.
      !>
      !>                The output is:
      !>
      !>                   T     is the next time to check for a state
      !>                         transition. T is expressed as seconds past
      !>                         J2000 TDB and is between T1 and T2.
      !>
      !>                If a simple bisection method is desired, the routine
      !>                GFREFN may be used.
      !>
      !>     RPT        is a logical variable which controls whether
      !>                progress reporting is enabled. When RPT is .TRUE.,
      !>                progress reporting is enabled and the routines
      !>                UDREPI, UDREPU, and UDPREF (see descriptions below)
      !>                are used to report progress.
      !>
      !>     UDREPI     is a user-defined subroutine that initializes a
      !>                progress report. When progress reporting is
      !>                enabled, UDREPI is called at the start
      !>                of a search. The calling sequence of UDREPI is
      !>
      !>                   UDREPI ( CNFINE, SRCPRE, SRCSUF )
      !>
      !>                   DOUBLE PRECISION    CNFINE ( LBCELL : * )
      !>                   CHARACTER*(*)       SRCPRE
      !>                   CHARACTER*(*)       SRCSUF
      !>
      !>                where
      !>
      !>                   CNFINE
      !>
      !>                is the confinement window and
      !>
      !>                   SRCPRE
      !>                   SRCSUF
      !>
      !>                are prefix and suffix strings used in the progress
      !>                report: these strings are intended to bracket a
      !>                representation of the fraction of work done.  For
      !>                example, when the CSPICE progress reporting functions
      !>                are used, if SRCPRE and SRCSUF are, respectively,
      !>
      !>                   "User defined boolean event search"
      !>                   "done."
      !>
      !>                the progress report display at the end of the
      !>                search will be:
      !>
      !>                   User defined boolean event search 100.00% done.
      !>
      !>                The SPICELIB routine GFREPI may be used as the
      !>                actual argument corresponding to UDREPI. If so,
      !>                the SPICELIB routines GFREPU and GFREPF must be
      !>                the actual arguments corresponding to UDREPU and
      !>                UDREPF.
      !>
      !>     UDREPU     is a user-defined subroutine that updates the
      !>                progress report for a search.  The calling sequence
      !>                of UDREPU is
      !>
      !>                   UDREPU ( IVBEG, IVEND, ET )
      !>
      !>                   DOUBLE PRECISION      IVBEG
      !>                   DOUBLE PRECISION      IVEND
      !>                   DOUBLE PRECISION      ET
      !>
      !>                Here IVBEG, IVEND are the bounds of an interval that
      !>                is contained in some interval belonging to the
      !>                confinement window. The confinement window is
      !>                associated with some root finding activity. It is used
      !>                to determine how much total time is being searched in
      !>                order to find the events of interest.
      !>
      !>                ET is an epoch belonging to the interval
      !>                [IVBEG, IVEND].
      !>
      !>                In order for a meaningful progress report to be
      !>                displayed, IVBEG and IVEND must satisfy the following
      !>                constraints:
      !>
      !>                 - IVBEG must be less than or equal to IVEND.
      !>
      !>                 - The interval [ IVBEG, IVEND ] must be contained in
      !>                   some interval of the confinement window. It can be
      !>                   a proper subset of the containing interval; that
      !>                   is, it can be smaller than the interval of the
      !>                   confinement window that contains it.
      !>
      !>                 - Over a search, the sum of the differences
      !>
      !>                      IVEND - IVBEG
      !>
      !>                   for all calls to this routine made during the search
      !>                   must equal the measure of the confinement window.
      !>
      !>                The SPICELIB routine GFREPU may be used as the
      !>                actual argument corresponding to UDREPU. If so,
      !>                the SPICELIB routines GFREPI and GFREPF must be
      !>                the actual arguments corresponding to UDREPI and
      !>                UDREPF.
      !>
      !>     UDREPF     is a user-defined subroutine that finalizes a
      !>                progress report. UDREPF has no arguments.
      !>
      !>                The SPICELIB routine GFREPF may be used as the
      !>                actual argument corresponding to UDREPF. If so,
      !>                the SPICELIB routines GFREPI and GFREPU must be
      !>                the actual arguments corresponding to UDREPI and
      !>                UDREPU.
      !>
      !>     BAIL       is a logical variable indicating whether or not
      !>                interrupt handling is enabled. When BAIL is
      !>                set to .TRUE., the input function UDBAIL (see
      !>                description below) is used to determine whether
      !>                an interrupt has been issued.
      !>
      !>     UDBAIL     is the name of a user defined logical function that
      !>                indicates whether an interrupt signal has been
      !>                issued (for example, from the keyboard).  UDBAIL
      !>                has no arguments and returns a LOGICAL value.
      !>                The return value is .TRUE. if an interrupt has
      !>                been issued; otherwise the value is .FALSE.
      !>
      !>                GFUDB uses UDBAIL only when BAIL (see above) is set
      !>                to .TRUE., indicating that interrupt handling is
      !>                enabled. When interrupt handling is enabled, GFUDB
      !>                and routines in its call tree will call UDBAIL to
      !>                determine whether to terminate processing and return
      !>                immediately.
      !>
      !>                If interrupt handing is not enabled, a logical
      !>                function must still be passed to GFUDB as
      !>                an input argument. The SPICE function
      !>
      !>                   GFBAIL
      !>
      !>                may be used for this purpose.
      !>
      !>     CNFINE     is a SPICE window that confines the time period over
      !>                which the specified search is conducted. CNFINE may
      !>                consist of a single interval or a collection of
      !>                intervals.
      !>
      !>                The endpoints of the time intervals comprising CNFINE
      !>                are interpreted as seconds past J2000 TDB.
      !>
      !>                See the Examples section below for a code example
      !>                that shows how to create a confinement window.
      !>
      !>                CNFINE must be initialized by the caller via the
      !>                SPICELIB routine SSIZED.
      !>
      !>## Detailed Output
      !>
      !>     RESULT     is a SPICE window representing the set of time
      !>                intervals, within the confinement period, when the
      !>                specified boolean function has a value true.
      !>
      !>                The endpoints of the time intervals comprising RESULT
      !>                are interpreted as seconds past J2000 TDB.
      !>
      !>                If RESULT is non-empty on input, its contents
      !>                will be discarded before GFUDB conducts its
      !>                search.
      !>
      !>## Parameters
      !>
      !>     LBCELL     is the SPICELIB cell lower bound.
      !>
      !>## Exceptions
      !>
      !>     1)  SPICE(INVALIDTOLERANCE) will signal if the convergence
      !>         tolerance value is non-positive.
      !>
      !>## Files
      !>
      !>     Appropriate kernels must be loaded by the calling program before
      !>     this routine is called.
      !>
      !>     If the boolean function requires access to ephemeris data:
      !>
      !>        - SPK data: ephemeris data for any body over the
      !>          time period defined by the confinement window must be
      !>          loaded. If aberration corrections are used, the states of
      !>          target and observer relative to the solar system barycenter
      !>          must be calculable from the available ephemeris data.
      !>          Typically ephemeris data are made available by loading one
      !>          or more SPK files via FURNSH.
      !>
      !>        - If non-inertial reference frames are used, then PCK
      !>          files, frame kernels, C-kernels, and SCLK kernels may be
      !>          needed.
      !>
      !>     In all cases, kernel data are normally loaded once per program
      !>     run, NOT every time this routine is called.
      !>
      !>## Particulars
      !>
      !>     This routine provides the SPICE GF system's most flexible
      !>     interface for searching for boolean events based on a user
      !>     defined boolean function.
      !>
      !>     Applications that do not require support for progress
      !>     reporting, interrupt handling, non-default step refinement
      !>     functions, or non-default convergence tolerance normally should
      !>     call GFUDB rather than this routine.
      !>
      !>     This routine determines a set of one or more time intervals
      !>     within the confinement window when the boolean function
      !>     satisfies a caller-specified constraint. The resulting set of
      !>     intervals is returned as a SPICE window.
      !>
      !>     Below we discuss in greater detail aspects of this routine's
      !>     solution process that are relevant to correct and efficient
      !>     use of this routine in user applications.
      !>
      !>     The Search Process
      !>     ==================
      !>
      !>     The search for boolean events is treated as a search for state
      !>     transitions: times are sought when the boolean function value
      !>     changes from true to false or vice versa.
      !>
      !>     Step Size
      !>     =========
      !>
      !>     Each interval of the confinement window is searched as follows:
      !>     first, the input step size is used to determine the time
      !>     separation at which the boolean function will be sampled.
      !>     Starting at the left endpoint of the interval, samples of the
      !>     boolean function will be taken at each step. If a state change
      !>     is detected, a root has been bracketed; at that point, the
      !>     "root"--the time at which the state change occurs---is found by a
      !>     refinement process, for example, via binary search.
      !>
      !>     Note that the optimal choice of step size depends on the lengths
      !>     of the intervals over which the boolean function is constant:
      !>     the step size should be shorter than the shortest such interval
      !>     and the shortest separation between the intervals, within
      !>     the confinement window.
      !>
      !>     Having some knowledge of the relative geometry of the targets and
      !>     observer can be a valuable aid in picking a reasonable step size.
      !>     In general, the user can compensate for lack of such knowledge by
      !>     picking a very short step size; the cost is increased computation
      !>     time.
      !>
      !>     Note that the step size is not related to the precision with which
      !>     the endpoints of the intervals of the result window are computed.
      !>     That precision level is controlled by the convergence tolerance.
      !>
      !>     Convergence Tolerance
      !>     =====================
      !>
      !>     Once a root has been bracketed, a refinement process is used to
      !>     narrow down the time interval within which the root must lie.
      !>     This refinement process terminates when the location of the root
      !>     has been determined to within an error margin called the
      !>     "convergence tolerance." The default convergence tolerance
      !>     used by this routine is set by the parameter CNVTOL (defined
      !>     in gf.inc).
      !>
      !>     The value of CNVTOL is set to a "tight" value so that the
      !>     tolerance doesn't become the limiting factor in the accuracy of
      !>     solutions found by this routine. In general the accuracy of input
      !>     data will be the limiting factor.
      !>
      !>     The user may change the convergence tolerance from the default
      !>     CNVTOL value by calling the routine GFSTOL, e.g.
      !>
      !>        CALL GFSTOL( tolerance value )
      !>
      !>     Call GFSTOL prior to calling this routine. All subsequent
      !>     searches will use the updated tolerance value.
      !>
      !>     Setting the tolerance tighter than CNVTOL is unlikely to be
      !>     useful, since the results are unlikely to be more accurate.
      !>     Making the tolerance looser will speed up searches somewhat,
      !>     since a few convergence steps will be omitted. However, in most
      !>     cases, the step size is likely to have a much greater effect
      !>     on processing time than would the convergence tolerance.
      !>
      !>     The Confinement Window
      !>     ======================
      !>
      !>     The simplest use of the confinement window is to specify a time
      !>     interval within which a solution is sought.
      !>
      !>     The confinement window also can be used to restrict a search to
      !>     a time window over which required data are known to be
      !>     available.
      !>
      !>     In some cases, the confinement window be used to make searches
      !>     more efficient. Sometimes it's possible to do an efficient search
      !>     to reduce the size of the time period over which a relatively
      !>     slow search of interest must be performed. See the "CASCADE"
      !>     example program in gf.req for a demonstration.
      !>
      !>## Examples
      !>
      !>    Refer to GFUDB.
      !>
      !>## Restrictions
      !>
      !>     1) Any kernel files required by this routine must be loaded
      !>        (normally via the SPICELIB routine FURNSH) before this routine
      !>        is called.
      !>
      !>## Literature References
      !>
      !>    None.
      !>
      !>## Author and Institution
      !>
      !>    N.J. Bachman   (JPL)
      !>    E.D. Wright    (JPL)
      !>
      !>## Version
      !>
      !>-   SPICELIB Version 1.0.0  17-OCT-2013 (EDW)
      !>
      !>       Logic and implementation based on GFOCCE by Nat Bachman.
      module subroutine zzgfudb ( ctx, udfuns, udfunb, tol, udstep, udrefn, rpt, udrepi, udrepu, &
            udrepf, bail, udbail, cnfine, result )
      use pepper_kinds, only: ip, wp
      use pepper_inc_gf
      implicit none


!
!     STEP is a step size initializer for the unused, dummy step size
!     argument to ZZGFSOLVX. The routine UDSTEP, which is passed to
!     ZZGFSOLVX, will be used by that routine to obtain the step size.
!
      real(wp), parameter :: step = 1.0_wp

!
!     CSTEP indicates whether a constant step size, provided
!     via the input argument STEP, is to be used by ZZGFSOLVX.
!
      logical, parameter :: cstep = .false.

      real(wp) :: finish
      real(wp) :: start

      integer(ip) :: count
      integer(ip) :: i
      class(pepper_context), intent(inout) :: ctx  !! the context
      real(wp), intent(in) :: tol  !! Convergence tolerance in seconds.
      logical, intent(in) :: rpt  !! Progress report flag.
      logical, intent(in) :: bail  !! Logical indicating program interrupt monitoring.
      procedure(gf_bail) :: udbail  !! Name of a routine that signals a program interrupt.
      real(wp), intent(in) :: cnfine ( lbcell : * )  !! SPICE window to which the search is restricted.
      real(wp), intent(inout) :: result ( lbcell : * )  !! SPICE window containing results.
      procedure(gf_scalar) :: udfuns  !! Name of the routine that computes a scalar quantity of interest.
      procedure(gf_boolean) :: udfunb  !! Name of the routine that computes the boolean value of interest.
      procedure(gf_step) :: udstep  !! Name of the routine that returns a time step.
      procedure(gf_refine) :: udrefn  !! Name of the routine that computes a refined time.
      procedure(gf_rep_init) :: udrepi  !! Function that initializes progress reporting.
      procedure(gf_rep_update) :: udrepu  !! Function that updates the progress report.
      procedure(gf_rep_final) :: udrepf  !! Function that finalizes progress reporting.

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Check the convergence tolerance.
!
      if ( tol <= 0.0_wp ) then

         call ctx%setmsg ( 'Tolerance must be positive but was #.' )
         call ctx%errdp  ( '#',  tol                               )
         call ctx%sigerr ( 'SPICE(INVALIDTOLERANCE)'               )
         return

      end if

!
!     Prepare the progress reporter if appropriate.
!
      if ( rpt ) then
         call udrepi ( ctx, cnfine, 'User defined boolean event search ', &
                               'done.' )
      end if

!
!     Cycle over the intervals in the confining window.
!
      count = wncard( ctx,cnfine)

      do i = 1, count

!
!        Retrieve the bounds for the Ith interval of the confinement
!        window. Search this interval for boolean events. Union the
!        result with the contents of the RESULT window.
!
         call wnfetd ( ctx, cnfine, i, start, finish )

!
!        Call ZZGFSOLVX to do the event detection work. The boolean
!        function passes as UDFUNB, the scalar as UDFUNS.
!

         call zzgfsolvx ( ctx, udfuns, udfunb, &
                          udstep, udrefn, &
                          bail,   udbail, &
                          cstep,  step, &
                          start,  finish, &
                          tol, &
                          rpt,    udrepu, &
                          result )

         if ( ctx%failed() ) return

         if ( bail ) then
!
!           Interrupt handling is enabled.
!
            if ( udbail ( ctx ) ) then
!
!              An interrupt has been issued. Return now regardless of
!              whether the search completed.
!
               return

            end if

         end if

      end do

!
!     End the progress report.
!
      if ( rpt ) then
         call udrepf ( ctx )
      end if

      return
      end subroutine zzgfudb

      !> Determine time intervals when an observer sees one target body
      !> occulted by, or in transit across, another.
      !>
      !> The surfaces of the target bodies may be represented by triaxial
      !> ellipsoids or by topographic data provided by DSK files.
      !>
      !>## Detailed Input
      !>
      !>     OCCTYP   indicates the type of occultation that is to be found.
      !>              Note that transits are considered to be a type of
      !>              occultation.
      !>
      !>              Supported values and corresponding definitions are:
      !>
      !>                 'FULL'      denotes the full occultation of the
      !>                             body designated by BACK by the body
      !>                             designated by FRONT, as seen from the
      !>                             location of the observer. In other
      !>                             words, the occulted body is completely
      !>                             invisible as seen from the observer's
      !>                             location.
      !>
      !>                 'ANNULAR'   denotes an annular occultation: the
      !>                             body designated by FRONT blocks part
      !>                             of, but not the limb of, the body
      !>                             designated by BACK, as seen from the
      !>                             location of the observer.
      !>
      !>                 'PARTIAL'   denotes a partial, non-annular
      !>                             occultation: the body designated by
      !>                             FRONT blocks part, but not all, of the
      !>                             limb of the body designated by BACK, as
      !>                             seen from the location of the observer.
      !>
      !>                 'ANY'       denotes any of the above three types of
      !>                             occultations: 'PARTIAL', 'ANNULAR', or
      !>                             'FULL'.
      !>
      !>                             'ANY' should be used to search for
      !>                             times when the body designated by FRONT
      !>                             blocks any part of the body designated
      !>                             by BACK.
      !>
      !>                             The option 'ANY' must be used if either
      !>                             the front or back target body is
      !>                             modeled as a point.
      !>
      !>              Case and leading or trailing blanks are not
      !>              significant in the string OCCTYP.
      !>
      !>     FRONT    is the name of the target body that occults---that is,
      !>              passes in front of---the other. Optionally, you may
      !>              supply the integer NAIF ID code for the body as a
      !>              string. For example both 'MOON' and '301' are
      !>              legitimate strings that designate the Moon.
      !>
      !>              Case and leading or trailing blanks are not
      !>              significant in the string FRONT.
      !>
      !>     FSHAPE   is a string indicating the geometric model used to
      !>              represent the shape of the front target body. The
      !>              supported options are:
      !>
      !>                 'ELLIPSOID'
      !>
      !>                     Use a triaxial ellipsoid model with radius
      !>                     values provided via the kernel pool. A kernel
      !>                     variable having a name of the form
      !>
      !>                        BODYnnn_RADII
      !>
      !>                     where nnn represents the NAIF integer code
      !>                     associated with the body, must be present in
      !>                     the kernel pool. This variable must be
      !>                     associated with three numeric values giving the
      !>                     lengths of the ellipsoid's X, Y, and Z
      !>                     semi-axes.
      !>
      !>                 'POINT'
      !>
      !>                     Treat the body as a single point. When a point
      !>                     target is specified, the occultation type must
      !>                     be set to 'ANY'.
      !>
      !>                 'DSK/UNPRIORITIZED[/SURFACES = <surface list>]'
      !>
      !>                     Use topographic data provided by DSK files to
      !>                     model the body's shape. These data must be
      !>                     provided by loaded DSK files.
      !>
      !>                     The surface list specification is optional. The
      !>                     syntax of the list is
      !>
      !>                        <surface 1> [, <surface 2>...]
      !>
      !>                     If present, it indicates that data only for the
      !>                     listed surfaces are to be used; however, data
      !>                     need not be available for all surfaces in the
      !>                     list. If absent, loaded DSK data for any surface
      !>                     associated with the target body are used.
      !>
      !>                     The surface list may contain surface names or
      !>                     surface ID codes. Names containing blanks must
      !>                     be delimited by double quotes, for example
      !>
      !>                        SURFACES = "Mars MEGDR 128 PIXEL/DEG"
      !>
      !>                     If multiple surfaces are specified, their names
      !>                     or IDs must be separated by commas.
      !>
      !>                     See the $Particulars section below for details
      !>                     concerning use of DSK data.
      !>
      !>              The combinations of the shapes of the target bodies
      !>              FRONT and BACK must be one of:
      !>
      !>                 One ELLIPSOID, one POINT
      !>                 Two ELLIPSOIDs
      !>                 One DSK, one POINT
      !>
      !>              Case and leading or trailing blanks are not
      !>              significant in the string FSHAPE.
      !>
      !>     FFRAME   is the name of the body-fixed, body-centered reference
      !>              frame associated with the front target body. Examples of
      !>              such names are 'IAU_SATURN' (for Saturn) and 'ITRF93'
      !>              (for the Earth).
      !>
      !>              If the front target body is modeled as a point, FFRAME
      !>              should be left blank.
      !>
      !>              Case and leading or trailing blanks bracketing a
      !>              non-blank frame name are not significant in the string
      !>              FFRAME.
      !>
      !>     BACK     is the name of the target body that is occulted
      !>              by---that is, passes in back of---the other.
      !>              Optionally, you may supply the integer NAIF ID code
      !>              for the body as a string. For example both 'MOON' and
      !>              '301' are legitimate strings that designate the Moon.
      !>
      !>              Case and leading or trailing blanks are not
      !>              significant in the string BACK.
      !>
      !>     BSHAPE   is the shape specification for the body designated
      !>              by BACK. The supported options are those for
      !>              FSHAPE. See the description of FSHAPE above for
      !>              details.
      !>
      !>     BFRAME   is the name of the body-fixed, body-centered reference
      !>              frame associated with the ``back'' target body. Examples
      !>              of such names are 'IAU_SATURN' (for Saturn) and 'ITRF93'
      !>              (for the Earth).
      !>
      !>              If the back target body is modeled as a point, BFRAME
      !>              should be left blank.
      !>
      !>              Case and leading or trailing blanks bracketing a
      !>              non-blank frame name are not significant in the string
      !>              BFRAME.
      !>
      !>     ABCORR   indicates the aberration corrections to be applied to
      !>              the state of each target body to account for one-way
      !>              light time. Stellar aberration corrections are
      !>              ignored if specified, since these corrections don't
      !>              improve the accuracy of the occultation determination.
      !>
      !>              See the header of the SPICE routine SPKEZR for a
      !>              detailed description of the aberration correction
      !>              options. For convenience, the options supported by
      !>              this routine are listed below:
      !>
      !>                 'NONE'     Apply no correction.
      !>
      !>                 'LT'       "Reception" case: correct for
      !>                            one-way light time using a Newtonian
      !>                            formulation.
      !>
      !>                 'CN'       "Reception" case: converged
      !>                            Newtonian light time correction.
      !>
      !>                 'XLT'      "Transmission" case: correct for
      !>                            one-way light time using a Newtonian
      !>                            formulation.
      !>
      !>                 'XCN'      "Transmission" case: converged
      !>                            Newtonian light time correction.
      !>
      !>              Case and blanks are not significant in the string
      !>              ABCORR.
      !>
      !>     OBSRVR   is the name of the body from which the occultation is
      !>              observed. Optionally, you may supply the integer NAIF
      !>              ID code for the body as a string.
      !>
      !>              Case and leading or trailing blanks are not
      !>              significant in the string OBSRVR.
      !>
      !>     STEP     is the step size to be used in the search. STEP must
      !>              be shorter than any interval, within the confinement
      !>              window, over which the specified occultation condition
      !>              is met. In other words, STEP must be shorter than the
      !>              shortest occultation event that the user wishes to
      !>              detect; STEP must also be shorter than the shortest
      !>              time interval between two occultation events that
      !>              occur within the confinement window (see below).
      !>              However, STEP must not be *too* short, or the search
      !>              will take an unreasonable amount of time.
      !>
      !>              The choice of STEP affects the completeness but not
      !>              the precision of solutions found by this routine; the
      !>              precision is controlled by the convergence tolerance.
      !>              See the discussion of the parameter CNVTOL for
      !>              details.
      !>
      !>              STEP has units of TDB seconds.
      !>
      !>     CNFINE   is a SPICE window that confines the time period over
      !>              which the specified search is conducted. CNFINE may
      !>              consist of a single interval or a collection of
      !>              intervals.
      !>
      !>              The endpoints of the time intervals comprising CNFINE
      !>              are interpreted as seconds past J2000 TDB.
      !>
      !>              See the $Examples section below for a code example
      !>              that shows how to create a confinement window.
      !>
      !>              CNFINE must be initialized by the caller via the
      !>              SPICELIB routine SSIZED.
      !>
      !>     RESULT   is a double precision SPICE window which will contain
      !>              the search results. RESULT must be declared and
      !>              initialized with sufficient size to capture the full
      !>              set of time intervals within the search region on which
      !>              the specified condition is satisfied.
      !>
      !>              RESULT must be initialized by the caller via the
      !>              SPICELIB routine SSIZED.
      !>
      !>              If RESULT is non-empty on input, its contents will be
      !>              discarded before GFOCLT conducts its search.
      !>
      !>## Detailed Output
      !>
      !>     RESULT   is a SPICE window representing the set of time intervals,
      !>              within the confinement window, when the specified
      !>              occultation occurs.
      !>
      !>              The endpoints of the time intervals comprising RESULT are
      !>              interpreted as seconds past J2000 TDB.
      !>
      !>              If no times within the confinement window satisfy the
      !>              search criteria, RESULT will be returned with a
      !>              cardinality of zero.
      !>
      !>## Parameters
      !>
      !>     LBCELL   is the lower bound for SPICE cell arrays.
      !>
      !>     CNVTOL   is the convergence tolerance used for finding
      !>              endpoints of the intervals comprising the result
      !>              window. CNVTOL is used to determine when binary
      !>              searches for roots should terminate: when a root is
      !>              bracketed within an interval of length CNVTOL, the
      !>              root is considered to have been found.
      !>
      !>              The accuracy, as opposed to precision, of roots found
      !>              by this routine depends on the accuracy of the input
      !>              data. In most cases, the accuracy of solutions will be
      !>              inferior to their precision.
      !>
      !>     See INCLUDE file gf.inc for declarations and descriptions of
      !>     parameters used throughout the GF system.
      !>
      !>## Exceptions
      !>
      !>     1)  In order for this routine to produce correct results,
      !>         the step size must be appropriate for the problem at hand.
      !>         Step sizes that are too large may cause this routine to miss
      !>         roots; step sizes that are too small may cause this routine
      !>         to run unacceptably slowly and in some cases, find spurious
      !>         roots.
      !>
      !>         This routine does not diagnose invalid step sizes, except
      !>         that if the step size is non-positive, an error is signaled by
      !>         a routine in the call tree of this routine.
      !>
      !>     2)  Due to numerical errors, in particular,
      !>
      !>            - Truncation error in time values
      !>            - Finite tolerance value
      !>            - Errors in computed geometric quantities
      !>
      !>         it is *normal* for the condition of interest to not always be
      !>         satisfied near the endpoints of the intervals comprising the
      !>         result window.
      !>
      !>         The result window may need to be contracted slightly by the
      !>         caller to achieve desired results. The SPICE window routine
      !>         WNCOND can be used to contract the result window.
      !>
      !>     3)  If name of either target or the observer cannot be translated
      !>         to a NAIF ID code, an error is signaled by a routine
      !>         in the call tree of this routine.
      !>
      !>     4)  If the radii of a target body modeled as an ellipsoid cannot
      !>         be determined by searching the kernel pool for a kernel
      !>         variable having a name of the form
      !>
      !>            'BODYnnn_RADII'
      !>
      !>         where nnn represents the NAIF integer code associated with
      !>         the body, an error is signaled by a routine in the
      !>         call tree of this routine.
      !>
      !>     5)  If either of the target bodies FRONT or BACK coincides with
      !>         the observer body OBSRVR, an error is signaled by a
      !>         routine in the call tree of this routine.
      !>
      !>     6)  If the body designated by FRONT coincides with that
      !>         designated by BACK, an error is signaled by a routine
      !>         in the call tree of this routine.
      !>
      !>     7)  If either of the body model specifiers FSHAPE or BSHAPE
      !>         is not recognized, an error is signaled by a routine
      !>         in the call tree of this routine.
      !>
      !>     8)  If both of the body model specifiers FSHAPE and BSHAPE
      !>         specify point targets, an error is signaled by a
      !>         routine in the call tree of this routine.
      !>
      !>     9)  If one of the body model specifiers FSHAPE and BSHAPE
      !>         specifies a DSK model, and the other argument does not
      !>         specify a point target, an error is signaled by a routine in
      !>         the call tree of this routine.
      !>
      !>     10) If a target body-fixed reference frame associated with a
      !>         non-point target is not recognized, an error is signaled by a
      !>         routine in the call tree of this routine.
      !>
      !>     11) If a target body-fixed reference frame is not centered at the
      !>         corresponding target body, an error is signaled by a routine
      !>         in the call tree of this routine.
      !>
      !>     12) If the loaded kernels provide insufficient data to compute any
      !>         required state vector, an error is signaled by a routine in
      !>         the call tree of this routine.
      !>
      !>     13) If an error occurs while reading an SPK or other kernel file,
      !>         the error is signaled by a routine in the call tree
      !>         of this routine.
      !>
      !>     14) If a point target is specified and the occultation type is set
      !>         to a valid value other than 'ANY', an error is signaled by a
      !>         routine in the call tree of this routine.
      !>
      !>     15) If the output SPICE window RESULT has size less than 2, the
      !>         error SPICE(WINDOWTOOSMALL) is signaled.
      !>
      !>     16) If the output SPICE window RESULT has insufficient capacity
      !>         to contain the number of intervals on which the specified
      !>         occultation condition is met, an error is signaled
      !>         by a routine in the call tree of this routine.
      !>
      !>     17) If the occultation type OCCTYP is invalid, an error is
      !>         signaled by a routine in the call tree of this routine.
      !>
      !>     18) If the aberration correction specification ABCORR is invalid,
      !>         an error is signaled by a routine in the call tree of this
      !>         routine.
      !>
      !>     19) If either FSHAPE or BSHAPE specifies that the target surface
      !>         is represented by DSK data, and no DSK files are loaded for
      !>         the specified target, an error is signaled by a routine in
      !>         the call tree of this routine.
      !>
      !>     20) If either FSHAPE or BSHAPE specifies that the target surface
      !>         is represented by DSK data, but the shape specification is
      !>         invalid, an error is signaled by a routine in the call tree
      !>         of this routine.
      !>
      !>## Files
      !>
      !>     Appropriate SPICE kernels must be loaded by the calling program
      !>     before this routine is called.
      !>
      !>     The following data are required:
      !>
      !>     -  SPK data: the calling application must load ephemeris data
      !>        for the targets, source and observer that cover the time
      !>        period specified by the window CNFINE. If aberration
      !>        corrections are used, the states of the target bodies and of
      !>        the observer relative to the solar system barycenter must be
      !>        calculable from the available ephemeris data. Typically
      !>        ephemeris data are made available by loading one or more SPK
      !>        files via FURNSH.
      !>
      !>     -  PCK data: bodies modeled as triaxial ellipsoids must have
      !>        semi-axis lengths provided by variables in the kernel pool.
      !>        Typically these data are made available by loading a text
      !>        PCK file via FURNSH.
      !>
      !>     -  FK data: if either of the reference frames designated by
      !>        BFRAME or FFRAME are not built in to the SPICE system,
      !>        one or more FKs specifying these frames must be loaded.
      !>
      !>     The following data may be required:
      !>
      !>     -  DSK data: if either FSHAPE or BSHAPE indicates that DSK
      !>        data are to be used, DSK files containing topographic data
      !>        for the target body must be loaded. If a surface list is
      !>        specified, data for at least one of the listed surfaces must
      !>        be loaded.
      !>
      !>     -  Surface name-ID associations: if surface names are specified
      !>        in FSHAPE or BSHAPE, the association of these names with
      !>        their corresponding surface ID codes must be established by
      !>        assignments of the kernel variables
      !>
      !>           NAIF_SURFACE_NAME
      !>           NAIF_SURFACE_CODE
      !>           NAIF_SURFACE_BODY
      !>
      !>        Normally these associations are made by loading a text
      !>        kernel containing the necessary assignments. An example
      !>        of such a set of assignments is
      !>
      !>           NAIF_SURFACE_NAME += 'Mars MEGDR 128 PIXEL/DEG'
      !>           NAIF_SURFACE_CODE += 1
      !>           NAIF_SURFACE_BODY += 499
      !>
      !>     -  CK data: either of the body-fixed frames to which FFRAME or
      !>        BFRAME refer might be a CK frame. If so, at least one CK
      !>        file will be needed to permit transformation of vectors
      !>        between that frame and the J2000 frame.
      !>
      !>     -  SCLK data: if a CK file is needed, an associated SCLK
      !>        kernel is required to enable conversion between encoded SCLK
      !>        (used to time-tag CK data) and barycentric dynamical time
      !>        (TDB).
      !>
      !>     Kernel data are normally loaded once per program run, NOT every
      !>     time this routine is called.
      !>
      !>## Particulars
      !>
      !>     This routine provides a simpler, but less flexible, interface
      !>     than does the SPICELIB routine GFOCCE for conducting searches for
      !>     occultation events. Applications that require support for
      !>     progress reporting, interrupt handling, non-default step or
      !>     refinement functions, or non-default convergence tolerance should
      !>     call GFOCCE rather than this routine.
      !>
      !>     This routine determines a set of one or more time intervals
      !>     within the confinement window when a specified type of
      !>     occultation occurs. The resulting set of intervals is returned as
      !>     a SPICE window.
      !>
      !>     Below we discuss in greater detail aspects of this routine's
      !>     solution process that are relevant to correct and efficient
      !>     use of this routine in user applications.
      !>
      !>     The Search Process
      !>     ==================
      !>
      !>     The search for occultations is treated as a search for state
      !>     transitions: times are sought when the state of the BACK body
      !>     changes from "not occulted" to "occulted" or vice versa.
      !>
      !>     Step Size
      !>     =========
      !>
      !>     Each interval of the confinement window is searched as follows:
      !>     first, the input step size is used to determine the time
      !>     separation at which the occultation state will be sampled.
      !>     Starting at the left endpoint of the interval, samples of the
      !>     occultation state will be taken at each step. If a state change
      !>     is detected, a root has been bracketed; at that point, the
      !>     "root"--the time at which the state change occurs---is found by a
      !>     refinement process, for example, via binary search.
      !>
      !>     Note that the optimal choice of step size depends on the lengths
      !>     of the intervals over which the occultation state is constant:
      !>     the step size should be shorter than the shortest occultation
      !>     duration and the shortest period between occultations, within
      !>     the confinement window.
      !>
      !>     Having some knowledge of the relative geometry of the targets and
      !>     observer can be a valuable aid in picking a reasonable step size.
      !>     In general, the user can compensate for lack of such knowledge by
      !>     picking a very short step size; the cost is increased computation
      !>     time.
      !>
      !>     Note that the step size is not related to the precision with which
      !>     the endpoints of the intervals of the result window are computed.
      !>     That precision level is controlled by the convergence tolerance.
      !>
      !>     Convergence Tolerance
      !>     =====================
      !>
      !>     Once a root has been bracketed, a refinement process is used to
      !>     narrow down the time interval within which the root must lie.
      !>     This refinement process terminates when the location of the root
      !>     has been determined to within an error margin called the
      !>     "convergence tolerance." The default convergence tolerance
      !>     used by this routine is set by the parameter CNVTOL (defined
      !>     in gf.inc).
      !>
      !>     The value of CNVTOL is set to a "tight" value so that the
      !>     tolerance doesn't become the limiting factor in the accuracy of
      !>     solutions found by this routine. In general the accuracy of input
      !>     data will be the limiting factor.
      !>
      !>     The user may change the convergence tolerance from the default
      !>     CNVTOL value by calling the routine GFSTOL, e.g.
      !>
      !>        CALL GFSTOL( tolerance value )
      !>
      !>     Call GFSTOL prior to calling this routine. All subsequent
      !>     searches will use the updated tolerance value.
      !>
      !>     Setting the tolerance tighter than CNVTOL is unlikely to be
      !>     useful, since the results are unlikely to be more accurate.
      !>     Making the tolerance looser will speed up searches somewhat,
      !>     since a few convergence steps will be omitted. However, in most
      !>     cases, the step size is likely to have a much greater effect
      !>     on processing time than would the convergence tolerance.
      !>
      !>     The Confinement Window
      !>     ======================
      !>
      !>     The simplest use of the confinement window is to specify a time
      !>     interval within which a solution is sought.
      !>
      !>     The confinement window also can be used to restrict a search to
      !>     a time window over which required data (typically ephemeris
      !>     data, in the case of occultation searches) are known to be
      !>     available.
      !>
      !>     In some cases, the confinement window be used to make searches
      !>     more efficient. Sometimes it's possible to do an efficient search
      !>     to reduce the size of the time period over which a relatively
      !>     slow search of interest must be performed. See the "CASCADE"
      !>     example program in gf.req for a demonstration.
      !>
      !>     Using DSK data
      !>     ==============
      !>
      !>        DSK loading and unloading
      !>        -------------------------
      !>
      !>        DSK files providing data used by this routine are loaded by
      !>        calling FURNSH and can be unloaded by calling UNLOAD or
      !>        KCLEAR. See the documentation of FURNSH for limits on numbers
      !>        of loaded DSK files.
      !>
      !>        For run-time efficiency, it's desirable to avoid frequent
      !>        loading and unloading of DSK files. When there is a reason to
      !>        use multiple versions of data for a given target body---for
      !>        example, if topographic data at varying resolutions are to be
      !>        used---the surface list can be used to select DSK data to be
      !>        used for a given computation. It is not necessary to unload
      !>        the data that are not to be used. This recommendation presumes
      !>        that DSKs containing different versions of surface data for a
      !>        given body have different surface ID codes.
      !>
      !>        DSK data priority
      !>        -----------------
      !>
      !>        A DSK coverage overlap occurs when two segments in loaded DSK
      !>        files cover part or all of the same domain---for example, a
      !>        given longitude-latitude rectangle---and when the time
      !>        intervals of the segments overlap as well.
      !>
      !>        When DSK data selection is prioritized, in case of a coverage
      !>        overlap, if the two competing segments are in different DSK
      !>        files, the segment in the DSK file loaded last takes
      !>        precedence. If the two segments are in the same file, the
      !>        segment located closer to the end of the file takes
      !>        precedence.
      !>
      !>        When DSK data selection is unprioritized, data from competing
      !>        segments are combined. For example, if two competing segments
      !>        both represent a surface as sets of triangular plates, the
      !>        union of those sets of plates is considered to represent the
      !>        surface.
      !>
      !>        Currently only unprioritized data selection is supported.
      !>        Because prioritized data selection may be the default behavior
      !>        in a later version of the routine, the UNPRIORITIZED keyword is
      !>        required in the FSHAPE and BSHAPE arguments.
      !>
      !>        Syntax of the shape input arguments for the DSK case
      !>        ----------------------------------------------------
      !>
      !>        The keywords and surface list in the target shape arguments
      !>        FSHAPE and BSHAPE, when DSK shape models are specified, are
      !>        called "clauses." The clauses may appear in any order, for
      !>        example
      !>
      !>           DSK/<surface list>/UNPRIORITIZED
      !>           DSK/UNPRIORITIZED/<surface list>
      !>           UNPRIORITIZED/<surface list>/DSK
      !>
      !>        The simplest form of a target argument specifying use of
      !>        DSK data is one that lacks a surface list, for example:
      !>
      !>           'DSK/UNPRIORITIZED'
      !>
      !>        For applications in which all loaded DSK data for the target
      !>        body are for a single surface, and there are no competing
      !>        segments, the above string suffices. This is expected to be
      !>        the usual case.
      !>
      !>        When, for the specified target body, there are loaded DSK
      !>        files providing data for multiple surfaces for that body, the
      !>        surfaces to be used by this routine for a given call must be
      !>        specified in a surface list, unless data from all of the
      !>        surfaces are to be used together.
      !>
      !>        The surface list consists of the string
      !>
      !>           SURFACES =
      !>
      !>        followed by a comma-separated list of one or more surface
      !>        identifiers. The identifiers may be names or integer codes in
      !>        string format. For example, suppose we have the surface
      !>        names and corresponding ID codes shown below:
      !>
      !>           Surface Name                              ID code
      !>           ------------                              -------
      !>           'Mars MEGDR 128 PIXEL/DEG'                1
      !>           'Mars MEGDR 64 PIXEL/DEG'                 2
      !>           'Mars_MRO_HIRISE'                         3
      !>
      !>        If data for all of the above surfaces are loaded, then
      !>        data for surface 1 can be specified by either
      !>
      !>           'SURFACES = 1'
      !>
      !>        or
      !>
      !>           'SURFACES = "Mars MEGDR 128 PIXEL/DEG"'
      !>
      !>        Double quotes are used to delimit the surface name because
      !>        it contains blank characters.
      !>
      !>        To use data for surfaces 2 and 3 together, any
      !>        of the following surface lists could be used:
      !>
      !>           'SURFACES = 2, 3'
      !>
      !>           'SURFACES = "Mars MEGDR  64 PIXEL/DEG", 3'
      !>
      !>           'SURFACES = 2, Mars_MRO_HIRISE'
      !>
      !>           'SURFACES = "Mars MEGDR 64 PIXEL/DEG", Mars_MRO_HIRISE'
      !>
      !>        An example of a shape argument that could be constructed
      !>        using one of the surface lists above is
      !>
      !>          'DSK/UNPRIORITIZED/SURFACES = "Mars MEGDR 64 PIXEL/DEG", 3'
      !>
      !>## Examples
      !>
      !>     The numerical results shown for these examples may differ across
      !>     platforms. The results depend on the SPICE kernels used as
      !>     input, the compiler and supporting libraries, and the machine
      !>     specific arithmetic implementation.
      !>
      !>     1) Find occultations of the Sun by the Moon (that is, solar
      !>        eclipses) as seen from the center of the Earth over the month
      !>        December, 2001.
      !>
      !>        Use light time corrections to model apparent positions of Sun
      !>        and Moon. Stellar aberration corrections are not specified
      !>        because they don't affect occultation computations.
      !>
      !>        We select a step size of 3 minutes, which means we
      !>        ignore occultation events lasting less than 3 minutes,
      !>        if any exist.
