      !>C     Local parameters
      !>C
      !>      CHARACTER*(*)         META
      !>      PARAMETER           ( META   = 'gfoclt_ex3.tm' )
      !>
      !>      CHARACTER*(*)         TIMFMT
      !>      PARAMETER           ( TIMFMT =
      !>     .   'YYYY MON DD HR:MN:SC.###### (TDB)::TDB' )
      !>
      !>      INTEGER               MAXWIN
      !>      PARAMETER           ( MAXWIN = 2 * 100 )
      !>
      !>      INTEGER               CORLEN
      !>      PARAMETER           ( CORLEN = 10 )
      !>
      !>      INTEGER               TIMLEN
      !>      PARAMETER           ( TIMLEN = 40 )
      !>
      !>      INTEGER               BDNMLN
      !>      PARAMETER           ( BDNMLN = 36 )
      !>
      !>      INTEGER               FRNMLN
      !>      PARAMETER           ( FRNMLN = 32 )
      !>
      !>      INTEGER               SHPLEN
      !>      PARAMETER           ( SHPLEN = 100 )
      !>
      !>      INTEGER               OTYPLN
      !>      PARAMETER           ( OTYPLN = 20 )
      !>
      !>      INTEGER               LBCELL
      !>      PARAMETER           ( LBCELL = -5 )
      !>
      !>C
      !>C     Local variables
      !>C
      !>      CHARACTER*(CORLEN)    ABCORR
      !>      CHARACTER*(BDNMLN)    BACK
      !>      CHARACTER*(FRNMLN)    BFRAME
      !>      CHARACTER*(SHPLEN)    BSHAPE
      !>      CHARACTER*(BDNMLN)    FRONT
      !>      CHARACTER*(SHPLEN)    FSHAPE
      !>      CHARACTER*(FRNMLN)    FFRAME
      !>      CHARACTER*(OTYPLN)    OCCTYP
      !>      CHARACTER*(BDNMLN)    OBSRVR
      !>      CHARACTER*(TIMLEN)    WIN0
      !>      CHARACTER*(TIMLEN)    WIN1
      !>      CHARACTER*(TIMLEN)    BEGSTR
      !>      CHARACTER*(TIMLEN)    ENDSTR
      !>
      !>      DOUBLE PRECISION      CNFINE ( LBCELL : 2 )
      !>      DOUBLE PRECISION      ET0
      !>      DOUBLE PRECISION      ET1
      !>      DOUBLE PRECISION      LEFT
      !>      DOUBLE PRECISION      RESULT ( LBCELL : MAXWIN )
      !>      DOUBLE PRECISION      RIGHT
      !>      DOUBLE PRECISION      STEP
      !>
      !>      INTEGER               I
      !>      INTEGER               J
      !>      INTEGER               K
      !>
      !>C
      !>C     Saved variables
      !>C
      !>C     The confinement and result windows CNFINE and RESULT are
      !>C     saved because this practice helps to prevent stack
      !>C     overflow.
      !>C
      !>      SAVE                  CNFINE
      !>      SAVE                  RESULT
      !>
      !>C
      !>C     Load kernels.
      !>C
      !>      CALL FURNSH ( META )
      !>
      !>C
      !>C     Initialize the confinement and result windows.
      !>C
      !>      CALL SSIZED ( MAXWIN, CNFINE )
      !>      CALL SSIZED ( MAXWIN, RESULT )
      !>
      !>C
      !>C     Set the observer and aberration correction.
      !>C
      !>      OBSRVR = 'DSS-14'
      !>      ABCORR = 'CN'
      !>
      !>C
      !>C     Set the occultation type.
      !>C
      !>      OCCTYP = 'ANY'
      !>
      !>C
      !>C     Set the TDB time bounds of the confinement
      !>C     window, which is a single interval in this case.
      !>C
      !>      WIN0 = '2015 FEB 28 07:00:00 TDB'
      !>      WIN1 = '2015 FEB 28 12:00:00 TDB'
      !>
      !>      CALL STR2ET ( WIN0, ET0 )
      !>      CALL STR2ET ( WIN1, ET1 )
      !>
      !>C
      !>C     Insert the time bounds into the confinement
      !>C     window.
      !>C
      !>      CALL WNINSD ( ET0, ET1, CNFINE )
      !>
      !>C
      !>C     Select a 3-minute step. We'll ignore any occultations
      !>C     lasting less than 3 minutes. Units are TDB seconds.
      !>C
      !>      STEP = 180.D0
      !>
      !>C
      !>C     Perform both spacecraft occultation and spacecraft
      !>C     transit searches.
      !>C
      !>      WRITE (*,*) ' '
      !>
      !>      DO I = 1, 2
      !>
      !>         IF ( I .EQ. 1 ) THEN
      !>
      !>C
      !>C           Perform a spacecraft occultation search.
      !>C
      !>            FRONT  = 'MARS'
      !>            FFRAME = 'IAU_MARS'
      !>
      !>            BACK   = 'MRO'
      !>            BSHAPE = 'POINT'
      !>            BFRAME = ' '
      !>
      !>         ELSE
      !>
      !>C
      !>C           Perform a spacecraft transit search.
      !>C
      !>            FRONT  = 'MRO'
      !>            FSHAPE = 'POINT'
      !>            FFRAME = ' '
      !>
      !>            BACK   = 'MARS'
      !>            BFRAME = 'IAU_MARS'
      !>
      !>         END IF
      !>
      !>         DO J = 1, 2
      !>
      !>            IF ( J .EQ. 1 ) THEN
      !>
      !>C
      !>C              Model the planet shape as an ellipsoid.
      !>C
      !>               IF ( I .EQ. 1 ) THEN
      !>                  FSHAPE = 'ELLIPSOID'
      !>               ELSE
      !>                  BSHAPE = 'ELLIPSOID'
      !>               END IF
      !>
      !>            ELSE
      !>
      !>C
      !>C              Model the planet shape using DSK data.
      !>C
      !>               IF ( I .EQ. 1 ) THEN
      !>                  FSHAPE = 'DSK/UNPRIORITIZED'
      !>               ELSE
      !>                  BSHAPE = 'DSK/UNPRIORITIZED'
      !>               END IF
      !>
      !>            END IF
      !>
      !>C
      !>C           Perform the spacecraft occultation or
      !>C           transit search.
      !>
      !>            IF ( I .EQ. 1 ) THEN
      !>               CALL TOSTDO ( 'Using shape model '//FSHAPE     )
      !>               CALL TOSTDO ( 'Starting occultation search...' )
      !>            ELSE
      !>               CALL TOSTDO ( 'Using shape model '//BSHAPE )
      !>               CALL TOSTDO ( 'Starting transit search...' )
      !>            END IF
      !>
      !>            CALL GFOCLT ( OCCTYP,
      !>     .                    FRONT,  FSHAPE, FFRAME,
      !>     .                    BACK,   BSHAPE, BFRAME,
      !>     .                    ABCORR, OBSRVR, STEP,
      !>     .                    CNFINE, RESULT         )
      !>
      !>            IF ( WNCARD(RESULT) .EQ. 0 ) THEN
      !>
      !>               WRITE (*,*) 'No event was found.'
      !>
      !>            ELSE
      !>
      !>               DO K = 1, WNCARD(RESULT)
      !>
      !>C
      !>C                 Fetch and display each event interval.
      !>C
      !>                  CALL WNFETD ( RESULT, K, LEFT, RIGHT )
      !>
      !>                  CALL TIMOUT ( LEFT,  TIMFMT, BEGSTR )
      !>                  CALL TIMOUT ( RIGHT, TIMFMT, ENDSTR )
      !>
      !>                  WRITE (*,*) '   Interval ', K
      !>                  WRITE (*,*) '      Start time: '//BEGSTR
      !>                  WRITE (*,*) '      Stop time:  '//ENDSTR
      !>
      !>               END DO
      !>
      !>            END IF
      !>
      !>            WRITE (*,*) ' '
      !>
      !>         END DO
      !>
      !>      END DO
      !>
      !>      END
      !>```
      !>
      !>        When this program was executed on a Mac/Intel/gfortran/64-bit
      !>        platform, the output was:
      !>
      !>        Using shape model ELLIPSOID
      !>        Starting occultation search...
      !>            Interval            1
      !>               Start time: 2015 FEB 28 07:17:35.379879 (TDB)
      !>               Stop time:  2015 FEB 28 07:50:37.710284 (TDB)
      !>            Interval            2
      !>               Start time: 2015 FEB 28 09:09:46.920140 (TDB)
      !>               Stop time:  2015 FEB 28 09:42:50.497193 (TDB)
      !>            Interval            3
      !>               Start time: 2015 FEB 28 11:01:57.845730 (TDB)
      !>               Stop time:  2015 FEB 28 11:35:01.489716 (TDB)
      !>
      !>        Using shape model DSK/UNPRIORITIZED
      !>        Starting occultation search...
      !>            Interval            1
      !>               Start time: 2015 FEB 28 07:17:38.130608 (TDB)
      !>               Stop time:  2015 FEB 28 07:50:38.310802 (TDB)
      !>            Interval            2
      !>               Start time: 2015 FEB 28 09:09:50.314903 (TDB)
      !>               Stop time:  2015 FEB 28 09:42:55.369626 (TDB)
      !>            Interval            3
      !>               Start time: 2015 FEB 28 11:02:01.756296 (TDB)
      !>               Stop time:  2015 FEB 28 11:35:08.368384 (TDB)
      !>
      !>        Using shape model ELLIPSOID
      !>        Starting transit search...
      !>            Interval            1
      !>               Start time: 2015 FEB 28 08:12:21.112018 (TDB)
      !>               Stop time:  2015 FEB 28 08:45:48.401746 (TDB)
      !>            Interval            2
      !>               Start time: 2015 FEB 28 10:04:32.682324 (TDB)
      !>               Stop time:  2015 FEB 28 10:37:59.920302 (TDB)
      !>            Interval            3
      !>               Start time: 2015 FEB 28 11:56:39.757564 (TDB)
      !>               Stop time:  2015 FEB 28 12:00:00.000000 (TDB)
      !>
      !>        Using shape model DSK/UNPRIORITIZED
      !>        Starting transit search...
      !>            Interval            1
      !>               Start time: 2015 FEB 28 08:12:15.750020 (TDB)
      !>               Stop time:  2015 FEB 28 08:45:43.406870 (TDB)
      !>            Interval            2
      !>               Start time: 2015 FEB 28 10:04:29.031706 (TDB)
      !>               Stop time:  2015 FEB 28 10:37:55.565509 (TDB)
      !>            Interval            3
      !>               Start time: 2015 FEB 28 11:56:34.634642 (TDB)
      !>               Stop time:  2015 FEB 28 12:00:00.000000 (TDB)
      !>
      !>## Restrictions
      !>
      !>     1)  The kernel files to be used by GFOCLT must be loaded (normally
      !>         via the SPICELIB routine FURNSH) before GFOCLT is called.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     L.S. Elson         (JPL)
      !>     E.D. Wright        (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 2.0.1, 25-NOV-2021 (JDR) (NJB)
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>        Modified code example #2 output to comply with maximum line
      !>        length of header comments. Added SAVE statements for CNFINE and
      !>        RESULT variables in code examples.
      !>
      !>        The $Exceptions section now lists the case of the combination
      !>        of DSK and non-point target shapes.
      !>
      !>        Updated description of RESULT argument in $Brief_I/O,
      !>        $Detailed_Input and $Detailed_Output.
      !>
      !>-    SPICELIB Version 2.0.0, 29-FEB-2016 (NJB)
      !>
      !>        Header was updated. An example program demonstrating
      !>        DSK usage was added.
      !>
      !>        04-MAR-2015 (NJB)
      !>
      !>        Upgraded to support surfaces represented by DSKs.
      !>
      !>-    SPICELIB Version 1.1.0, 31-AUG-2010 (EDW)
      !>
      !>        Implemented use of ZZHOLDD to allow user to alter convergence
      !>        tolerance.
      !>
      !>        Removed the STEP > 0 error check. The GFSSTP call includes
      !>        the check.
      !>
      !>-    SPICELIB Version 1.0.0, 07-APR-2009 (NJB) (LSE) (EDW)
      module subroutine gfoclt ( ctx, occtyp, front, fshape, fframe, back, bshape, bframe, abcorr, obsrvr, step, cnfine, result )
      use pepper_kinds, only: ip, wp
      use pepper_inc_gf
      use pepper_inc_zzholdd
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), parameter :: lbcell = -5
      character(*), intent(in) :: occtyp  !! Type of occultation.
      character(*), intent(in) :: front  !! Name of body occulting the other.
      character(*), intent(in) :: fshape  !! Type of shape model used for front body.
      character(*), intent(in) :: fframe  !! Body-fixed, body-centered frame for front body.
      character(*), intent(in) :: back  !! Name of body occulted by the other.
      character(*), intent(in) :: bshape  !! Type of shape model used for back body.
      character(*), intent(in) :: bframe  !! Body-fixed, body-centered frame for back body.
      character(*), intent(in) :: abcorr  !! Aberration correction flag.
      character(*), intent(in) :: obsrvr  !! Name of the observing body.
      real(wp), intent(in) :: step  !! Step size in seconds for finding occultation events.
      real(wp), intent(in) :: cnfine ( lbcell : * )  !! SPICE window to which the search is restricted.
      real(wp), intent(inout) :: result ( lbcell : * )  !! SPICE window containing results.


!
!     Local variables.
!
      real(wp) :: tol
      logical :: ok

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Note to maintenance programmer: input exception checks
!     are delegated to GFOCCE. If the implementation of that
!     routine changes, or if this routine is modified to call
!     a different routine in place of GFOCCE, then the error
!     handling performed by GFOCCE will have to be performed
!     here or in a routine called by this routine.
!
!     Check the result window's size.
!
      if ( sized( ctx,result) < 2 ) then

         call ctx%setmsg ( 'Result window size must be at least 2 ' &
         //            'but was #.'                            )
         call ctx%errint ( '#',  sized( ctx,result)                     )
         call ctx%sigerr ( 'SPICE(WINDOWTOOSMALL)'                 )
         return

      end if

!
!     Check and set the step size.
!
      call gfsstp ( ctx, step )

!
!     Retrieve the convergence tolerance, if set.
!
      call zzholdd ( ctx, zzget, gf_tol, ok, tol )

!
!     Use the default value CNVTOL if no stored tolerance value.
!
      if ( .not. ok ) then

         tol = cnvtol

      end if

!
!     Look for solutions.
!
      call gfocce ( ctx, occtyp,  front,   fshape,  fframe, &
                    back,    bshape,  bframe,  abcorr, &
                    obsrvr,  tol,     gfstep,  gfrefn, &
                    rpt,     gfrepi,  gfrepu,  gfrepf, &
                    bail,    gfbail,  cnfine,  result )

      return
      end subroutine gfoclt

      !> Determine time intervals when a specified ray intersects the
      !> space bounded by the field-of-view (FOV) of a specified
      !> instrument.
      !>
      !>## Detailed Input
      !>
      !>     INST     indicates the name of an instrument, such as a
      !>              spacecraft-mounted framing camera, the field of view
      !>              (FOV) of which is to be used for an target intersection
      !>              search: the direction from the observer to a target
      !>              is represented by a ray, and times when the specified
      !>              ray intersects the region of space bounded by the FOV
      !>              are sought.
      !>
      !>              The position of the instrument designated by INST is
      !>              considered to coincide with that of the ephemeris
      !>              object designated by the input argument OBSRVR (see
      !>              description below).
      !>
      !>              INST must have a corresponding NAIF ID and a frame
      !>              defined, as is normally done in a frame kernel. It
      !>              must also have an associated reference frame and a FOV
      !>              shape, boresight and boundary vertices (or reference
      !>              vector and reference angles) defined, as is usually
      !>              done in an instrument kernel.
      !>
      !>              See the header of the SPICELIB routine GETFOV for a
      !>              description of the required parameters associated with
      !>              an instrument.
      !>
      !>     RAYDIR   is the direction vector associated with a ray
      !>              representing a target. The ray emanates from the
      !>              location of the ephemeris object designated by the
      !>              input argument OBSRVR and is expressed relative to the
      !>              reference frame designated by RFRAME (see descriptions
      !>              below).
      !>
      !>     RFRAME   is the name of the reference frame associated with
      !>              the input ray's direction vector RAYDIR.
      !>
      !>              Since light time corrections are not supported for
      !>              rays, the orientation of the frame is always evaluated
      !>              at the epoch associated with the observer, as opposed
      !>              to the epoch associated with the light-time corrected
      !>              position of the frame center.
      !>
      !>              Case and leading or trailing blanks bracketing a
      !>              non-blank frame name are not significant in the string
      !>              RFRAME.
      !>
      !>     ABCORR   indicates the aberration corrections to be applied
      !>              when computing the ray's direction.
      !>
      !>              The supported aberration correction options are
      !>
      !>                 'NONE'          No correction.
      !>
      !>                 'S'             Stellar aberration correction,
      !>                                 reception case.
      !>
      !>                 'XS'            Stellar aberration correction,
      !>                                 transmission case.
      !>
      !>              For detailed information, see the geometry finder
      !>              required reading, gf.req.
      !>
      !>              Case, leading and trailing blanks are not significant
      !>              in the string ABCORR.
      !>
      !>     OBSRVR   is the name of the body from which the target
      !>              represented by RAYDIR is observed. The instrument
      !>              designated by INST is treated as if it were co-located
      !>              with the observer.
      !>
      !>              Optionally, you may supply the integer NAIF ID code
      !>              for the body as a string.
      !>
      !>              Case and leading or trailing blanks are not
      !>              significant in the string OBSRVR.
      !>
      !>     STEP     is the step size to be used in the search. STEP must
      !>              be shorter than any interval, within the confinement
      !>              window, over which the specified condition is met. In
      !>              other words, STEP must be shorter than the shortest
      !>              visibility event that the user wishes to detect. STEP
      !>              also must be shorter than the minimum duration
      !>              separating any two visibility events. However, STEP
      !>              must not be *too* short, or the search will take an
      !>              unreasonable amount of time.
      !>
      !>              The choice of STEP affects the completeness but not
      !>              the precision of solutions found by this routine; the
      !>              precision is controlled by the convergence tolerance.
      !>              See the discussion of the parameter CNVTOL for
      !>              details.
      !>
      !>              STEP has units of seconds.
      !>
      !>     CNFINE   is a SPICE window that confines the time period over
      !>              which the specified search is conducted. CNFINE may
      !>              consist of a single interval or a collection of
      !>              intervals.
      !>
      !>              The endpoints of the time intervals comprising CNFINE
      !>              are interpreted as seconds past J2000 TDB.
      !>
      !>              See the $Examples section below for a code example
      !>              that shows how to create a confinement window.
      !>
      !>              CNFINE must be initialized by the caller via the
      !>              SPICELIB routine SSIZED.
      !>
      !>     RESULT   is a double precision SPICE window which will contain
      !>              the search results. RESULT must be declared and
      !>              initialized with sufficient size to capture the full
      !>              set of time intervals within the search region on which
      !>              the specified condition is satisfied.
      !>
      !>              RESULT must be initialized by the caller via the
      !>              SPICELIB routine SSIZED.
      !>
      !>              If RESULT is non-empty on input, its contents will be
      !>              discarded before GFRFOV conducts its search.
      !>
      !>## Detailed Output
      !>
      !>     RESULT   is a SPICE window representing the set of time intervals,
      !>              within the confinement period, when the input ray is
      !>              "visible"; that is, when the ray is contained in the
      !>              space bounded by the specified instrument's field of
      !>              view.
      !>
      !>              The endpoints of the time intervals comprising RESULT are
      !>              interpreted as seconds past J2000 TDB.
      !>
      !>              If no times within the confinement window satisfy the
      !>              search criteria, RESULT will be returned with a
      !>              cardinality of zero.
      !>
      !>## Parameters
      !>
      !>     LBCELL   is the lower bound for SPICE cell arrays.
      !>
      !>     CNVTOL   is the convergence tolerance used for finding
      !>              endpoints of the intervals comprising the result
      !>              window. CNVTOL is used to determine when binary
      !>              searches for roots should terminate: when a root is
      !>              bracketed within an interval of length CNVTOL; the
      !>              root is considered to have been found.
      !>
      !>              The accuracy, as opposed to precision, of roots found
      !>              by this routine depends on the accuracy of the input
      !>              data. In most cases, the accuracy of solutions will be
      !>              inferior to their precision.
      !>
      !>     MAXVRT   is the maximum number of vertices that may be used
      !>              to define the boundary of the specified instrument's
      !>              field of view.
      !>
      !>     MARGIN   is a small positive number used to constrain the
      !>              orientation of the boundary vectors of polygonal
      !>              FOVs. Such FOVs must satisfy the following constraints:
      !>
      !>                 1)  The boundary vectors must be contained within
      !>                     a right circular cone of angular radius less
      !>                     than than (pi/2) - MARGIN radians; in other
      !>                     words, there must be a vector A such that all
      !>                     boundary vectors have angular separation from
      !>                     A of less than (pi/2)-MARGIN radians.
      !>
      !>                 2)  There must be a pair of boundary vectors U, V
      !>                     such that all other boundary vectors lie in
      !>                     the same half space bounded by the plane
      !>                     containing U and V. Furthermore, all other
      !>                     boundary vectors must have orthogonal
      !>                     projections onto a specific plane normal to
      !>                     this plane (the normal plane contains the angle
      !>                     bisector defined by U and V) such that the
      !>                     projections have angular separation of at least
      !>                     2*MARGIN radians from the plane spanned by U
      !>                     and V.
      !>
      !>               MARGIN is currently set to 1.D-12.
      !>
      !>     See INCLUDE file gf.inc for declarations and descriptions of
      !>     parameters used throughout the GF system.
      !>
      !>## Exceptions
      !>
      !>     1)  In order for this routine to produce correct results,
      !>         the step size must be appropriate for the problem at hand.
      !>         Step sizes that are too large may cause this routine to miss
      !>         roots; step sizes that are too small may cause this routine
      !>         to run unacceptably slowly and in some cases, find spurious
      !>         roots.
      !>
      !>         This routine does not diagnose invalid step sizes, except that
      !>         if the step size is non-positive, an error is signaled by a
      !>         routine in the call tree of this routine.
      !>
      !>     2)  Due to numerical errors, in particular,
      !>
      !>            - Truncation error in time values
      !>            - Finite tolerance value
      !>            - Errors in computed geometric quantities
      !>
      !>         it is *normal* for the condition of interest to not always be
      !>         satisfied near the endpoints of the intervals comprising the
      !>         result window.
      !>
      !>         The result window may need to be contracted slightly by the
      !>         caller to achieve desired results. The SPICE window routine
      !>         WNCOND can be used to contract the result window.
      !>
      !>     3)  If the observer's name cannot be mapped to an ID code, an
      !>         error is signaled by a routine in the call tree of this
      !>         routine.
      !>
      !>     4)  If the aberration correction flag calls for light time
      !>         correction, an error is signaled by a routine in the call tree
      !>         of this routine.
      !>
      !>     5)  If the ray's direction vector is zero, an error is signaled by
      !>         a routine in the call tree of this routine.
      !>
      !>     6)  If the instrument name INST does not have corresponding NAIF
      !>         ID code, an error is signaled by a routine in the call
      !>         tree of this routine.
      !>
      !>     7)  If the FOV parameters of the instrument are not present in
      !>         the kernel pool, an error is signaled by a routine
      !>         in the call tree of this routine.
      !>
      !>     8)  If the FOV boundary has more than MAXVRT vertices, an error
      !>         is signaled by a routine in the call tree of this
      !>         routine.
      !>
      !>     9)  If the instrument FOV is polygonal, and this routine cannot
      !>         find a ray R emanating from the FOV vertex such that maximum
      !>         angular separation of R and any FOV boundary vector is within
      !>         the limit (pi/2)-MARGIN radians, an error is signaled
      !>         by a routine in the call tree of this routine. If the FOV
      !>         is any other shape, the same error check will be applied with
      !>         the instrument boresight vector serving the role of R.
      !>
      !>     10) If the loaded kernels provide insufficient data to compute a
      !>         requested state vector, an error is signaled by a
      !>         routine in the call tree of this routine.
      !>
      !>     11) If an error occurs while reading an SPK or other kernel file,
      !>         the error is signaled by a routine in the call tree
      !>         of this routine.
      !>
      !>     12) If the output SPICE window RESULT has size less than 2, the
      !>         error SPICE(WINDOWTOOSMALL) is signaled.
      !>
      !>     13) If the output SPICE window RESULT has insufficient capacity
      !>         to contain the number of intervals on which the specified
      !>         visibility condition is met, an error is signaled
      !>         by a routine in the call tree of this routine.
      !>
      !>## Files
      !>
      !>     Appropriate SPICE kernels must be loaded by the calling program
      !>     before this routine is called.
      !>
      !>     The following data are required:
      !>
      !>     -  SPK data: ephemeris data for the observer for the period
      !>        defined by the confinement window CNFINE must be loaded.
      !>        If aberration corrections are used, the state of the
      !>        observer relative to the solar system barycenter must be
      !>        calculable from the available ephemeris data. Typically
      !>        ephemeris data are made available by loading one or more SPK
      !>        files via FURNSH.
      !>
      !>     -  Data defining the reference frame associated with the
      !>        instrument designated by INST must be available in the kernel
      !>        pool. Additionally the name INST must be associated with an
      !>        ID code. Normally these data are  made available by loading
      !>        a frame kernel via FURNSH.
      !>
      !>     -  IK data: the kernel pool must contain data such that
      !>        the SPICELIB routine GETFOV may be called to obtain
      !>        parameters for INST. Normally such data are provided by
      !>        an IK via FURNSH.
      !>
      !>     The following data may be required:
      !>
      !>     -  CK data: if the instrument frame is fixed to a spacecraft,
      !>        at least one CK file will be needed to permit transformation
      !>        of vectors between that frame and the J2000 frame.
      !>
      !>     -  SCLK data: if a CK file is needed, an associated SCLK
      !>        kernel is required to enable conversion between encoded SCLK
      !>        (used to time-tag CK data) and barycentric dynamical time
      !>        (TDB).
      !>
      !>     -  Since the input ray direction may be expressed in any
      !>        frame, FKs, CKs, SCLK kernels, PCKs, and SPKs may be
      !>        required to map the direction to the J2000 frame.
      !>
      !>     Kernel data are normally loaded once per program run, NOT every
      !>     time this routine is called.
      !>
      !>## Particulars
      !>
      !>     This routine determines a set of one or more time intervals when
      !>     the specified ray in contained within the field of view of a
      !>     specified instrument. We'll use the term "visibility event" to
      !>     designate such an appearance. The set of time intervals resulting
      !>     from the search is returned as a SPICE window.
      !>
      !>     This routine provides a simpler, but less flexible, interface
      !>     than does the SPICELIB routine GFFOVE for conducting searches for
      !>     visibility events. Applications that require support for progress
      !>     reporting, interrupt handling, non-default step or refinement
      !>     functions, or non-default convergence tolerance should call
      !>     GFFOVE rather than this routine.
      !>
      !>     Below we discuss in greater detail aspects of this routine's
      !>     solution process that are relevant to correct and efficient use
      !>     of this routine in user applications.
      !>
      !>     The Search Process
      !>     ==================
      !>
      !>     The search for visibility events is treated as a search for state
      !>     transitions: times are sought when the state of the ray
      !>     changes from "not visible" to "visible" or vice versa.
      !>
      !>     Step Size
      !>     =========
      !>
      !>     Each interval of the confinement window is searched as follows:
      !>     first, the input step size is used to determine the time
      !>     separation at which the visibility state will be sampled.
      !>     Starting at the left endpoint of an interval, samples will be
      !>     taken at each step. If a state change is detected, a root has
      !>     been bracketed; at that point, the "root"--the time at which the
      !>     state change occurs---is found by a refinement process, for
      !>     example, via binary search.
      !>
      !>     Note that the optimal choice of step size depends on the lengths
      !>     of the intervals over which the visibility state is constant:
      !>     the step size should be shorter than the shortest visibility event
      !>     duration and the shortest period between visibility events, within
      !>     the confinement window.
      !>
      !>     Having some knowledge of the relative geometry of the ray and
      !>     observer can be a valuable aid in picking a reasonable step size.
      !>     In general, the user can compensate for lack of such knowledge by
      !>     picking a very short step size; the cost is increased computation
      !>     time.
      !>
      !>     Note that the step size is not related to the precision with which
      !>     the endpoints of the intervals of the result window are computed.
      !>     That precision level is controlled by the convergence tolerance.
      !>
      !>     Convergence Tolerance
      !>     =====================
      !>
      !>     Once a root has been bracketed, a refinement process is used to
      !>     narrow down the time interval within which the root must lie.
      !>     This refinement process terminates when the location of the root
      !>     has been determined to within an error margin called the
      !>     "convergence tolerance." The default convergence tolerance
      !>     used by this routine is set by the parameter CNVTOL (defined
      !>     in gf.inc).
      !>
      !>     The value of CNVTOL is set to a "tight" value so that the
      !>     tolerance doesn't become the limiting factor in the accuracy of
      !>     solutions found by this routine. In general the accuracy of input
      !>     data will be the limiting factor.
      !>
      !>     The user may change the convergence tolerance from the default
      !>     CNVTOL value by calling the routine GFSTOL, e.g.
      !>
      !>        CALL GFSTOL( tolerance value )
      !>
      !>     Call GFSTOL prior to calling this routine. All subsequent
      !>     searches will use the updated tolerance value.
      !>
      !>     Setting the tolerance tighter than CNVTOL is unlikely to be
      !>     useful, since the results are unlikely to be more accurate.
      !>     Making the tolerance looser will speed up searches somewhat,
      !>     since a few convergence steps will be omitted. However, in most
      !>     cases, the step size is likely to have a much greater effect
      !>     on processing time than would the convergence tolerance.
      !>
      !>     The Confinement Window
      !>     ======================
      !>
      !>     The simplest use of the confinement window is to specify a time
      !>     interval within which a solution is sought. However, the
      !>     confinement window can, in some cases, be used to make searches
      !>     more efficient. Sometimes it's possible to do an efficient search
      !>     to reduce the size of the time period over which a relatively
      !>     slow search of interest must be performed. For an example, see
      !>     the program CASCADE in the GF Example Programs chapter of the GF
      !>     Required Reading, gf.req.
      !>
      !>## Examples
      !>
      !>     The numerical results shown for this example may differ across
      !>     platforms. The results depend on the SPICE kernels used as
      !>     input, the compiler and supporting libraries, and the machine
      !>     specific arithmetic implementation.
      !>
      !>     1) This example is an extension of example #1 in the
      !>        header of
      !>
      !>           GFTFOV
      !>
      !>        The problem statement for that example is
      !>
      !>           Search for times when Saturn's satellite Phoebe is within
      !>           the FOV of the Cassini narrow angle camera
      !>           (CASSINI_ISS_NAC). To simplify the problem, restrict the
      !>           search to a short time period where continuous Cassini bus
      !>           attitude data are available.
      !>
      !>           Use a step size of 10 seconds to reduce chances of missing
      !>           short visibility events.
      !>
      !>        Here we search the same confinement window for times when a
      !>        selected background star is visible. We use the FOV of the
      !>        Cassini ISS wide angle camera (CASSINI_ISS_WAC) to enhance the
      !>        probability of viewing the star.
      !>
      !>        The star we'll use has catalog number 6000 in the Hipparcos
      !>        Catalog. The star's J2000 right ascension and declination,
      !>        proper motion, and parallax are taken from that catalog.
      !>
      !>        Use the meta-kernel shown below to load the required SPICE
      !>        kernels.
      !>
      !>           KPL/MK
      !>
      !>           File name: gfrfov_ex1.tm
      !>
      !>           This meta-kernel is intended to support operation of SPICE
      !>           example programs. The kernels shown here should not be
      !>           assumed to contain adequate or correct versions of data
      !>           required by SPICE-based user applications.
      !>
      !>           In order for an application to use this meta-kernel, the
      !>           kernels referenced here must be present in the user's
      !>           current working directory.
      !>
      !>           The names and contents of the kernels referenced
      !>           by this meta-kernel are as follows:
      !>
      !>              File name                       Contents
      !>              -----------------------------   ----------------------
      !>              naif0012.tls                    Leapseconds
      !>              041014R_SCPSE_01066_04199.bsp   CASSINI, planetary and
      !>                                              Saturn satellite
      !>                                              ephemeris
      !>              cas_v40.tf                      Cassini FK
      !>              04161_04164ra.bc                Cassini bus CK
      !>              cas00071.tsc                    Cassini SCLK kernel
      !>              cas_iss_v10.ti                  Cassini IK
      !>
      !>           \begindata
      !>
      !>              KERNELS_TO_LOAD = ( 'naif0012.tls',
      !>                                  '041014R_SCPSE_01066_04199.bsp',
      !>                                  'cas_v40.tf',
      !>                                  '04161_04164ra.bc',
      !>                                  'cas00071.tsc',
      !>                                  'cas_iss_v10.ti'            )
      !>           \begintext
      !>
      !>           End of meta-kernel
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM GFRFOV_EX1
      !>      IMPLICIT NONE
      !>
      !>C
      !>C     SPICELIB functions
      !>C
      !>      DOUBLE PRECISION      J1950
      !>      DOUBLE PRECISION      J2000
      !>      DOUBLE PRECISION      JYEAR
      !>      DOUBLE PRECISION      RPD
      !>
      !>      INTEGER               WNCARD
      !>
      !>C
      !>C     Local parameters
      !>C
      !>      CHARACTER*(*)         META
      !>      PARAMETER           ( META   = 'gfrfov_ex1.tm' )
      !>
      !>      CHARACTER*(*)         TIMFMT
      !>      PARAMETER           ( TIMFMT =
      !>     .      'YYYY-MON-DD HR:MN:SC.######::TDB' )
      !>
      !>      DOUBLE PRECISION      AU
      !>      PARAMETER           ( AU     = 149597870.693D0 )
      !>
      !>      INTEGER               LBCELL
      !>      PARAMETER           ( LBCELL = -5 )
      !>
      !>      INTEGER               MAXWIN
      !>      PARAMETER           ( MAXWIN = 10000 )
      !>
      !>      INTEGER               CORLEN
      !>      PARAMETER           ( CORLEN = 10 )
      !>
      !>      INTEGER               BDNMLN
      !>      PARAMETER           ( BDNMLN = 36 )
      !>
      !>      INTEGER               FRNMLN
      !>      PARAMETER           ( FRNMLN = 32 )
      !>
      !>      INTEGER               TIMLEN
      !>      PARAMETER           ( TIMLEN = 35 )
      !>
      !>      INTEGER               LNSIZE
      !>      PARAMETER           ( LNSIZE = 80 )
      !>
      !>C
      !>C     Local variables
      !>C
      !>      CHARACTER*(CORLEN)    ABCORR
      !>      CHARACTER*(BDNMLN)    INST
      !>      CHARACTER*(LNSIZE)    LINE
      !>      CHARACTER*(BDNMLN)    OBSRVR
      !>      CHARACTER*(FRNMLN)    RFRAME
      !>      CHARACTER*(TIMLEN)    TIMSTR ( 2 )
      !>
      !>      DOUBLE PRECISION      CNFINE ( LBCELL : 2 )
      !>      DOUBLE PRECISION      DEC
      !>      DOUBLE PRECISION      DECEPC
      !>      DOUBLE PRECISION      DECPM
      !>      DOUBLE PRECISION      DECDEG
      !>      DOUBLE PRECISION      DECDG0
      !>      DOUBLE PRECISION      DTDEC
      !>      DOUBLE PRECISION      DTRA
      !>      DOUBLE PRECISION      ENDPT  ( 2 )
      !>      DOUBLE PRECISION      ET0
      !>      DOUBLE PRECISION      ET1
      !>      DOUBLE PRECISION      LT
      !>      DOUBLE PRECISION      PARLAX
      !>      DOUBLE PRECISION      PLXDEG
      !>      DOUBLE PRECISION      POS    ( 3 )
      !>      DOUBLE PRECISION      PSTAR  ( 3 )
      !>      DOUBLE PRECISION      RA
      !>      DOUBLE PRECISION      RADEG
      !>      DOUBLE PRECISION      RADEG0
      !>      DOUBLE PRECISION      RAEPC
      !>      DOUBLE PRECISION      RAPM
      !>      DOUBLE PRECISION      RAYDIR ( 3 )
      !>      DOUBLE PRECISION      RESULT ( LBCELL : MAXWIN )
      !>      DOUBLE PRECISION      RSTAR
      !>      DOUBLE PRECISION      STEPSZ
      !>      DOUBLE PRECISION      T
      !>
      !>      INTEGER               CATNO
      !>      INTEGER               I
      !>      INTEGER               J
      !>      INTEGER               N
      !>
      !>C
      !>C     Saved variables
      !>C
      !>C     The confinement and result windows CNFINE and RESULT are
      !>C     saved because this practice helps to prevent stack
      !>C     overflow.
      !>C
      !>      SAVE                  CNFINE
      !>      SAVE                  RESULT
      !>
      !>C
      !>C     Load kernels.
      !>C
      !>      CALL FURNSH ( META )
      !>
      !>C
      !>C     Initialize windows.
      !>C
      !>      CALL SSIZED ( 2,      CNFINE )
      !>      CALL SSIZED ( MAXWIN, RESULT )
      !>
      !>C
      !>C     Insert search time interval bounds into the
      !>C     confinement window.
      !>C
      !>      CALL STR2ET ( '2004 JUN 11 06:30:00 TDB', ET0 )
      !>      CALL STR2ET ( '2004 JUN 11 12:00:00 TDB', ET1 )
      !>
      !>      CALL WNINSD ( ET0, ET1, CNFINE )
      !>
      !>C
      !>C     Initialize inputs for the search.
      !>C
      !>      INST   = 'CASSINI_ISS_WAC'
      !>
      !>C
      !>C     Create a unit direction vector pointing from
      !>c     observer to star. We'll assume the direction
      !>C     is constant during the confinement window, and
      !>C     we'll use et0 as the epoch at which to compute the
      !>C     direction from the spacecraft to the star.
      !>C
      !>C     The data below are for the star with catalog
      !>C     number 6000 in the Hipparcos catalog. Angular
      !>C     units are degrees; epochs have units of Julian
      !>C     years and have a reference epoch of J1950.
      !>C     The reference frame is J2000.
      !>C
      !>      CATNO  = 6000
      !>
      !>      PLXDEG = 0.000001056D0
      !>
      !>      RADEG0 = 19.290789927D0
      !>      RAPM   = -0.000000720D0
      !>      RAEPC  = 41.2000D0
      !>
      !>      DECDG0 =  2.015271007D0
      !>      DECPM  =  0.000001814D0
      !>      DECEPC = 41.1300D0
      !>
      !>      RFRAME = 'J2000'
      !>
      !>C
      !>C     Correct the star's direction for proper motion.
      !>C
      !>C     The argument t represents et0 as Julian years
      !>C     past J1950.
      !>C
      !>      T      =      ET0/JYEAR()
      !>     .         +  ( J2000()- J1950() ) / 365.25D0
      !>
      !>      DTRA   = T - RAEPC
      !>      DTDEC  = T - DECEPC
      !>
      !>      RADEG  = RADEG0  +  DTRA  * RAPM
      !>      DECDEG = DECDG0  +  DTDEC * DECPM
      !>
      !>      RA     = RADEG  * RPD()
      !>      DEC    = DECDEG * RPD()
      !>
      !>      CALL RADREC ( 1.D0, RA, DEC, PSTAR )
      !>
      !>C
      !>C     Correct star position for parallax applicable at
      !>C     the Cassini orbiter's position. (The parallax effect
      !>C     is negligible in this case; we're simply demonstrating
      !>C     the computation.)
      !>C
      !>      PARLAX = PLXDEG * RPD()
      !>      RSTAR  = AU / TAN(PARLAX)
      !>
      !>C
      !>C     Scale the star's direction vector by its distance from
      !>C     the solar system barycenter. Subtract off the position
      !>C     of the spacecraft relative to the solar system
      !>C     barycenter; the result is the ray's direction vector.
      !>C
      !>      CALL VSCLIP ( RSTAR, PSTAR )
      !>
      !>      CALL SPKPOS ( 'CASSINI', ET0, 'J2000',  'NONE',
      !>     .              'SOLAR SYSTEM BARYCENTER', POS,  LT )
      !>
      !>      CALL VSUB   ( PSTAR, POS, RAYDIR )
      !>
      !>C
      !>C     Correct the star direction for stellar aberration when
      !>C     we conduct the search.
      !>C
      !>      ABCORR = 'S'
      !>      OBSRVR = 'CASSINI'
      !>      STEPSZ = 10.D0
      !>
      !>      WRITE (*,*) ' '
      !>      WRITE (*,*) 'Instrument:              '//INST
      !>      WRITE (*,*) 'Star''s catalog number:  ', CATNO
      !>      WRITE (*,*) ' '
      !>
      !>C
      !>C     Perform the search.
      !>C
      !>      CALL GFRFOV ( INST,   RAYDIR, RFRAME, ABCORR,
      !>     .              OBSRVR, STEPSZ, CNFINE, RESULT )
      !>
      !>      N = WNCARD( RESULT )
      !>
      !>      IF ( N .EQ. 0 ) THEN
      !>
      !>         WRITE (*,*) 'No FOV intersection found.'
      !>
      !>      ELSE
      !>
      !>         WRITE (*, '(A)' ) '  Visibility start time (TDB)'
      !>     .    //               '           Stop time (TDB)'
      !>         WRITE (*, '(A)' ) '  ---------------------------'
      !>     .    //               '     ---------------------------'
      !>
      !>         DO I = 1, N
      !>
      !>            CALL WNFETD ( RESULT, I, ENDPT(1), ENDPT(2) )
      !>
      !>            DO J = 1, 2
      !>               CALL TIMOUT ( ENDPT(J), TIMFMT, TIMSTR(J) )
      !>            END DO
      !>
      !>            LINE( :3) = ' '
      !>            LINE(2: ) = TIMSTR(1)
      !>            LINE(34:) = TIMSTR(2)
      !>
      !>            WRITE (*,*) LINE
      !>
      !>         END DO
      !>
      !>      END IF
      !>
      !>      WRITE (*,*) ' '
      !>      END
      !>```
      !>
      !>        When this program was executed on a Mac/Intel/gfortran/64-bit
      !>        platform, the output was:
      !>
      !>         Instrument:              CASSINI_ISS_WAC
      !>         Star's catalog number:          6000
      !>
      !>          Visibility start time (TDB)           Stop time (TDB)
      !>          ---------------------------     ---------------------------
      !>          2004-JUN-11 06:30:00.000000     2004-JUN-11 12:00:00.000000
      !>
      !>        Note that the star is visible throughout the confinement
      !>        window.
      !>
      !>## Restrictions
      !>
      !>     1)  The kernel files to be used by GFRFOV must be loaded (normally
      !>         via the SPICELIB routine FURNSH) before GFRFOV is called.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     L.S. Elson         (JPL)
      !>     E.D. Wright        (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.1.1, 06-AUG-2021 (JDR)
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>        Modified code examples' output to comply with maximum line
      !>        length of header comments. Updated Example's kernels set to use
      !>        PDS archived data. Added SAVE statements for CNFINE and RESULT
      !>        variables in code example.
      !>
      !>        Updated description of RESULT argument in $Brief_I/O,
      !>        $Detailed_Input and $Detailed_Output.
      !>
      !>-    SPICELIB Version 1.1.0, 28-FEB-2012 (EDW)
      !>
      !>        Implemented use of ZZHOLDD to allow user to alter convergence
      !>        tolerance.
      !>
      !>        Removed the STEP > 0 error check. The GFSSTP call includes
      !>        the check.
      !>
      !>-    SPICELIB Version 1.0.0, 15-APR-2009 (NJB) (LSE) (EDW)
      module subroutine gfrfov ( ctx, inst, raydir, rframe, abcorr, obsrvr, step, cnfine, result )
      use pepper_kinds, only: ip, wp
      use pepper_inc_gf
      use pepper_inc_zzholdd
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), parameter :: lbcell = -5
      character(*), intent(in) :: inst  !! Name of the instrument.
      real(wp), intent(in) :: raydir ( 3 )  !! Ray's direction vector.
      character(*), intent(in) :: rframe  !! Reference frame of ray's direction vector.
      character(*), intent(in) :: abcorr  !! Aberration correction flag.
      character(*), intent(in) :: obsrvr  !! Name of the observing body.
      real(wp), intent(in) :: step  !! Step size in seconds for finding FOV events.
      real(wp), intent(in) :: cnfine ( lbcell : * )  !! SPICE window to which the search is restricted.
      real(wp), intent(inout) :: result ( lbcell : * )  !! SPICE window containing results.


      real(wp) :: tol
      logical :: ok

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Note to maintenance programmer: input exception checks
!     are delegated to GFFOVE. If the implementation of that
!     routine changes, or if this routine is modified to call
!     a different routine in place of GFFOVE, then the error
!     handling performed by GFFOVE will have to be performed
!     here or in a routine called by this routine.
!
!     Check the result window's size.
!
      if ( sized( ctx,result) < 2 ) then

         call ctx%setmsg ( 'Result window size must be at least 2 ' &
         //            'but was #.'                            )
         call ctx%errint ( '#',  sized( ctx,result)                     )
         call ctx%sigerr ( 'SPICE(WINDOWTOOSMALL)'                 )
         return

      end if

!
!     Set the step size.
!
      call gfsstp ( ctx,step)

!
!     Retrieve the convergence tolerance, if set.
!
      call zzholdd ( ctx, zzget, gf_tol, ok, tol )

!
!     Use the default value CNVTOL if no stored tolerance value.
!
      if ( .not. ok ) then

         tol = cnvtol

      end if

!
!     Look for solutions.
!
      call gffove ( ctx, inst,   ryshap, raydir, ' ',    rframe, abcorr, &
                    obsrvr, tol,    gfstep, gfrefn, rpt,    gfrepi, &
                    gfrepu, gfrepf, bail,   gfbail, cnfine, result )

      return
      end subroutine gfrfov

      !> Initialize a search progress report.
      !>
      !>## Detailed Input
      !>
      !>     WINDOW   is the name of a constraint window. This is the window
      !>              associated with some root finding activity. It is
      !>              used to determine how much total time is being searched
      !>              in order to find the events of interest.
      !>
      !>     BEGMSS   is the beginning of the progress report message written
      !>              to standard output by the GF subsystem. This output
      !>              message has the form
      !>
      !>                 BEGMSS(1:LASTNB(BEGMSS)) // ' xxx.xx% ' // ENDMSS
      !>
      !>              The total length of BEGMSS must be less than MXBEGM
      !>              characters. All characters of BEGMSS must be printable.
      !>
      !>              For example, the progress report message created by the
      !>              SPICELIB routine GFOCCE at the completion of a search is
      !>
      !>                 Occultation/transit search 100.00% done.
      !>
      !>              In this message, BEGMSS is
      !>
      !>                 'Occultation/transit search'
      !>
      !>     ENDMSS   is the last portion of the output message written to
      !>              standard output by the GF subsystem.
      !>
      !>              The total length of ENDMSS must be less than MXENDM
      !>              characters. All characters of ENDMSS must be printable.
      !>
      !>              In the progress report message created by GFOCCE at the
      !>              completion of a search, ENDMSS is
      !>
      !>                 'done.'
      !>
      !>## Detailed Output
      !>
      !>     None.
      !>
      !>## Parameters
      !>
      !>     LBCELL   is the SPICE cell lower bound.
      !>
      !>     MXBEGM,
      !>     MXENDM   are, respectively, the maximum lengths of the progress
      !>              report message prefix and suffix. See the INCLUDE file
      !>              zzgf.inc for details.
      !>
      !>## Exceptions
      !>
      !>     1)  If BEGMSS has length greater than MXBEGM characters, or if
      !>         ENDMSS has length greater than MXENDM characters, the error
      !>         SPICE(MESSAGETOOLONG) is signaled.
      !>
      !>     2)  If either BEGMSS or ENDMSS contains non-printing characters,
      !>         the error SPICE(NOTPRINTABLECHARS) is signaled.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     This entry point initializes the GF progress reporting system. It
      !>     is called by the GF root finding utilities once at the start of
      !>     each search pass. See the $Particulars section of the main
      !>     subroutine header for further details of its function.
      !>
      !>## Examples
      !>
      !>     See $Examples in GFRPRT.
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     L.S. Elson         (JPL)
      !>     B.V. Semenov       (JPL)
      !>     W.L. Taber         (JPL)
      !>     I.M. Underwood     (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.2, 27-AUG-2021 (JDR)
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>        Extended description of BEGMSS and ENDMSS arguments.
      !>
      !>-    SPICELIB Version 1.0.1, 10-FEB-2014 (BVS)
      !>
      !>        Corrected declaration of WINDOW in the $Declarations
      !>        section. Added description of LBCELL to the $Declarations,
      !>        $Brief_I/O, and $Parameters sections.
      !>
      !>-    SPICELIB Version 1.0.0, 21-FEB-2009 (NJB) (LSE) (WLT) (IMU)
      module subroutine gfrepi ( ctx, window, begmss, endmss )
      use pepper_kinds, only: ip, wp
      use pepper_inc_zzgf
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), parameter :: lbcell = -5
      real(wp), intent(in) :: window ( lbcell : * )  !! A window over which a job is to be performed.
      character(*), intent(in) :: begmss  !! Beginning of the text portion of output message.
      character(*), intent(in) :: endmss  !! End of the text portion of output message.
      integer(ip), parameter :: fprint = 32
      integer(ip), parameter :: lprint = 126
      character(mxbegm) :: begin
      character(mxendm) :: end
      real(wp) :: ave
      real(wp) :: freq
      real(wp) :: incr
      real(wp) :: measur
      real(wp) :: stddev
      real(wp) :: total
      integer(ip) :: chrcod
      integer(ip) :: i
      integer(ip) :: long
      integer(ip) :: short
      integer(ip) :: unit
      if ( .not. allocated ( ctx%gfrprt_state ) ) allocate ( ctx%gfrprt_state )
      associate ( copyb => ctx%gfrprt_state%copyb, &
                  copye => ctx%gfrprt_state%copye, &
                  t0 => ctx%gfrprt_state%t0, &
                  remain => ctx%gfrprt_state%remain )
      if ( ctx%failed() ) return

!
!     Check to see if either the message prefix or suffix
!     is too long.
!
      if ( len_trim(begmss) > mxbegm ) then

         call ctx%setmsg ( 'Progress report prefix message contains ' &
         //            '# characters; limit is #.'                 )
         call ctx%errint ( '#', len_trim(begmss)                         )
         call ctx%errint ( '#', mxbegm                                 )
         call ctx%sigerr ( 'SPICE(MESSAGETOOLONG)'                     )
         return

      end if

      if ( len_trim(endmss) > mxendm ) then

         call ctx%setmsg ( 'Progress report suffix message contains ' &
         //            '# characters; limit is #.'                 )
         call ctx%errint ( '#', len_trim(endmss)                         )
         call ctx%errint ( '#', mxendm                                 )
         call ctx%sigerr ( 'SPICE(MESSAGETOOLONG)'                     )
         return

      end if

!
!     Now check that all the characters in the message prefix and
!     suffix can be printed.
!
      do i = 1, len_trim(begmss)

         chrcod = ichar( begmss(i:i) )

         if ( ( chrcod < fprint ) .or. ( chrcod > lprint ) ) then

            call ctx%setmsg ( 'The progress report message prefix ' &
            //            'contains a nonprintable character; ' &
            //            'ASCII code is #.'                    )
            call ctx%errint ( '#', chrcod                           )
            call ctx%sigerr ( 'SPICE(NONPRINTABLECHARS)'            )
            return

         end if

      end do

      do i = 1, len_trim(endmss)

         chrcod = ichar( endmss(i:i) )

         if ( ( chrcod < fprint ) .or. ( chrcod > lprint ) ) then

            call ctx%setmsg ( 'The progress report message suffix ' &
            //            'contains a nonprintable character; ' &
            //            'ASCII code is #.'                    )
            call ctx%errint ( '#', chrcod                           )
            call ctx%sigerr ( 'SPICE(NONPRINTABLECHARS)'            )
            return

         end if

      end do

      copyb = begmss
      copye = endmss

!
!     Find the length of the window. Use that to initialize the work
!     reporter.
!
      call wnsumd   ( ctx, window, measur, ave, stddev, short, long )
      call zzgftswk ( ctx, measur, 1.0_wp,  4,   begmss, endmss )

      if ( ctx%failed() ) return

!
!     Initialize the time to the start of the confinement window.
!     The remaining amount of work in the current interval is
!     the measure of the interval.
!
      if ( cardd( ctx,window) >= 2 ) then

         t0     = window(1)
         remain = window(2) - t0

      else

         remain = 0.0_wp

      end if

      return
      end associate
      end subroutine gfrepi

      !> Tell the progress reporting system how far a search has
      !> progressed.
      !>
      !>## Detailed Input
      !>
      !>     IVBEG,
      !>     IVEND    are the bounds of an interval that is contained in some
      !>              interval belonging to the confinement window. The
      !>              confinement window is associated with some root finding
      !>              activity. It is used to determine how much total time is
      !>              being searched in order to find the events of interest.
      !>
      !>              In order for a meaningful progress report to be
      !>              displayed, IVBEG and IVEND must satisfy the following
      !>              constraints:
      !>
      !>                 - IVBEG must be less than or equal to IVEND.
      !>
      !>                 - The interval [ IVBEG, IVEND ] must be contained in
      !>                   some interval of the confinement window. It can be
      !>                   a proper subset of the containing interval; that
      !>                   is, it can be smaller than the interval of the
      !>                   confinement window that contains it.
      !>
      !>                 - Over a search pass, the sum of the differences
      !>
      !>                      IVEND - IVBEG
      !>
      !>                   for all calls to this routine made during the pass
      !>                   must equal the measure of the confinement window.
      !>
      !>     TIME     is the current time reached in the search for an event.
      !>              TIME must lie in the interval
      !>
      !>                 IVBEG : IVEND
      !>
      !>              inclusive. The input values of TIME for a given interval
      !>              need not form an increasing sequence.
      !>
      !>## Detailed Output
      !>
      !>     None. This routine does perform console I/O when progress
      !>     reporting is enabled.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If IVBEG and IVEND are in decreasing order, the error
      !>         SPICE(BADENDPOINTS) is signaled.
      !>
      !>     2)  If TIME is not in the closed interval [IVBEG, IVEND], the
      !>         error SPICE(VALUEOUTOFRANGE) is signaled.
      !>
      !>     3)  If an I/O error results from writing to standard output, the
      !>         error is signaled by a routine in the call tree of this
      !>         routine.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     This entry point is used to indicate the current progress of a
      !>     search. Using information recorded through the initialization
      !>     entry point of this routine, the progress reporting system
      !>     determines how much work has been completed and whether or not to
      !>     report it on the users screen.
      !>
      !>## Examples
      !>
      !>     See $Examples in GFRPRT.
      !>
      !>## Restrictions
      !>
      !>     1)  This routine has no way of enforcing that the input values of
      !>         IVBEG and IVEND are compatible with the input window passed to
      !>         GFREPI. Callers of this routine are responsible for ensuring
      !>         that this requirement is obeyed.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     L.S. Elson         (JPL)
      !>     B.V. Semenov       (JPL)
      !>     W.L. Taber         (JPL)
      !>     I.M. Underwood     (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.2, 27-AUG-2021 (JDR)
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>-    SPICELIB Version 1.0.1, 10-FEB-2014 (BVS)
      !>
      !>        Added declarations of IVBEG and IVEND to the $Declarations
      !>        section.
      !>
      !>-    SPICELIB Version 1.0.0, 21-FEB-2009 (NJB) (LSE) (WLT) (IMU)
      module subroutine gfrepu ( ctx, ivbeg, ivend, time )
      use pepper_kinds, only: ip, wp
      use pepper_inc_zzgf
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      real(wp), intent(in) :: ivbeg  !! Start time of work interval.
      real(wp), intent(in) :: ivend  !! End time of work interval.
      real(wp), intent(in) :: time  !! Current time being examined in the search process
      character(mxbegm) :: begin
      character(mxendm) :: end
      real(wp) :: ave
      real(wp) :: freq
      real(wp) :: incr
      real(wp) :: measur
      real(wp) :: stddev
      real(wp) :: total
      integer(ip) :: chrcod
      integer(ip) :: i
      integer(ip) :: long
      integer(ip) :: short
      integer(ip) :: unit
      if ( .not. allocated ( ctx%gfrprt_state ) ) allocate ( ctx%gfrprt_state )
      associate ( t0 => ctx%gfrprt_state%t0, &
                  remain => ctx%gfrprt_state%remain )
      if ( ctx%failed() ) return

!
!     Do a few error checks before getting started.
!
!     We expect the endpoints of the current window to be in order.
!
      if ( ivend < ivbeg ) then

         call ctx%setmsg ( 'Interval endpoints are #:#; endpoints ' &
         //            'must be in increasing order.'             )
         call ctx%errdp  ( '#',  ivbeg                                )
         call ctx%errdp  ( '#',  ivend                                )
         call ctx%sigerr ( 'SPICE(BADENDPOINTS)'                      )
         return
      end if

!
!     We expect TIME to be in the current interval of the confinement
!     window.
!
      if (  ( time < ivbeg ) .or. ( time > ivend )  ) then

         call ctx%setmsg ( 'TIME should be in interval #:# but ' &
         //            'is #.'                               )
         call ctx%errdp  ( '#',  time                            )
         call ctx%errdp  ( '#',  ivbeg                           )
         call ctx%errdp  ( '#',  ivend                           )
         call ctx%sigerr ( 'SPICE(VALUEOUTOFRANGE)'              )
         return
      end if

!
!     The amount of work done is the difference between the current
!     time and the previous time T0, presuming both times are in
!     the current interval.  Note this work amount may be negative.
!
      if (  ( t0 >= ivbeg ) .and. ( t0 <= ivend )  ) then

         incr = time - t0

      else
!
!        T0 is in the previous interval.  The amount of work
!        done to complete processing of that interval is REMAIN.
!        The amount of work done in the current interval is
!        the difference of TIME and the left endpoint of the
!        interval.
!
         incr = remain + time - ivbeg

      end if

!
!     The remaining work is the distance from TIME to the right
!     endpoint of the current interval.
!
      remain = ivend - time

!
!     Record the current time as T0.
!
      t0  =  time

!
!     Report the work increment.
!
      call zzgfwkin ( ctx, incr )

      return
      end associate
      end subroutine gfrepu

      !> Finish a progress report.
      !>
      !>## Detailed Input
      !>
      !>     None.
      !>
      !>## Detailed Output
      !>
      !>     None. This routine does perform console I/O when progress
      !>     reporting is enabled.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If an I/O error results from writing to standard output, the
      !>         error is signaled by a routine in the call tree of this
      !>         routine.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     This entry point "finishes" a progress report, i.e. updates the
      !>     report to indicate the underlying task is 100% complete.
      !>
      !>## Examples
      !>
      !>     See $Examples in GFRPRT.
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     L.S. Elson         (JPL)
      !>     W.L. Taber         (JPL)
      !>     I.M. Underwood     (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.1, 07-APR-2021 (JDR)
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>-    SPICELIB Version 1.0.0, 21-FEB-2009 (NJB) (LSE) (WLT) (IMU)
      module subroutine gfrepf ( ctx )
      use, intrinsic :: iso_fortran_env, only: output_unit
      use pepper_kinds, only: ip, wp
      use pepper_inc_zzgf
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      character(mxbegm) :: begin
      character(mxendm) :: end
      real(wp) :: ave
      real(wp) :: freq
      real(wp) :: incr
      real(wp) :: measur
      real(wp) :: stddev
      real(wp) :: total
      integer(ip) :: chrcod
      integer(ip) :: i
      integer(ip) :: long
      integer(ip) :: short
      integer(ip) :: tcheck
      integer(ip) :: unit
      if ( .not. allocated ( ctx%gfrprt_state ) ) allocate ( ctx%gfrprt_state )
      associate ( copyb => ctx%gfrprt_state%copyb, &
                  copye => ctx%gfrprt_state%copye )
      if ( ctx%failed() ) return

      call zzgfwkad ( ctx, 0.0_wp, 1, copyb, copye )
      call zzgfwkin ( ctx, 0.0_wp )

!
!     Determine whether progress report output is currently
!     being sent to standard output. Fetch the output unit.
!
      call zzgfwkmo ( ctx, unit, total, freq, tcheck, begin, end, incr )

      if ( unit /= output_unit ) then
!
!        We're not currently writing to standard output, so we're
!        done.
!
         return

      end if

!
!     Emit a final blank line by moving the cursor down two
!     spaces.
!
!     The set of actual arguments passed here is rather funky
!     and deserves some explanation:
!
!        The first argument, calling for a leading blank line, moves
!        the cursor down so that the next blank line written won't
!        overwrite the final status message. That blank line is
!        followed with a cursor repositioning command that moves the
!        cursor to the beginning of the line that was just written. The
!        last argument, calling for another blank line, moves the
!        cursor down again. The total cursor movement is down 2 lines.
!        This results in one skipped line.
!
!     We could accomplish the same results more simply if were
!     were to use I/O statements in this routine; however, in the
!     interest of minimizing the number of places where I/O is
!     performed, we rely on ZZGFDSPS to do that job.
!
      call zzgfdsps  ( ctx, 1, ' ', 'A', 1 )

      return
      end associate
      end subroutine gfrepf

      !> Determine time intervals when a specified ephemeris object
      !> intersects the space bounded by the field-of-view (FOV) of a
      !> specified instrument.
      !>
      !>## Detailed Input
      !>
      !>     INST     indicates the name of an instrument, such as a
      !>              spacecraft-mounted framing camera, the field of view
      !>              (FOV) of which is to be used for a target intersection
      !>              search: times when the specified target intersects the
      !>              region of space corresponding to the FOV are sought.
      !>
      !>              The position of the instrument designated by INST is
      !>              considered to coincide with that of the ephemeris
      !>              object designated by the input argument OBSRVR (see
      !>              description below).
      !>
      !>              INST must have a corresponding NAIF ID and a frame
      !>              defined, as is normally done in a frame kernel. It
      !>              must also have an associated reference frame and a FOV
      !>              shape, boresight and boundary vertices (or reference
      !>              vector and reference angles) defined, as is usually
      !>              done in an instrument kernel.
      !>
      !>              See the header of the SPICELIB routine GETFOV for a
      !>              description of the required parameters associated with
      !>              an instrument.
      !>
      !>     TARGET   is the name of the target body, the appearances of
      !>              which in the specified instrument's field of view are
      !>              sought. The body must be an ephemeris object.
      !>
      !>              Optionally, you may supply the integer NAIF ID code
      !>              for the body as a string. For example both 'MOON' and
      !>              '301' are legitimate strings that designate the Moon.
      !>
      !>              Case and leading or trailing blanks are not
      !>              significant in the string TARGET.
      !>
      !>     TSHAPE   is a string indicating the geometric model used to
      !>              represent the shape of the target body. The supported
      !>              options are:
      !>
      !>                 'ELLIPSOID'     Use a triaxial ellipsoid model,
      !>                                 with radius values provided via the
      !>                                 kernel pool. A kernel variable
      !>                                 having a name of the form
      !>
      !>                                    BODYnnn_RADII
      !>
      !>                                 where nnn represents the NAIF
      !>                                 integer code associated with the
      !>                                 body, must be present in the kernel
      !>                                 pool. This variable must be
      !>                                 associated with three numeric
      !>                                 values giving the lengths of the
      !>                                 ellipsoid's X, Y, and Z semi-axes.
      !>
      !>                 'POINT'         Treat the body as a single point.
      !>
      !>              Case and leading or trailing blanks are not
      !>              significant in the string TSHAPE.
      !>
      !>     TFRAME   is the name of the body-fixed, body-centered reference
      !>              frame associated with the target body. Examples of
      !>              such names are 'IAU_SATURN' (for Saturn) and 'ITRF93'
      !>              (for the Earth).
      !>
      !>              If the target body is modeled as a point, TFRAME
      !>              is ignored and should be left blank.
      !>
      !>              Case and leading or trailing blanks bracketing a
      !>              non-blank frame name are not significant in the string
      !>              TFRAME.
      !>
      !>     ABCORR   indicates the aberration corrections to be applied
      !>              when computing the target's position and orientation.
      !>
      !>              For remote sensing applications, where the apparent
      !>              position and orientation of the target seen by the
      !>              observer are desired, normally either of the
      !>              corrections
      !>
      !>                 'LT+S'
      !>                 'CN+S'
      !>
      !>              should be used. These and the other supported options
      !>              are described below.
      !>
      !>              Supported aberration correction options for
      !>              observation (the case where radiation is received by
      !>              observer at ET) are:
      !>
      !>                 'NONE'         No correction.
      !>
      !>                 'LT'           Light time only
      !>
      !>                 'LT+S'         Light time and stellar aberration.
      !>
      !>                 'CN'           Converged Newtonian (CN) light time.
      !>
      !>                 'CN+S'         CN light time and stellar aberration.
      !>
      !>              Supported aberration correction options for
      !>              transmission (the case where radiation is emitted from
      !>              observer at ET) are:
      !>
      !>                 'XLT'          Light time only.
      !>
      !>                 'XLT+S'        Light time and stellar aberration.
      !>
      !>                 'XCN'          Converged Newtonian (CN) light time.
      !>
      !>                 'XCN+S'        CN light time and stellar aberration.
      !>
      !>              For detailed information, see the GF Required Reading,
      !>              gf.req.
      !>
      !>              Case, leading and trailing blanks are not significant
      !>              in the string ABCORR.
      !>
      !>     OBSRVR   is the name of the body from which the target is
      !>              observed. The instrument designated by INST is treated
      !>              as if it were co-located with the observer.
      !>
      !>              Optionally, you may supply the integer NAIF ID code
      !>              for the body as a string.
      !>
      !>              Case and leading or trailing blanks are not
      !>              significant in the string OBSRVR.
      !>
      !>     STEP     is the step size to be used in the search. STEP must
      !>              be shorter than any interval, within the confinement
      !>              window, over which the specified condition is met. In
      !>              other words, STEP must be shorter than the shortest
      !>              visibility event that the user wishes to detect. STEP
      !>              also must be shorter than the minimum duration
      !>              separating any two visibility events. However, STEP
      !>              must not be *too* short, or the search will take an
      !>              unreasonable amount of time.
      !>
      !>              The choice of STEP affects the completeness but not
      !>              the precision of solutions found by this routine; the
      !>              precision is controlled by the convergence tolerance.
      !>              See the discussion of the parameter CNVTOL for
      !>              details.
      !>
      !>              STEP has units of seconds.
      !>
      !>     CNFINE   is a SPICE window that confines the time period over
      !>              which the specified search is conducted. CNFINE may
      !>              consist of a single interval or a collection of
      !>              intervals.
      !>
      !>              The endpoints of the time intervals comprising CNFINE
      !>              are interpreted as seconds past J2000 TDB.
      !>
      !>              See the $Examples section below for a code example
      !>              that shows how to create a confinement window.
      !>
      !>              CNFINE must be initialized by the caller via the
      !>              SPICELIB routine SSIZED.
      !>
      !>     RESULT   is a double precision SPICE window which will contain
      !>              the search results. RESULT must be declared and
      !>              initialized with sufficient size to capture the full
      !>              set of time intervals within the search region on which
      !>              the specified condition is satisfied.
      !>
      !>              RESULT must be initialized by the caller via the
      !>              SPICELIB routine SSIZED.
      !>
      !>              If RESULT is non-empty on input, its contents will be
      !>              discarded before GFTFOV conducts its search.
      !>
      !>## Detailed Output
      !>
      !>     RESULT   is a SPICE window representing the set of time intervals,
      !>              within the confinement period, when the target body is
      !>              visible; that is, when the target body intersects the
      !>              space bounded by the specified instrument's field of
      !>              view.
      !>
      !>              The endpoints of the time intervals comprising RESULT are
      !>              interpreted as seconds past J2000 TDB.
      !>
      !>              If no times within the confinement window satisfy the
      !>              search criteria, RESULT will be returned with a
      !>              cardinality of zero.
      !>
      !>## Parameters
      !>
      !>     LBCELL   is the lower bound for SPICE cell arrays.
      !>
      !>     CNVTOL   is the convergence tolerance used for finding
      !>              endpoints of the intervals comprising the result
      !>              window. CNVTOL is used to determine when binary
      !>              searches for roots should terminate: when a root is
      !>              bracketed within an interval of length CNVTOL, the
      !>              root is considered to have been found.
      !>
      !>              The accuracy, as opposed to precision, of roots found
      !>              by this routine depends on the accuracy of the input
      !>              data. In most cases, the accuracy of solutions will be
      !>              inferior to their precision.
      !>
      !>     MAXVRT   is the maximum number of vertices that may be used
      !>              to define the boundary of the specified instrument's
      !>              field of view.
      !>
      !>     MARGIN   is a small positive number used to constrain the
      !>              orientation of the boundary vectors of polygonal
      !>              FOVs. Such FOVs must satisfy the following constraints:
      !>
      !>                 1)  The boundary vectors must be contained within
      !>                     a right circular cone of angular radius less
      !>                     than than (pi/2) - MARGIN radians; in other
      !>                     words, there must be a vector A such that all
      !>                     boundary vectors have angular separation from
      !>                     A of less than (pi/2)-MARGIN radians.
      !>
      !>                 2)  There must be a pair of boundary vectors U, V
      !>                     such that all other boundary vectors lie in
      !>                     the same half space bounded by the plane
      !>                     containing U and V. Furthermore, all other
      !>                     boundary vectors must have orthogonal
      !>                     projections onto a specific plane normal to
      !>                     this plane (the normal plane contains the angle
      !>                     bisector defined by U and V) such that the
      !>                     projections have angular separation of at least
      !>                     2*MARGIN radians from the plane spanned by U
      !>                     and V.
      !>
      !>               MARGIN is currently set to 1.D-12.
      !>
      !>     See INCLUDE file gf.inc for declarations and descriptions of
      !>     parameters used throughout the GF system.
      !>
      !>## Exceptions
      !>
      !>     1)  In order for this routine to produce correct results,
      !>         the step size must be appropriate for the problem at hand.
      !>         Step sizes that are too large may cause this routine to miss
      !>         roots; step sizes that are too small may cause this routine
      !>         to run unacceptably slowly and in some cases, find spurious
      !>         roots.
      !>
      !>         This routine does not diagnose invalid step sizes, except that
      !>         if the step size is non-positive, an error is signaled by a
      !>         routine in the call tree of this routine.
      !>
      !>     2)  Due to numerical errors, in particular,
      !>
      !>            - Truncation error in time values
      !>            - Finite tolerance value
      !>            - Errors in computed geometric quantities
      !>
      !>         it is *normal* for the condition of interest to not always be
      !>         satisfied near the endpoints of the intervals comprising the
      !>         result window.
      !>
      !>         The result window may need to be contracted slightly by the
      !>         caller to achieve desired results. The SPICE window routine
      !>         WNCOND can be used to contract the result window.
      !>
      !>     3)  If the name of either the target or observer cannot be
      !>         translated to a NAIF ID code, an error is signaled by
      !>         a routine in the call tree of this routine.
      !>
      !>     4)  If the specified aberration correction is an unrecognized
      !>         value, an error is signaled by a routine
      !>         in the call tree of this routine.
      !>
      !>     5)  If the radii of a target body modeled as an ellipsoid cannot
      !>         be determined by searching the kernel pool for a kernel
      !>         variable having a name of the form
      !>
      !>            'BODYnnn_RADII'
      !>
      !>         where nnn represents the NAIF integer code associated with
      !>         the body, an error is signaled by a routine in the
      !>         call tree of this routine.
      !>
      !>     6)  If the target body coincides with the observer body OBSRVR, an
      !>         error is signaled by a routine in the call tree of this
      !>         routine.
      !>
      !>     7)  If the body model specifier TSHAPE is invalid, an error is
      !>         signaled by either this routine or a routine in the call tree
      !>         of this routine.
      !>
      !>     8)  If a target body-fixed reference frame associated with a
      !>         non-point target is not recognized, an error is signaled by a
      !>         routine in the call tree of this routine.
      !>
      !>     9)  If a target body-fixed reference frame is not centered at the
      !>         corresponding target body, an error is signaled by a routine
      !>         in the call tree of this routine.
      !>
      !>     10) If the instrument name INST does not have corresponding NAIF
      !>         ID code, an error is signaled by a routine in the call
      !>         tree of this routine.
      !>
      !>     11) If the FOV parameters of the instrument are not present in
      !>         the kernel pool, an error is signaled by a routine
      !>         in the call tree of this routine.
      !>
      !>     12) If the FOV boundary has more than MAXVRT vertices, an error
      !>         is signaled by a routine in the call tree of this
      !>         routine.
      !>
      !>     13) If the instrument FOV is polygonal, and this routine cannot
      !>         find a ray R emanating from the FOV vertex such that maximum
      !>         angular separation of R and any FOV boundary vector is within
      !>         the limit (pi/2)-MARGIN radians, an error is signaled
      !>         by a routine in the call tree of this routine. If the FOV
      !>         is any other shape, the same error check will be applied with
      !>         the instrument boresight vector serving the role of R.
      !>
      !>     14) If the loaded kernels provide insufficient data to compute a
      !>         requested state vector, an error is signaled by a
      !>         routine in the call tree of this routine.
      !>
      !>     15) If an error occurs while reading an SPK or other kernel file,
      !>         the error is signaled by a routine in the call tree
      !>         of this routine.
      !>
      !>     16) If the output SPICE window RESULT has size less than 2, the
      !>         error SPICE(WINDOWTOOSMALL) is signaled.
      !>
      !>     17) If the output SPICE window RESULT has insufficient capacity
      !>         to contain the number of intervals on which the specified
      !>         visibility condition is met, an error is signaled
      !>         by a routine in the call tree of this routine.
      !>
      !>## Files
      !>
      !>     Appropriate SPICE kernels must be loaded by the calling program
      !>     before this routine is called.
      !>
      !>     The following data are required:
      !>
      !>     -  SPK data: ephemeris data for target and observer that
      !>        describes the ephemeris of these objects for the period
      !>        defined by the confinement window, CNFINE must be
      !>        loaded. If aberration corrections are used, the states of
      !>        target and observer relative to the solar system barycenter
      !>        must be calculable from the available ephemeris data.
      !>        Typically ephemeris data are made available by loading one
      !>        or more SPK files via FURNSH.
      !>
      !>     -  Frame data: if a frame definition is required to convert
      !>        the observer and target states to the body-fixed frame of
      !>        the target, that definition must be available in the kernel
      !>        pool. Typically the definitions of frames not already
      !>        built-in to SPICE are supplied by loading a frame kernel.
      !>
      !>        Data defining the reference frame associated with the
      !>        instrument designated by INST must be available in the
      !>        kernel pool. Additionally the name INST must be associated
      !>        with an ID code. Normally these data are  made available by
      !>        loading a frame kernel via FURNSH.
      !>
      !>     -  IK data: the kernel pool must contain data such that
      !>        the SPICELIB routine GETFOV may be called to obtain
      !>        parameters for INST. Normally such data are provided by
      !>        an IK via FURNSH.
      !>
      !>     The following data may be required:
      !>
      !>     -  PCK data: bodies modeled as triaxial ellipsoids must have
      !>        orientation data provided by variables in the kernel pool.
      !>        Typically these data are made available by loading a text
      !>        PCK file via FURNSH.
      !>
      !>        Bodies modeled as triaxial ellipsoids must have semi-axis
      !>        lengths provided by variables in the kernel pool. Typically
      !>        these data are made available by loading a text PCK file via
      !>        FURNSH.
      !>
      !>     -  CK data: if the instrument frame is fixed to a spacecraft,
      !>        at least one CK file will be needed to permit transformation
      !>        of vectors between that frame and both J2000 and the target
      !>        body-fixed frame.
      !>
      !>     -  SCLK data: if a CK file is needed, an associated SCLK
      !>        kernel is required to enable conversion between encoded SCLK
      !>        (used to time-tag CK data) and barycentric dynamical time
      !>        (TDB).
      !>
      !>     Kernel data are normally loaded once per program run, NOT every
      !>     time this routine is called.
      !>
      !>## Particulars
      !>
      !>     This routine determines a set of one or more time intervals
      !>     within the confinement window when any portion of a specified
      !>     target body appears within the field of view of a specified
      !>     instrument. We'll use the term "visibility event" to designate
      !>     such an appearance. The set of time intervals resulting from the
      !>     search is returned as a SPICE window.
      !>
      !>     This routine provides a simpler, but less flexible, interface
      !>     than does the SPICELIB routine GFFOVE for conducting searches for
      !>     visibility events. Applications that require support for progress
      !>     reporting, interrupt handling, non-default step or refinement
      !>     functions, or non-default convergence tolerance should call
      !>     GFFOVE rather than this routine.
      !>
      !>     To treat the target as a ray rather than as an ephemeris object,
      !>     use either the higher-level SPICELIB routine GFRFOV or GFFOVE.
      !>     Those routines may be used to search for times when distant
      !>     target objects such as stars are visible in an instrument FOV, as
      !>     long the direction from the observer to the target can be modeled
      !>     as a ray.
      !>
      !>     Below we discuss in greater detail aspects of this routine's
      !>     solution process that are relevant to correct and efficient use
      !>     of this routine in user applications.
      !>
      !>     The Search Process
      !>     ==================
      !>
      !>     The search for visibility events is treated as a search for state
      !>     transitions: times are sought when the state of the target body
      !>     changes from "not visible" to "visible" or vice versa.
      !>
      !>     Step Size
      !>     =========
      !>
      !>     Each interval of the confinement window is searched as follows:
      !>     first, the input step size is used to determine the time
      !>     separation at which the visibility state will be sampled.
      !>     Starting at the left endpoint of an interval, samples will be
      !>     taken at each step. If a state change is detected, a root has
      !>     been bracketed; at that point, the "root"--the time at which the
      !>     state change occurs---is found by a refinement process, for
      !>     example, via binary search.
      !>
      !>     Note that the optimal choice of step size depends on the lengths
      !>     of the intervals over which the visibility state is constant:
      !>     the step size should be shorter than the shortest visibility event
      !>     duration and the shortest period between visibility events, within
      !>     the confinement window.
      !>
      !>     Having some knowledge of the relative geometry of the target and
      !>     observer can be a valuable aid in picking a reasonable step size.
      !>     In general, the user can compensate for lack of such knowledge by
      !>     picking a very short step size; the cost is increased computation
      !>     time.
      !>
      !>     Note that the step size is not related to the precision with which
      !>     the endpoints of the intervals of the result window are computed.
      !>     That precision level is controlled by the convergence tolerance.
      !>
      !>     Convergence Tolerance
      !>     =====================
      !>
      !>     Once a root has been bracketed, a refinement process is used to
      !>     narrow down the time interval within which the root must lie.
      !>     This refinement process terminates when the location of the root
      !>     has been determined to within an error margin called the
      !>     "convergence tolerance." The default convergence tolerance
      !>     used by this routine is set by the parameter CNVTOL (defined
      !>     in gf.inc).
      !>
      !>     The value of CNVTOL is set to a "tight" value so that the
      !>     tolerance doesn't become the limiting factor in the accuracy of
      !>     solutions found by this routine. In general the accuracy of input
      !>     data will be the limiting factor.
      !>
      !>     The user may change the convergence tolerance from the default
      !>     CNVTOL value by calling the routine GFSTOL, e.g.
      !>
      !>        CALL GFSTOL( tolerance value )
      !>
      !>     Call GFSTOL prior to calling this routine. All subsequent
      !>     searches will use the updated tolerance value.
      !>
      !>     Setting the tolerance tighter than CNVTOL is unlikely to be
      !>     useful, since the results are unlikely to be more accurate.
      !>     Making the tolerance looser will speed up searches somewhat,
      !>     since a few convergence steps will be omitted. However, in most
      !>     cases, the step size is likely to have a much greater effect
      !>     on processing time than would the convergence tolerance.
      !>
      !>     The Confinement Window
      !>     ======================
      !>
      !>     The simplest use of the confinement window is to specify a time
      !>     interval within which a solution is sought. However, the
      !>     confinement window can, in some cases, be used to make searches
      !>     more efficient. Sometimes it's possible to do an efficient search
      !>     to reduce the size of the time period over which a relatively
      !>     slow search of interest must be performed. For an example, see
      !>     the program CASCADE in the GF Example Programs chapter of the GF
      !>     Required Reading, gf.req.
      !>
      !>## Examples
      !>
      !>     The numerical results shown for this example may differ across
      !>     platforms. The results depend on the SPICE kernels used as
      !>     input, the compiler and supporting libraries, and the machine
      !>     specific arithmetic implementation.
      !>
      !>     1) Search for times when Saturn's satellite Phoebe is within
      !>        the FOV of the Cassini narrow angle camera (CASSINI_ISS_NAC).
      !>        To simplify the problem, restrict the search to a short time
      !>        period where continuous Cassini bus attitude data are
      !>        available.
      !>
      !>        Use a step size of 10 seconds to reduce chances of missing
      !>        short visibility events.
      !>
      !>        Use the meta-kernel shown below to load the required SPICE
      !>        kernels.
      !>
      !>           KPL/MK
      !>
      !>           File name: gftfov_ex1.tm
      !>
      !>           This meta-kernel is intended to support operation of SPICE
      !>           example programs. The kernels shown here should not be
      !>           assumed to contain adequate or correct versions of data
      !>           required by SPICE-based user applications.
      !>
      !>           In order for an application to use this meta-kernel, the
      !>           kernels referenced here must be present in the user's
      !>           current working directory.
      !>
      !>           The names and contents of the kernels referenced
      !>           by this meta-kernel are as follows:
      !>
      !>              File name                       Contents
      !>              -----------------------------   ----------------------
      !>              naif0012.tls                    Leapseconds
      !>              pck00010.tpc                    Satellite orientation
      !>                                              and radii
      !>              041014R_SCPSE_01066_04199.bsp   CASSINI, planetary and
      !>                                              Saturn satellite
      !>                                              ephemeris
      !>              cas_v40.tf                      Cassini FK
      !>              04161_04164ra.bc                Cassini bus CK
      !>              cas00071.tsc                    Cassini SCLK kernel
      !>              cas_iss_v10.ti                  Cassini IK
      !>
      !>           \begindata
      !>
      !>              KERNELS_TO_LOAD = ( 'naif0012.tls',
      !>                                  'pck00010.tpc',
      !>                                  '041014R_SCPSE_01066_04199.bsp',
      !>                                  'cas_v40.tf',
      !>                                  '04161_04164ra.bc',
      !>                                  'cas00071.tsc',
      !>                                  'cas_iss_v10.ti'            )
      !>           \begintext
      !>
      !>           End of meta-kernel
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM GFTFOV_EX1
      !>      IMPLICIT NONE
      !>
      !>C
      !>C     SPICELIB functions
      !>C
      !>      INTEGER               WNCARD
      !>
      !>C
      !>C     Local parameters
      !>C
      !>      CHARACTER*(*)         META
      !>      PARAMETER           ( META   = 'gftfov_ex1.tm' )
      !>
      !>      CHARACTER*(*)         TIMFMT
      !>      PARAMETER           ( TIMFMT =
      !>     .      'YYYY-MON-DD HR:MN:SC.######::TDB' )
      !>
      !>      INTEGER               LBCELL
      !>      PARAMETER           ( LBCELL = -5 )
      !>
      !>      INTEGER               MAXWIN
      !>      PARAMETER           ( MAXWIN = 10000 )
      !>
      !>      INTEGER               CORLEN
      !>      PARAMETER           ( CORLEN = 10 )
      !>
      !>      INTEGER               BDNMLN
      !>      PARAMETER           ( BDNMLN = 36 )
      !>
      !>      INTEGER               FRNMLN
      !>      PARAMETER           ( FRNMLN = 32 )
      !>
      !>      INTEGER               SHPLEN
      !>      PARAMETER           ( SHPLEN = 25 )
      !>
      !>      INTEGER               TIMLEN
      !>      PARAMETER           ( TIMLEN = 35 )
      !>
      !>      INTEGER               LNSIZE
      !>      PARAMETER           ( LNSIZE = 80 )
      !>
      !>C
      !>C     Local variables
      !>C
      !>      CHARACTER*(CORLEN)    ABCORR
      !>      CHARACTER*(BDNMLN)    INST
      !>      CHARACTER*(LNSIZE)    LINE
      !>      CHARACTER*(BDNMLN)    OBSRVR
      !>      CHARACTER*(BDNMLN)    TARGET
      !>      CHARACTER*(FRNMLN)    TFRAME
      !>      CHARACTER*(TIMLEN)    TIMSTR ( 2 )
      !>      CHARACTER*(SHPLEN)    TSHAPE
      !>
      !>      DOUBLE PRECISION      CNFINE ( LBCELL : 2 )
      !>      DOUBLE PRECISION      ENDPT  ( 2 )
      !>      DOUBLE PRECISION      ET0
      !>      DOUBLE PRECISION      ET1
      !>      DOUBLE PRECISION      RESULT ( LBCELL : MAXWIN )
      !>      DOUBLE PRECISION      STEPSZ
      !>
      !>      INTEGER               I
      !>      INTEGER               J
      !>      INTEGER               N
      !>
      !>C
      !>C     Saved variables
      !>C
      !>C     The confinement and result windows CNFINE and RESULT are
      !>C     saved because this practice helps to prevent stack
      !>C     overflow.
      !>C
      !>      SAVE                  CNFINE
      !>      SAVE                  RESULT
      !>
      !>C
      !>C     Load kernels.
      !>C
      !>      CALL FURNSH ( META )
      !>
      !>C
      !>C     Initialize windows.
      !>C
      !>      CALL SSIZED ( 2,      CNFINE )
      !>      CALL SSIZED ( MAXWIN, RESULT )
      !>
      !>C
      !>C     Insert search time interval bounds into the
      !>C     confinement window.
      !>C
      !>      CALL STR2ET ( '2004 JUN 11 06:30:00 TDB', ET0 )
      !>      CALL STR2ET ( '2004 JUN 11 12:00:00 TDB', ET1 )
      !>
      !>      CALL WNINSD ( ET0, ET1, CNFINE )
      !>
      !>C
      !>C     Initialize inputs for the search.
      !>C
      !>      INST   = 'CASSINI_ISS_NAC'
      !>      TARGET = 'PHOEBE'
      !>      TSHAPE = 'ELLIPSOID'
      !>      TFRAME = 'IAU_PHOEBE'
      !>      ABCORR = 'LT+S'
      !>      OBSRVR = 'CASSINI'
      !>      STEPSZ = 10.D0
      !>
      !>      WRITE (*,*) ' '
      !>      WRITE (*,*) 'Instrument: '//INST
      !>      WRITE (*,*) 'Target:     '//TARGET
      !>      WRITE (*,*) ' '
      !>
      !>C
      !>C     Perform the search.
      !>C
      !>      CALL GFTFOV ( INST,   TARGET, TSHAPE, TFRAME,
      !>     .              ABCORR, OBSRVR, STEPSZ, CNFINE, RESULT )
      !>
      !>      N = WNCARD( RESULT )
      !>
      !>      IF ( N .EQ. 0 ) THEN
      !>
      !>         WRITE (*,*) 'No FOV intersection found.'
      !>
      !>      ELSE
      !>
      !>         WRITE (*, '(A)' ) '  Visibility start time (TDB)'
      !>     .    //               '           Stop time (TDB)'
      !>         WRITE (*, '(A)' ) '  ---------------------------'
      !>     .    //               '     ---------------------------'
      !>
      !>         DO I = 1, N
      !>
      !>            CALL WNFETD ( RESULT, I, ENDPT(1), ENDPT(2) )
      !>
      !>            DO J = 1, 2
      !>               CALL TIMOUT ( ENDPT(J), TIMFMT, TIMSTR(J) )
      !>            END DO
      !>
      !>            LINE( :3) = ' '
      !>            LINE(2: ) = TIMSTR(1)
      !>            LINE(34:) = TIMSTR(2)
      !>
      !>            WRITE (*,*) LINE
      !>
      !>         END DO
      !>
      !>      END IF
      !>
      !>      WRITE (*,*) ' '
      !>      END
      !>```
      !>
      !>        When this program was executed on a Mac/Intel/gfortran/64-bit
      !>        platform, the output was:
      !>
      !>         Instrument: CASSINI_ISS_NAC
      !>         Target:     PHOEBE
      !>
      !>          Visibility start time (TDB)           Stop time (TDB)
      !>          ---------------------------     ---------------------------
      !>          2004-JUN-11 07:35:27.066980     2004-JUN-11 08:48:03.954696
      !>          2004-JUN-11 09:02:56.580045     2004-JUN-11 09:35:04.038509
      !>          2004-JUN-11 09:49:56.476397     2004-JUN-11 10:22:04.242879
      !>          2004-JUN-11 10:36:56.283772     2004-JUN-11 11:09:04.397165
      !>          2004-JUN-11 11:23:56.020645     2004-JUN-11 11:56:04.733535
      !>
      !>## Restrictions
      !>
      !>     1)  The reference frame associated with INST must be
      !>         centered at the observer or must be inertial. No check is done
      !>         to ensure this.
      !>
      !>     2)  The kernel files to be used by GFTFOV must be loaded (normally
      !>         via the SPICELIB routine FURNSH) before GFTFOV is called.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     L.S. Elson         (JPL)
      !>     E.D. Wright        (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.1.1, 06-AUG-2021 (JDR)
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>        Modified code example's output to comply with maximum line
      !>        length of header comments. Updated Example's kernels set to use
      !>        PDS archived data. Added SAVE statements for CNFINE and RESULT
      !>        variables in code example.
      !>
      !>        Updated description of RESULT argument in $Brief_I/O,
      !>        $Detailed_Input and $Detailed_Output.
      !>
      !>-    SPICELIB Version 1.1.0, 28-FEB-2012 (EDW)
      !>
      !>        Implemented use of ZZHOLDD to allow user to alter convergence
      !>        tolerance.
      !>
      !>        Removed the STEP > 0 error check. The GFSSTP call includes
      !>        the check.
      !>
      !>-    SPICELIB Version 1.0.0, 15-APR-2009 (NJB) (LSE) (EDW)
      module subroutine gftfov ( ctx, inst, target, tshape, tframe, abcorr, obsrvr, step, cnfine, result )
      use pepper_kinds, only: ip, wp
      use pepper_strings, only: eqstr
      use pepper_inc_gf
      use pepper_inc_zzholdd
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), parameter :: lbcell = -5
      character(*), intent(in) :: inst  !! Name of the instrument.
      character(*), intent(in) :: target  !! Name of the target body.
      character(*), intent(in) :: tshape  !! Type of shape model used for target body.
      character(*), intent(in) :: tframe  !! Body-fixed, body-centered frame for target body.
      character(*), intent(in) :: abcorr  !! Aberration correction flag.
      character(*), intent(in) :: obsrvr  !! Name of the observing body.
      real(wp), intent(in) :: step  !! Step size in seconds for finding FOV events.
      real(wp), intent(in) :: cnfine ( lbcell : * )  !! SPICE window to which the search is restricted.
      real(wp), intent(inout) :: result ( lbcell : * )  !! SPICE window containing results.
      real(wp) :: tol
      logical :: ok
      if ( .not. allocated ( ctx%gftfov_state ) ) allocate ( ctx%gftfov_state )
      associate ( raydir => ctx%gftfov_state%raydir )
      if ( ctx%failed() ) return

!
!     Reject the target shape 'RAY'.
!
      if (  eqstr( tshape, ryshap )  ) then

         call ctx%setmsg ( 'The target shape RAY is not supported ' &
         //            'by this routine. Use the routine ' &
         //            'GFRFOV instead.'                       )
         call ctx%sigerr ( 'SPICE(INVALIDOPTION)'                  )
         return

      end if

!
!     Note to maintenance programmer: input exception checks
!     are delegated to GFFOVE. If the implementation of that
!     routine changes, or if this routine is modified to call
!     a different routine in place of GFFOVE, then the error
!     handling performed by GFFOVE will have to be performed
!     here or in a routine called by this routine.
!
!     Check the result window's size.
!
      if ( sized( ctx,result) < 2 ) then

         call ctx%setmsg ( 'Result window size must be at least 2 ' &
         //            'but was #.'                            )
         call ctx%errint ( '#',  sized( ctx,result)                     )
         call ctx%sigerr ( 'SPICE(WINDOWTOOSMALL)'                 )
         return

      end if

!
!     Set the step size.
!
      call gfsstp ( ctx,step)

!
!     Retrieve the convergence tolerance, if set.
!
      call zzholdd ( ctx, zzget, gf_tol, ok, tol )

!
!     Use the default value CNVTOL if no stored tolerance value.
!
      if ( .not. ok ) then

         tol = cnvtol

      end if

!
!     Look for solutions.
!
      call gffove ( ctx, inst,   tshape, raydir, target, tframe, abcorr, &
                    obsrvr, tol,    gfstep, gfrefn, rpt,    gfrepi, &
                    gfrepu, gfrepf, bail,   gfbail, cnfine, result )

      return
      end associate
      end subroutine gftfov

      !> Perform a GF search on a user defined boolean quantity.
      !>
      !>## Detailed Input
      !>
      !>     UDFUNS   is the routine that returns the value of the scalar
      !>              quantity of interest at time ET. The calling sequence for
      !>              UDFUNC is:
      !>
      !>                 CALL UDFUNS ( ET, VALUE )
      !>
      !>              where:
      !>
      !>                 ET      a double precision value representing
      !>                         ephemeris time, expressed as seconds past
      !>                         J2000 TDB at which to evaluate UDFUNS.
      !>
      !>                 VALUE   is the value of the scalar quantity
      !>                         at ET.
      !>
      !>     UDFUNB   is the user defined routine returning a boolean value for
      !>              an epoch ET. The calling sequence for UNFUNB is:
      !>
      !>                 CALL UDFUNB ( UDFUNS, ET, BOOL )
      !>
      !>              where:
      !>
      !>                 UDFUNS   the name of the scalar function as
      !>                          defined above.
      !>
      !>                 ET       a double precision value representing
      !>                          ephemeris time, expressed as seconds past
      !>                          J2000 TDB, at which to evaluate UDFUNB.
      !>
      !>                 BOOL     the boolean value at ET.
      !>
      !>              GFUDB will correctly operate only for boolean functions
      !>              with true conditions defining non zero measure time
      !>              intervals.
      !>
      !>              Note, UDFUNB need not call UDFUNS. The use of UDFUNS is
      !>              determined by the needs of the calculation and the user's
      !>              design.
      !>
      !>     STEP     is the step size to be used in the search. STEP must be
      !>              shorter than any interval, within the confinement window,
      !>              over which the user defined boolean function is met. In
      !>              other words, STEP must be shorter than the shortest time
      !>              interval for which the boolean function is .TRUE.; STEP
      !>              must also be shorter than the shortest time interval
      !>              between two boolean function true events occurring within
      !>              the confinement window (see below). However, STEP must
      !>              not be *too* short, or the search will take an
      !>              unreasonable amount of time.
      !>
      !>              The choice of STEP affects the completeness but not
      !>              the precision of solutions found by this routine; the
      !>              precision is controlled by the convergence tolerance.
      !>              See the discussion of the parameter CNVTOL for
      !>              details.
      !>
      !>              STEP has units of TDB seconds.
      !>
      !>     CNFINE   is a SPICE window that confines the time period over
      !>              which the specified search is conducted. CNFINE may
      !>              consist of a single interval or a collection of
      !>              intervals.
      !>
      !>              In some cases the confinement window can be used to
      !>              greatly reduce the time period that must be searched
      !>              for the desired solution. See the $Particulars section
      !>              below for further discussion.
      !>
      !>              See the $Examples section below for a code example
      !>              that shows how to create a confinement window.
      !>
      !>              CNFINE must be initialized by the caller via the
      !>              SPICELIB routine SSIZED.
      !>
      !>              Certain computations can expand the time window over
      !>              which UDFUNS and UDFUNB require data. See $Particulars
      !>              for details.
      !>
      !>     RESULT   is a double precision SPICE window which will contain
      !>              the search results. RESULT must be declared and
      !>              initialized with sufficient size to capture the full
      !>              set of time intervals within the search region on which
      !>              the specified condition is satisfied.
      !>
      !>              RESULT must be initialized by the caller via the
      !>              SPICELIB routine SSIZED.
      !>
      !>              If RESULT is non-empty on input, its contents will be
      !>              discarded before GFUDB conducts its search.
      !>
      !>## Detailed Output
      !>
      !>     RESULT   is a SPICE window containing the time intervals within
      !>              the confinement window, during which the specified
      !>              boolean quantity is .TRUE.
      !>
      !>              The endpoints of the time intervals comprising RESULT are
      !>              interpreted as seconds past J2000 TDB.
      !>
      !>              If no times within the confinement window satisfy the
      !>              search criteria, RESULT will be returned with a
      !>              cardinality of zero.
      !>
      !>## Parameters
      !>
      !>     LBCELL   is the integer value defining the lower bound for
      !>              SPICE Cell arrays (a SPICE window is a kind of cell).
      !>
      !>     CNVTOL   is the convergence tolerance used for finding
      !>              endpoints of the intervals comprising the result
      !>              window. CNVTOL is used to determine when binary
      !>              searches for roots should terminate: when a root is
      !>              bracketed within an interval of length CNVTOL, the
      !>              root is considered to have been found.
      !>
      !>              The accuracy, as opposed to precision, of roots found
      !>              by this routine depends on the accuracy of the input
      !>              data. In most cases, the accuracy of solutions will be
      !>              inferior to their precision.
      !>
      !>     See INCLUDE file gf.inc for declarations and descriptions of
      !>     parameters used throughout the GF system.
      !>
      !>## Exceptions
      !>
      !>     1)  In order for this routine to produce correct results,
      !>         the step size must be appropriate for the problem at hand.
      !>         Step sizes that are too large may cause this routine to miss
      !>         roots; step sizes that are too small may cause this routine
      !>         to run unacceptably slowly and in some cases, find spurious
      !>         roots.
      !>
      !>         This routine does not diagnose invalid step sizes, except that
      !>         if the step size is non-positive, an error is signaled by a
      !>         routine in the call tree of this routine.
      !>
      !>     2)  Due to numerical errors, in particular,
      !>
      !>            - truncation error in time values
      !>            - finite tolerance value
      !>            - errors in computed geometric quantities
      !>
      !>         it is *normal* for the condition of interest to not always be
      !>         satisfied near the endpoints of the intervals comprising the
      !>         RESULT window. One technique to handle such a situation,
      !>         slightly contract RESULT using the window routine WNCOND.
      !>
      !>     3)  If an error (typically cell overflow) occurs while performing
      !>         window arithmetic, the error is signaled by a routine
      !>         in the call tree of this routine.
      !>
      !>     4)  If the size of the SPICE window RESULT is less than 2 or not
      !>         an even value, the error SPICE(INVALIDDIMENSION) is signaled.
      !>
      !>     5)  If RESULT has insufficient capacity to contain the number of
      !>         intervals on which the specified condition is met, an error is
      !>         signaled by a routine in the call tree of this routine.
      !>
      !>     6)  If required ephemerides or other kernel data are not
      !>         available, an error is signaled by a routine in the call tree
      !>         of this routine.
      !>
      !>## Files
      !>
      !>     Appropriate kernels must be loaded by the calling program before
      !>     this routine is called.
      !>
      !>     If the boolean function requires access to ephemeris data:
      !>
      !>     -  SPK data: ephemeris data for any body over the
      !>        time period defined by the confinement window must be
      !>        loaded. If aberration corrections are used, the states of
      !>        target and observer relative to the solar system barycenter
      !>        must be calculable from the available ephemeris data.
      !>        Typically ephemeris data are made available by loading one
      !>        or more SPK files via FURNSH.
      !>
      !>     -  If non-inertial reference frames are used, then PCK
      !>        files, frame kernels, C-kernels, and SCLK kernels may be
      !>        needed.
      !>
      !>     -  Certain computations can expand the time window over which
      !>        UDFUNS and UDFUNB require data; such data must be provided by
      !>        loaded kernels. See $Particulars for details.
      !>
      !>     In all cases, kernel data are normally loaded once per program
      !>     run, NOT every time this routine is called.
      !>
      !>## Particulars
      !>
      !>     This routine determines a set of one or more time intervals
      !>     within the confinement window when the boolean function
      !>     evaluates to true. The resulting set of intervals is returned
      !>     as a SPICE window.
      !>
      !>     Below we discuss in greater detail aspects of this routine's
      !>     solution process that are relevant to correct and efficient
      !>     use of this routine in user applications.
      !>
      !>     UDFUNS Default Template
      !>     =======================
      !>
      !>     The boolean function includes an argument for an input scalar
      !>     function. Use of a scalar function during the evaluation of
      !>     the boolean function is not required. SPICE provides a no-op
      !>     scalar routine, UDF, as a dummy argument for instances when
      !>     the boolean function does not need to call the scalar function.
      !>
      !>     The Search Process
      !>     ==================
      !>
      !>     The search for boolean events is treated as a search for state
      !>     transitions: times are sought when the boolean function value
      !>     changes from true to false or vice versa.
      !>
      !>     Step Size
      !>     =========
      !>
      !>     Each interval of the confinement window is searched as follows:
      !>     first, the input step size is used to determine the time
      !>     separation at which the boolean function will be sampled.
      !>     Starting at the left endpoint of the interval, samples of the
      !>     boolean function will be taken at each step. If a state change
      !>     is detected, a root has been bracketed; at that point, the
      !>     "root"--the time at which the state change occurs---is found by a
      !>     refinement process, for example, via binary search.
      !>
      !>     Note that the optimal choice of step size depends on the lengths
      !>     of the intervals over which the boolean function is constant:
      !>     the step size should be shorter than the shortest such interval
      !>     and the shortest separation between the intervals, within
      !>     the confinement window.
      !>
      !>     Having some knowledge of the relative geometry of the targets and
      !>     observer can be a valuable aid in picking a reasonable step size.
      !>     In general, the user can compensate for lack of such knowledge by
      !>     picking a very short step size; the cost is increased computation
      !>     time.
      !>
      !>     Note that the step size is not related to the precision with which
      !>     the endpoints of the intervals of the result window are computed.
      !>     That precision level is controlled by the convergence tolerance.
      !>
      !>     Convergence Tolerance
      !>     =====================
      !>
      !>     Once a root has been bracketed, a refinement process is used to
      !>     narrow down the time interval within which the root must lie.
      !>     This refinement process terminates when the location of the root
      !>     has been determined to within an error margin called the
      !>     "convergence tolerance." The default convergence tolerance
      !>     used by this routine is set by the parameter CNVTOL (defined
      !>     in gf.inc).
      !>
      !>     The value of CNVTOL is set to a "tight" value so that the
      !>     tolerance doesn't become the limiting factor in the accuracy of
      !>     solutions found by this routine. In general the accuracy of input
      !>     data will be the limiting factor.
      !>
      !>     The user may change the convergence tolerance from the default
      !>     CNVTOL value by calling the routine GFSTOL, e.g.
      !>
      !>        CALL GFSTOL( tolerance value )
      !>
      !>     Call GFSTOL prior to calling this routine. All subsequent
      !>     searches will use the updated tolerance value.
      !>
      !>     Setting the tolerance tighter than CNVTOL is unlikely to be
      !>     useful, since the results are unlikely to be more accurate.
      !>     Making the tolerance looser will speed up searches somewhat,
      !>     since a few convergence steps will be omitted. However, in most
      !>     cases, the step size is likely to have a much greater effect
      !>     on processing time than would the convergence tolerance.
      !>
      !>     The Confinement Window
      !>     ======================
      !>
      !>     The simplest use of the confinement window is to specify a time
      !>     interval within which a solution is sought.
      !>
      !>     The confinement window also can be used to restrict a search to
      !>     a time window over which required data are known to be
      !>     available.
      !>
      !>     In some cases, the confinement window can be used to make
      !>     searches more efficient. Sometimes it's possible to do an
      !>     efficient search to reduce the size of the time period over
      !>     which a relatively slow search of interest must be performed.
      !>     See the "CASCADE" example program in gf.req for a demonstration.
      !>
      !>     Certain user-defined computations may expand the window over
      !>     which computations are performed. Here "expansion" of a window by
      !>     an amount "T" means that the left endpoint of each interval
      !>     comprising the window is shifted left by T, the right endpoint of
      !>     each interval is shifted right by T, and any overlapping
      !>     intervals are merged. Note that the input window CNFINE itself is
      !>     not modified.
      !>
      !>     Computation of observer-target states by SPKEZR or SPKEZ, using
      !>     stellar aberration corrections, requires the state of the
      !>     observer, relative to the solar system barycenter, to be computed
      !>     at times offset from the input time by +/- 1 second. If the input
      !>     time ET is used by UDFUNS or UDFUNB to compute such a state, the
      !>     window over which the observer state is computed is expanded by 1
      !>     second.
      !>
      !>     When light time corrections are used in the computation of
      !>     observer-target states, expansion of the search window also
      !>     affects the set of times at which the light time-corrected states
      !>     of the targets are computed.
      !>
      !>     In addition to possible expansion of the search window when
      !>     stellar aberration corrections are used, round-off error should
      !>     be taken into account when the need for data availability is
      !>     analyzed.
      !>
      !>## Examples
      !>
      !>     The numerical results shown for these examples may differ across
      !>     platforms. The results depend on the SPICE kernels used as
      !>     input, the compiler and supporting libraries, and the machine
      !>     specific arithmetic implementation.
      !>
      !>     1) Calculate the time intervals when the position of the Moon
      !>        relative to the Earth in the IAU_EARTH frame has a positive
      !>        value for the Z position component, also with a positive value
      !>        for the Vz velocity component.
      !>
      !>        Use the meta-kernel shown below to load the required SPICE
      !>        kernels.
      !>
      !>           KPL/MK
      !>
      !>           File name: gfudb_ex1.tm
      !>
      !>           This meta-kernel is intended to support operation of SPICE
      !>           example programs. The kernels shown here should not be
      !>           assumed to contain adequate or correct versions of data
      !>           required by SPICE-based user applications.
      !>
      !>           In order for an application to use this meta-kernel, the
      !>           kernels referenced here must be present in the user's
      !>           current working directory.
      !>
      !>           The names and contents of the kernels referenced
      !>           by this meta-kernel are as follows:
      !>
      !>              File name                     Contents
      !>              ---------                     --------
      !>              de418.bsp                     Planetary ephemeris
      !>              pck00009.tpc                  Planet orientation and
      !>                                            radii
      !>              naif0009.tls                  Leapseconds
      !>
      !>           \begindata
      !>
      !>              KERNELS_TO_LOAD = ( 'de418.bsp',
      !>                                  'pck00009.tpc',
      !>                                  'naif0009.tls'  )
      !>
      !>           \begintext
      !>
      !>           End of meta-kernel
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM GFUDB_EX1
      !>      IMPLICIT NONE
      !>
      !>C
      !>C     SPICELIB functions
      !>C
      !>      INTEGER               WNCARD
      !>      DOUBLE PRECISION      SPD
      !>
      !>C
      !>C     User defined external routines
      !>C
      !>      EXTERNAL              UDF
      !>      EXTERNAL              GFB
      !>
      !>C
      !>C     Local parameters
      !>C
      !>      INTEGER               LBCELL
      !>      PARAMETER           ( LBCELL = -5 )
      !>
      !>C
      !>C     Use the parameter MAXWIN for both the result window size
      !>C     and the workspace size.
      !>C
      !>      INTEGER               MAXWIN
      !>      PARAMETER           ( MAXWIN = 100 )
      !>
      !>C
      !>C     Local variables
      !>C
      !>      CHARACTER*(32)        UTC
      !>
      !>      DOUBLE PRECISION      LEFT
      !>      DOUBLE PRECISION      RIGHT
      !>      DOUBLE PRECISION      ET
      !>      DOUBLE PRECISION      ETS
      !>      DOUBLE PRECISION      ETE
      !>      DOUBLE PRECISION      LT
      !>      DOUBLE PRECISION      STEP
      !>      DOUBLE PRECISION      STATE  (6)
      !>      DOUBLE PRECISION      CNFINE ( LBCELL : 2      )
      !>      DOUBLE PRECISION      RESULT ( LBCELL : MAXWIN )
      !>
      !>      INTEGER               I
      !>
      !>C
      !>C     Saved variables
      !>C
      !>C     The confinement and result windows CNFINE and RESULT are
      !>C     saved because this practice helps to prevent stack
      !>C     overflow.
      !>C
      !>      SAVE                  CNFINE
      !>      SAVE                  RESULT
      !>
      !>C
      !>C     Load needed kernels.
      !>C
      !>      CALL FURNSH ( 'gfudb_ex1.tm' )
      !>
      !>C
      !>C     Initialize windows.
      !>C
      !>      CALL SSIZED ( MAXWIN, RESULT )
      !>      CALL SSIZED ( 2,      CNFINE )
      !>
      !>C
      !>C     Store the time bounds of our search interval in
      !>C     the confinement window.
      !>C
      !>      CALL STR2ET ( 'Jan 1 2011', ETS )
      !>      CALL STR2ET ( 'Apr 1 2011', ETE )
      !>      CALL WNINSD ( ETS, ETE, CNFINE  )
      !>
      !>C
      !>C     The moon orbit about the earth-moon barycenter is
      !>C     twenty-eight days. The event condition occurs
      !>C     during (very) approximately a quarter of the orbit. Use
      !>C     a step of five days.
      !>C
      !>      STEP = 5.D0 * SPD()
      !>
      !>      CALL GFUDB ( UDF, GFB, STEP, CNFINE, RESULT )
      !>
      !>      IF ( WNCARD(RESULT) .EQ. 0 ) THEN
      !>
      !>            WRITE (*, '(A)') 'Result window is empty.'
      !>
      !>      ELSE
      !>
      !>         DO I = 1, WNCARD(RESULT)
      !>
      !>C
      !>C           Fetch and display each RESULT interval.
      !>C
      !>            CALL WNFETD ( RESULT, I, LEFT, RIGHT )
      !>            WRITE (*,*) 'Interval ', I
      !>
      !>            CALL ET2UTC ( LEFT, 'C', 4, UTC )
      !>            WRITE (*, *) '   Interval start: ', UTC
      !>
      !>            CALL SPKEZ ( 301, LEFT, 'IAU_EARTH', 'NONE', 399,
      !>     .                   STATE, LT )
      !>            WRITE (*, *) '                Z= ', STATE(3)
      !>            WRITE (*, *) '               Vz= ', STATE(6)
      !>
      !>            CALL ET2UTC ( RIGHT, 'C', 4, UTC )
      !>            WRITE (*, *) '   Interval end  : ', UTC
      !>
      !>            CALL SPKEZ ( 301, RIGHT, 'IAU_EARTH', 'NONE', 399,
      !>     .                   STATE, LT )
      !>            WRITE (*, *) '                Z= ', STATE(3)
      !>            WRITE (*, *) '               Vz= ', STATE(6)
      !>            WRITE (*, *) ' '
      !>
      !>         END DO
      !>
      !>      END IF
      !>
      !>      END
      !>
      !>C-Procedure GFB
      !>C
      !>C     User defined boolean routine.
      !>C
      !>
      !>      SUBROUTINE GFB ( UDFUNS, ET, BOOL )
      !>      IMPLICIT NONE
      !>
      !>C- Abstract
      !>C
      !>C     User defined geometric boolean function:
      !>C
      !>C        Z >= 0 with dZ/dt > 0.
      !>C
      !>
      !>      EXTERNAL              UDFUNS
      !>
      !>      DOUBLE PRECISION      ET
      !>      LOGICAL               BOOL
      !>
      !>C
      !>C     Local variables.
      !>C
      !>      INTEGER               TARG
      !>      INTEGER               OBS
      !>
      !>      CHARACTER*(12)        REF
      !>      CHARACTER*(12)        ABCORR
      !>
      !>      DOUBLE PRECISION      STATE ( 6 )
      !>      DOUBLE PRECISION      LT
      !>
      !>C
      !>C     Initialization. Retrieve the vector from the earth to
      !>C     the moon in the IAU_EARTH frame, without aberration
      !>C     correction.
      !>C
      !>      TARG   = 301
      !>      REF    = 'IAU_EARTH'
      !>      ABCORR = 'NONE'
      !>      OBS    = 399
      !>
      !>C
      !>C     Evaluate the state of TARG from OBS at ET with
      !>C     correction ABCORR.
      !>C
      !>      CALL SPKEZ ( TARG, ET, REF, ABCORR, OBS, STATE, LT )
      !>
      !>C
      !>C     Calculate the boolean value.
      !>C
      !>      BOOL = (STATE(3) .GE. 0.D0) .AND. (STATE(6) .GT. 0.D0 )
      !>
      !>      RETURN
      !>
      !>      END
      !>```
      !>
      !>        When this program was executed on a Mac/Intel/gfortran/64-bit
      !>        platform, the output was:
      !>
      !>         Interval            1
      !>            Interval start: 2011 JAN 09 15:24:23.4165
      !>                         Z=   -1.1251040632487275E-007
      !>                        Vz=   0.39698408454587081
      !>            Interval end  : 2011 JAN 16 16:08:28.5642
      !>                         Z=    156247.48804193645
      !>                        Vz=    4.0992339730983041E-013
      !>
      !>         Interval            2
      !>            Interval start: 2011 FEB 05 23:17:57.3600
      !>                         Z=   -1.2467506849134224E-007
      !>                        Vz=   0.39678128284337311
      !>            Interval end  : 2011 FEB 13 01:38:28.4265
      !>                         Z=    157016.05500077485
      !>                        Vz=    1.7374578338558155E-013
      !>
      !>         Interval            3
      !>            Interval start: 2011 MAR 05 06:08:17.6689
      !>                         Z=   -7.7721836078126216E-008
      !>                        Vz=   0.39399025363429169
      !>            Interval end  : 2011 MAR 12 10:27:45.1896
      !>                         Z=    157503.77377718856
      !>                        Vz=   -2.9786351336824612E-013
      !>
      !>     2) Calculate the time intervals when the Z component of the
      !>        Earth to Moon position vector in the IAU_EARTH frame has
      !>        value between -1000 km and 1000 km (e.g. above and below
      !>        the equatorial plane).
      !>
      !>        Use the meta-kernel from the first example.
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM GFUDB_EX2
      !>      IMPLICIT NONE
      !>
      !>C
      !>C     SPICELIB functions.
      !>C
      !>      INTEGER               WNCARD
      !>      DOUBLE PRECISION      SPD
      !>
      !>C
      !>C     User defined external routines
      !>C
      !>      EXTERNAL              GFB
      !>      EXTERNAL              GFQ
      !>
      !>C
      !>C     Local parameters
      !>C
      !>      INTEGER               LBCELL
      !>      PARAMETER           ( LBCELL = -5 )
      !>
      !>C
      !>C     Use the parameter MAXWIN for both the result window size
      !>C     and the workspace size.
      !>C
      !>      INTEGER               MAXWIN
      !>      PARAMETER           ( MAXWIN = 100 )
      !>
      !>C
      !>C     Local variables
      !>C
      !>      CHARACTER*(32)        UTC
      !>
      !>      DOUBLE PRECISION      LEFT
      !>      DOUBLE PRECISION      RIGHT
      !>      DOUBLE PRECISION      ET
      !>      DOUBLE PRECISION      ETS
      !>      DOUBLE PRECISION      ETE
      !>      DOUBLE PRECISION      LT
      !>      DOUBLE PRECISION      STEP
      !>      DOUBLE PRECISION      POS (3)
      !>      DOUBLE PRECISION      CNFINE ( LBCELL : 2      )
      !>      DOUBLE PRECISION      RESULT ( LBCELL : MAXWIN )
      !>
      !>      INTEGER               I
      !>
      !>C
      !>C     Saved variables
      !>C
      !>C     The confinement and result windows CNFINE and RESULT are
      !>C     saved because this practice helps to prevent stack
      !>C     overflow.
      !>C
      !>      SAVE                  CNFINE
      !>      SAVE                  RESULT
      !>
      !>C
      !>C     Load needed kernels.
      !>C
      !>      CALL FURNSH ( 'gfudb_ex1.tm' )
      !>
      !>C
      !>C     Initialize windows.
      !>C
      !>      CALL SSIZED ( MAXWIN, RESULT )
      !>      CALL SSIZED ( 2,      CNFINE )
      !>
      !>C
      !>C     Store the time bounds of our search interval in
      !>C     the confinement window.
      !>C
      !>      CALL STR2ET ( 'Jan 1 2011', ETS )
      !>      CALL STR2ET ( 'Apr 1 2011', ETE )
      !>      CALL WNINSD ( ETS, ETE, CNFINE )
      !>
      !>C
      !>C     The duration of the event is approximately ninety
      !>C     minutes. Use a step of one hour.
      !>C
      !>      STEP = 60.D0*60.D0
      !>
      !>      CALL GFUDB ( GFQ, GFB, STEP, CNFINE, RESULT )
      !>
      !>      IF ( WNCARD(RESULT) .EQ. 0 ) THEN
      !>
      !>            WRITE (*, '(A)') 'Result window is empty.'
      !>
      !>      ELSE
      !>
      !>         DO I = 1, WNCARD(RESULT)
      !>
      !>C
      !>C           Fetch and display each RESULT interval.
      !>C
      !>            CALL WNFETD ( RESULT, I, LEFT, RIGHT )
      !>            WRITE (*,*) 'Interval ', I
      !>
      !>            CALL ET2UTC ( LEFT, 'C', 4, UTC )
      !>            WRITE (*, *) '   Interval start: ', UTC
      !>
      !>            CALL SPKEZP ( 301, LEFT, 'IAU_EARTH', 'NONE', 399,
      !>     .                   POS, LT )
      !>            WRITE (*, *) '                Z= ', POS(3)
      !>
      !>            CALL ET2UTC ( RIGHT, 'C', 4, UTC )
      !>            WRITE (*, *) '   Interval end  : ', UTC
      !>
      !>            CALL SPKEZP ( 301, RIGHT, 'IAU_EARTH', 'NONE', 399,
      !>     .                   POS, LT )
      !>            WRITE (*, *) '                Z= ', POS(3)
      !>            WRITE (*, *) ' '
      !>
      !>         END DO
      !>
      !>      END IF
      !>
      !>      END
      !>
      !>C-Procedure GFQ
      !>C
      !>C     User defined scalar routine.
      !>C
      !>
      !>      SUBROUTINE GFQ ( ET, VALUE )
      !>      IMPLICIT NONE
      !>
      !>C- Abstract
      !>C
      !>C     Return the Z component of the POS vector.
      !>C
      !>
      !>      DOUBLE PRECISION      ET
      !>      DOUBLE PRECISION      VALUE
      !>
      !>C
      !>C     Local variables.
      !>C
      !>      INTEGER               TARG
      !>      INTEGER               OBS
      !>
      !>      CHARACTER*(12)        REF
      !>      CHARACTER*(12)        ABCORR
      !>
      !>      DOUBLE PRECISION      POS ( 3 )
      !>      DOUBLE PRECISION      LT
      !>
      !>C
      !>C     Initialization. Retrieve the vector from the earth to
      !>C     the moon in the IAU_EARTH frame, without aberration
      !>C     correction.
      !>C
      !>      TARG   = 301
      !>      REF    = 'IAU_EARTH'
      !>      ABCORR = 'NONE'
      !>      OBS    = 399
      !>
      !>C
      !>C     Evaluate the position of TARG from OBS at ET with
      !>C     correction ABCORR.
      !>C
      !>      CALL SPKEZP ( TARG, ET, REF, ABCORR, OBS, POS, LT )
      !>
      !>      VALUE = POS(3)
      !>
      !>      RETURN
      !>      END
      !>
      !>C-Procedure GFB
      !>C
      !>C     User defined boolean routine.
      !>C
      !>
      !>      SUBROUTINE GFB ( UDFUNS, ET, BOOL )
      !>      IMPLICIT NONE
      !>
      !>C- Abstract
      !>C
      !>C     User defined boolean function:
      !>C
      !>C        VALUE >= LIM1 with VALUE <= LIM2.
      !>C
      !>
      !>      EXTERNAL              UDFUNS
      !>
      !>      DOUBLE PRECISION      ET
      !>      LOGICAL               BOOL
      !>      DOUBLE PRECISION      VALUE
      !>
      !>      DOUBLE PRECISION      LIM1
      !>      DOUBLE PRECISION      LIM2
      !>
      !>      LIM1 = -1000.D0
      !>      LIM2 =  1000.D0
      !>
      !>      CALL UDFUNS ( ET, VALUE )
      !>
      !>C
      !>C     Calculate the boolean value.
      !>C
      !>      BOOL = (VALUE .GE. LIM1) .AND. (VALUE .LE. LIM2 )
      !>
      !>      RETURN
      !>      END
      !>```
      !>
      !>        When this program was executed on a Mac/Intel/gfortran/64-bit
      !>        platform, the output was:
      !>
      !>         Interval            1
      !>            Interval start: 2011 JAN 09 14:42:24.4855
      !>                         Z=   -999.99999984083206
      !>            Interval end  : 2011 JAN 09 16:06:22.5030
      !>                         Z=    999.99999987627757
      !>
      !>         Interval            2
      !>            Interval start: 2011 JAN 23 04:07:44.4563
      !>                         Z=    999.99999992179255
      !>            Interval end  : 2011 JAN 23 05:23:06.2446
      !>                         Z=   -1000.0000001340870
      !>
      !>         Interval            3
      !>            Interval start: 2011 FEB 05 22:35:57.1570
      !>                         Z=   -1000.0000000961383
      !>            Interval end  : 2011 FEB 05 23:59:57.7497
      !>                         Z=    999.99999984281567
      !>
      !>         Interval            4
      !>            Interval start: 2011 FEB 19 14:11:28.2944
      !>                         Z=    1000.0000000983686
      !>            Interval end  : 2011 FEB 19 15:26:01.7199
      !>                         Z=   -999.99999985420800
      !>
      !>         Interval            5
      !>            Interval start: 2011 MAR 05 05:25:59.5621
      !>                         Z=   -1000.0000000277355
      !>            Interval end  : 2011 MAR 05 06:50:35.8628
      !>                         Z=    1000.0000000934349
      !>
      !>         Interval            6
      !>            Interval start: 2011 MAR 19 01:30:19.1660
      !>                         Z=    999.99999982956138
      !>            Interval end  : 2011 MAR 19 02:45:21.1121
      !>                         Z=   -1000.0000000146936
      !>
      !>        Note that the default convergence tolerance for the GF system
      !>        has value 10^-6 seconds.
      !>
      !>## Restrictions
      !>
      !>     1)  Any kernel files required by this routine must be loaded
      !>         (normally via the SPICELIB routine FURNSH) before this routine
      !>         is called.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     E.D. Wright        (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.1, 21-OCT-2021 (JDR) (NJB)
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>        Added "IMPLICIT NONE" to example code and declared "LT"
      !>        variable. Reduced the search interval to limit the length of
      !>        the solutions. Added SAVE statements for CNFINE and RESULT
      !>        variables in code examples.
      !>
      !>        Updated description of RESULT argument in $Brief_I/O,
      !>        $Detailed_Input and $Detailed_Output.
      !>
      !>        Added entry #3 in $Exceptions section.
      !>
      !>        Updated header to describe use of expanded confinement window.
      !>
      !>-    SPICELIB Version 1.0.0, 15-JUL-2014 (EDW) (NJB)
      module subroutine gfudb ( ctx, udfuns, udfunb, step, cnfine, result )
      use pepper_kinds, only: ip, wp
      use pepper_math, only: odd
      use pepper_inc_gf
      use pepper_inc_zzgf
      use pepper_inc_zzholdd
      implicit none


!
!     Local variables.
!

      real(wp) :: tol
      logical :: ok


      class(pepper_context), intent(inout) :: ctx  !! the context
      real(wp), intent(in) :: step  !! Constant step size in seconds for finding geometric events.
      real(wp), intent(in) :: cnfine ( lbcell : * )  !! SPICE window to which the search is restricted.
      real(wp), intent(inout) :: result ( lbcell : * )  !! SPICE window containing results.
      procedure(gf_scalar) :: udfuns  !! Name of the routine that computes a scalar quantity corresponding to an ET.
      procedure(gf_boolean) :: udfunb  !! Name of the routine returning the boolean value corresponding to an ET.

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Check the result window size.
!
      if ( (sized( ctx,result) < 2) .or. odd( sized( ctx,result) ) ) then

         call ctx%setmsg ( 'Result window size was #; size must be ' &
         //            'at least 2 and an even value.'             )
         call ctx%errint ( '#', sized( ctx,result)                          )
         call ctx%sigerr ( 'SPICE(INVALIDDIMENSION)'                   )
         return

      end if

!
!     Set the step size.
!
      call gfsstp ( ctx,step)

!
!     Retrieve the convergence tolerance, if set.
!
      call zzholdd ( ctx, zzget, gf_tol, ok, tol )

!
!     Use the default value CNVTOL if no stored tolerance value.
!
      if ( .not. ok ) then

         tol = cnvtol

      end if

!
!     Initialize the RESULT window to empty.
!
      call scardd ( ctx, 0, result)

      call zzgfudb ( ctx, udfuns, udfunb, tol,     gfstep,  gfrefn, &
                     norpt,  gfrepi,  gfrepu,  gfrepf, &
                     nobail, gfbail,  cnfine,  result )

      return
      end subroutine gfudb

      !> Perform a GF search on a user defined scalar quantity.
      !>
      !>## Detailed Input
      !>
      !>     UDFUNS   is the routine that returns the value of the scalar
      !>              quantity of interest at time ET. The calling sequence for
      !>              UDFUNS is:
      !>
      !>                 CALL UDFUNS ( ET, VALUE )
      !>
      !>              where:
      !>
      !>                 ET      is a double precision value representing
      !>                         ephemeris time, expressed as seconds past
      !>                         J2000 TDB, at which to determine the scalar
      !>                         value.
      !>
      !>                 VALUE   is the value of the scalar quantity at ET.
      !>
      !>     UDQDEC   is the name of the routine that determines if the scalar
      !>              quantity calculated by UDFUNS is decreasing. The calling
      !>              sequence of UDQDEC is:
      !>
      !>                 CALL UDQDEC ( UDFUNS, ET, ISDECR )
      !>
      !>              where:
      !>
      !>                 UDFUNS   is the name of the scalar function as defined
      !>                          above.
      !>
      !>                 ET       is a double precision value representing
      !>                          ephemeris time, expressed as seconds past
      !>                          J2000 TDB, at which to determine the time
      !>                          derivative of UDFUNS.
      !>
      !>                 ISDECR   is a logical output variable indicating
      !>                          whether or not the scalar value returned by
      !>                          UDFUNS is decreasing. ISDECR returns .TRUE.
      !>                          if the time derivative of UDFUNS at ET is
      !>                          negative.
      !>
      !>     RELATE   is the scalar string comparison operator indicating
      !>              the numeric constraint of interest. Values are:
      !>
      !>                 '>'        value of scalar quantity greater than some
      !>                            reference (REFVAL).
      !>
      !>                 '='        value of scalar quantity equal to some
      !>                            reference (REFVAL).
      !>
      !>                 '<'        value of scalar quantity less than some
      !>                            reference (REFVAL).
      !>
      !>                 'ABSMAX'   The scalar quantity is at an absolute
      !>                            maximum.
      !>
      !>                 'ABSMIN'   The scalar quantity is at an absolute
      !>                            minimum.
      !>
      !>                 'LOCMAX'   The scalar quantity is at a local
      !>                            maximum.
      !>
      !>                 'LOCMIN'   The scalar quantity is at a local
      !>                            minimum.
      !>
      !>              The caller may indicate that the region of interest
      !>              is the set of time intervals where the quantity is
      !>              within a specified distance of an absolute extremum.
      !>              The argument ADJUST (described below) is used to
      !>              specified this distance.
      !>
      !>              Local extrema are considered to exist only in the
      !>              interiors of the intervals comprising the confinement
      !>              window:  a local extremum cannot exist at a boundary
      !>              point of the confinement window.
      !>
      !>              RELATE is insensitive to case, leading and
      !>              trailing blanks.
      !>
      !>     REFVAL   is the reference value used to define an equality or
      !>              inequality to  satisfied by the scalar quantity.
      !>              The units of REFVAL are those of the scalar quantity.
      !>
      !>     ADJUST   is the amount by which the quantity is allowed to vary
      !>              from an absolute extremum.
      !>
      !>              If the search is for an absolute minimum is performed,
      !>              the resulting window contains time intervals when the
      !>              geometric quantity value has values between ABSMIN and
      !>              ABSMIN + ADJUST.
      !>
      !>              If the search is for an absolute maximum, the
      !>              corresponding range is between ABSMAX - ADJUST and
      !>              ABSMAX.
      !>
      !>              ADJUST is not used for searches for local extrema,
      !>              equality or inequality conditions and must have value
      !>              zero for such searches.
      !>
      !>     STEP     is the double precision time step size to use in
      !>              the search.
      !>
      !>              STEP must be short enough to for a search using this
      !>              step size to locate the time intervals where the
      !>              scalar quantity function is monotone increasing or
      !>              decreasing. However, STEP must not be *too* short,
      !>              or the search will take an unreasonable amount of time.
      !>
      !>              The choice of STEP affects the completeness but not
      !>              the precision of solutions found by this routine; the
      !>              precision is controlled by the convergence tolerance.
      !>              See the discussion of the parameter CNVTOL for
      !>              details.
      !>
      !>              STEP has units of TDB seconds.
      !>
      !>     CNFINE   is a SPICE window that confines the time period over
      !>              which the specified search is conducted. CNFINE may
      !>              consist of a single interval or a collection of
      !>              intervals.
      !>
      !>              In some cases the confinement window can be used to
      !>              greatly reduce the time period that must be searched
      !>              for the desired solution. See the $Particulars section
      !>              below for further discussion.
      !>
      !>              See the $Examples section below for a code example
      !>              that shows how to create a confinement window.
      !>
      !>              CNFINE must be initialized by the caller via the
      !>              SPICELIB routine SSIZED.
      !>
      !>              Certain computations can expand the time window over
      !>              which UDFUNS and UDQDEC require data. See $Particulars
      !>              for details.
      !>
      !>     MW       is a parameter specifying the length of the SPICE
      !>              windows in the workspace array WORK (see description
      !>              below) used by this routine.
      !>
      !>              MW should be set to a number at least twice as large
      !>              as the maximum number of intervals required by any
      !>              workspace window. In many cases, it's not necessary to
      !>              compute an accurate estimate of how many intervals are
      !>              needed; rather, the user can pick a size considerably
      !>              larger than what's really required.
      !>
      !>              However, since excessively large arrays can prevent
      !>              applications from compiling, linking, or running
      !>              properly, sometimes MW must be set according to
      !>              the actual workspace requirement. A rule of thumb
      !>              for the number of intervals NINTVLS needed is
      !>
      !>                 NINTVLS  =  2*N  +  ( M / STEP )
      !>
      !>              where
      !>
      !>                 N     is the number of intervals in the confinement
      !>                       window
      !>
      !>                 M     is the measure of the confinement window, in
      !>                       units of seconds
      !>
      !>                 STEP  is the search step size in seconds
      !>
      !>              MW should then be set to
      !>
      !>                 2 * NINTVLS
      !>
      !>     NW       is a parameter specifying the number of SPICE windows
      !>              in the workspace array WORK (see description below)
      !>              used by this routine. (The reason this dimension is
      !>              an input argument is that this allows run-time
      !>              error checking to be performed.)
      !>
      !>              NW must be at least as large as the parameter NWUDS.
      !>
      !>     RESULT   is a double precision SPICE window which will contain
      !>              the search results. RESULT must be declared and
      !>              initialized with sufficient size to capture the full
      !>              set of time intervals within the search region on which
      !>              the specified condition is satisfied.
      !>
      !>              RESULT must be initialized by the caller via the
      !>              SPICELIB routine SSIZED.
      !>
      !>              If RESULT is non-empty on input, its contents will be
      !>              discarded before GFUDS conducts its search.
      !>
      !>## Detailed Output
      !>
      !>     WORK     is an array used to store workspace windows.
      !>
      !>              This array should be declared by the caller as shown:
      !>
      !>                  DOUBLE PRECISION     WORK ( LBCELL : MW,  NW )
      !>
      !>              WORK need not be initialized by the caller.
      !>
      !>              WORK is modified by this routine. The caller should
      !>              re-initialize this array before attempting to use it for
      !>              any other purpose.
      !>
      !>     RESULT   is a SPICE window containing the time intervals within
      !>              the confinement window, during which the specified
      !>              condition on the scalar quantity is met.
      !>
      !>              The endpoints of the time intervals comprising RESULT are
      !>              interpreted as seconds past J2000 TDB.
      !>
      !>              If the search is for local extrema, or for absolute
      !>              extrema with ADJUST set to zero, then normally each
      !>              interval of RESULT will be a singleton: the left and
      !>              right endpoints of each interval will be identical.
      !>
      !>              If no times within the confinement window satisfy the
      !>              search criteria, RESULT will be returned with a
      !>              cardinality of zero.
      !>
      !>## Parameters
      !>
      !>     LBCELL   is the integer value defining the lower bound for
      !>              SPICE Cell arrays (a SPICE window is a kind of cell).
      !>
      !>     CNVTOL   is the convergence tolerance used for finding
      !>              endpoints of the intervals comprising the result
      !>              window. CNVTOL is also used for finding intermediate
      !>              results; in particular, CNVTOL is used for finding the
      !>              windows on which the range rate is increasing
      !>              or decreasing. CNVTOL is used to determine when binary
      !>              searches for roots should terminate: when a root is
      !>              bracketed within an interval of length CNVTOL; the
      !>              root is considered to have been found.
      !>
      !>              The accuracy, as opposed to precision, of roots found
      !>              by this routine depends on the accuracy of the input
      !>              data. In most cases, the accuracy of solutions will be
      !>              inferior to their precision.
      !>
      !>     See INCLUDE file gf.inc for declarations and descriptions of
      !>     parameters used throughout the GF system.
      !>
      !>## Exceptions
      !>
      !>     1)  In order for this routine to produce correct results,
      !>         the step size must be appropriate for the problem at hand.
      !>         Step sizes that are too large may cause this routine to miss
      !>         roots; step sizes that are too small may cause this routine
      !>         to run unacceptably slowly and in some cases, find spurious
      !>         roots.
      !>
      !>         This routine does not diagnose invalid step sizes, except that
      !>         if the step size is non-positive, an error is signaled by a
      !>         routine in the call tree of this routine.
      !>
      !>     2)  Due to numerical errors, in particular,
      !>
      !>            - truncation error in time values
      !>            - finite tolerance value
      !>            - errors in computed geometric quantities
      !>
      !>         it is *normal* for the condition of interest to not always be
      !>         satisfied near the endpoints of the intervals comprising the
      !>         RESULT window. One technique to handle such a situation,
      !>         slightly contract RESULT using the window routine WNCOND.
      !>
      !>     3)  If the workspace window size MW is less than 2 or not an even
      !>         value, the error SPICE(INVALIDDIMENSION) is signaled.
      !>
      !>     4)  If the number of workspace windows NW is too small for the
      !>         required search, an error is signaled by a routine in the call
      !>         tree of this routine.
      !>
      !>     5)  If the size of the SPICE window RESULT is less than 2 or not
      !>         an even value, the error SPICE(INVALIDDIMENSION) is signaled.
      !>
      !>     6)  If RESULT has insufficient capacity to contain the
      !>         number of intervals on which the specified condition
      !>         is met, an error is signaled by a routine in the call
      !>         tree of this routine.
      !>
      !>     7)  If the window count NW is less than NWUDS, the error
      !>         SPICE(INVALIDDIMENSION) is signaled.
      !>
      !>     8)  If an error (typically cell overflow) occurs during
      !>         window arithmetic, the error is signaled by a routine
      !>         in the call tree of this routine.
      !>
      !>     9)  If the relational operator RELATE is not recognized, an
      !>         error is signaled by a routine in the call tree of this
      !>         routine.
      !>
      !>     10) If ADJUST is negative, an error is signaled by a routine in
      !>         the call tree of this routine.
      !>
      !>     11) If a non-zero value is provided for ADJUST when RELATE has any
      !>         value other than 'ABSMIN' or 'ABSMAX', an error is signaled by
      !>         a routine in the call tree of this routine.
      !>
      !>     12) If required ephemerides or other kernel data are not
      !>         available, an error is signaled by a routine in the call tree
      !>         of this routine.
      !>
      !>## Files
      !>
      !>     Appropriate kernels must be loaded by the calling program before
      !>     this routine is called.
      !>
      !>     If the scalar function requires access to ephemeris data:
      !>
      !>     -  SPK data: ephemeris data for any body over the
      !>        time period defined by the confinement window must be
      !>        loaded. If aberration corrections are used, the states of
      !>        target and observer relative to the solar system barycenter
      !>        must be calculable from the available ephemeris data.
      !>        Typically ephemeris data are made available by loading one
      !>        or more SPK files via FURNSH.
      !>
      !>     -  If non-inertial reference frames are used, then PCK
      !>        files, frame kernels, C-kernels, and SCLK kernels may be
      !>        needed.
      !>
      !>     -  Certain computations can expand the time window over which
      !>        UDFUNS and UDQDEC require data; such data must be provided by
      !>        loaded kernels. See $Particulars for details.
      !>
      !>     In all cases, kernel data are normally loaded once per program
      !>     run, NOT every time this routine is called.
      !>
      !>## Particulars
      !>
      !>     This routine determines a set of one or more time intervals
      !>     within the confinement window when the scalar function
      !>     satisfies a caller-specified constraint. The resulting set of
      !>     intervals is returned as a SPICE window.
      !>
      !>     UDQDEC Default Template
      !>     =======================
      !>
      !>     The user must supply a routine to determine whether sign of the
      !>     time derivative of UDFUNS is positive or negative at ET. For
      !>     cases where UDFUNS is numerically well behaved, the user
      !>     may find it convenient to use a routine based on the below
      !>     template. UDDC determines the truth of the expression
      !>
      !>        d (UDFUNS)
      !>        --         < 0
      !>        dt
      !>
      !>     using the library routine UDDF to numerically calculate the
      !>     derivative of UDFUNS using a three-point estimation.
      !>     Please see the $Examples section for an example of GFDECR use.
      !>
      !>           SUBROUTINE GFDECR ( UDFUNS, ET, ISDECR )
      !>           IMPLICIT NONE
      !>
      !>           EXTERNAL              UDFUNS
      !>           EXTERNAL              UDDF
      !>
      !>           DOUBLE PRECISION      ET
      !>           LOGICAL               ISDECR
      !>
      !>           DOUBLE PRECISION      DT
      !>
      !>           DT =  h, double precision interval size
      !>
      !>           CALL UDDC ( UDFUNS, ET, DT, ISDECR )
      !>
      !>           END
      !>
      !>     The Search Process
      !>     ==================
      !>
      !>     Regardless of the type of constraint selected by the caller, this
      !>     routine starts the search for solutions by determining the time
      !>     periods, within the confinement window, over which the specified
      !>     scalar function is monotone increasing and monotone
      !>     decreasing. Each of these time periods is represented by a SPICE
      !>     window. Having found these windows, all of the quantity
      !>     function's local extrema within the confinement window are known.
      !>     Absolute extrema then can be found very easily.
      !>
      !>     Within any interval of these "monotone" windows, there will be at
      !>     most one solution of any equality constraint. Since the boundary
      !>     of the solution set for any inequality constraint is contained in
      !>     the union of
      !>
      !>     -  the set of points where an equality constraint is met
      !>
      !>     -  the boundary points of the confinement window
      !>
      !>     the solutions of both equality and inequality constraints can be
      !>     found easily once the monotone windows have been found.
      !>
      !>     Step Size
      !>     =========
      !>
      !>     The monotone windows (described above) are found using a two-step
      !>     search process. Each interval of the confinement window is
      !>     searched as follows: first, the input step size is used to
      !>     determine the time separation at which the sign of the rate of
      !>     change of quantity function will be sampled. Starting at
      !>     the left endpoint of an interval, samples will be taken at each
      !>     step. If a change of sign is found, a root has been bracketed; at
      !>     that point, the time at which the time derivative of the quantity
      !>     function is zero can be found by a refinement process, for
      !>     example, using a binary search.
      !>
      !>     Note that the optimal choice of step size depends on the lengths
      !>     of the intervals over which the quantity function is monotone:
      !>     the step size should be shorter than the shortest of these
      !>     intervals (within the confinement window).
      !>
      !>     The optimal step size is *not* necessarily related to the lengths
      !>     of the intervals comprising the result window. For example, if
      !>     the shortest monotone interval has length 10 days, and if the
      !>     shortest result window interval has length 5 minutes, a step size
      !>     of 9.9 days is still adequate to find all of the intervals in the
      !>     result window. In situations like this, the technique of using
      !>     monotone windows yields a dramatic efficiency improvement over a
      !>     state-based search that simply tests at each step whether the
      !>     specified constraint is satisfied. The latter type of search can
      !>     miss solution intervals if the step size is longer than the
      !>     shortest solution interval.
      !>
      !>     Having some knowledge of the relative geometry of the targets and
      !>     observer can be a valuable aid in picking a reasonable step size.
      !>     In general, the user can compensate for lack of such knowledge by
      !>     picking a very short step size; the cost is increased computation
      !>     time.
      !>
      !>     Note that the step size is not related to the precision with which
      !>     the endpoints of the intervals of the result window are computed.
      !>     That precision level is controlled by the convergence tolerance.
      !>
      !>     Convergence Tolerance
      !>     =====================
      !>
      !>     Once a root has been bracketed, a refinement process is used to
      !>     narrow down the time interval within which the root must lie.
      !>     This refinement process terminates when the location of the root
      !>     has been determined to within an error margin called the
      !>     "convergence tolerance." The default convergence tolerance
      !>     used by this routine is set by the parameter CNVTOL (defined
      !>     in gf.inc).
      !>
      !>     The value of CNVTOL is set to a "tight" value so that the
      !>     tolerance doesn't become the limiting factor in the accuracy of
      !>     solutions found by this routine. In general the accuracy of input
      !>     data will be the limiting factor.
      !>
      !>     The user may change the convergence tolerance from the default
      !>     CNVTOL value by calling the routine GFSTOL, e.g.
      !>
      !>        CALL GFSTOL( tolerance value )
      !>
      !>     Call GFSTOL prior to calling this routine. All subsequent
      !>     searches will use the updated tolerance value.
      !>
      !>     Setting the tolerance tighter than CNVTOL is unlikely to be
      !>     useful, since the results are unlikely to be more accurate.
      !>     Making the tolerance looser will speed up searches somewhat,
      !>     since a few convergence steps will be omitted. However, in most
      !>     cases, the step size is likely to have a much greater effect
      !>     on processing time than would the convergence tolerance.
      !>
      !>     The Confinement Window
      !>     ======================
      !>
      !>     The simplest use of the confinement window is to specify a time
      !>     interval within which a solution is sought. However, the
      !>     confinement window can, in some cases, be used to make searches
      !>     more efficient. Sometimes it's possible to do an efficient search
      !>     to reduce the size of the time period over which a relatively
      !>     slow search of interest must be performed.
      !>
      !>     Certain user-defined computations may expand the window over
      !>     which computations are performed. Here "expansion" of a window by
      !>     an amount "T" means that the left endpoint of each interval
      !>     comprising the window is shifted left by T, the right endpoint of
      !>     each interval is shifted right by T, and any overlapping
      !>     intervals are merged. Note that the input window CNFINE itself is
      !>     not modified.
      !>
      !>     If a search uses an equality constraint, the time window over
      !>     which the functions UDFUNS and UDQDEC are called is expanded by 1
      !>     second.
      !>
      !>     Computation of observer-target states by SPKEZR or SPKEZ, using
      !>     stellar aberration corrections, requires the state of the
      !>     observer, relative to the solar system barycenter, to be computed
      !>     at times offset from the input time by +/- 1 second. If the input
      !>     time ET is used by UDFUNS or UDQDEC to compute such a state, the
      !>     window over which the observer state is computed is expanded by
      !>     1 second.
      !>
      !>     The window expansions described above are additive: if both
      !>     conditions apply, the window expansion amount is the sum of the
      !>     individual amounts.
      !>
      !>     When light time corrections are used in the computation of
      !>     observer-target states, expansion of the search window also
      !>     affects the set of times at which the light time-corrected states
      !>     of the targets are computed.
      !>
      !>     In addition to the possible expansion of the search window that
      !>     occurs when both an equality constraint and stellar aberration
      !>     corrections are used, round-off error should be taken into
      !>     account when the need for data availability is analyzed.
      !>
      !>## Examples
      !>
      !>     The numerical results shown for this example may differ across
      !>     platforms. The results depend on the SPICE kernels used as
      !>     input, the compiler and supporting libraries, and the machine
      !>     specific arithmetic implementation.
      !>
      !>     1) Conduct a search on the range-rate of the vector from the Sun
      !>        to the Moon. Define a function to calculate the value.
      !>
      !>        Use the meta-kernel shown below to load the required SPICE
      !>        kernels.
      !>
      !>           KPL/MK
      !>
      !>           File name: gfuds_ex1.tm
      !>
      !>           This meta-kernel is intended to support operation of SPICE
      !>           example programs. The kernels shown here should not be
      !>           assumed to contain adequate or correct versions of data
      !>           required by SPICE-based user applications.
      !>
      !>           In order for an application to use this meta-kernel, the
      !>           kernels referenced here must be present in the user's
      !>           current working directory.
      !>
      !>           The names and contents of the kernels referenced
      !>           by this meta-kernel are as follows:
      !>
      !>              File name                     Contents
      !>              ---------                     --------
      !>              de414.bsp                     Planetary ephemeris
      !>              pck00008.tpc                  Planet orientation and
      !>                                            radii
      !>              naif0009.tls                  Leapseconds
      !>
      !>           \begindata
      !>
      !>              KERNELS_TO_LOAD = ( 'de414.bsp',
      !>                                  'pck00008.tpc',
      !>                                  'naif0009.tls'  )
      !>
      !>           \begintext
      !>
      !>           End of meta-kernel
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM GFUDS_EX1
      !>      IMPLICIT NONE
      !>
      !>C
      !>C     Include GF parameter declarations:
      !>C
      !>      INCLUDE 'gf.inc'
      !>
      !>C
      !>C     User defined external routines
      !>C
      !>      EXTERNAL     GFQ
      !>      EXTERNAL     GFDECR
      !>
      !>C
      !>C     SPICELIB functions
      !>C
      !>      DOUBLE PRECISION      SPD
      !>      DOUBLE PRECISION      DVNORM
      !>      INTEGER               WNCARD
      !>
      !>C
      !>C     Local parameters
      !>C
      !>      INTEGER               LBCELL
      !>      PARAMETER           ( LBCELL = -5 )
      !>
      !>C
      !>C     Use the parameter MAXWIN for both the result window size
      !>C     and the workspace size.
      !>C
      !>      INTEGER               MAXWIN
      !>      PARAMETER           ( MAXWIN = 20000 )
      !>
      !>C
      !>C     Length of strings:
      !>C
      !>      INTEGER               TIMLEN
      !>      PARAMETER           ( TIMLEN = 26 )
      !>
      !>      INTEGER               NLOOPS
      !>      PARAMETER           ( NLOOPS = 7 )
      !>
      !>C
      !>C     Local variables
      !>C
      !>      CHARACTER*(TIMLEN)    TIMSTR
      !>      CHARACTER*(TIMLEN)    RELATE (NLOOPS)
      !>
      !>      DOUBLE PRECISION      ADJUST
      !>      DOUBLE PRECISION      CNFINE ( LBCELL : 2 )
      !>      DOUBLE PRECISION      DRDT
      !>      DOUBLE PRECISION      ET0
      !>      DOUBLE PRECISION      ET1
      !>      DOUBLE PRECISION      FINISH
      !>      DOUBLE PRECISION      LT
      !>      DOUBLE PRECISION      POS    ( 6 )
      !>      DOUBLE PRECISION      REFVAL
      !>      DOUBLE PRECISION      RESULT ( LBCELL : MAXWIN )
      !>      DOUBLE PRECISION      START
      !>      DOUBLE PRECISION      STEP
      !>      DOUBLE PRECISION      WORK   ( LBCELL : MAXWIN, NWUDS )
      !>
      !>      INTEGER               I
      !>      INTEGER               J
      !>
      !>C
      !>C     Saved variables
      !>C
      !>C     The confinement, workspace and result windows CNFINE,
      !>C     WORK and RESULT are saved because this practice helps to
      !>C     prevent stack overflow.
      !>C
      !>      SAVE                  CNFINE
      !>      SAVE                  RESULT
      !>      SAVE                  WORK
      !>
      !>      DATA                  RELATE / '=',
      !>     .                               '<',
      !>     .                               '>',
      !>     .                               'LOCMIN',
      !>     .                               'ABSMIN',
      !>     .                               'LOCMAX',
      !>     .                               'ABSMAX'  /
      !>
      !>C
      !>C     Load kernels.
      !>C
      !>      CALL FURNSH ( 'gfuds_ex1.tm' )
      !>
      !>C
      !>C     Initialize windows.
      !>C
      !>      CALL SSIZED ( MAXWIN, RESULT )
      !>      CALL SSIZED ( 2,      CNFINE )
      !>
      !>      CALL SCARDD ( 0,      CNFINE )
      !>
      !>C
      !>C     Store the time bounds of our search interval in
      !>C     the confinement window.
      !>C
      !>      CALL STR2ET ( '2007 JAN 1', ET0 )
      !>      CALL STR2ET ( '2007 APR 1', ET1 )
      !>
      !>      CALL WNINSD ( ET0, ET1, CNFINE )
      !>
      !>C
      !>C     Search using a step size of 1 day (in units of seconds).
      !>C     The reference value is .3365 km/s - a range rate value
      !>C     known to exist during the confinement window. We're not
      !>C     using the adjustment feature, so we set ADJUST to zero.
      !>C
      !>      STEP   = SPD()
      !>      REFVAL = .3365D0
      !>      ADJUST = 0.D0
      !>
      !>      DO J=1, NLOOPS
      !>
      !>         WRITE(*,*) 'Relation condition: ', RELATE(J)
      !>
      !>C
      !>C        Perform the search. The SPICE window RESULT contains
      !>C        the set of times when the condition is met.
      !>C
      !>         CALL GFUDS ( GFQ,    GFDECR, RELATE(J),
      !>     .                REFVAL, ADJUST,      STEP, CNFINE,
      !>     .                MAXWIN,  NWUDS,      WORK, RESULT )
      !>
      !>C
      !>C        Display the results.
      !>C
      !>         IF ( WNCARD(RESULT) .EQ. 0 ) THEN
      !>
      !>            WRITE (*, '(A)') 'Result window is empty.'
      !>
      !>         ELSE
      !>
      !>            DO I = 1, WNCARD(RESULT)
      !>
      !>C
      !>C              Fetch the endpoints of the Ith interval
      !>C              of the result window.
      !>C
      !>               CALL WNFETD ( RESULT, I, START, FINISH )
      !>
      !>               CALL SPKEZR ( 'MOON',  START, 'J2000', 'NONE',
      !>     .                       'SUN', POS,   LT               )
      !>               DRDT = DVNORM(POS)
      !>
      !>               CALL TIMOUT ( START,
      !>     .                       'YYYY-MON-DD HR:MN:SC.###',
      !>     .                       TIMSTR                     )
      !>
      !>               WRITE (*, '(A,F16.9)' ) 'Start time, drdt = '//
      !>     .                                 TIMSTR, DRDT
      !>
      !>               CALL SPKEZR ( 'MOON',  FINISH, 'J2000', 'NONE',
      !>     .                       'SUN', POS,     LT              )
      !>               DRDT = DVNORM(POS)
      !>
      !>               CALL TIMOUT ( FINISH,
      !>     .                       'YYYY-MON-DD HR:MN:SC.###',
      !>     .                       TIMSTR                    )
      !>
      !>               WRITE (*, '(A,F16.9)' ) 'Stop time,  drdt = '//
      !>     .                              TIMSTR, DRDT
      !>            END DO
      !>
      !>         END IF
      !>
      !>         WRITE(*,*) ' '
      !>
      !>      END DO
      !>
      !>      END
      !>
      !>C-Procedure GFQ
      !>
      !>      SUBROUTINE GFQ ( ET, VALUE )
      !>      IMPLICIT NONE
      !>
      !>C- Abstract
      !>C
      !>C     User defined geometric quantity function. In this case,
      !>C     the range from the sun to the Moon at TDB time ET.
      !>C
      !>
      !>      DOUBLE PRECISION      ET
      !>      DOUBLE PRECISION      VALUE
      !>
      !>C
      !>C     Local variables.
      !>C
      !>      INTEGER               TARG
      !>      INTEGER               OBS
      !>
      !>      CHARACTER*(12)        REF
      !>      CHARACTER*(12)        ABCORR
      !>
      !>      DOUBLE PRECISION      STATE ( 6 )
      !>      DOUBLE PRECISION      LT
      !>      DOUBLE PRECISION      DVNORM
      !>
      !>C
      !>C     Initialization. Retrieve the vector from the Sun to
      !>C     the Moon in the J2000 frame, without aberration
      !>C     correction.
      !>C
      !>      TARG   = 301
      !>      REF    = 'J2000'
      !>      ABCORR = 'NONE'
      !>      OBS    = 10
      !>
      !>      CALL SPKEZ ( TARG, ET, REF, ABCORR, OBS, STATE, LT )
      !>
      !>C
      !>C     Calculate the scalar range rate corresponding the
      !>C     STATE vector.
      !>C
      !>      VALUE = DVNORM( STATE )
      !>
      !>      END
      !>
      !>C-Procedure GFDECR
      !>
      !>      SUBROUTINE GFDECR ( UDFUNS, ET, ISDECR )
      !>      IMPLICIT NONE
      !>
      !>C- Abstract
      !>C
      !>C     User defined function to detect if the function
      !>C     derivative is negative (the function is decreasing)
      !>C     at TDB time ET.
      !>C
      !>
      !>      EXTERNAL              UDFUNS
      !>      EXTERNAL              UDDF
      !>
      !>      DOUBLE PRECISION      ET
      !>      LOGICAL               ISDECR
      !>
      !>      DOUBLE PRECISION      DT
      !>
      !>      DT = 1.D0
      !>
      !>C
      !>C     Determine if GFQ is decreasing at ET.
      !>C
      !>C     UDDC - the default GF function to determine if
      !>C                the derivative of the user defined
      !>C                function is negative at ET.
      !>C
      !>C     UDFUNS - the user defined scalar quantity function.
      !>C
      !>      CALL UDDC ( UDFUNS, ET, DT, ISDECR )
      !>
      !>      END
      !>```
      !>
      !>        When this program was executed on a Mac/Intel/gfortran/64-bit
      !>        platform, the output was:
      !>
      !>         Relation condition: =
      !>        Start time, drdt = 2007-JAN-02 00:35:19.574       0.336500000
      !>        Stop time,  drdt = 2007-JAN-02 00:35:19.574       0.336500000
      !>        Start time, drdt = 2007-JAN-19 22:04:54.899       0.336500000
      !>        Stop time,  drdt = 2007-JAN-19 22:04:54.899       0.336500000
      !>        Start time, drdt = 2007-FEB-01 23:30:13.428       0.336500000
      !>        Stop time,  drdt = 2007-FEB-01 23:30:13.428       0.336500000
      !>        Start time, drdt = 2007-FEB-17 11:10:46.540       0.336500000
      !>        Stop time,  drdt = 2007-FEB-17 11:10:46.540       0.336500000
      !>        Start time, drdt = 2007-MAR-04 15:50:19.929       0.336500000
      !>        Stop time,  drdt = 2007-MAR-04 15:50:19.929       0.336500000
      !>        Start time, drdt = 2007-MAR-18 09:59:05.959       0.336500000
      !>        Stop time,  drdt = 2007-MAR-18 09:59:05.959       0.336500000
      !>
      !>         Relation condition: <
      !>        Start time, drdt = 2007-JAN-02 00:35:19.574       0.336500000
      !>        Stop time,  drdt = 2007-JAN-19 22:04:54.899       0.336500000
      !>        Start time, drdt = 2007-FEB-01 23:30:13.428       0.336500000
      !>        Stop time,  drdt = 2007-FEB-17 11:10:46.540       0.336500000
      !>        Start time, drdt = 2007-MAR-04 15:50:19.929       0.336500000
      !>        Stop time,  drdt = 2007-MAR-18 09:59:05.959       0.336500000
      !>
      !>         Relation condition: >
      !>        Start time, drdt = 2007-JAN-01 00:00:00.000       0.515522367
      !>        Stop time,  drdt = 2007-JAN-02 00:35:19.574       0.336500000
      !>        Start time, drdt = 2007-JAN-19 22:04:54.899       0.336500000
      !>        Stop time,  drdt = 2007-FEB-01 23:30:13.428       0.336500000
      !>        Start time, drdt = 2007-FEB-17 11:10:46.540       0.336500000
      !>        Stop time,  drdt = 2007-MAR-04 15:50:19.929       0.336500000
      !>        Start time, drdt = 2007-MAR-18 09:59:05.959       0.336500000
      !>        Stop time,  drdt = 2007-APR-01 00:00:00.000       0.793546222
      !>
      !>         Relation condition: LOCMIN
      !>        Start time, drdt = 2007-JAN-11 07:03:58.988      -0.803382743
      !>        Stop time,  drdt = 2007-JAN-11 07:03:58.988      -0.803382743
      !>        Start time, drdt = 2007-FEB-10 06:26:15.438      -0.575837623
      !>        Stop time,  drdt = 2007-FEB-10 06:26:15.438      -0.575837623
      !>        Start time, drdt = 2007-MAR-12 03:28:36.404      -0.441800446
      !>        Stop time,  drdt = 2007-MAR-12 03:28:36.404      -0.441800446
      !>
      !>         Relation condition: ABSMIN
      !>        Start time, drdt = 2007-JAN-11 07:03:58.988      -0.803382743
      !>        Stop time,  drdt = 2007-JAN-11 07:03:58.988      -0.803382743
      !>
      !>         Relation condition: LOCMAX
      !>        Start time, drdt = 2007-JAN-26 02:27:33.767       1.154648992
      !>        Stop time,  drdt = 2007-JAN-26 02:27:33.767       1.154648992
