      !>
      !>           Phase Angle
      !>           Illumination Angle
      !>
      !>        Code edits to implement use of ZZGFRELX in event calculations:
      !>
      !>           Range rate
      !>           Separation angle
      !>           Distance
      !>           Coordinate
      !>
      !>        The code changes for ZZGFRELX use should not affect the
      !>        numerical results of GF computations.
      !>
      !>-    SPICELIB Version 1.1.0, 09-OCT-2009 (NJB) (EDW)
      !>
      !>        Edits to argument descriptions.
      !>
      !>        Added geometric quantities:
      !>
      !>           Range Rate
      !>
      !>-    SPICELIB Version 1.0.0, 19-MAR-2009 (NJB) (EDW)
      module subroutine gfevnt ( ctx, udstep, udrefn, gquant, qnpars, qpnams, qcpars, qdpars, &
            qipars, qlpars, op, refval, tol, adjust, cnfine, rpt, udrepi, udrepu, udrepf, mw, nw, &
            work, bail, udbail, result )
      use pepper_kinds, only: ip, wp
      use pepper_strings, only: ucase_inplace
      use pepper_inc_gf
      use pepper_inc_zzgf
      use pepper_inc_zzabcorr
      implicit none
      integer(ip), parameter :: maxpar = 10
      integer(ip), parameter :: sep = 1
      integer(ip), parameter :: dist = 2
      integer(ip), parameter :: coord = 3
      integer(ip), parameter :: rngrat = 4
      integer(ip), parameter :: phase = 5
      integer(ip), parameter :: iluang = 6
      integer(ip), parameter :: angspd = 7
      integer(ip), parameter :: apdiam = 8
      integer(ip), parameter :: nq = 8
      character(maxcln) :: abcorr
      character(maxcln) :: angtyp
      character(maxcln) :: cornam
      character(maxcln) :: corsys
      character(maxcln) :: cpars  ( maxpar )
      character(maxcln) :: frame  ( 2 )
      character(maxcln) :: illum
      character(maxcln) :: method
      character(maxcln) :: obsrvr
      character(maxcln) :: of     ( 2 )
      character(maxcln) :: pnames ( maxpar )
      character(maxcln), parameter :: qpars ( maxpar, nq ) = reshape ( [ character(maxcln) :: &
         'TARGET1', 'FRAME1', 'SHAPE1', 'TARGET2', 'FRAME2', 'SHAPE2', 'OBSERVER', 'ABCORR', ' ', ' ',&
         'TARGET', 'OBSERVER', 'ABCORR', ' ', ' ', ' ', ' ', ' ', ' ', ' ',&
         'TARGET', 'OBSERVER', 'ABCORR', 'COORDINATE SYSTEM', 'COORDINATE', 'REFERENCE FRAME', 'VECTOR DEFINITION', 'METHOD', 'DVEC', 'DREF',&
         'TARGET', 'OBSERVER', 'ABCORR', ' ', ' ', ' ', ' ', ' ', ' ', ' ',&
         'TARGET', 'OBSERVER', 'ILLUM', 'ABCORR', ' ', ' ', ' ', ' ', ' ', ' ',&
         'TARGET', 'ILLUM', 'OBSERVER', 'ABCORR', 'REFERENCE FRAME', 'ANGTYP', 'METHOD', 'SPOINT', ' ', ' ',&
         'TARGET1', 'TARGET2', 'OBSERVER', 'ABCORR', 'REFERENCE FRAME', ' ', ' ', ' ', ' ', ' ',&
         'TARGET', 'OBSERVER', 'ABCORR', 'REFERENCE FRAME', ' ', ' ', ' ', ' ', ' ', ' ' ], &
         [ maxpar, nq ] )
      character(maxcln) :: quant
      character(maxcln) :: ref
      character(maxcln) :: shape  ( 2 )
      character(maxcln) :: target
      character(maxcln) :: vecdef
      character(maxop) :: uop
      character(mxbegm) :: rptpre ( 2 )
      real(wp) :: dt
      integer(ip) :: i
      integer(ip) :: loc
      integer(ip) :: npass
      integer(ip) :: qtnum
      logical :: localx
      logical :: noadjx
      real(wp) :: dvec   ( 3 )
      real(wp) :: spoint ( 3 )
      class(pepper_context), intent(inout) :: ctx  !! the context
      character(*), intent(in) :: gquant  !! Type of geometric quantity.
      integer(ip), intent(in) :: qnpars  !! Number of quantity definition parameters.
      character(*), intent(in) :: qpnams ( * )  !! Names of quantity definition parameters.
      character(*), intent(in) :: qcpars ( * )  !! Array of character quantity definition parameters.
      real(wp), intent(in) :: qdpars ( * )  !! Array of double precision quantity definition parameters.
      integer(ip), intent(in) :: qipars ( * )  !! Array of integer quantity definition parameters.
      logical, intent(in) :: qlpars ( * )  !! Array of logical quantity definition parameters.
      character(*), intent(in) :: op  !! Operator that either looks for an extreme value (max, min, local, absolute) or compares the geometric quantity value and a number.
      real(wp), intent(in) :: refval  !! Reference value.
      real(wp), intent(in) :: tol  !! Convergence tolerance in seconds
      real(wp), intent(in) :: adjust  !! Absolute extremum adjustment value.
      real(wp), intent(in) :: cnfine ( lbcell : * )  !! SPICE window to which the search is restricted.
      logical, intent(in) :: rpt  !! Progress reporter on (.TRUE.) or off (.FALSE.).
      integer(ip), intent(in) :: mw  !! Size of workspace windows.
      integer(ip), intent(in) :: nw  !! The number of workspace windows needed for the search.
      real(wp), intent(inout) :: work   ( lbcell : mw, nw )  !! Array containing workspace windows.
      logical, intent(in) :: bail  !! Logical indicating program interrupt monitoring.
      procedure(gf_bail) :: udbail  !! Name of a routine that signals a program interrupt.
      real(wp), intent(inout) :: result ( lbcell : * )  !! SPICE window containing results.
      procedure(gf_step) :: udstep  !! Name of the routine that computes and returns a time step.
      procedure(gf_refine) :: udrefn  !! Name of the routine that computes a refined time.
      procedure(gf_rep_init) :: udrepi  !! Function that initializes progress reporting.
      procedure(gf_rep_update) :: udrepu  !! Function that updates the progress report.
      procedure(gf_rep_final) :: udrepf  !! Function that finalizes progress reporting.
      if ( .not. allocated ( ctx%gfevnt_state ) ) allocate ( ctx%gfevnt_state )
      associate ( first => ctx%gfevnt_state%first, &
                  cnames => ctx%gfevnt_state%cnames, &
                  dref => ctx%gfevnt_state%dref, &
                  qnames => ctx%gfevnt_state%qnames, &
                  srcpre => ctx%gfevnt_state%srcpre, &
                  srcsuf => ctx%gfevnt_state%srcsuf )
      if ( ctx%failed() ) return

      if ( first ) then

!
!        Set the progress report prefix and suffix strings for
!        each quantity. No need to set coordinate quantity strings.
!        The coordinate solver performs that function.
!
         first = .false.

         srcpre ( 1, sep    ) = 'Angular separation pass 1 of #'
         srcpre ( 2, sep    ) = 'Angular separation pass 2 of #'

         srcpre ( 1, dist   ) = 'Distance pass 1 of # '
         srcpre ( 2, dist   ) = 'Distance pass 2 of # '

         srcpre ( 1, angspd ) = 'Angular Rate pass 1 of #'
         srcpre ( 2, angspd ) = 'Angular Rate pass 2 of #'

         srcpre ( 1, rngrat ) = 'Range Rate pass 1 of #'
         srcpre ( 2, rngrat ) = 'Range Rate pass 2 of #'

         srcpre ( 1, phase  ) = 'Phase angle search pass 1 of #'
         srcpre ( 2, phase  ) = 'Phase angle search pass 2 of #'

         srcpre ( 1, apdiam ) = 'Diameter pass 1 of #'
         srcpre ( 2, apdiam ) = 'Diameter pass 2 of #'

         srcpre ( 1, iluang ) = 'Illumination angle pass 1 of #'
         srcpre ( 2, iluang ) = 'Illumination angle pass 2 of #'

         srcsuf ( 1, sep    ) = 'done.'
         srcsuf ( 2, sep    ) = 'done.'

         srcsuf ( 1, dist   ) = 'done.'
         srcsuf ( 2, dist   ) = 'done.'

         srcsuf ( 1, angspd ) = 'done.'
         srcsuf ( 2, angspd ) = 'done.'

         srcsuf ( 1, rngrat ) = 'done.'
         srcsuf ( 2, rngrat ) = 'done.'

         srcsuf ( 1, phase  ) = 'done.'
         srcsuf ( 2, phase  ) = 'done.'

         srcsuf ( 1, apdiam ) = 'done.'
         srcsuf ( 2, apdiam ) = 'done.'

         srcsuf ( 1, iluang ) = 'done.'
         srcsuf ( 2, iluang ) = 'done.'

      end if

!
!     Make sure the requested quantity is one we recognize.
!

      quant = adjustl(gquant)
      call ucase_inplace ( quant )

      qtnum = findloc(qnames, quant, dim=1)

      if ( qtnum == 0 ) then

        call ctx%setmsg ('The geometric quantity, # is not '             // &
                     'recognized. Supported quantities are: '        // &
                     'DISTANCE, '                                    // &
                     'PHASE ANGLE, '                                 // &
                     'COORDINATE, '                                  // &
                     'RANGE RATE, '                                  // &
                     'ANGULAR SEPARATION,'                           // &
                     'ILLUMINATION ANGLE.'                            )
         call ctx%errch  ('#', gquant                                     )
         call ctx%sigerr ('SPICE(NOTRECOGNIZED)'                          )
         return

      end if

!
!     Check number of quantity definition parameters.
!
      if (  ( qnpars < 0 ) .or. ( qnpars > maxpar )  ) then

         call ctx%setmsg ( 'Number of quantity definition parameters = ' // &
                       '#;  must be in range 0:#.'                    )
         call ctx%errint ( '#', qnpars                                    )
         call ctx%errint ( '#', maxpar                                    )
         call ctx%sigerr ( 'SPICE(INVALIDCOUNT)'                          )
         return

      end if

!
!     Make left-justified, upper case copies of parameter names.
!
      do i = 1, qnpars

         pnames(i) = adjustl(qpnams(i))
         call ucase_inplace ( pnames(i) )

         cpars(i) = adjustl(qcpars(i))
         call ucase_inplace ( cpars(i) )

      end do

!
!     Make sure all parameters have been supplied for the requested
!     quantity.
!
      do i = 1, maxpar

         if ( qpars(i,qtnum) /= ' ' ) then
!
!           The Ith parameter must be supplied by the caller.
!
            loc = findloc(pnames(1:qnpars), qpars(i,qtnum), dim=1)

            if ( loc == 0 ) then

               call ctx%setmsg ( 'The parameter # is required in order ' // &
                             'to compute events pertaining to the '  // &
                             'quantity #; this parameter was not '   // &
                             'supplied.'                             )
               call ctx%errch  ( '#', qpars (i,qtnum)                    )
               call ctx%errch  ( '#', qnames(  qtnum)                    )
               call ctx%sigerr ( 'SPICE(MISSINGVALUE)'                   )
               return

            end if

         end if

      end do

!
!     Capture as local variables those parameters passed from the
!     callers.
!
!     If the PNAMES array contains any of the parameters
!
!        TARGET
!        OBSERVER
!        ILLUM
!        TARGET1
!        FRAME1
!        SHAPE1
!        TARGET2
!        FRAME2
!        SHAPE2
!        ABCORR
!        REFERENCE FRAME
!        DREF
!        DVEC
!
!     copy the value corresponding to the parameter to a local variable.
!
!     These operations demonstrate the need for associative arrays
!     as part of Fortran.
!

!
!     -TARGET-
!
      loc = findloc(pnames(1:qnpars), 'TARGET', dim=1)

      if ( loc > 0 ) then

         target = cpars(loc)

      end if

!
!     -OBSERVER-
!
      loc = findloc(pnames(1:qnpars), 'OBSERVER', dim=1)

      if ( loc > 0 ) then

         obsrvr = cpars(loc)

      end if

!
!     -ILLUM-
!
      loc = findloc(pnames(1:qnpars), 'ILLUM', dim=1)

      if ( loc > 0 ) then

         illum = cpars(loc)

      end if

!
!     -TARGET1-
!
      loc = findloc(pnames(1:qnpars), 'TARGET1', dim=1)

      if ( loc > 0 ) then

         of(1) = cpars(loc)

      end if

!
!     -TARGET2-
!
      loc = findloc(pnames(1:qnpars), 'TARGET2', dim=1)

      if ( loc > 0 ) then

         of(2) = cpars(loc)

      end if

!
!     -FRAME1-
!
      loc = findloc(pnames(1:qnpars), 'FRAME1', dim=1)

      if ( loc > 0 ) then

         frame(1) = cpars(loc)

      end if

!
!     -FRAME2-
!
      loc = findloc(pnames(1:qnpars), 'FRAME2', dim=1)

      if ( loc > 0 ) then

         frame(2) = cpars(loc)

      end if

!
!     -SHAPE1-
!
      loc = findloc(pnames(1:qnpars), 'SHAPE1', dim=1)

      if ( loc > 0 ) then

         shape(1) = cpars(loc)

      end if

!
!     -SHAPE2-
!
      loc = findloc(pnames(1:qnpars), 'SHAPE2', dim=1)

      if ( loc > 0 ) then

         shape(2) = cpars(loc)

      end if

!
!     -ABCORR-
!
      loc = findloc(pnames(1:qnpars), 'ABCORR', dim=1)

      if ( loc > 0 ) then

         abcorr = cpars(loc)

      end if

!
!     -REFERENCE FRAME-
!
      loc = findloc(pnames(1:qnpars), 'REFERENCE FRAME', dim=1)

      if ( loc > 0 ) then

         ref = cpars(loc)

      end if

!
!     -COORDINATE SYSTEM-
!
      loc = findloc(qpnams(1:qnpars), 'COORDINATE SYSTEM', dim=1)

      if ( loc > 0 ) then

         corsys = qcpars(loc)

      end if

!
!     -COORDINATE-
!
      loc = findloc(qpnams(1:qnpars), 'COORDINATE', dim=1)

      if ( loc > 0 ) then

         cornam = qcpars(loc)

      end if

!
!     -VECTOR DEFINITION-
!
      loc = findloc(qpnams(1:qnpars), 'VECTOR DEFINITION', dim=1)

      if ( loc > 0 ) then

         vecdef = qcpars(loc)

      end if

!
!     -DVEC-
!
      loc = findloc(pnames(1:qnpars), 'DVEC', dim=1)

      if ( loc > 0 ) then

         dvec(1:3) = qdpars(1:3)

      end if

!
!     -METHOD-
!
      loc = findloc(qpnams(1:qnpars), 'METHOD', dim=1)

      if ( loc > 0 ) then

         method = qcpars(loc)

      end if

!
!     -DREF-
!
      loc = findloc(pnames(1:qnpars), 'DREF', dim=1)

      if ( loc > 0 ) then

         dref = cpars(loc)

      end if

!
!     -ANGTYP-
!
      loc = findloc(pnames(1:qnpars), 'ANGTYP', dim=1)

      if ( loc > 0 ) then

         angtyp = cpars(loc)

      end if

!
!     -SPOINT-
!
      loc = findloc(pnames(1:qnpars), 'SPOINT', dim=1)

      if ( loc > 0 ) then

         spoint = qdpars(1:3)

      end if

!
!     Make sure that the requested comparison operation is one we
!     recognize.
!

      uop = adjustl(op)
      call ucase_inplace ( uop )

      loc = findloc(cnames, uop, dim=1)

      if ( loc == 0 ) then

        call ctx%setmsg ('The comparison operator, # is not '            // &
                     'recognized.  Supported operators are: '        // &
                     '>, '                                           // &
                     '=, '                                           // &
                     '<, '                                           // &
                     'ABSMAX, '                                      // &
                     'ABSMIN, '                                      // &
                     'LOCMAX, '                                      // &
                     'LOCMIN. '                                       )
         call ctx%errch  ('#', op                                         )
         call ctx%sigerr ('SPICE(NOTRECOGNIZED)'                          )
         return

      end if

!
!     If progress reporting is enabled, set the report prefix array
!     according to the quantity and the relational operator.
!
      if ( rpt ) then
!
!        We'll use the logical flag LOCALX to indicate a local extremum
!        operator and the flag NOADJX to indicate an absolute extremum
!        operator with zero adjustment.
!
         localx = ( uop == 'LOCMIN' ) .or. ( uop == 'LOCMAX' )

         noadjx =  ( adjust ==  0.0_wp    ) .and. &
                 ( ( uop    == 'ABSMIN' ) .or. ( uop == 'ABSMAX' ) )

         if ( localx .or. noadjx ) then

!
!           These operators correspond to 1-pass searches.
!
            npass = 1

         else

            npass = 2

         end if

!
!        Fill in the prefix strings.
!
!        Note that we've already performed error checks on QTNUM.
!
         do i = 1, npass
            call repmi ( ctx, srcpre(i,qtnum), '#', npass, rptpre(i) )
         end do

      end if

!
!     Here's where the real work gets done:  we solve for the
!     result window.  The code below is quantity-specific.  However,
!     in each case, we always initialize the utility routines for
!     the quantity of interest, then call the generic relation
!     pre-image solver ZZGFREL.
!
      if ( qtnum == sep ) then

!
!        Separation condition initializer.
!
         call zzgfspin( ctx, of, obsrvr, shape, frame, abcorr )

         call zzgfrelx( ctx, udstep,        udrefn,   zzgfspdc, &
                        zzgfudlt,      zzgfspgq, &
                        op,            refval,   tol, &
                        adjust,        cnfine,   mw,      nw, &
                        work,          rpt,      udrepi, &
                        udrepu,        udrepf,   rptpre, &
                        srcsuf(1,sep), bail,     udbail, &
                        result  )

      else if ( qtnum == dist ) then

!
!        Distance condition initializer.
!
         call zzgfdiin ( ctx, target, abcorr, obsrvr )

         call zzgfrelx( ctx, udstep,         udrefn,   zzgfdidc, &
                        zzgfudlt,       zzgfdigq, &
                        op,             refval,   tol, &
                        adjust,         cnfine,   mw,     nw, &
                        work,           rpt,      udrepi, &
                        udrepu,         udrepf,   rptpre, &
                        srcsuf(1,dist), bail,     udbail, &
                        result  )

      else if ( qtnum == coord ) then

!
!        Solve for a coordinate condition. ZZGFCSLV calls the coordinate
!        event initializer.
!
         call  zzgfcslv ( ctx, vecdef, method, target, ref,    abcorr, &
                          obsrvr, dref,   dvec,   corsys, cornam, &
                          op,     refval, tol,    adjust, udstep, &
                          udrefn, rpt,    udrepi, udrepu, udrepf, &
                          bail,   udbail, mw,     nw,     work, &
                          cnfine, result                        )

      else if ( qtnum == angspd  ) then

!
!        d( sep )
!        --------     ---Not yet implemented---
!        dt
!

      else if ( qtnum == rngrat ) then

!
!        Range rate condition initializer.
!
!        Default the interval for the QDERIV call in ZZGFRRDC to one
!        TDB second. This should have a function interface to
!        reset.
!
         dt = 1.0_wp

         call zzgfrrin ( ctx, target, abcorr, obsrvr, dt )

         call zzgfrelx( ctx, udstep,           udrefn,   zzgfrrdc, &
                        zzgfudlt,         zzgfrrgq, &
                        op,               refval,   tol, &
                        adjust,           cnfine,   mw,      nw, &
                        work,             rpt,      udrepi, &
                        udrepu,           udrepf,   rptpre, &
                        srcsuf(1,rngrat), bail,     udbail, &
                        result  )

      else if ( qtnum == phase ) then

!
!        Phase angle condition initializer.
!
         call zzgfpain ( ctx, target, illum, abcorr, obsrvr )

         call zzgfrelx( ctx, udstep,          udrefn,   zzgfpadc, &
                        zzgfudlt,        zzgfpagq, &
                        op,              refval,   tol, &
                        adjust,          cnfine,   mw,     nw, &
                        work,            rpt,      udrepi, &
                        udrepu,          udrepf,   rptpre, &
                        srcsuf(1,phase), bail,     udbail, &
                        result  )

      else if ( qtnum == apdiam ) then

!
!                ---Not yet implemented---
!

      else if ( qtnum == iluang ) then
!
!        Illumination angle condition initializer.
!
         call zzgfilin ( ctx, method, angtyp, target, illum, &
                         ref,    abcorr, obsrvr, spoint )

         call zzgfrelx( ctx, udstep,           udrefn,   zzgfildc, &
                        zzgfudlt,         zzgfilgq, &
                        op,               refval,   tol, &
                        adjust,           cnfine,   mw,       nw, &
                        work,             rpt,      udrepi, &
                        udrepu,           udrepf,   rptpre, &
                        srcsuf(1,iluang), bail,     udbail, &
                        result                                   )

      else

!
!        QTNUM is not a recognized event code. This block should
!        never execute since we already checked the input quantity
!        name string.
!
         call ctx%setmsg ( 'Unknown event ''#''. This error indicates ' &
                    // 'a bug. Please contact NAIF.' )
         call ctx%errch  ( '#', gquant            )
         call ctx%sigerr ( 'SPICE(BUG)'           )
         return

      end  if

      return
      end associate
      end subroutine gfevnt

      !> Determine time intervals over which a specified constraint on
      !> observer-target distance is met.
      !>
      !>## Detailed Input
      !>
      !>     TARGET   is the name of a target body. Optionally, you may supply
      !>              the integer ID code for the object as an integer string.
      !>              For example both 'MOON' and '301' are legitimate strings
      !>              that indicate the Moon is the target body.
      !>
      !>              The target and observer define a position vector which
      !>              points from the observer to the target; the length of
      !>              this vector is the "distance" that serves as the subject
      !>              of the search performed by this routine.
      !>
      !>              Case and leading or trailing blanks are not significant
      !>              in the string TARGET.
      !>
      !>     ABCORR   indicates the aberration corrections to be applied to the
      !>              observer-target position vector to account for one-way
      !>              light time and stellar aberration.
      !>
      !>              Any aberration correction accepted by the SPICE routine
      !>              SPKEZR is accepted here. See the header of SPKEZR for a
      !>              detailed description of the aberration correction
      !>              options. For convenience, the options are listed below:
      !>
      !>                 'NONE'     Apply no correction.
      !>
      !>                 'LT'       "Reception" case: correct for
      !>                            one-way light time using a Newtonian
      !>                            formulation.
      !>
      !>                 'LT+S'     "Reception" case: correct for
      !>                            one-way light time and stellar
      !>                            aberration using a Newtonian
      !>                            formulation.
      !>
      !>                 'CN'       "Reception" case: converged
      !>                            Newtonian light time correction.
      !>
      !>                 'CN+S'     "Reception" case: converged
      !>                            Newtonian light time and stellar
      !>                            aberration corrections.
      !>
      !>                 'XLT'      "Transmission" case: correct for
      !>                            one-way light time using a Newtonian
      !>                            formulation.
      !>
      !>                 'XLT+S'    "Transmission" case: correct for
      !>                            one-way light time and stellar
      !>                            aberration using a Newtonian
      !>                            formulation.
      !>
      !>                 'XCN'      "Transmission" case: converged
      !>                            Newtonian light time correction.
      !>
      !>                 'XCN+S'    "Transmission" case: converged
      !>                            Newtonian light time and stellar
      !>                            aberration corrections.
      !>
      !>              Case and leading or trailing blanks are not significant
      !>              in the string ABCORR.
      !>
      !>     OBSRVR   is the name of an observing body. Optionally, you may
      !>              supply the ID code of the object as an integer string.
      !>              For example, both 'EARTH' and '399' are legitimate
      !>              strings to supply to indicate the observer is Earth.
      !>
      !>              Case and leading or trailing blanks are not significant
      !>              in the string OBSRVR.
      !>
      !>     RELATE   is a relational operator used to define a constraint on
      !>              the observer-target distance. The result window found by
      !>              this routine indicates the time intervals where the
      !>              constraint is satisfied.
      !>
      !>              Supported values of RELATE and corresponding meanings are
      !>              shown below:
      !>
      !>                 '>'        Distance is greater than the reference
      !>                            value REFVAL.
      !>
      !>                 '='        Distance is equal to the reference
      !>                            value REFVAL.
      !>
      !>                 '<'        Distance is less than the reference
      !>                            value REFVAL.
      !>
      !>                 'ABSMAX'   Distance is at an absolute maximum.
      !>
      !>                 'ABSMIN'   Distance is at an absolute  minimum.
      !>
      !>                 'LOCMAX'   Distance is at a local maximum.
      !>
      !>                 'LOCMIN'   Distance is at a local minimum.
      !>
      !>              The caller may indicate that the region of interest is
      !>              the set of time intervals where the distance is within a
      !>              specified offset relative to an absolute extremum. The
      !>              argument ADJUST (described below) is used to specify this
      !>              offset.
      !>
      !>              Local extrema are considered to exist only in the
      !>              interiors of the intervals comprising the confinement
      !>              window:  a local extremum cannot exist at a boundary
      !>              point of the confinement window.
      !>
      !>              Case and leading or trailing blanks are not significant
      !>              in the string RELATE.
      !>
      !>     REFVAL   is the reference value used together with the argument
      !>              RELATE to define an equality or inequality to be
      !>              satisfied by the distance between the specified target
      !>              and observer. See the discussion of RELATE above for
      !>              further information.
      !>
      !>              The units of REFVAL are km.
      !>
      !>     ADJUST   is a parameter used to modify searches for absolute
      !>              extrema: when RELATE is set to 'ABSMAX' or 'ABSMIN' and
      !>              ADJUST is set to a positive value, GFDIST will find times
      !>              when the observer-target distance is within ADJUST km of
      !>              the specified extreme value.
      !>
      !>              If ADJUST is non-zero and a search for an absolute
      !>              minimum AMIN is performed, the result window contains
      !>              time intervals when the observer-target distance has
      !>              values between AMIN and AMIN + ADJUST.
      !>
      !>              If the search is for an absolute maximum AMAX, the
      !>              corresponding range is  between AMAX - ADJUST and AMAX.
      !>
      !>              ADJUST is not used for searches for local extrema,
      !>              equality or inequality conditions.
      !>
      !>     STEP     is the step size to be used in the search. STEP must be
      !>              shorter than any maximal time interval on which the
      !>              specified distance function is monotone increasing or
      !>              decreasing. That is, if the confinement window is
      !>              partitioned into alternating intervals on which the
      !>              distance function is either monotone increasing or
      !>              decreasing, STEP must be shorter than any of these
      !>              intervals.
      !>
      !>              However, STEP must not be *too* short, or the search will
      !>              take an unreasonable amount of time.
      !>
      !>              The choice of STEP affects the completeness but not the
      !>              precision of solutions found by this routine; the
      !>              precision is controlled by the convergence tolerance. See
      !>              the discussion of the parameter CNVTOL for details.
      !>
      !>              STEP has units of TDB seconds.
      !>
      !>     CNFINE   is a SPICE window that confines the time period over
      !>              which the specified search is conducted. CNFINE may
      !>              consist of a single interval or a collection of
      !>              intervals.
      !>
      !>              The endpoints of the time intervals comprising CNFINE are
      !>              interpreted as seconds past J2000 TDB.
      !>
      !>              See the $Examples section below for a code example that
      !>              shows how to create a confinement window.
      !>
      !>              CNFINE must be initialized by the caller via the SPICELIB
      !>              routine SSIZED.
      !>
      !>              In some cases the observer's state may be computed at
      !>              times outside of CNFINE by as much as 2 seconds. See
      !>              $Particulars for details.
      !>
      !>     MW       is a parameter specifying the length of the SPICE windows
      !>              in the workspace array WORK (see description below) used
      !>              by this routine.
      !>
      !>              MW should be set to a number at least twice as large as
      !>              the maximum number of intervals required by any workspace
      !>              window. In many cases, it's not necessary to compute an
      !>              accurate estimate of how many intervals are needed;
      !>              rather, the user can pick a size considerably larger than
      !>              what's really required.
      !>
      !>              However, since excessively large arrays can prevent
      !>              applications from compiling, linking, or running
      !>              properly, sometimes MW must be set according to the
      !>              actual workspace requirement. A rule of thumb for the
      !>              number of intervals NINTVLS needed is
      !>
      !>                 NINTVLS  =  2*N  +  ( M / STEP )
      !>
      !>              where
      !>
      !>                 N     is the number of intervals in the confinement
      !>                       window
      !>
      !>                 M     is the measure of the confinement window, in
      !>                       units of seconds
      !>
      !>                 STEP  is the search step size in seconds
      !>
      !>              MW should then be set to
      !>
      !>                 2 * NINTVLS
      !>
      !>     NW       is a parameter specifying the number of SPICE windows in
      !>              the workspace array WORK (see description below) used by
      !>              this routine. NW should be set to the parameter NWDIST;
      !>              this parameter is declared in the include file gf.inc.
      !>              (The reason this dimension is an input argument is that
      !>              this allows run-time error checking to be performed.)
      !>
      !>     RESULT   is a double precision SPICE window which will contain
      !>              the search results. RESULT must be declared and
      !>              initialized with sufficient size to capture the full
      !>              set of time intervals within the search region on which
      !>              the specified condition is satisfied.
      !>
      !>              RESULT must be initialized by the caller via the
      !>              SPICELIB routine SSIZED.
      !>
      !>              If RESULT is non-empty on input, its contents will be
      !>              discarded before GFDIST conducts its search.
      !>
      !>## Detailed Output
      !>
      !>     WORK     is an array used to store workspace windows.
      !>
      !>              This array should be declared by the caller as shown:
      !>
      !>                 INCLUDE 'gf.inc'
      !>                    ...
      !>
      !>                 DOUBLE PRECISION    WORK ( LBCELL : MW, NWDIST )
      !>
      !>              where MW is a constant declared by the caller and NWDIST
      !>              is a constant defined in the SPICELIB INCLUDE file
      !>              gf.inc. See the discussion of MW above.
      !>
      !>              WORK need not be initialized by the caller.
      !>
      !>              WORK is modified by this routine. The caller should
      !>              re-initialize this array before attempting to use it for
      !>              any other purpose.
      !>
      !>     RESULT   is the SPICE window of intervals, contained within the
      !>              confinement window CNFINE, on which the specified
      !>              distance constraint is satisfied.
      !>
      !>              The endpoints of the time intervals comprising RESULT
      !>              are interpreted as seconds past J2000 TDB.
      !>
      !>              If the search is for local extrema, or for absolute
      !>              extrema with ADJUST set to zero, then normally each
      !>              interval of RESULT will be a singleton: the left and
      !>              right endpoints of each interval will be identical.
      !>
      !>              If no times within the confinement window satisfy the
      !>              search criteria, RESULT will be returned with a
      !>              cardinality of zero.
      !>
      !>## Parameters
      !>
      !>     LBCELL   is the lower bound for SPICE Cell arrays.
      !>
      !>     CNVTOL   is the convergence tolerance used for finding
      !>              endpoints of the intervals comprising the result
      !>              window. CNVTOL is also used for finding intermediate
      !>              results; in particular, CNVTOL is used for finding the
      !>              windows on which the specified distance is increasing
      !>              or decreasing. CNVTOL is used to determine when binary
      !>              searches for roots should terminate: when a root is
      !>              bracketed within an interval of length CNVTOL; the
      !>              root is considered to have been found.
      !>
      !>              The accuracy, as opposed to precision, of roots found
      !>              by this routine depends on the accuracy of the input
      !>              data. In most cases, the accuracy of solutions will be
      !>              inferior to their precision.
      !>
      !>     NWDIST   is the number of workspace windows required by
      !>              this routine.
      !>
      !>     See INCLUDE file gf.inc for declarations and descriptions of
      !>     parameters used throughout the GF system.
      !>
      !>## Exceptions
      !>
      !>     1)  In order for this routine to produce correct results,
      !>         the step size must be appropriate for the problem at hand.
      !>         Step sizes that are too large may cause this routine to miss
      !>         roots; step sizes that are too small may cause this routine
      !>         to run unacceptably slowly and in some cases, find spurious
      !>         roots.
      !>
      !>         This routine does not diagnose invalid step sizes, except that
      !>         if the step size is non-positive, an error is signaled by a
      !>         routine in the call tree of this routine.
      !>
      !>     2)  Due to numerical errors, in particular,
      !>
      !>            - Truncation error in time values
      !>            - Finite tolerance value
      !>            - Errors in computed geometric quantities
      !>
      !>         it is *normal* for the condition of interest to not always be
      !>         satisfied near the endpoints of the intervals comprising the
      !>         result window.
      !>
      !>         The result window may need to be contracted slightly by the
      !>         caller to achieve desired results. The SPICE window routine
      !>         WNCOND can be used to contract the result window.
      !>
      !>     3)  If an error (typically cell overflow) occurs while performing
      !>         window arithmetic, the error is signaled by a routine
      !>         in the call tree of this routine.
      !>
      !>     4)  If the relational operator RELATE is not recognized, an
      !>         error is signaled by a routine in the call tree of this
      !>         routine.
      !>
      !>     5)  If the aberration correction specifier contains an
      !>         unrecognized value, an error is signaled by a routine in the
      !>         call tree of this routine.
      !>
      !>     6)  If ADJUST is negative, an error is signaled by a routine in
      !>         the call tree of this routine.
      !>
      !>     7)  If either of the input body names do not map to NAIF ID
      !>         codes, an error is signaled by a routine in the call tree of
      !>         this routine.
      !>
      !>     8)  If required ephemerides or other kernel data are not
      !>         available, an error is signaled by a routine in the call tree
      !>         of this routine.
      !>
      !>     9)  If the window size MW is less than 2, the error
      !>         SPICE(INVALIDDIMENSION) is signaled.
      !>
      !>     10) If the window count NW is less than NWDIST, the error
      !>         SPICE(INVALIDDIMENSION) is signaled.
      !>
      !>     11) If the result window has size less than 2, the error
      !>         SPICE(INVALIDDIMENSION) is signaled.
      !>
      !>     12) If the output SPICE window RESULT has insufficient capacity
      !>         to contain the number of intervals on which the specified
      !>         distance condition is met, an error is signaled
      !>         by a routine in the call tree of this routine.
      !>
      !>## Files
      !>
      !>     Appropriate kernels must be loaded by the calling program before
      !>     this routine is called.
      !>
      !>     The following data are required:
      !>
      !>     -  SPK data: ephemeris data for target and observer for the
      !>        time period defined by the confinement window must be
      !>        loaded. If aberration corrections are used, the states of
      !>        target and observer relative to the solar system barycenter
      !>        must be calculable from the available ephemeris data.
      !>        Typically ephemeris data are made available by loading one
      !>        or more SPK files via FURNSH.
      !>
      !>     -  If non-inertial reference frames are used, then PCK
      !>        files, frame kernels, C-kernels, and SCLK kernels may be
      !>        needed.
      !>
      !>     -  In some cases the observer's state may be computed at times
      !>        outside of CNFINE by as much as 2 seconds; data required to
      !>        compute this state must be provided by loaded kernels. See
      !>        $Particulars for details.
      !>
      !>     Kernel data are normally loaded once per program run, NOT every
      !>     time this routine is called.
      !>
      !>## Particulars
      !>
      !>     This routine determines a set of one or more time intervals
      !>     within the confinement window when the distance between the
      !>     specified target and observer satisfies a caller-specified
      !>     constraint. The resulting set of intervals is returned as a SPICE
      !>     window.
      !>
      !>     Below we discuss in greater detail aspects of this routine's
      !>     solution process that are relevant to correct and efficient
      !>     use of this routine in user applications.
      !>
      !>     The Search Process
      !>     ==================
      !>
      !>     Regardless of the type of constraint selected by the caller, this
      !>     routine starts the search for solutions by determining the time
      !>     periods, within the confinement window, over which the
      !>     distance function is monotone increasing and monotone
      !>     decreasing. Each of these time periods is represented by a SPICE
      !>     window. Having found these windows, all of the range rate
      !>     function's local extrema within the confinement window are known.
      !>     Absolute extrema then can be found very easily.
      !>
      !>     Within any interval of these "monotone" windows, there will be at
      !>     most one solution of any equality constraint. Since the boundary
      !>     of the solution set for any inequality constraint is contained in
      !>     the union of
      !>
      !>     -  the set of points where an equality constraint is met
      !>
      !>     -  the boundary points of the confinement window
      !>
      !>     the solutions of both equality and inequality constraints can be
      !>     found easily once the monotone windows have been found.
      !>
      !>     Step Size
      !>     =========
      !>
      !>     The monotone windows (described above) are found via a two-step
      !>     search process. Each interval of the confinement window is
      !>     searched as follows: first, the input step size is the time
      !>     separation at which the sign of the rate of change of distance
      !>     ("range rate") is sampled. Starting at the left endpoint of the
      !>     interval, samples will be taken at each step. If a change of sign
      !>     is found, a root has been bracketed; at that point, the time at
      !>     which the range rate is zero can be found by a refinement
      !>     process, for example, via binary search.
      !>
      !>     Note that the optimal choice of step size depends on the lengths
      !>     of the intervals over which the distance function is monotone:
      !>     the step size should be shorter than the shortest of these
      !>     intervals (within the confinement window).
      !>
      !>     The optimal step size is *not* necessarily related to the lengths
      !>     of the intervals comprising the result window. For example, if
      !>     the shortest monotone interval has length 10 days, and if the
      !>     shortest result window interval has length 5 minutes, a step size
      !>     of 9.9 days is still adequate to find all of the intervals in the
      !>     result window. In situations like this, the technique of using
      !>     monotone windows yields a dramatic efficiency improvement over a
      !>     state-based search that simply tests at each step whether the
      !>     specified constraint is satisfied. The latter type of search can
      !>     miss solution intervals if the step size is longer than the
      !>     shortest solution interval.
      !>
      !>     Having some knowledge of the relative geometry of the target and
      !>     observer can be a valuable aid in picking a reasonable step size.
      !>     In general, the user can compensate for lack of such knowledge by
      !>     picking a very short step size; the cost is increased computation
      !>     time.
      !>
      !>     Note that the step size is not related to the precision with which
      !>     the endpoints of the intervals of the result window are computed.
      !>     That precision level is controlled by the convergence tolerance.
      !>
      !>     Convergence Tolerance
      !>     =====================
      !>
      !>     As described above, the root-finding process used by this routine
      !>     involves first bracketing roots and then using a search process
      !>     to locate them. "Roots" include times when extrema are attained
      !>     and times when the distance function is equal to a reference
      !>     value or adjusted extremum. All endpoints of the intervals
      !>     comprising the result window are either endpoints of intervals of
      !>     the confinement window or roots.
      !>
      !>     Once a root has been bracketed, a refinement process is used to
      !>     narrow down the time interval within which the root must lie.
      !>     This refinement process terminates when the location of the root
      !>     has been determined to within an error margin called the
      !>     "convergence tolerance." The default convergence tolerance
      !>     used by this routine is set by the parameter CNVTOL (defined
      !>     in gf.inc).
      !>
      !>     The value of CNVTOL is set to a "tight" value so that the
      !>     tolerance doesn't become the limiting factor in the accuracy of
      !>     solutions found by this routine. In general the accuracy of input
      !>     data will be the limiting factor.
      !>
      !>     The user may change the convergence tolerance from the default
      !>     CNVTOL value by calling the routine GFSTOL, e.g.
      !>
      !>        CALL GFSTOL( tolerance value )
      !>
      !>     Call GFSTOL prior to calling this routine. All subsequent
      !>     searches will use the updated tolerance value.
      !>
      !>     Setting the tolerance tighter than CNVTOL is unlikely to be
      !>     useful, since the results are unlikely to be more accurate.
      !>     Making the tolerance looser will speed up searches somewhat,
      !>     since a few convergence steps will be omitted. However, in most
      !>     cases, the step size is likely to have a much greater effect
      !>     on processing time than would the convergence tolerance.
      !>
      !>     The Confinement Window
      !>     ======================
      !>
      !>     The simplest use of the confinement window is to specify a time
      !>     interval within which a solution is sought. However, the
      !>     confinement window can, in some cases, be used to make searches
      !>     more efficient. Sometimes it's possible to do an efficient search
      !>     to reduce the size of the time period over which a relatively
      !>     slow search of interest must be performed. See the "CASCADE"
      !>     example program in gf.req for a demonstration.
      !>
      !>     Certain types of searches require the state of the observer,
      !>     relative to the solar system barycenter, to be computed at times
      !>     slightly outside the confinement window CNFINE. The time window
      !>     that is actually used is the result of "expanding" CNFINE by a
      !>     specified amount "T": each time interval of CNFINE is expanded by
      !>     shifting the interval's left endpoint to the left and the right
      !>     endpoint to the right by T seconds. Any overlapping intervals are
      !>     merged. (The input argument CNFINE is not modified.)
      !>
      !>     The window expansions listed below are additive: if both
      !>     conditions apply, the window expansion amount is the sum of the
      !>     individual amounts.
      !>
      !>     -  If a search uses an equality constraint, the time window
      !>        over which the state of the observer is computed is expanded
      !>        by 1 second at both ends of all of the time intervals
      !>        comprising the window over which the search is conducted.
      !>
      !>     -  If a search uses stellar aberration corrections, the time
      !>        window over which the state of the observer is computed is
      !>        expanded as described above.
      !>
      !>     When light time corrections are used, expansion of the search
      !>     window also affects the set of times at which the light time-
      !>     corrected state of the target is computed.
      !>
      !>     In addition to the possible 2 second expansion of the search
      !>     window that occurs when both an equality constraint and stellar
      !>     aberration corrections are used, round-off error should be taken
      !>     into account when the need for data availability is analyzed.
      !>
      !>## Examples
      !>
      !>     The numerical results shown for these examples may differ across
      !>     platforms. The results depend on the SPICE kernels used as
      !>     input, the compiler and supporting libraries, and the machine
      !>     specific arithmetic implementation.
      !>
      !>     1) Find times during the first three months of the year 2007 when
      !>        the geometric Earth-Moon distance is greater than 400000 km.
      !>        Display the start and stop times of the time intervals over
      !>        which this constraint is met, along with the Earth-Moon
      !>        distance at each interval endpoint.
      !>
      !>        We expect the Earth-Moon distance to be an oscillatory
      !>        function with extrema roughly two weeks apart. Using
      !>        a step size of one day guarantees that the GF system
      !>        won't fail to find any distance extrema. (Recall that a
      !>        search for distance extrema is an intermediate step
      !>        in the GF search process.)
      !>
      !>        Use the meta-kernel shown below to load the required SPICE
      !>        kernels.
      !>
      !>           KPL/MK
      !>
      !>           File name: gfdist_ex1.tm
      !>
      !>           This meta-kernel is intended to support operation of SPICE
      !>           example programs. The kernels shown here should not be
      !>           assumed to contain adequate or correct versions of data
      !>           required by SPICE-based user applications.
      !>
      !>           In order for an application to use this meta-kernel, the
      !>           kernels referenced here must be present in the user's
      !>           current working directory.
      !>
      !>           The names and contents of the kernels referenced
      !>           by this meta-kernel are as follows:
      !>
      !>              File name                     Contents
      !>              ---------                     --------
      !>              de421.bsp                     Planetary ephemeris
      !>              pck00008.tpc                  Planet orientation and
      !>                                            radii
      !>              naif0009.tls                  Leapseconds
      !>
      !>           \begindata
      !>
      !>              KERNELS_TO_LOAD = ( 'de421.bsp',
      !>                                  'pck00008.tpc',
      !>                                  'naif0009.tls'  )
      !>
      !>           \begintext
      !>
      !>           End of meta-kernel
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM GFDIST_EX1
      !>      IMPLICIT NONE
      !>
      !>C
      !>C     Include GF parameter declarations:
      !>C
      !>      INCLUDE 'gf.inc'
      !>
      !>C
      !>C     SPICELIB functions
      !>C
      !>      DOUBLE PRECISION      SPD
      !>      DOUBLE PRECISION      VNORM
      !>      INTEGER               WNCARD
      !>
      !>C
      !>C     Local parameters
      !>C
      !>      INTEGER               LBCELL
      !>      PARAMETER           ( LBCELL = -5 )
      !>
      !>C
      !>C     Use the parameter MAXWIN for both
      !>C     the result window size and the workspace
      !>C     size.
      !>C
      !>      INTEGER               MAXWIN
      !>      PARAMETER           ( MAXWIN = 20000 )
      !>
      !>C
      !>C     Length of output time string:
      !>C
      !>      INTEGER               TIMLEN
      !>      PARAMETER           ( TIMLEN = 26 )
      !>
      !>C
      !>C     Local variables
      !>C
      !>      CHARACTER*(TIMLEN)    TIMSTR
      !>
      !>      DOUBLE PRECISION      ADJUST
      !>      DOUBLE PRECISION      CNFINE ( LBCELL : 2 )
      !>      DOUBLE PRECISION      DIST
      !>      DOUBLE PRECISION      ET0
      !>      DOUBLE PRECISION      ET1
      !>      DOUBLE PRECISION      FINISH
      !>      DOUBLE PRECISION      LT
      !>      DOUBLE PRECISION      POS    ( 3 )
      !>      DOUBLE PRECISION      REFVAL
      !>      DOUBLE PRECISION      RESULT ( LBCELL : MAXWIN )
      !>      DOUBLE PRECISION      START
      !>      DOUBLE PRECISION      STEP
      !>      DOUBLE PRECISION      WORK   ( LBCELL : MAXWIN, NWDIST )
      !>
      !>      INTEGER               I
      !>
      !>C
      !>C     Saved variables
      !>C
      !>C     The confinement, workspace and result windows CNFINE,
      !>C     WORK and RESULT are saved because this practice helps to
      !>C     prevent stack overflow.
      !>C
      !>      SAVE                  CNFINE
      !>      SAVE                  RESULT
      !>      SAVE                  WORK
      !>
      !>C
      !>C     Load kernels.
      !>C
      !>      CALL FURNSH ( 'gfdist_ex1.tm' )
      !>
      !>C
      !>C     Initialize windows.
      !>C
      !>      CALL SSIZED ( MAXWIN, RESULT )
      !>      CALL SSIZED ( 2,      CNFINE )
      !>
      !>C
      !>C     Store the time bounds of our search interval in
      !>C     the confinement window.
      !>C
      !>      CALL STR2ET ( '2007 JAN 1', ET0 )
      !>      CALL STR2ET ( '2007 APR 1', ET1 )
      !>
      !>      CALL WNINSD ( ET0, ET1, CNFINE )
      !>
      !>C
      !>C     Search using a step size of 1 day (in units of
      !>C     seconds). The reference value is 450000 km.
      !>C     We're not using the adjustment feature, so
      !>C     we set ADJUST to zero.
      !>C
      !>      STEP   = SPD()
      !>      REFVAL = 4.D5
      !>      ADJUST = 0.D0
      !>
      !>C
      !>C     Perform the search. The set of times when the
      !>C     constraint is met will be stored in the SPICE
      !>C     window RESULT.
      !>C
      !>      CALL GFDIST ( 'MOON', 'NONE', 'EARTH', '>',
      !>     .              REFVAL, ADJUST, STEP,    CNFINE,
      !>     .              MAXWIN, NWDIST, WORK,    RESULT )
      !>
      !>C
      !>C     Display the results.
      !>C
      !>      IF ( WNCARD(RESULT) .EQ. 0 ) THEN
      !>
      !>         WRITE (*, '(A)') 'Result window is empty.'
      !>
      !>      ELSE
      !>
      !>         DO I = 1, WNCARD(RESULT)
      !>
      !>C
      !>C           Fetch the endpoints of the Ith interval
      !>C           of the result window.
      !>C
      !>            CALL WNFETD ( RESULT, I, START, FINISH )
      !>
      !>C
      !>C           Check the distance at the start and stop times.
      !>C
      !>            CALL SPKPOS ( 'MOON',  START, 'J2000', 'NONE',
      !>     .                    'EARTH', POS,   LT            )
      !>            DIST = VNORM(POS)
      !>
      !>            CALL TIMOUT ( START, 'YYYY-MON-DD HR:MN:SC.###',
      !>     .                    TIMSTR                            )
      !>
      !>            WRITE (*, '(A,F14.7)' ) 'Start time, distance = '//
      !>     .                              TIMSTR, DIST
      !>
      !>            CALL SPKPOS ( 'MOON',  FINISH, 'J2000', 'NONE',
      !>     .                    'EARTH', POS,     LT            )
      !>            DIST = VNORM(POS)
      !>
      !>            CALL TIMOUT ( FINISH, 'YYYY-MON-DD HR:MN:SC.###',
      !>     .                    TIMSTR                            )
      !>
      !>            WRITE (*, '(A,F14.7)' ) 'Stop time,  distance = '//
      !>     .                              TIMSTR, DIST
      !>         END DO
      !>
      !>      END IF
      !>      END
      !>```
      !>
      !>        When this program was executed on a Mac/Intel/gfortran/64-bit
      !>        platform, the output was:
      !>
      !>        Start time, distance = 2007-JAN-08 00:10:02.439  400000.0000000
      !>        Stop time,  distance = 2007-JAN-13 06:36:42.770  400000.0000000
      !>        Start time, distance = 2007-FEB-04 07:01:30.094  400000.0000000
      !>        Stop time,  distance = 2007-FEB-10 09:29:56.659  400000.0000000
      !>        Start time, distance = 2007-MAR-03 00:19:19.998  400000.0000000
      !>        Stop time,  distance = 2007-MAR-10 14:03:33.312  400000.0000000
      !>        Start time, distance = 2007-MAR-29 22:52:52.961  400000.0000000
      !>        Stop time,  distance = 2007-APR-01 00:00:00.000  404531.9552322
      !>
      !>        Note that the distance at the final solutions interval's stop
      !>        time is not close to the reference value of 400000 km. This is
      !>        because the interval's stop time was determined by the stop
      !>        time of the confinement window.
      !>
      !>     2) Extend the first example to demonstrate use of all supported
      !>        relational operators. Find times when
      !>
      !>           Earth-Moon distance is = 400000 km
      !>           Earth-Moon distance is < 400000 km
      !>           Earth-Moon distance is > 400000 km
      !>           Earth-Moon distance is at a local minimum
      !>           Earth-Moon distance is at the absolute minimum
      !>           Earth-Moon distance is > the absolute minimum + 100 km
      !>           Earth-Moon distance is at a local maximum
      !>           Earth-Moon distance is at the absolute maximum
      !>           Earth-Moon distance is > the absolute maximum - 100 km
      !>
      !>        To shorten the search time and output, use the
      !>        shorter search interval
      !>
      !>           2007 JAN 15 00:00:00 UTC  to
      !>           2007 MAR 15 00:00:00 UTC
      !>
      !>        As before, use geometric (uncorrected) positions, so
      !>        set the aberration correction flag to 'NONE'.
      !>
      !>        Use the meta-kernel from the first example.
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM GFDIST_EX2
      !>      IMPLICIT NONE
      !>
      !>C
      !>C     Include GF parameter declarations:
      !>C
      !>      INCLUDE 'gf.inc'
      !>
      !>C
      !>C     SPICELIB functions
      !>C
      !>      DOUBLE PRECISION      SPD
      !>      DOUBLE PRECISION      VNORM
      !>      INTEGER               WNCARD
      !>
      !>C
      !>C     Local parameters
      !>C
      !>      INTEGER               LBCELL
      !>      PARAMETER           ( LBCELL = -5 )
      !>
      !>C
      !>C     Use the parameter MAXWIN for both
      !>C     the result window size and the workspace
      !>C     size.
      !>C
      !>      INTEGER               MAXWIN
      !>      PARAMETER           ( MAXWIN = 20000 )
      !>
      !>C
      !>C     Length of output time string:
      !>C
      !>      INTEGER               TIMLEN
      !>      PARAMETER           ( TIMLEN = 26 )
      !>
      !>C
      !>C     Number of relational operators:
      !>C
      !>      INTEGER               NRELOP
      !>      PARAMETER           ( NRELOP = 9 )
      !>
      !>C
      !>C     Operator name length:
      !>C
      !>      INTEGER               OPNMLN
      !>      PARAMETER           ( OPNMLN = 6 )
      !>
      !>C
      !>C     Output line length:
      !>C
      !>      INTEGER               LNSIZE
      !>      PARAMETER           ( LNSIZE = 80 )
      !>
      !>C
      !>C     Output format
      !>C
      !>      CHARACTER*(*)         FMT1
      !>      PARAMETER           ( FMT1 = '(A,F12.5)' )
      !>
      !>C
      !>C     Local variables
      !>C
      !>      CHARACTER*(OPNMLN)    RELATE ( NRELOP )
      !>      CHARACTER*(LNSIZE)    TEMPLT ( NRELOP )
      !>      CHARACTER*(TIMLEN)    TIMSTR
      !>      CHARACTER*(LNSIZE)    TITLE
      !>
      !>      DOUBLE PRECISION      ADJUST ( NRELOP )
      !>      DOUBLE PRECISION      CNFINE ( LBCELL : 2 )
      !>      DOUBLE PRECISION      DIST
      !>      DOUBLE PRECISION      ET0
      !>      DOUBLE PRECISION      ET1
      !>      DOUBLE PRECISION      FINSH
      !>      DOUBLE PRECISION      LT
      !>      DOUBLE PRECISION      POS    ( 3 )
      !>      DOUBLE PRECISION      REFVAL
      !>      DOUBLE PRECISION      RESULT ( LBCELL : MAXWIN )
      !>      DOUBLE PRECISION      START
      !>      DOUBLE PRECISION      STEP
      !>      DOUBLE PRECISION      WORK   ( LBCELL : MAXWIN, NWDIST )
      !>
      !>      INTEGER               I
      !>      INTEGER               J
      !>
      !>C
      !>C     Saved variables
      !>C
      !>      SAVE                  ADJUST
      !>      SAVE                  RELATE
      !>      SAVE                  TEMPLT
      !>
      !>C
      !>C     The confinement, workspace and result windows CNFINE,
      !>C     WORK and RESULT are saved because this practice helps to
      !>C     prevent stack overflow.
      !>C
      !>      SAVE                  CNFINE
      !>      SAVE                  RESULT
      !>      SAVE                  WORK
      !>
      !>C
      !>C     Initial values
      !>C
      !>      DATA                  ADJUST / 0.D0,
      !>     .                               0.D0,
      !>     .                               0.D0,
      !>     .                               0.D0,
      !>     .                               0.D0,
      !>     .                               100.D0,
      !>     .                               0.D0,
      !>     .                               0.D0,
      !>     .                               100.D0 /
      !>
      !>      DATA                  RELATE / '=',
      !>     .                               '<',
      !>     .                               '>',
      !>     .                               'LOCMIN',
      !>     .                               'ABSMIN',
      !>     .                               'ABSMIN',
      !>     .                               'LOCMAX',
      !>     .                               'ABSMAX',
      !>     .                               'ABSMAX'  /
      !>
      !>      DATA                  TEMPLT /
      !>     .   'Condition: distance = # km',
      !>     .   'Condition: distance < # km',
      !>     .   'Condition: distance > # km',
      !>     .   'Condition: distance is a local minimum',
      !>     .   'Condition: distance is the absolute minimum',
      !>     .   'Condition: distance < the absolute minimum + * km',
      !>     .   'Condition: distance is a local maximum',
      !>     .   'Condition: distance is the absolute maximum',
      !>     .   'Condition: distance > the absolute maximum - * km' /
      !>
      !>C
      !>C     Load kernels.
      !>C
      !>      CALL FURNSH ( 'gfdist_ex1.tm' )
      !>
      !>C
      !>C     Initialize windows.
      !>C
      !>      CALL SSIZED ( MAXWIN, RESULT )
      !>      CALL SSIZED ( 2,      CNFINE )
      !>
      !>C
      !>C     Store the time bounds of our search interval in
      !>C     the confinement window.
      !>C
      !>      CALL STR2ET ( '2007 JAN 15', ET0 )
      !>      CALL STR2ET ( '2007 MAR 15', ET1 )
      !>
      !>      CALL WNINSD ( ET0, ET1, CNFINE )
      !>
      !>C
      !>C     Search using a step size of 1 day (in units of
      !>C     seconds). Use a reference value of 400000 km.
      !>C
      !>      STEP   = SPD()
      !>      REFVAL = 4.D5
      !>
      !>      DO I = 1, NRELOP
      !>
      !>         CALL GFDIST ( 'MOON', 'NONE',    'EARTH', RELATE(I),
      !>     .                 REFVAL, ADJUST(I), STEP,    CNFINE,
      !>     .                 MAXWIN, NWDIST,    WORK,    RESULT    )
      !>
      !>C
      !>C        Display the results.
      !>C
      !>         WRITE (*,*) ' '
      !>
      !>C
      !>C        Substitute the reference and adjustment values,
      !>C        where applicable, into the title string:
      !>C
      !>         CALL REPMD ( TEMPLT(I), '#', REFVAL,    6, TITLE )
      !>         CALL REPMD ( TITLE,     '*', ADJUST(I), 6, TITLE )
      !>
      !>         WRITE (*, '(A)' ) TITLE
      !>
      !>         IF ( WNCARD(RESULT) .EQ. 0 ) THEN
      !>            WRITE (*, '(A)' ) ' Result window is empty.'
      !>         ELSE
      !>            WRITE (*, '(A)' ) ' Result window:'
      !>
      !>            DO J = 1, WNCARD(RESULT)
      !>
      !>C
      !>C              Fetch the endpoints of the Jth interval
      !>C              of the result window.
      !>C
      !>               CALL WNFETD ( RESULT, J, START, FINSH )
      !>
      !>C
      !>C              Check the distance at the start and stop times.
      !>C
      !>               CALL SPKPOS ( 'MOON',  START, 'J2000', 'NONE',
      !>     .                       'EARTH', POS,   LT              )
      !>               DIST = VNORM(POS)
      !>
      !>               CALL TIMOUT ( START, 'YYYY-MON-DD HR:MN:SC.###',
      !>     .                       TIMSTR                           )
      !>
      !>               WRITE (*, FMT1 ) '  Start time, distance = '
      !>     .         //               TIMSTR, DIST
      !>
      !>               CALL SPKPOS ( 'MOON',  FINSH, 'J2000', 'NONE',
      !>     .                       'EARTH', POS,     LT            )
      !>               DIST = VNORM(POS)
      !>
      !>               CALL TIMOUT ( FINSH, 'YYYY-MON-DD HR:MN:SC.###',
      !>     .                       TIMSTR                           )
      !>
      !>               WRITE (*, FMT1 ) '  Stop time,  distance = '
      !>     .         //               TIMSTR, DIST
      !>            END DO
      !>
      !>         END IF
      !>
      !>      END DO
      !>
      !>      WRITE (*,*) ' '
      !>
      !>      END
      !>```
      !>
      !>        When this program was executed on a Mac/Intel/gfortran/64-bit
      !>        platform, the output was:
      !>
      !>        Condition: distance = 4.00000E+05 km
      !>         Result window:
      !>          Start time, distance = 2007-FEB-04 07:01:30.094  400000.00000
      !>          Stop time,  distance = 2007-FEB-04 07:01:30.094  400000.00000
      !>          Start time, distance = 2007-FEB-10 09:29:56.659  400000.00000
      !>          Stop time,  distance = 2007-FEB-10 09:29:56.659  400000.00000
      !>          Start time, distance = 2007-MAR-03 00:19:19.998  400000.00000
      !>          Stop time,  distance = 2007-MAR-03 00:19:19.998  400000.00000
      !>          Start time, distance = 2007-MAR-10 14:03:33.312  400000.00000
      !>          Stop time,  distance = 2007-MAR-10 14:03:33.312  400000.00000
      !>
      !>        Condition: distance < 4.00000E+05 km
      !>         Result window:
      !>          Start time, distance = 2007-JAN-15 00:00:00.000  393018.60991
      !>          Stop time,  distance = 2007-FEB-04 07:01:30.094  400000.00000
      !>          Start time, distance = 2007-FEB-10 09:29:56.659  400000.00000
      !>          Stop time,  distance = 2007-MAR-03 00:19:19.998  400000.00000
      !>          Start time, distance = 2007-MAR-10 14:03:33.312  400000.00000
      !>          Stop time,  distance = 2007-MAR-15 00:00:00.000  376255.45393
      !>
      !>        Condition: distance > 4.00000E+05 km
      !>         Result window:
      !>          Start time, distance = 2007-FEB-04 07:01:30.094  400000.00000
      !>          Stop time,  distance = 2007-FEB-10 09:29:56.659  400000.00000
      !>          Start time, distance = 2007-MAR-03 00:19:19.998  400000.00000
      !>          Stop time,  distance = 2007-MAR-10 14:03:33.312  400000.00000
      !>
      !>        Condition: distance is a local minimum
      !>         Result window:
      !>          Start time, distance = 2007-JAN-22 12:30:49.458  366925.80411
      !>          Stop time,  distance = 2007-JAN-22 12:30:49.458  366925.80411
      !>          Start time, distance = 2007-FEB-19 09:36:29.968  361435.64681
      !>          Stop time,  distance = 2007-FEB-19 09:36:29.968  361435.64681
      !>
      !>        Condition: distance is the absolute minimum
      !>         Result window:
      !>          Start time, distance = 2007-FEB-19 09:36:29.968  361435.64681
      !>          Stop time,  distance = 2007-FEB-19 09:36:29.968  361435.64681
      !>
      !>        Condition: distance < the absolute minimum + 1.00000E+02 km
      !>         Result window:
      !>          Start time, distance = 2007-FEB-19 01:09:52.706  361535.64681
      !>          Stop time,  distance = 2007-FEB-19 18:07:45.136  361535.64681
      !>
      !>        Condition: distance is a local maximum
      !>         Result window:
      !>          Start time, distance = 2007-FEB-07 12:38:29.870  404992.42429
      !>          Stop time,  distance = 2007-FEB-07 12:38:29.870  404992.42429
      !>          Start time, distance = 2007-MAR-07 03:37:02.122  405853.45213
      !>          Stop time,  distance = 2007-MAR-07 03:37:02.122  405853.45213
      !>
      !>        Condition: distance is the absolute maximum
      !>         Result window:
      !>          Start time, distance = 2007-MAR-07 03:37:02.122  405853.45213
      !>          Stop time,  distance = 2007-MAR-07 03:37:02.122  405853.45213
      !>
      !>        Condition: distance > the absolute maximum - 1.00000E+02 km
      !>         Result window:
      !>          Start time, distance = 2007-MAR-06 15:56:00.957  405753.45213
      !>          Stop time,  distance = 2007-MAR-07 15:00:38.674  405753.45213
      !>
      !>## Restrictions
      !>
      !>     1)  The kernel files to be used by this routine must be loaded
      !>         (normally via the SPICELIB routine FURNSH) before this routine
      !>         is called.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     E.D. Wright        (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.1.1, 27-OCT-2021 (JDR) (NJB)
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>        Edited second example code and modified the output resolution
      !>        for the distances in that example to fit in the $Examples
      !>        section without modifications. Renamed example's meta-kernel.
      !>        Added SAVE statements for CNFINE, WORK and RESULT variables in
      !>        code examples.
      !>
      !>        Updated description of WORK and RESULT arguments in $Brief_I/O,
      !>        $Detailed_Input and $Detailed_Output.
      !>
      !>        Updated header to describe use of expanded confinement window.
      !>
      !>-    SPICELIB Version 1.1.0, 05-SEP-2012 (EDW)
      !>
      !>        Edit to comments to correct search description.
      !>
      !>        Implemented use of ZZHOLDD to allow user to alter convergence
      !>        tolerance.
      !>
      !>        Removed the STEP > 0 error check. The GFSSTP call includes
      !>        the check.
      !>
      !>-    SPICELIB Version 1.0.0, 15-APR-2009 (NJB) (EDW)
      module subroutine gfdist ( ctx, target, abcorr, obsrvr, relate, refval, adjust, step, cnfine, mw, nw, work, result )
      use pepper_kinds, only: ip, wp
      use pepper_inc_gf
      use pepper_inc_zzholdd
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), parameter :: lbcell = -5
      character(*), intent(in) :: target  !! Name of the target body.
      character(*), intent(in) :: abcorr  !! Aberration correction flag.
      character(*), intent(in) :: obsrvr  !! Name of the observing body.
      character(*), intent(in) :: relate  !! Relational operator.
      real(wp), intent(in) :: refval  !! Reference value.
      real(wp), intent(in) :: adjust  !! Adjustment value for absolute extrema searches.
      real(wp), intent(in) :: step  !! Step size used for locating extrema and roots.
      real(wp), intent(in) :: cnfine ( lbcell : * )  !! SPICE window to which the search is confined.
      integer(ip), intent(in) :: mw  !! Workspace window size.
      integer(ip), intent(in) :: nw  !! Workspace window count.
      real(wp), intent(inout) :: work   ( lbcell : mw, nw )  !! Array of workspace windows.
      real(wp), intent(inout) :: result ( lbcell : * )  !! SPICE window containing results.


!
!     External functions
!

      integer(ip), parameter :: qnpars = 3



      real(wp) :: tol
      logical :: ok

!
!     Quantity definition parameter arrays:
!
      character(lnsize) :: qcpars ( qnpars )
      character(lnsize) :: qpnams ( qnpars )

      real(wp) :: qdpars ( qnpars )

      integer(ip) :: qipars ( qnpars )

      logical :: qlpars ( qnpars )

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Check the workspace window dimensions.
!
      if ( mw < 2 ) then

         call ctx%setmsg ( 'Workspace window size was #; size must be ' &
         //            'at least 2.'                               )
         call ctx%errint ( '#',  mw                                    )
         call ctx%sigerr ( 'SPICE(INVALIDDIMENSION)'                   )
         return

      end if

      if ( nw < nwdist ) then

         call ctx%setmsg ( 'Workspace window count was #; count must be ' &
         //            'at least #.'                                 )
         call ctx%errint ( '#',  nw                                      )
         call ctx%errint ( '#',  nwdist                                  )
         call ctx%sigerr ( 'SPICE(INVALIDDIMENSION)'                     )
         return

      end if

!
!     Check the result window size.
!
      if ( sized( ctx,result) < 2 ) then

         call ctx%setmsg ( 'Result window size was #; size must be ' &
         //            'at least 2.'                             )
         call ctx%errint ( '#',  sized( ctx,result)                       )
         call ctx%sigerr ( 'SPICE(INVALIDDIMENSION)'                 )
         return

      end if

!
!     Set up a call to GFEVNT, which will handle the search.
!
      qpnams(1) = 'TARGET'
      qcpars(1) =  target

      qpnams(2) = 'OBSERVER'
      qcpars(2) =  obsrvr

      qpnams(3) = 'ABCORR'
      qcpars(3) =  abcorr

!
!     Check and set the step size.
!
      call gfsstp ( ctx, step )

!
!     Retrieve the convergence tolerance, if set.
!
      call zzholdd ( ctx, zzget, gf_tol, ok, tol )

!
!     Use the default value CNVTOL if no stored tolerance value.
!
      if ( .not. ok ) then

         tol = cnvtol

      end if

!
!     Initialize the RESULT window.
!
      call scardd ( ctx, 0, result )

!
!     Look for solutions.
!
!     Progress report and bail-out options are set to .FALSE.
!
      call gfevnt ( ctx, gfstep,   gfrefn,   'DISTANCE',  qnpars, &
                    qpnams,   qcpars,   qdpars,      qipars, &
                    qlpars,   relate,   refval,      tol, &
                    adjust,   cnfine,   norpt,       gfrepi, &
                    gfrepu,   gfrepf,   mw,          nwdist, &
                    work,     nobail,   gfbail,      result  )

      return
      end subroutine gfdist

      !> Determine time intervals over which a specified constraint on
      !> the observed phase, solar incidence, or emission angle at
      !> a specified target body surface point is met.
      !>
      !>## Detailed Input
      !>
      !>     METHOD   is a short string providing parameters defining the
      !>              computation method to be used. Parameters include, but
      !>              are not limited to, the shape model used to represent the
      !>              surface of the target body.
      !>
      !>              The only choice currently supported is
      !>
      !>                 'Ellipsoid'        The illumination angle
      !>                                    computation uses a triaxial
      !>                                    ellipsoid to model the surface
      !>                                    of the target body. The
      !>                                    ellipsoid's radii must be
      !>                                    available in the kernel pool.
      !>
      !>              Neither case nor whitespaces are significant in METHOD.
      !>              For example, the string ' eLLipsoid ' is valid.
      !>
      !>     ANGTYP   is a string specifying the type of illumination angle for
      !>              which a search is to be performed. The possible values of
      !>              ANGTYP are
      !>
      !>                 'PHASE'
      !>                 'INCIDENCE'
      !>                 'EMISSION'
      !>
      !>              When the illumination source is the sun, the incidence
      !>              angle is commonly called the "solar incidence angle."
      !>
      !>              See the $Particulars section below for a detailed
      !>              description of these angles.
      !>
      !>              Neither case nor whitespaces are significant in ANGTYP.
      !>              For example, the string ' Incidence ' is valid.
      !>
      !>     TARGET   is the name of a target body. The point at which the
      !>              illumination angles are defined is located on the surface
      !>              of this body.
      !>
      !>              Optionally, you may supply the integer ID code for the
      !>              object as an integer string. For example both 'MOON' and
      !>              '301' are legitimate strings that indicate the moon is
      !>              the target body.
      !>
      !>              Neither case nor leading and trailing blanks are
      !>              significant in TARGET. For example, the string
      !>              ' Incidence ' is valid. Sequences of embedded blanks are
      !>              treated as a single blank.
      !>
      !>     ILLMN    is the name of the illumination source. This source may
      !>              be any ephemeris object. Case, blanks, and numeric values
      !>              are treated in the same way as for the input TARGET.
      !>
      !>     FIXREF   is the name of the body-fixed, body-centered reference
      !>              frame associated with the target body. The input surface
      !>              point SPOINT is expressed relative to this reference
      !>              frame, and this frame is used to define the orientation
      !>              of the target body as a function of time.
      !>
      !>              The string FIXREF is case-insensitive, and leading
      !>              and trailing blanks in FIXREF are not significant.
      !>
      !>     ABCORR   indicates the aberration corrections to be applied to the
      !>              observer-surface point vector, the surface point-
      !>              illumination source vector, and the target body
      !>              orientation to account for one-way light time and stellar
      !>              aberration.
      !>
      !>              Any "reception" correction accepted by SPKEZR can be used
      !>              here. See the header of SPKEZR for a detailed description
      !>              of the aberration correction options. For convenience,
      !>              the options are listed below:
      !>
      !>                 'NONE'     Apply no correction.
      !>
      !>                 'LT'       "Reception" case: correct for
      !>                            one-way light time using a Newtonian
      !>                            formulation.
      !>
      !>                 'LT+S'     "Reception" case: correct for
      !>                            one-way light time and stellar
      !>                            aberration using a Newtonian
      !>                            formulation.
      !>
      !>                 'CN'       "Reception" case: converged
      !>                            Newtonian light time correction.
      !>
      !>                 'CN+S'     "Reception" case: converged
      !>                            Newtonian light time and stellar
      !>                            aberration corrections.
      !>
      !>              Case and blanks are not significant in the string ABCORR.
      !>
      !>     OBSRVR   is the name of an observing body. Case, blanks, and
      !>              numeric values are treated in the same way as for the
      !>              input TARGET.
      !>
      !>     SPOINT   is a surface point on the target body, expressed in
      !>              Cartesian coordinates, relative to the body-fixed target
      !>              frame designated by FIXREF.
      !>
      !>              SPOINT need not be visible from the observer's location
      !>              in order for the constraint specified by RELATE and
      !>              REFVAL (see descriptions below) to be satisfied.
      !>
      !>              The components of SPOINT have units of km.
      !>
      !>     RELATE   is a relational operator used to define a constraint on a
      !>              specified illumination angle. The result window found by
      !>              this routine indicates the time intervals where the
      !>              constraint is satisfied. Supported values of RELATE and
      !>              corresponding meanings are shown below:
      !>
      !>                 '>'      The angle is greater than the reference
      !>                          value REFVAL.
      !>
      !>                 '='      The angle is equal to the reference
      !>                          value REFVAL.
      !>
      !>                 '<'      The angle is less than the reference
      !>                          value REFVAL.
      !>
      !>                'ABSMAX'  The angle is at an absolute maximum.
      !>
      !>                'ABSMIN'  The angle is at an absolute minimum.
      !>
      !>                'LOCMAX'  The angle is at a local maximum.
      !>
      !>                'LOCMIN'  The angle is at a local minimum.
      !>
      !>              The caller may indicate that the window of interest is
      !>              the set of time intervals where the angle is within a
      !>              specified separation from an absolute extremum. The
      !>              argument ADJUST (described below) is used to specify this
      !>              separation.
      !>
      !>              Local extrema are considered to exist only in the
      !>              interiors of the intervals comprising the confinement
      !>              window: a local extremum cannot exist at a boundary point
      !>              of the confinement window.
      !>
      !>              Case is not significant in the string RELATE.
      !>
      !>     REFVAL   is the reference value used together with the argument
      !>              RELATE to define an equality or inequality to be
      !>              satisfied by the specified illumination angle. See the
      !>              discussion of RELATE above for further information.
      !>
      !>              The units of REFVAL are radians.
      !>
      !>     ADJUST   is a parameter used to modify searches for absolute
      !>              extrema: when RELATE is set to 'ABSMAX' or 'ABSMIN' and
      !>              ADJUST is set to a positive value, GFILUM will find times
      !>              when the specified illumination angle is within ADJUST
      !>              radians of the specified extreme value.
      !>
      !>              If ADJUST is non-zero and a search for an absolute
      !>              minimum is performed, the result window contains time
      !>              intervals when the specified illumination angle has
      !>              values between the absolute minimum ABSMIN and
      !>              ABSMIN + ADJUST radians.
      !>
      !>              If ADJUST is non-zero and the search is for an absolute
      !>              maximum, the corresponding angle is between the absolute
      !>              maximum ABSMAX and ABSMAX - ADJUST radians.
      !>
      !>              ADJUST is not used for searches for local extrema,
      !>              equality or inequality conditions.
      !>
      !>     STEP     is the step size to be used in the search. STEP must be
      !>              short enough for a search using this step size to locate
      !>              the time intervals where the specified illumination angle
      !>              is monotone increasing or decreasing. However, STEP must
      !>              not be *too* short, or the search will take an
      !>              unreasonable amount of time.
      !>
      !>              The choice of STEP affects the completeness but not the
      !>              precision of solutions found by this routine; the
      !>              precision is controlled by the convergence tolerance. See
      !>              the discussion of the parameter CNVTOL for details.
      !>
      !>              STEP has units of seconds.
      !>
      !>     CNFINE   is a SPICE window that confines the time period over
      !>              which the specified search is conducted. CNFINE may
      !>              consist of a single interval or a collection of
      !>              intervals.
      !>
      !>              The endpoints of the time intervals comprising CNFINE are
      !>              interpreted as seconds past J2000 TDB.
      !>
      !>              In some cases the confinement window can be used to
      !>              greatly reduce the time window that must be searched for
      !>              the desired solution. See the $Particulars section below
      !>              for further discussion.
      !>
      !>              See the $Examples section below for a code example that
      !>              shows how to create a confinement window.
      !>
      !>              CNFINE must be initialized by the caller via the SPICELIB
      !>              routine SSIZED.
      !>
      !>              In some cases the observer's state may be computed at
      !>              times outside of CNFINE by as much as 2 seconds. See
      !>              $Particulars for details.
      !>
      !>     MW       is a parameter specifying the length of the workspace
      !>              array WORK (see description below) used by this routine.
      !>              MW should be at least as large as TWICE the number of
      !>              intervals within the search window on which the specified
      !>              illumination angle is monotone increasing or decreasing.
      !>              It does no harm to pick a value of MW larger than the
      !>              minimum required to execute the specified search, but if
      !>              MW is too small, the search will fail.
      !>
      !>     RESULT   is a double precision SPICE window which will contain
      !>              the search results. RESULT must be declared and
      !>              initialized with sufficient size to capture the full
      !>              set of time intervals within the search region on which
      !>              the specified condition is satisfied.
      !>
      !>              RESULT must be initialized by the caller via the
      !>              SPICELIB routine SSIZED.
      !>
      !>              If RESULT is non-empty on input, its contents will be
      !>              discarded before GFILUM conducts its search.
      !>
      !>## Detailed Output
      !>
      !>     WORK     is an array used to store workspace windows.
      !>
      !>              This array should be declared by the caller as shown:
      !>
      !>                 INCLUDE 'gf.inc'
      !>                    ...
      !>
      !>                 DOUBLE PRECISION    WORK ( LBCELL : MW, NWILUM )
      !>
      !>              where MW is a constant declared by the caller and NWILUM
      !>              is a constant defined in the SPICELIB INCLUDE file
      !>              gf.inc.
      !>
      !>              WORK need not be initialized by the caller.
      !>
      !>              WORK is modified by this routine. The caller should
      !>              re-initialize this array before attempting to use it for
      !>              any other purpose.
      !>
      !>     RESULT   is the SPICE window of intervals, contained within the
      !>              confinement window CNFINE, on which the specified
      !>              constraint is satisfied.
      !>
      !>              The endpoints of the time intervals comprising RESULT are
      !>              interpreted as seconds past J2000 TDB.
      !>
      !>              If the search is for local extrema, or for absolute
      !>              extrema with ADJUST set to zero, then normally each
      !>              interval of RESULT will be a singleton: the left and
      !>              right endpoints of each interval will be identical.
      !>
      !>              If no times within the confinement window satisfy the
      !>              search criteria, RESULT will be returned with a
      !>              cardinality of zero.
      !>
      !>## Parameters
      !>
      !>     LBCELL   is the lower bound for SPICE Cell arrays.
      !>
      !>     CNVTOL   is the default convergence tolerance used for finding
      !>              endpoints of the intervals comprising the result
      !>              window. CNVTOL is also used for finding intermediate
      !>              results; in particular, CNVTOL is used for finding the
      !>              windows on which the specified illumination angle is
      !>              increasing or decreasing. CNVTOL is used to determine
      !>              when binary searches for roots should terminate: when
      !>              a root is bracketed within an interval of length
      !>              CNVTOL, the root is considered to have been found.
      !>
      !>              The accuracy, as opposed to precision, of roots found
      !>              by this routine depends on the accuracy of the input
      !>              data. In most cases, the accuracy of solutions will be
      !>              inferior to their precision.
      !>
      !>              The calling program can reset the convergence
      !>              tolerance; see the $Particulars section below for
      !>              further information.
      !>
      !>     NWILUM   is the number of workspace windows required by
      !>              this routine.
      !>
      !>     See INCLUDE file gf.inc for declarations and descriptions of
      !>     parameters used throughout the GF subsystem.
      !>
      !>## Exceptions
      !>
      !>     1)  In order for this routine to produce correct results,
      !>         the step size must be appropriate for the problem at hand.
      !>         Step sizes that are too large may cause this routine to miss
      !>         roots; step sizes that are too small may cause this routine
      !>         to run unacceptably slowly and in some cases, find spurious
      !>         roots.
      !>
      !>         This routine does not diagnose invalid step sizes, except
      !>         that if the step size is non-positive, the error
      !>         SPICE(INVALIDSTEP) is signaled.
      !>
      !>     2)  Due to numerical errors, in particular,
      !>
      !>            - Truncation error in time values
      !>            - Finite tolerance value
      !>            - Errors in computed geometric quantities
      !>
      !>         it is *normal* for the condition of interest to not always be
      !>         satisfied near the endpoints of the intervals comprising the
      !>         result window.
      !>
      !>         The result window may need to be contracted slightly by the
      !>         caller to achieve desired results. The SPICE window routine
      !>         WNCOND can be used to contract the result window.
      !>
      !>     3)  If the window size MW is less than 2, the error
      !>         SPICE(INVALIDDIMENSION) is signaled.
      !>
      !>     4)  If the window count NW is less than NWILUM, the error
      !>         SPICE(INVALIDDIMENSION) is signaled.
      !>
      !>     5)  If an error (typically cell overflow) occurs while performing
      !>         window arithmetic, the error is signaled by a routine
      !>         in the call tree of this routine.
      !>
      !>     6)  If the output SPICE window RESULT has size less than 2, the
      !>         error SPICE(INVALIDDIMENSION) is signaled.
      !>
      !>     7)  If the output SPICE window RESULT has insufficient capacity to
      !>         hold the set of intervals on which the specified illumination
      !>         angle condition is met, an error is signaled by a routine in
      !>         the call tree of this routine.
      !>
      !>     8)  If the input target body-fixed frame FIXREF is not
      !>         recognized, an error is signaled by a routine in the call
      !>         tree of this routine. A frame name may fail to be recognized
      !>         because a required frame specification kernel has not been
      !>         loaded; another cause is a misspelling of the frame name.
      !>
      !>     9)  If the input frame FIXREF is not centered at the target body,
      !>         an error is signaled by a routine in the call tree of this
      !>         routine.
      !>
      !>     10) If the input argument METHOD is not recognized, an error is
      !>         signaled by a routine in the call tree of this routine.
      !>
      !>     11) If the illumination angle type ANGTYP is not recognized,
      !>         an error is signaled by a routine in the call tree
      !>         of this routine.
      !>
      !>     12) If the relational operator RELATE is not recognized, an
      !>         error is signaled by a routine in the call tree of this
      !>         routine.
      !>
      !>     13) If the aberration correction specifier contains an
      !>         unrecognized value, an error is signaled by a routine in the
      !>         call tree of this routine.
      !>
      !>     14) If ADJUST is negative, an error is signaled by a routine in
      !>         the call tree of this routine.
      !>
      !>     15) If any of the input body names do not map to NAIF ID
      !>         codes, an error is signaled by a routine in the call tree of
      !>         this routine.
      !>
      !>     16) If the target coincides with the observer or the illumination
      !>         source, an error is signaled by a routine in the call tree
      !>         of this routine.
      !>
      !>     17) If required ephemerides or other kernel data are not
      !>         available, an error is signaled by a routine in the call tree
      !>         of this routine.
      !>
      !>## Files
      !>
      !>     Appropriate kernels must be loaded by the calling program before
      !>     this routine is called.
      !>
      !>     The following data are required:
      !>
      !>     -  SPK data: ephemeris data for target, observer, and the
      !>        illumination source must be loaded. If aberration
      !>        corrections are used, the states of target, observer, and
      !>        the illumination source relative to the solar system
      !>        barycenter must be calculable from the available ephemeris
      !>        data. Typically ephemeris data are made available by loading
      !>        one or more SPK files via FURNSH.
      !>
      !>     -  PCK data: if the target body shape is modeled as an
      !>        ellipsoid (currently no other shapes are supported),
      !>        triaxial radii for the target body must be loaded
      !>        into the kernel pool. Typically this is done by loading a
      !>        text PCK file via FURNSH.
      !>
      !>     -  Further PCK data: rotation data for the target body must be
      !>        loaded. These may be provided in a text or binary PCK file.
      !>
      !>     -  Frame data: if a frame definition not built into SPICE
      !>        is required to convert the observer and target states to the
      !>        body-fixed frame of the target, that definition must be
      !>        available in the kernel pool. Typically the definition is
      !>        supplied by loading a frame kernel via FURNSH.
      !>
      !>     -  In some cases the observer's state may be computed at times
      !>        outside of CNFINE by as much as 2 seconds; data required to
      !>        compute this state must be provided by loaded kernels. See
      !>        $Particulars for details.
      !>
      !>     In all cases, kernel data are normally loaded once per program
      !>     run, NOT every time this routine is called.
      !>
      !>## Particulars
      !>
      !>     This routine determines a set of one or more time intervals
      !>     within the confinement window when the specified illumination
      !>     angle satisfies a caller-specified constraint. The resulting set
      !>     of intervals is returned as a SPICE window.
      !>
      !>     The term "illumination angles" refers to the following set of
      !>     angles:
      !>
      !>        phase angle              Angle between the vectors from the
      !>                                 surface point to the observer and
      !>                                 from the surface point to the
      !>                                 illumination source.
      !>
      !>        incidence angle          Angle between the surface normal at
      !>                                 the specified surface point and the
      !>                                 vector from the surface point to the
      !>                                 illumination source. When the sun is
      !>                                 the illumination source, this angle is
      !>                                 commonly called the "solar incidence
      !>                                 angle."
      !>
      !>        emission angle           Angle between the surface normal at
      !>                                 the specified surface point and the
      !>                                 vector from the surface point to the
      !>                                 observer.
      !>
      !>     The diagram below illustrates the geometric relationships
      !>     defining these angles. The labels for the incidence, emission,
      !>     and phase angles are "inc.", "e.", and "phase".
      !>
      !>                                                      *
      !>                                              illumination source
      !>
      !>                    surface normal vector
      !>                              ._                 _.
      !>                              |\                 /|  illumination
      !>                                \    phase      /    source vector
      !>                                 \   .    .    /
      !>                                 .            .
      !>                                   \   ___   /
      !>                              .     \/     \/
      !>                                    _\ inc./
      !>                             .    /   \   /
      !>                             .   |  e. \ /
      !>         *             <--------------- *  surface point on
      !>      viewing            vector            target body
      !>      location           to viewing
      !>      (observer)         location
      !>
      !>     Note that if the target-observer vector, the target normal vector
      !>     at the surface point, and the target-illumination source vector
      !>     are coplanar, then phase is the sum of the incidence and emission
      !>     angles. This rarely occurs; usually
      !>
      !>        phase angle  <  incidence angle + emission angle
      !>
      !>     All of the above angles can be computed using light time
      !>     corrections, light time and stellar aberration corrections, or no
      !>     aberration corrections. In order to describe apparent geometry as
      !>     observed by a remote sensing instrument, both light time and
      !>     stellar aberration corrections should be used.
      !>
      !>     The way aberration corrections are applied by this routine
      !>     is described below.
      !>
      !>        Light time corrections
      !>        ======================
      !>
      !>           Observer-target surface point vector
      !>           ------------------------------------
      !>
      !>           Let ET be the epoch at which an observation or remote
      !>           sensing measurement is made, and let ET - LT (LT stands
      !>           for "light time") be the epoch at which the photons
      !>           received at ET were emitted from the surface point SPOINT.
      !>           Note that the light time between the surface point and
      !>           observer will generally differ from the light time between
      !>           the target body's center and the observer.
      !>
      !>           Target body's orientation
      !>           -------------------------
      !>
      !>           Using the definitions of ET and LT above, the target body's
      !>           orientation at ET - LT is used. The surface normal is
      !>           dependent on the target body's orientation, so the body's
      !>           orientation model must be evaluated for the correct epoch.
      !>
      !>           Target body -- illumination source vector
      !>           -----------------------------------------
      !>
      !>           The surface features on the target body near SPOINT will
      !>           appear in a measurement made at ET as they were at ET-LT.
      !>           In particular, lighting on the target body is dependent on
      !>           the apparent location of the illumination source as seen
      !>           from the target body at ET-LT. So, a second light time
      !>           correction is used to compute the position of the
      !>           illumination source relative to the surface point.
      !>
      !>        Stellar aberration corrections
      !>        ==============================
      !>
      !>        Stellar aberration corrections are applied only if
      !>        light time corrections are applied as well.
      !>
      !>           Observer-target surface point body vector
      !>           -----------------------------------------
      !>
      !>           When stellar aberration correction is performed, the
      !>           observer-to-surface point direction vector, which we'll
      !>           call SRFVEC, is adjusted so as to point to the apparent
      !>           position of SPOINT: considering SPOINT to be an ephemeris
      !>           object, SRFVEC points from the observer's position at ET to
      !>           the light time and stellar aberration
      !>           corrected position of SPOINT.
      !>
      !>           Target body-illumination source vector
      !>           --------------------------------------
      !>
      !>           The target body-illumination source vector is the apparent
      !>           position of the illumination source, corrected for light
      !>           time and stellar aberration, as seen from the surface point
      !>           SPOINT at time ET-LT.
      !>
      !>     Below we discuss in greater detail aspects of this routine's
      !>     solution process that are relevant to correct and efficient
      !>     use of this routine in user applications.
      !>
      !>     The Search Process
      !>     ==================
      !>
      !>     Regardless of the type of constraint selected by the caller, this
      !>     routine starts the search for solutions by determining the time
      !>     periods, within the confinement window, over which the specified
      !>     illumination angle is monotone increasing and monotone decreasing.
      !>     Each of these time periods is represented by a SPICE window.
      !>     Having found these windows, all of the illumination angle's local
      !>     extrema within the confinement window are known. Absolute extrema
      !>     then can be found very easily.
      !>
      !>     Within any interval of these "monotone" windows, there will be at
      !>     most one solution of any equality constraint. Since the boundary
      !>     of the solution set for any inequality constraint is contained in
      !>     the union of
      !>
      !>     -  the set of points where an equality constraint is met
      !>
      !>     -  the boundary points of the confinement window
      !>
      !>     the solutions of both equality and inequality constraints can be
      !>     found easily once the monotone windows have been found.
      !>
      !>     Step Size
      !>     =========
      !>
      !>     The monotone windows (described above) are found via a two-step
      !>     search process. Each interval of the confinement window is
      !>     searched as follows: first, the input step size is used to
      !>     determine the time separation at which the sign of the rate of
      !>     change of the illumination angle will be sampled. Starting at the
      !>     left endpoint of an interval, samples will be taken at each step.
      !>     If a change of sign is found, a root has been bracketed; at that
      !>     point, the time at which the rate of change of the selected
      !>     illumination angle is zero can be found by a refinement process,
      !>     for example, via binary search.
      !>
      !>     Note that the optimal choice of step size depends on the lengths
      !>     of the intervals over which the illumination angle is monotone:
      !>     the step size should be shorter than the shortest of these
      !>     intervals (within the confinement window).
      !>
      !>     The optimal step size is *not* necessarily related to the lengths
      !>     of the intervals comprising the result window. For example, if
      !>     the shortest monotone interval has length 10 days, and if the
      !>     shortest result window interval has length 5 minutes, a step size
      !>     of 9.9 days is still adequate to find all of the intervals in the
      !>     result window. In situations like this, the technique of using
      !>     monotone windows yields a dramatic efficiency improvement over a
      !>     state-based search that simply tests at each step whether the
      !>     specified constraint is satisfied. The latter type of search can
      !>     miss solution intervals if the step size is longer than the
      !>     shortest solution interval.
      !>
      !>     Having some knowledge of the relative geometry of the target,
      !>     observer, and illumination source can be a valuable aid in
      !>     picking a reasonable step size. In general, the user can
      !>     compensate for lack of such knowledge by picking a very short
      !>     step size; the cost is increased computation time.
      !>
      !>     Note that the step size is not related to the precision with which
      !>     the endpoints of the intervals of the result window are computed.
      !>     That precision level is controlled by the convergence tolerance.
      !>
      !>     Convergence Tolerance
      !>     =====================
      !>
      !>     As described above, the root-finding process used by this routine
      !>     involves first bracketing roots and then using a search process
      !>     to locate them. "Roots" are both times when local extrema are
      !>     attained and times when the illumination angle is equal to a
      !>     reference value. All endpoints of the intervals comprising the
      !>     result window are either endpoints of intervals of the
      !>     confinement window or roots.
      !>
      !>     Once a root has been bracketed, a refinement process is used to
      !>     narrow down the time interval within which the root must lie.
      !>     This refinement process terminates when the location of the root
      !>     has been determined to within an error margin called the
      !>     "convergence tolerance." The convergence tolerance used by this
      !>     routine is set via the parameter CNVTOL.
      !>
      !>     The value of CNVTOL is set to a "tight" value so that the
      !>     tolerance doesn't become the limiting factor in the accuracy of
      !>     solutions found by this routine. In general the accuracy of input
      !>     data will be the limiting factor.
      !>
      !>     The user may change the convergence tolerance from the default
      !>     CNVTOL value by calling the routine GFSTOL, e.g.
      !>
      !>        CALL GFSTOL( tolerance value in seconds )
      !>
      !>     Call GFSTOL prior to calling this routine. All subsequent
      !>     searches will use the updated tolerance value.
      !>
      !>     Searches over time windows of long duration may require use of
      !>     larger tolerance values than the default: the tolerance must be
      !>     large enough so that it, when added to or subtracted from the
      !>     confinement window's lower and upper bounds, yields distinct time
      !>     values.
      !>
      !>     Setting the tolerance tighter than CNVTOL is unlikely to be
      !>     useful, since the results are unlikely to be more accurate.
      !>     Making the tolerance looser will speed up searches somewhat,
      !>     since a few convergence steps will be omitted.
      !>
      !>     The Confinement Window
      !>     ======================
      !>
      !>     The simplest use of the confinement window is to specify a time
      !>     interval within which a solution is sought. However, the
      !>     confinement window can, in some cases, be used to make searches
      !>     more efficient. Sometimes it's possible to do an efficient search
      !>     to reduce the size of the time period over which a relatively
      !>     slow search of interest must be performed.
      !>
      !>     Certain types of searches require the state of the observer,
      !>     relative to the solar system barycenter, to be computed at times
      !>     slightly outside the confinement window CNFINE. The time window
      !>     that is actually used is the result of "expanding" CNFINE by a
      !>     specified amount "T": each time interval of CNFINE is expanded by
      !>     shifting the interval's left endpoint to the left and the right
      !>     endpoint to the right by T seconds. Any overlapping intervals are
      !>     merged. (The input argument CNFINE is not modified.)
      !>
      !>     The window expansions listed below are additive: if both
      !>     conditions apply, the window expansion amount is the sum of the
      !>     individual amounts.
      !>
      !>     -  If a search uses an equality constraint, the time window
      !>        over which the state of the observer is computed is expanded
      !>        by 1 second at both ends of all of the time intervals
      !>        comprising the window over which the search is conducted.
      !>
      !>     -  If a search uses stellar aberration corrections, the time
      !>        window over which the state of the observer is computed is
      !>        expanded as described above.
      !>
      !>     When light time corrections are used, expansion of the search
      !>     window also affects the set of times at which the light time-
      !>     corrected state of the target is computed.
      !>
      !>     In addition to the possible 2 second expansion of the search
      !>     window that occurs when both an equality constraint and stellar
      !>     aberration corrections are used, round-off error should be taken
      !>     into account when the need for data availability is analyzed.
      !>
      !>## Examples
      !>
      !>     The numerical results shown for this example may differ across
      !>     platforms. The results depend on the SPICE kernels used as
      !>     input, the compiler and supporting libraries, and the machine
      !>     specific arithmetic implementation.
      !>
      !>     1) Determine time intervals over which the MER-1 ("Opportunity")
      !>        rover's location satisfies certain constraints on its
      !>        illumination and visibility as seen from the Mars
      !>        Reconnaissance Orbiter (MRO) spacecraft.
      !>
      !>        In this case we require the emission angle to be less than
      !>        20 degrees and the solar incidence angle to be less than
      !>        60 degrees.
      !>
      !>        The reader can verify that the observation start times of the
      !>        MRO HIRISE images
      !>
      !>           Product ID              Image start time
      !>           ----------              ----------------
      !>           TRA_000873_1780_RED     2006-10-03T12:44:13.425
      !>           PSP_001414_1780_RED     2006-11-14T15:39:55.373
      !>           PSP_001612_1780_RED     2006-11-30T01:38:34.390
      !>
      !>        are contained within the result window found by the
      !>        example program shown below.
      !>
      !>        Use the meta-kernel shown below to load the required SPICE
      !>        kernels.
      !>
      !>           KPL/MK
      !>
      !>           File: gfilum_ex1.tm
      !>
      !>           This meta-kernel is intended to support operation of SPICE
      !>           example programs. The kernels shown here should not be
      !>           assumed to contain adequate or correct versions of data
      !>           required by SPICE-based user applications.
      !>
      !>           In order for an application to use this meta-kernel, the
      !>           kernels referenced here must be present in the user's
      !>           current working directory.
      !>
      !>           The names and contents of the kernels referenced
      !>           by this meta-kernel are as follows:
      !>
      !>              File name                     Contents
      !>              ---------                     --------
      !>              de421.bsp                     Planetary ephemeris
      !>              pck00010.tpc                  Planet orientation
      !>                                            and radii
      !>              naif0010.tls                  Leapseconds
      !>              mro_psp1.bsp                  MRO ephemeris
      !>              mer1_surf_rover_ext10_v1.bsp  MER-1 ephemeris
      !>              mer1_surf_rover_ext11_v1.bsp  MER-1 ephemeris
      !>              mer1_ls_040128_iau2000_v1.bsp MER-1 landing site
      !>                                            ephemeris
      !>              mer1_v10.tf                   MER-1 frame kernel
      !>
      !>           \begindata
      !>
      !>              KERNELS_TO_LOAD = ( 'de421.bsp',
      !>                                  'pck00010.tpc',
      !>                                  'naif0010.tls',
      !>                                  'mro_psp1.bsp',
      !>                                  'mer1_surf_rover_ext10_v1.bsp',
      !>                                  'mer1_surf_rover_ext11_v1.bsp',
      !>                                  'mer1_ls_040128_iau2000_v1.bsp',
      !>                                  'mro_psp1.bsp',
      !>                                  'mer1_v10.tf'                    )
      !>           \begintext
      !>
      !>           End of meta-kernel
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM GFILUM_EX1
      !>      IMPLICIT NONE
      !>
      !>C
      !>C     Global parameters
      !>C
      !>      INCLUDE 'gf.inc'
      !>      INCLUDE 'zzabcorr.inc'
      !>
      !>C
      !>C     SPICELIB functions
      !>C
      !>      DOUBLE PRECISION      DPR
      !>      DOUBLE PRECISION      RPD
      !>
      !>      INTEGER               WNCARD
      !>
      !>C
      !>C     Local parameters
      !>C
      !>C
      !>C     Output time format
      !>C
      !>      CHARACTER*(*)         FMT
      !>      PARAMETER           ( FMT =
      !>     .             'YYYY MON DD HR:MN:SC.### UTC' )
      !>
      !>C
      !>C     Meta-kernel name
      !>C
      !>      CHARACTER*(*)         META
      !>      PARAMETER           ( META   = 'gfilum_ex1.tm' )
      !>
      !>C
      !>C     SPICE cell lower bound
      !>C
      !>      INTEGER               LBCELL
      !>      PARAMETER           ( LBCELL = -5 )
      !>
      !>C
      !>C     Maximum number of intervals in the windows
      !>C     used in this program
      !>C
      !>      INTEGER               MAXIVL
      !>      PARAMETER           ( MAXIVL = 1000 )
      !>
      !>      INTEGER               MAXWIN
      !>      PARAMETER           ( MAXWIN = 2 * MAXIVL )
      !>
      !>C
      !>C     Maximum length of reference frame name
      !>C
      !>      INTEGER               FRNMLN
      !>      PARAMETER           ( FRNMLN = 32 )
      !>
      !>C
      !>C     Maximum length of body name
      !>C
      !>      INTEGER               BDNMLN
      !>      PARAMETER           ( BDNMLN = 36 )
      !>
      !>C
      !>C     Maximum length of time string
      !>C
      !>      INTEGER               TIMLEN
      !>      PARAMETER           ( TIMLEN = 40 )
      !>
      !>C
      !>C     Length of computation method string
      !>C
      !>      INTEGER               METLEN
      !>      PARAMETER           ( METLEN = 80 )
      !>
      !>C
      !>C     Local variables
      !>C
      !>      CHARACTER*(CORLEN)    ABCORR
      !>      CHARACTER*(FRNMLN)    FIXREF
      !>      CHARACTER*(BDNMLN)    ILLMN
      !>      CHARACTER*(METLEN)    METHOD
      !>      CHARACTER*(BDNMLN)    OBSRVR
      !>      CHARACTER*(BDNMLN)    TARGET
      !>      CHARACTER*(TIMLEN)    TIMSTR
      !>      CHARACTER*(TIMLEN)    UTCBEG
      !>      CHARACTER*(TIMLEN)    UTCEND
      !>
      !>      DOUBLE PRECISION      ADJUST
      !>      DOUBLE PRECISION      CNFINE ( LBCELL : 2 )
      !>      DOUBLE PRECISION      EMISSN
      !>      DOUBLE PRECISION      ET0
      !>      DOUBLE PRECISION      ET1
      !>      DOUBLE PRECISION      FINISH
      !>      DOUBLE PRECISION      PHASE
      !>      DOUBLE PRECISION      REFVAL
      !>      DOUBLE PRECISION      RESULT ( LBCELL : MAXWIN )
      !>      DOUBLE PRECISION      ROVLT
      !>      DOUBLE PRECISION      ROVPOS ( 3 )
      !>      DOUBLE PRECISION      SOLAR
      !>      DOUBLE PRECISION      SRFVEC ( 3 )
      !>      DOUBLE PRECISION      START
      !>      DOUBLE PRECISION      STEP
      !>      DOUBLE PRECISION      TRGEPC
      !>      DOUBLE PRECISION      WORK   ( LBCELL : MAXWIN, NWILUM )
      !>      DOUBLE PRECISION      WNSOLR ( LBCELL : MAXWIN )
      !>
      !>      INTEGER               I
      !>
      !>C
      !>C     Saved variables
      !>C
      !>C     The confinement, workspace and result windows CNFINE,
      !>C     WORK, WNSOLR and RESULT are saved because this practice
      !>C     helps to prevent stack overflow.
      !>C
      !>      SAVE                  CNFINE
      !>      SAVE                  RESULT
      !>      SAVE                  WORK
      !>      SAVE                  WNSOLR
      !>
      !>C
      !>C     Load kernels:
      !>C
      !>      CALL FURNSH ( META )
      !>
      !>C
      !>C     Set window sizes:
      !>C
      !>      CALL SSIZED ( 2,      CNFINE )
      !>      CALL SSIZED ( MAXWIN, RESULT )
      !>      CALL SSIZED ( MAXWIN, WNSOLR )
      !>
      !>C
      !>C     Set the search interval:
      !>C
      !>      UTCBEG = '2006 OCT 02 00:00:00 UTC'
      !>      CALL STR2ET ( UTCBEG, ET0 )
      !>
      !>      UTCEND = '2006 NOV 30 12:00:00 UTC'
      !>      CALL STR2ET ( UTCEND, ET1 )
      !>
      !>      CALL WNINSD ( ET0, ET1, CNFINE )
      !>
      !>C
      !>C     Set observer, target, aberration correction, and the
      !>C     Mars body-fixed, body-centered reference frame. The
      !>C     lighting source is the sun.
      !>C
      !>C     Aberration corrections are set for remote observations.
      !>C
      !>      ILLMN  = 'SUN'
      !>      OBSRVR = 'MRO'
      !>      TARGET = 'MARS'
      !>      ABCORR = 'CN+S'
      !>      FIXREF = 'IAU_MARS'
      !>
      !>C
      !>C     Use the rover position at the start of
      !>C     the search interval as the surface point.
      !>C
      !>      CALL SPKPOS ( 'MER-1', ET0,    FIXREF,
      !>     .              'NONE',  TARGET, ROVPOS, ROVLT )
      !>
      !>C
      !>C     Initialize the adjustment value for absolute
      !>C     extremum searches. We're not performing
      !>C     such searches in this example, but this input
      !>C     to GFILUM must still be set.
      !>C
      !>      ADJUST = 0.D0
      !>
      !>C
      !>C     The computation uses an ellipsoidal model for the
      !>C     target body shape.
      !>C
      !>      METHOD = 'Ellipsoid'
      !>
      !>C
      !>C     Set the reference value to use for the solar
      !>C     incidence angle search.
      !>C
      !>      REFVAL = 60.D0 * RPD()
      !>
      !>C
      !>C     Since the period of the solar incidence angle
      !>C     is about one Martian day, we can safely use 6 hours
      !>C     as the search step.
      !>C
      !>      STEP   = 21600.D0
      !>
      !>C
      !>C     Search over the confinement window for times
      !>C     when the solar incidence angle is less than
      !>C     the reference value.
      !>C
      !>      CALL GFILUM ( METHOD, 'INCIDENCE',    TARGET, ILLMN,
      !>     .              FIXREF, ABCORR,         OBSRVR, ROVPOS,
      !>     .              '<',    REFVAL, ADJUST, STEP,   CNFINE,
      !>     .              MAXWIN, NWILUM, WORK,   WNSOLR          )
      !>
      !>C
      !>C     With the search on the incidence angle complete, perform
      !>C     a search on the emission angle.
      !>C
      !>C     Set the reference value for the emission angle search.
      !>C
      !>      REFVAL = 20D0 * RPD()
      !>
      !>C
      !>C     We'll use 15 minutes as the search step. This step
      !>C     is small enough to be suitable for Mars orbiters.
      !>C     Units are seconds.
      !>C
      !>      STEP   = 900.D0
      !>
      !>C
      !>C     Search over the previous result window for times when
      !>C     the emission angle is less than the reference value.
      !>C
      !>      CALL GFILUM ( METHOD, 'EMISSION', TARGET, ILLMN,
      !>     .              FIXREF, ABCORR,     OBSRVR, ROVPOS,
      !>     .              '<',    REFVAL,     ADJUST, STEP,
      !>     .              WNSOLR, MAXWIN,     NWILUM, WORK,
      !>     .              RESULT                             )
      !>
      !>C
      !>C     Display the result window. Show the solar incidence
      !>C     and emission angles at the window's interval
      !>C     boundaries.
      !>C
      !>      WRITE (*,*) ' '
      !>
      !>      IF ( WNCARD( RESULT ) .EQ. 0 ) THEN
      !>
      !>         WRITE (*,*) '     Window is empty: condition '
      !>     .   //          'is not met.'
      !>
      !>      ELSE
      !>
      !>         WRITE (*,*) '                                   '
      !>     .   //          'Solar Incidence   Emission'
      !>         WRITE (*,*) '                                   '
      !>     .   //          '      (deg)         (deg)'
      !>         WRITE (*,*) ' '
      !>
      !>         DO I = 1, WNCARD( RESULT )
      !>
      !>            CALL WNFETD ( RESULT, I, START, FINISH )
      !>
      !>            CALL TIMOUT ( START,  FMT,   TIMSTR )
      !>C
      !>C           Compute the angles of interest at the boundary
      !>C           epochs.
      !>C
      !>            CALL ILUMIN ( METHOD, TARGET, START,  FIXREF,
      !>     .                    ABCORR, OBSRVR, ROVPOS, TRGEPC,
      !>     .                    SRFVEC, PHASE,  SOLAR,  EMISSN )
      !>
      !>            WRITE (*, '(A7, A28, 2F14.8)' )
      !>     .            'Start: ', TIMSTR, SOLAR*DPR(), EMISSN*DPR()
      !>
      !>            CALL TIMOUT ( FINISH, FMT,   TIMSTR )
      !>
      !>            CALL ILUMIN ( METHOD, TARGET, FINISH, FIXREF,
      !>     .                    ABCORR, OBSRVR, ROVPOS, TRGEPC,
      !>     .                    SRFVEC, PHASE,  SOLAR,  EMISSN )
      !>
      !>            WRITE (*, '(A7, A28, 2F14.8)' )
      !>     .            'Stop:  ', TIMSTR, SOLAR*DPR(), EMISSN*DPR()
      !>
      !>            WRITE (*,*) ' '
      !>
      !>         END DO
      !>
      !>      END IF
      !>
      !>      END
      !>```
      !>
      !>        When this program was executed on a Mac/Intel/gfortran/64-bit
      !>        platform, the output was:
      !>
      !>                                            Solar Incidence   Emission
      !>                                                  (deg)         (deg)
      !>
      !>        Start: 2006 OCT 03 12:43:46.949 UTC   56.10415019   20.00000019
      !>        Stop:  2006 OCT 03 12:44:42.288 UTC   56.29996181   20.00000015
      !>
      !>        Start: 2006 OCT 08 16:03:33.956 UTC   56.48955485   20.00000021
      !>        Stop:  2006 OCT 08 16:04:29.495 UTC   56.68754510   19.99999997
      !>
      !>        Start: 2006 OCT 13 19:23:24.634 UTC   56.88741059   19.99999988
      !>        Stop:  2006 OCT 13 19:24:12.492 UTC   57.05931857   20.00000017
      !>
      !>        Start: 2006 OCT 18 22:43:21.631 UTC   57.30924467   20.00000012
      !>        Stop:  2006 OCT 18 22:43:47.966 UTC   57.40457272   20.00000004
      !>
      !>        Start: 2006 NOV 14 15:39:44.153 UTC   54.32875839   19.99999994
      !>        Stop:  2006 NOV 14 15:40:10.446 UTC   54.42668077   19.99999990
      !>
      !>        Start: 2006 NOV 19 18:59:10.190 UTC   54.63096111   20.00000007
      !>        Stop:  2006 NOV 19 18:59:54.776 UTC   54.79840753   19.99999985
      !>
      !>        Start: 2006 NOV 24 22:18:38.342 UTC   54.94960000   19.99999982
      !>        Stop:  2006 NOV 24 22:19:30.964 UTC   55.14883883   20.00000003
      !>
      !>        Start: 2006 NOV 30 01:38:07.309 UTC   55.28054784   19.99999983
      !>        Stop:  2006 NOV 30 01:39:03.296 UTC   55.49418925   19.99999999
      !>
      !>## Restrictions
      !>
      !>     1)  The kernel files to be used by this routine must be loaded
      !>         (normally using the SPICELIB routine FURNSH) before this
      !>         routine is called.
      !>
      !>     2)  This routine has the side effect of re-initializing the
      !>         illumination angle utility package. Callers may
      !>         need to re-initialize the package after calling this routine.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     B.V. Semenov       (JPL)
      !>     E.D. Wright        (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.1.0, 27-OCT-2021 (JDR) (NJB)
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>        Changed the code example for the solution to fit within the
      !>        $Examples section without modifications. Added SAVE statements
      !>        for CNFINE, WNSOLR, WORK and RESULT variables in code example.
      !>
      !>        Added initialization of QCPARS(8) to pacify Valgrind.
      !>
      !>        Updated description of WORK and RESULT arguments in $Brief_I/O,
      !>        $Detailed_Input and $Detailed_Output.
      !>
      !>        Updated header to describe use of expanded confinement window.
      !>
      !>-    SPICELIB Version 1.0.0, 20-NOV-2012 (NJB) (BVS) (EDW)
      module subroutine gfilum ( ctx, method, angtyp, target, illmn, fixref, abcorr, obsrvr, spoint, relate, refval, adjust, step, cnfine, mw, nw, work, result )
      use pepper_kinds, only: ip, wp
      use pepper_inc_gf
      use pepper_inc_zzabcorr
      use pepper_inc_zzholdd
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), parameter :: lbcell = -5
      character(*), intent(in) :: method  !! Computation method.
      character(*), intent(in) :: angtyp  !! Type of illumination angle.
      character(*), intent(in) :: target  !! Name of the target body.
      character(*), intent(in) :: illmn  !! Name of the illumination source.
      character(*), intent(in) :: fixref  !! Body-fixed, body-centered target body frame.
      character(*), intent(in) :: abcorr  !! Aberration correction flag.
      character(*), intent(in) :: obsrvr  !! Name of the observing body.
      real(wp), intent(in) :: spoint ( 3 )  !! Body-fixed coordinates of a target surface point.
      character(*), intent(in) :: relate  !! Relational operator.
      real(wp), intent(in) :: refval  !! Reference value.
      real(wp), intent(in) :: adjust  !! Adjustment value for absolute extrema searches.
      real(wp), intent(in) :: step  !! Step size used for locating extrema and roots.
      real(wp), intent(in) :: cnfine ( lbcell : * )  !! SPICE window to which the search is confined.
      integer(ip), intent(in) :: mw  !! Workspace window size.
      integer(ip), intent(in) :: nw  !! Workspace window count.
      real(wp), intent(inout) :: work   ( lbcell : mw, nw )  !! Array of workspace windows.
      real(wp), intent(inout) :: result ( lbcell : * )  !! SPICE window containing results.


!
!     External functions
!

      integer(ip), parameter :: qnpars = 8



!
!     Quantity definition parameter arrays:
!
      character(lnsize) :: qcpars ( qnpars )
      character(lnsize) :: qpnams ( qnpars )

      real(wp) :: qdpars ( qnpars )

      integer(ip) :: qipars ( qnpars )

      logical :: qlpars ( qnpars )

      real(wp) :: tol

      logical :: ok

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Check the result window's size.
!
      if ( sized( ctx,result) < 2 ) then

         call ctx%setmsg ( 'Result window size must be at least 2 ' &
         //            'but was #.'                            )
         call ctx%errint ( '#',  sized( ctx,result)                     )
         call ctx%sigerr ( 'SPICE(INVALIDDIMENSION)'               )
         return

      end if

!
!     Check the workspace window dimensions.
!
      if ( mw < 2 ) then

         call ctx%setmsg ( 'Workspace window size was #; size must be ' &
         //            'at least 2.'                               )
         call ctx%errint ( '#',  mw                                    )
         call ctx%sigerr ( 'SPICE(INVALIDDIMENSION)'                   )
         return

      end if

      if ( nw < nwilum ) then

         call ctx%setmsg ( 'Workspace window count was #; count must be ' &
         //            'at least #.'                                 )
         call ctx%errint ( '#',  nw                                      )
         call ctx%errint ( '#',  nwilum                                  )
         call ctx%sigerr ( 'SPICE(INVALIDDIMENSION)'                     )
         return

      end if

!
!     Set up a call to GFEVNT, which will handle the search.
!
      qpnams(1) = 'TARGET'
      qcpars(1) = target

      qpnams(2) = 'ILLUM'
      qcpars(2) = illmn

      qpnams(3) = 'OBSERVER'
      qcpars(3) =  obsrvr

      qpnams(4) = 'ABCORR'
      qcpars(4) =  abcorr

      qpnams(5) = 'REFERENCE FRAME'
      qcpars(5) =  fixref

      qpnams(6) = 'ANGTYP'
      qcpars(6) =  angtyp

      qpnams(7) = 'METHOD'
      qcpars(7) =  method

!
!     Copy SPOINT to elements 1-3 of the QDPARS array.
!
      qpnams(8) = 'SPOINT'
      qdpars(1:3) = spoint

!
!     Initialize the corresponding character parameter, even though
!     we don't need it, since GFEVNT will left-justify it and convert
!     it to upper case. Memory usage checkers such as Valgrind dislike
!     code that operates on uninitialized variables.
!
      qcpars(8) = ' '

!
!     Set the step size.
!
      if ( step <= 0.0_wp ) then

         call ctx%setmsg ( 'Step size was #; step size must be positive.' )
         call ctx%errdp  ( '#',  step                                     )
         call ctx%sigerr ( 'SPICE(INVALIDSTEP)'                           )
         return

      end if

      call gfsstp ( ctx, step )

!
!     Retrieve the convergence tolerance, if set.
!
      call zzholdd ( ctx, zzget, gf_tol, ok, tol )

!
!     Use the default value CNVTOL if there's no stored tolerance
!     value.
!
      if ( .not. ok ) then

         tol = cnvtol

      end if

!
!     Initialize the RESULT window.
!
      call scardd ( ctx, 0, result )

!
!     Look for solutions.
!
!     Progress report and bail-out options are set to .FALSE.
!
      call gfevnt ( ctx, gfstep,  gfrefn,  'ILLUMINATION ANGLE',  qnpars, &
                    qpnams,  qcpars,  qdpars,                qipars, &
                    qlpars,  relate,  refval,                tol, &
                    adjust,  cnfine,  norpt,                 gfrepi, &
                    gfrepu,  gfrepf,  mw,                    nwilum, &
                    work,    nobail,  gfbail,                result )

      return
      end subroutine gfilum

      !> Determine time intervals for which a specified constraint
      !> on the phase angle between an illumination source, a target,
      !> and observer body centers is met.
      !>
      !>## Detailed Input
      !>
      !>     TARGET   is the name of a target body. Optionally, you may supply
      !>              a string containing the integer ID code for the object.
      !>              For example both 'MOON' and '301' are legitimate strings
      !>              that indicate the Moon is the target body.
      !>
      !>              Case and leading or trailing blanks are not significant
      !>              in the string TARGET.
      !>
      !>     ILLMN    is the name of the illuminating body. This will normally
      !>              be 'SUN' but the algorithm can use any ephemeris object.
      !>
      !>              Case and leading or trailing blanks are not significant
      !>              in the string ILLMN.
      !>
      !>     ABCORR   is the description of the aberration corrections to apply
      !>              to the state evaluations to account for one-way light
      !>              time and stellar aberration.
      !>
      !>              This routine accepts only reception mode aberration
      !>              corrections. See the header of SPKEZR for a detailed
      !>              description of the aberration correction options. For
      !>              convenience, the allowed aberration options are listed
      !>              below:
      !>
      !>                 'NONE'     Apply no correction. Returns the "true"
      !>                            geometric state.
      !>
      !>                 'LT'       "Reception" case: correct for
      !>                            one-way light time using a Newtonian
      !>                            formulation.
      !>
      !>                 'LT+S'     "Reception" case: correct for
      !>                            one-way light time and stellar
      !>                            aberration using a Newtonian
      !>                            formulation.
      !>
      !>                 'CN'       "Reception" case: converged
      !>                            Newtonian light time correction.
      !>
      !>                'CN+S'      "Reception" case: converged
      !>                            Newtonian light time and stellar
      !>                            aberration corrections.
      !>
      !>              Case and leading or trailing blanks are not significant
      !>              in the string ABCORR.
      !>
      !>     OBSRVR   is the name of an observing body. Optionally, you may
      !>              supply a string containing the integer ID code for the
      !>              object. For example both "MOON" and "301" are legitimate
      !>              strings that indicate the Moon is the observer.
      !>
      !>              Case and leading or trailing blanks are not significant
      !>              in the string OBSRVR.
      !>
      !>     RELATE   is a relational operator used to define a constraint on a
      !>              specified phase angle. The result window found by this
      !>              routine indicates the time intervals where the constraint
      !>              is satisfied. Supported values of RELATE and
      !>              corresponding meanings are shown below:
      !>
      !>                 '>'        The phase angle value is greater than the
      !>                            reference value REFVAL.
      !>
      !>                 '='        The phase angle value is equal to the
      !>                            reference value REFVAL.
      !>
      !>                 '<'        The phase angle value is less than the
      !>                            reference value REFVAL.
      !>
      !>                 'ABSMAX'   The phase angle value is at an absolute
      !>                            maximum.
      !>
      !>                 'ABSMIN'   The phase angle value is at an absolute
      !>                            minimum.
      !>
      !>                 'LOCMAX'   The phase angle value is at a local
      !>                            maximum.
      !>
      !>                 'LOCMIN'   The phase angle value is at a local
      !>                            minimum.
      !>
      !>              RELATE may be used to specify an "adjusted" absolute
      !>              extremum constraint: this requires the phase angle to be
      !>              within a specified offset relative to an absolute
      !>              extremum. The argument ADJUST (described below) is used
      !>              to specify this offset.
      !>
      !>              Local extrema are considered to exist only in the
      !>              interiors of the intervals comprising the confinement
      !>              window:  a local extremum cannot exist at a boundary
      !>              point of the confinement window.
      !>
      !>              Case and leading or trailing blanks are not
      !>              significant in the string RELATE.
      !>
      !>     REFVAL   is the double precision reference value used together
      !>              with the argument RELATE to define an equality or
      !>              inequality to be satisfied by the phase angle. See the
      !>              discussion of RELATE above for further information.
      !>
      !>              The units of REFVAL are radians.
      !>
      !>     ADJUST   is a double precision value used to modify searches for
      !>              absolute extrema: when RELATE is set to 'ABSMAX' or
      !>              'ABSMIN' and ADJUST is set to a positive value, GFPA
      !>              finds times when the phase angle is within ADJUST radians
      !>              of the specified extreme value.
      !>
      !>              For RELATE set to 'ABSMAX', the RESULT window contains
      !>              time intervals when the phase angle has
      !>              values between ABSMAX - ADJUST and ABSMAX.
      !>
      !>              For RELATE set to 'ABSMIN', the RESULT window contains
      !>              time intervals when the phase angle has
      !>              values between ABSMIN and ABSMIN + ADJUST.
      !>
      !>              ADJUST is not used for searches for local extrema,
      !>              equality or inequality conditions.
      !>
      !>     STEP     is the double precision time step size to use in the
      !>              search.
      !>
      !>              STEP must be short enough for a search using this step
      !>              size to locate the time intervals where the phase angle
      !>              function is monotone increasing or decreasing. However,
      !>              STEP must not be *too* short, or the search will take an
      !>              unreasonable amount of time.
      !>
      !>              The choice of STEP affects the completeness but not
      !>              the precision of solutions found by this routine; the
      !>              precision is controlled by the convergence tolerance.
      !>              See the discussion of the parameter CNVTOL for
      !>              details.
      !>
      !>              STEP has units of TDB seconds.
      !>
      !>     CNFINE   is a double precision SPICE window that confines the time
      !>              period over which the specified search is conducted.
      !>              CNFINE may consist of a single interval or a collection
      !>              of intervals.
      !>
      !>              In some cases the confinement window can be used to
      !>              greatly reduce the time period that must be searched
      !>              for the desired solution. See the $Particulars section
      !>              below for further discussion.
      !>
      !>              The endpoints of the time intervals comprising CNFINE are
      !>              interpreted as seconds past J2000 TDB.
      !>
      !>              See the $Examples section below for a code example
      !>              that shows how to create a confinement window.
      !>
      !>              CNFINE must be initialized by the caller using the
      !>              SPICELIB routine SSIZED.
      !>
      !>              In some cases the observer's state may be computed at
      !>              times outside of CNFINE by as much as 2 seconds. See
      !>              $Particulars for details.
      !>
      !>     MW       is a parameter specifying the length of the SPICE
      !>              windows in the workspace array WORK (see description
      !>              below) used by this routine.
      !>
      !>              MW should be set to a number at least twice as large
      !>              as the maximum number of intervals required by any
      !>              workspace window. In many cases, it's not necessary to
      !>              compute an accurate estimate of how many intervals are
      !>              needed; rather, the user can pick a size considerably
      !>              larger than what's really required.
      !>
      !>              However, since excessively large arrays can prevent
      !>              applications from compiling, linking, or running
      !>              properly, sometimes MW must be set according to
      !>              the actual workspace requirement. A rule of thumb
      !>              for the number of intervals NINTVLS needed is
      !>
      !>                  NINTVLS  =  2*N  +  ( M / STEP )
      !>
      !>              where
      !>
      !>                  N     is the number of intervals in the confinement
      !>                        window
      !>
      !>                  M     is the measure of the confinement window, in
      !>                        units of seconds
      !>
      !>                  STEP  is the search step size in seconds
      !>
      !>              MW should then be set to
      !>
      !>                  2 * NINTVLS
      !>
      !>     NW       is a parameter specifying the number of SPICE windows
      !>              in the workspace array WORK (see description below)
      !>              used by this routine. NW should be set to the
      !>              parameter NWPA; this parameter is declared in the
      !>              include file gf.inc. (The reason this dimension is
      !>              an input argument is that this allows run-time
      !>              error checking to be performed.)
      !>
      !>     RESULT   is a double precision SPICE window which will contain
      !>              the search results. RESULT must be declared and
      !>              initialized with sufficient size to capture the full
      !>              set of time intervals within the search region on which
      !>              the specified condition is satisfied.
      !>
      !>              RESULT must be initialized by the caller via the
      !>              SPICELIB routine SSIZED.
      !>
      !>              If RESULT is non-empty on input, its contents will be
      !>              discarded before GFPA conducts its search.
      !>
      !>## Detailed Output
      !>
      !>     WORK     is an array used to store workspace windows.
      !>
      !>              This array should be declared by the caller as shown:
      !>
      !>                 INCLUDE 'gf.inc'
      !>                    ...
      !>
      !>                 DOUBLE PRECISION    WORK ( LBCELL : MW, NWPA )
      !>
      !>              where MW is a constant declared by the caller and
      !>              NWPA is a constant defined in the SPICELIB INCLUDE
      !>              file gf.inc. See the discussion of MW above.
      !>
      !>              WORK need not be initialized by the caller.
      !>
      !>              WORK is modified by this routine. The caller should
      !>              re-initialize this array before attempting to use it for
      !>              any other purpose.
      !>
      !>     RESULT   is the SPICE window of intervals, contained within the
      !>              confinement window CNFINE, on which the specified phase
      !>              angle constraint is satisfied.
      !>
      !>              The endpoints of the time intervals comprising RESULT are
      !>              interpreted as seconds past J2000 TDB.
      !>
      !>              If the search is for local extrema, or for absolute
      !>              extrema with ADJUST set to zero, then normally each
      !>              interval of RESULT will be a singleton: the left and
      !>              right endpoints of each interval will be identical.
      !>
      !>              If no times within the confinement window satisfy the
      !>              search criteria, RESULT will be returned with a
      !>              cardinality of zero.
      !>
      !>## Parameters
      !>
      !>     LBCELL   is the integer value defining the lower bound for
      !>              SPICE Cell arrays (a SPICE window is a kind of cell).
      !>
      !>     CNVTOL   is the default convergence tolerance used for finding
      !>              endpoints of the intervals comprising the result
      !>              window. CNVTOL is also used for finding intermediate
      !>              results; in particular, CNVTOL is used for finding the
      !>              windows on which the phase angle is increasing
      !>              or decreasing. CNVTOL is used to determine when binary
      !>              searches for roots should terminate: when a root is
      !>              bracketed within an interval of length CNVTOL; the
      !>              root is considered to have been found.
      !>
      !>              The accuracy, as opposed to precision, of roots found
      !>              by this routine depends on the accuracy of the input
      !>              data. In most cases, the accuracy of solutions will be
      !>              inferior to their precision.
      !>
      !>     See INCLUDE file gf.inc for declarations and descriptions of
      !>     parameters used throughout the GF system.
      !>
      !>## Exceptions
      !>
      !>     1)  In order for this routine to produce correct results,
      !>         the step size must be appropriate for the problem at hand.
      !>         Step sizes that are too large may cause this routine to miss
      !>         roots; step sizes that are too small may cause this routine
      !>         to run unacceptably slowly and in some cases, find spurious
      !>         roots.
      !>
      !>         This routine does not diagnose invalid step sizes, except that
      !>         if the step size is non-positive, an error is signaled by a
      !>         routine in the call tree of this routine.
      !>
      !>     2)  Due to numerical errors, in particular,
      !>
      !>            - truncation error in time values
      !>            - finite tolerance value
      !>            - errors in computed geometric quantities
      !>
      !>         it is *normal* for the condition of interest to not always be
      !>         satisfied near the endpoints of the intervals comprising the
      !>         RESULT window. One technique to handle such a situation,
      !>         slightly contract RESULT using the window routine WNCOND.
      !>
      !>     3)  If workspace window size, MW, is not at least 2 and an even
      !>         value, the error SPICE(INVALIDDIMENSION) is signaled is
      !>         signaled.
      !>
      !>     4)  If workspace window count, NW, is not at least NWPA, the error
      !>         SPICE(INVALIDDIMENSION) is signaled is signaled.
      !>
      !>     5)  If result window, RESULT, is not at least 2 and an even value,
      !>         the error SPICE(INVALIDDIMENSION) is signaled is signaled.
      !>
      !>     6)  If RESULT has insufficient capacity to contain the
      !>         number of intervals on which the specified angle condition
      !>         is met, an error is signaled by a routine in the call
      !>         tree of this routine.
      !>
      !>     7)  If an error (typically cell overflow) occurs during
      !>         window arithmetic, the error is signaled by a routine
      !>         in the call tree of this routine.
      !>
      !>     8)  If the relational operator RELATE is not recognized, an
      !>         error is signaled by a routine in the call tree of this
      !>         routine.
      !>
      !>     9)  If ADJUST is negative, an error is signaled by a routine in
      !>         the call tree of this routine.
      !>
      !>     10) If ADJUST has a non-zero value when RELATE has any value other
      !>         than 'ABSMIN' or 'ABSMAX', an error is signaled by a routine
      !>         in the call tree of this routine.
      !>
      !>     11) If any of the input body names, TARGET, ILLMN, OBSRVR, do
      !>         not map to NAIF ID codes, an error is signaled by a routine
      !>         in the call tree of this routine.
      !>
      !>     12) If the input body names, TARGET, ILLMN, OBSRVR, are not
      !>         distinct, an error is signaled by a routine in the call
      !>         tree of this routine.
      !>
      !>     13) If required ephemerides or other kernel data are not
      !>         available, an error is signaled by a routine in the call tree
      !>         of this routine.
      !>
      !>     14) If the aberration correction specifier contains an
      !>         unrecognized value, an error is signaled by a routine in the
      !>         call tree of this routine.
      !>
      !>     15) If a transmit mode aberration correction is requested, an
      !>         error is signaled by a routine in the call tree of this
      !>         routine.
      !>
      !>## Files
      !>
      !>     Appropriate SPK and PCK kernels must be loaded by the calling
      !>     program before this routine is called.
      !>
      !>     The following data are required:
      !>
      !>     -  SPK data: the calling application must load ephemeris data
      !>        for the targets, observer, and any intermediate objects in
      !>        a chain connecting the targets and observer that cover the
      !>        time period specified by the window CNFINE. If aberration
      !>        corrections are used, the states of target and observer
      !>        relative to the solar system barycenter must be calculable
      !>        from the available ephemeris data. Typically ephemeris data
      !>        are made available by loading one or more SPK files using
      !>        FURNSH.
      !>
      !>     -  In some cases the observer's state may be computed at times
      !>        outside of CNFINE by as much as 2 seconds; data required to
      !>        compute this state must be provided by loaded kernels. See
      !>        $Particulars for details.
      !>
      !>     Kernel data are normally loaded once per program run, NOT every
      !>     time this routine is called.
      !>
      !>## Particulars
      !>
      !>                        ILLMN      OBS
      !>        ILLMN as seen      *       /
      !>        from TARG at       |      /
      !>        ET - LT.           |     /
      !>                          >|..../< phase angle
      !>                           |   /
      !>                         . |  /
      !>                       .   | /
      !>                      .     *     TARG as seen from OBS
      !>                SEP   .   TARG    at ET
      !>                       .  /
      !>                         /
      !>                        *
      !>
      !>     This routine determines if the caller-specified constraint
      !>     condition on the geometric event (phase angle) is satisfied for
      !>     any time intervals within the confinement window CNFINE. If one
      !>     or more such time intervals exist, those intervals are added
      !>     to the RESULT window.
      !>
      !>     This routine provides a simpler, but less flexible interface
      !>     than does the routine GFEVNT for conducting searches for
      !>     illuminator-target-observer phase angle value events.
      !>     Applications that require support for progress reporting,
      !>     interrupt handling, non-default step or refinement functions
      !>     should call GFEVNT rather than this routine.
      !>
      !>     Below we discuss in greater detail aspects of this routine's
      !>     solution process that are relevant to correct and efficient
      !>     use of this routine in user applications.
      !>
      !>     The Search Process
      !>     ==================
      !>
      !>     Regardless of the type of constraint selected by the caller, this
      !>     routine starts the search for solutions by determining the time
      !>     periods, within the confinement window, over which the
      !>     phase angle function is monotone increasing and monotone
      !>     decreasing. Each of these time periods is represented by a SPICE
      !>     window. Having found these windows, all of the phase angle
      !>     function's local extrema within the confinement window are known.
      !>     Absolute extrema then can be found very easily.
      !>
      !>     Within any interval of these "monotone" windows, there will be at
      !>     most one solution of any equality constraint. Since the boundary
      !>     of the solution set for any inequality constraint is contained in
      !>     the union of
      !>
      !>     -  the set of points where an equality constraint is met
      !>
      !>     -  the boundary points of the confinement window
      !>
      !>     the solutions of both equality and inequality constraints can be
      !>     found easily once the monotone windows have been found.
      !>
      !>     Step Size
      !>     =========
      !>
      !>     The monotone windows (described above) are found using a two-step
      !>     search process. Each interval of the confinement window is
      !>     searched as follows: first, the input step size is used to
      !>     determine the time separation at which the sign of the rate of
      !>     change of phase angle will be sampled. Starting at
      !>     the left endpoint of an interval, samples will be taken at each
      !>     step. If a change of sign is found, a root has been bracketed; at
      !>     that point, the time at which the time derivative of the
      !>     phase angle is zero can be found by a refinement process, for
      !>     example, using a binary search.
      !>
      !>     Note that the optimal choice of step size depends on the lengths
      !>     of the intervals over which the phase angle function is monotone:
      !>     the step size should be shorter than the shortest of these
      !>     intervals (within the confinement window).
      !>
      !>     The optimal step size is *not* necessarily related to the lengths
      !>     of the intervals comprising the result window. For example, if
      !>     the shortest monotone interval has length 10 days, and if the
      !>     shortest result window interval has length 5 minutes, a step size
      !>     of 9.9 days is still adequate to find all of the intervals in the
      !>     result window. In situations like this, the technique of using
      !>     monotone windows yields a dramatic efficiency improvement over a
      !>     state-based search that simply tests at each step whether the
      !>     specified constraint is satisfied. The latter type of search can
      !>     miss solution intervals if the step size is longer than the
      !>     shortest solution interval.
      !>
      !>     Having some knowledge of the relative geometry of the target,
      !>     illumination source, and observer can be a valuable aid in
      !>     picking a reasonable step size. In general, the user can
      !>     compensate for lack of such knowledge by picking a very short
      !>     step size; the cost is increased computation time.
      !>
      !>     Note that the step size is not related to the precision with which
      !>     the endpoints of the intervals of the result window are computed.
      !>     That precision level is controlled by the convergence tolerance.
      !>
      !>     Convergence Tolerance
      !>     =====================
      !>
      !>     As described above, the root-finding process used by this routine
      !>     involves first bracketing roots and then using a search process
      !>     to locate them. "Roots" are both times when local extrema are
      !>     attained and times when the geometric quantity function is equal
      !>     to a reference value. All endpoints of the intervals comprising
      !>     the result window are either endpoints of intervals of the
      !>     confinement window or roots.
      !>
      !>     Once a root has been bracketed, a refinement process is used to
      !>     narrow down the time interval within which the root must lie.
      !>     This refinement process terminates when the location of the root
      !>     has been determined to within an error margin called the
      !>     "convergence tolerance." The default convergence tolerance
      !>     used by this routine is set by the parameter CNVTOL (defined
      !>     in gf.inc).
      !>
      !>     The value of CNVTOL is set to a "tight" value so that the
      !>     tolerance doesn't become the limiting factor in the accuracy of
      !>     solutions found by this routine. In general the accuracy of input
      !>     data will be the limiting factor.
      !>
      !>     The user may change the convergence tolerance from the default
      !>     CNVTOL value by calling the routine GFSTOL, e.g.
      !>
      !>        CALL GFSTOL( tolerance value )
      !>
      !>     Call GFSTOL prior to calling this routine. All subsequent
      !>     searches will use the updated tolerance value.
      !>
      !>     Setting the tolerance tighter than CNVTOL is unlikely to be
      !>     useful, since the results are unlikely to be more accurate.
      !>     Making the tolerance looser will speed up searches somewhat,
      !>     since a few convergence steps will be omitted. However, in most
      !>     cases, the step size is likely to have a much greater effect
      !>     on processing time than would the convergence tolerance.
      !>
      !>     The Confinement Window
      !>     ======================
      !>
      !>     The simplest use of the confinement window is to specify a time
      !>     interval within which a solution is sought. However, the
      !>     confinement window can, in some cases, be used to make searches
      !>     more efficient. Sometimes it's possible to do an efficient search
      !>     to reduce the size of the time period over which a relatively
      !>     slow search of interest must be performed.
      !>
      !>     Certain types of searches require the state of the observer,
      !>     relative to the solar system barycenter, to be computed at times
      !>     slightly outside the confinement window CNFINE. The time window
      !>     that is actually used is the result of "expanding" CNFINE by a
      !>     specified amount "T": each time interval of CNFINE is expanded by
      !>     shifting the interval's left endpoint to the left and the right
      !>     endpoint to the right by T seconds. Any overlapping intervals are
      !>     merged. (The input argument CNFINE is not modified.)
      !>
      !>     The window expansions listed below are additive: if both
      !>     conditions apply, the window expansion amount is the sum of the
      !>     individual amounts.
      !>
      !>     -  If a search uses an equality constraint, the time window
      !>        over which the state of the observer is computed is expanded
      !>        by 1 second at both ends of all of the time intervals
      !>        comprising the window over which the search is conducted.
      !>
      !>     -  If a search uses stellar aberration corrections, the time
      !>        window over which the state of the observer is computed is
      !>        expanded as described above.
      !>
      !>     When light time corrections are used, expansion of the search
      !>     window also affects the set of times at which the light time-
      !>     corrected state of the target is computed.
      !>
      !>     In addition to the possible 2 second expansion of the search
      !>     window that occurs when both an equality constraint and stellar
      !>     aberration corrections are used, round-off error should be taken
      !>     into account when the need for data availability is analyzed.
      !>
      !>## Examples
      !>
      !>     The numerical results shown for this example may differ across
      !>     platforms. The results depend on the SPICE kernels used as
      !>     input, the compiler and supporting libraries, and the machine
      !>     specific arithmetic implementation.
      !>
      !>     1) Determine the time windows from December 1, 2006 UTC to
      !>        January 31, 2007 UTC for which the sun-moon-earth configuration
      !>        phase angle satisfies the relation conditions with respect to a
      !>        reference value of .57598845 radians (the phase angle at
      !>        January 1, 2007 00:00:00.000 UTC, 33.001707 degrees). Also
      !>        determine the time windows corresponding to the local maximum
      !>        and minimum phase angles, and the absolute maximum and minimum
      !>        phase angles during the search interval. The configuration
      !>        defines the Sun as the illuminator, the Moon as the target,
      !>        and the Earth as the observer.
      !>
      !>        Use the meta-kernel shown below to load the required SPICE
      !>        kernels.
      !>
      !>           KPL/MK
      !>
      !>           File name: gfpa_ex1.tm
      !>
      !>           This meta-kernel is intended to support operation of SPICE
      !>           example programs. The kernels shown here should not be
      !>           assumed to contain adequate or correct versions of data
      !>           required by SPICE-based user applications.
      !>
      !>           In order for an application to use this meta-kernel, the
      !>           kernels referenced here must be present in the user's
      !>           current working directory.
      !>
      !>           The names and contents of the kernels referenced
      !>           by this meta-kernel are as follows:
      !>
      !>              File name                     Contents
      !>              ---------                     --------
      !>              de421.bsp                     Planetary ephemeris
      !>              pck00009.tpc                  Planet orientation and
      !>                                            radii
      !>              naif0009.tls                  Leapseconds
      !>
      !>           \begindata
      !>
      !>              KERNELS_TO_LOAD = ( 'de421.bsp',
      !>                                  'pck00009.tpc',
      !>                                  'naif0009.tls'  )
      !>
      !>           \begintext
      !>
      !>           End of meta-kernel
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM GFPA_EX1
      !>      IMPLICIT NONE
      !>
      !>C
      !>C     Include GF parameter declarations:
      !>C
      !>      INCLUDE 'gf.inc'
      !>
      !>C
      !>C     SPICELIB functions
      !>C
      !>      DOUBLE PRECISION      SPD
      !>      DOUBLE PRECISION      PHASEQ
      !>
      !>      INTEGER               WNCARD
      !>
      !>C
      !>C     Local parameters
      !>C
      !>      INTEGER               LBCELL
      !>      PARAMETER           ( LBCELL = -5 )
      !>
      !>C
      !>C     Use the parameter MAXWIN for both the result window size
      !>C     and the workspace size.
      !>C
      !>      INTEGER               MAXWIN
      !>      PARAMETER           ( MAXWIN = 1000 )
      !>
      !>C
      !>C     Length of strings:
      !>C
      !>      INTEGER               TIMLEN
      !>      PARAMETER           ( TIMLEN = 26 )
      !>
      !>      INTEGER               NLOOPS
      !>      PARAMETER           ( NLOOPS = 7 )
      !>
      !>C
      !>C     Local variables
      !>C
      !>      CHARACTER*(TIMLEN)    RELATE (NLOOPS)
      !>      CHARACTER*(6)         ABCORR
      !>      CHARACTER*(6)         ILLMN
      !>      CHARACTER*(6)         OBSRVR
      !>      CHARACTER*(6)         TARGET
      !>      CHARACTER*(TIMLEN)    TIMSTR
      !>
      !>      DOUBLE PRECISION      CNFINE ( LBCELL : 2 )
      !>      DOUBLE PRECISION      RESULT ( LBCELL : MAXWIN )
      !>      DOUBLE PRECISION      WORK   ( LBCELL : MAXWIN, NWPA )
      !>      DOUBLE PRECISION      ADJUST
      !>      DOUBLE PRECISION      ET0
      !>      DOUBLE PRECISION      ET1
      !>      DOUBLE PRECISION      FINISH
      !>      DOUBLE PRECISION      PHASE
      !>      DOUBLE PRECISION      REFVAL
      !>      DOUBLE PRECISION      START
      !>      DOUBLE PRECISION      STEP
      !>
      !>      INTEGER               I
      !>      INTEGER               J
      !>
      !>C
      !>C     Saved variables
      !>C
      !>C     The confinement, workspace and result windows CNFINE,
      !>C     WORK and RESULT are saved because this practice helps to
      !>C     prevent stack overflow.
      !>C
      !>      SAVE                  CNFINE
      !>      SAVE                  RESULT
      !>      SAVE                  WORK
      !>
      !>C
      !>C     The relation values for the search.
      !>C
      !>      DATA                  RELATE / '=',
      !>     .                               '<',
      !>     .                               '>',
      !>     .                               'LOCMIN',
      !>     .                               'ABSMIN',
      !>     .                               'LOCMAX',
      !>     .                               'ABSMAX'  /
      !>
      !>C
      !>C     Load kernels.
      !>C
      !>      CALL FURNSH ( 'gfpa_ex1.tm' )
      !>
      !>C
      !>C     Initialize windows.
      !>C
      !>      CALL SSIZED ( MAXWIN, RESULT )
      !>      CALL SSIZED ( 2,      CNFINE )
      !>
      !>C
      !>C     Store the time bounds of our search interval in
      !>C     the confinement window.
      !>C
      !>      CALL STR2ET ( '2006 DEC 01', ET0 )
      !>      CALL STR2ET ( '2007 JAN 31', ET1 )
      !>
      !>      CALL WNINSD ( ET0, ET1, CNFINE )
      !>
      !>C
      !>C     Search using a step size of 1 day (in units of seconds).
      !>C     The reference value is 0.57598845 radians. We're not
      !>C     using the adjustment feature, so we set ADJUST to zero.
      !>C
      !>      STEP   = SPD()
      !>      REFVAL = 0.57598845D0
      !>      ADJUST = 0.D0
      !>
      !>C
      !>C     Define the values for target, observer, illuminator, and
      !>C     aberration correction.
      !>C
      !>      TARGET = 'MOON'
      !>      ILLMN  = 'SUN'
      !>      ABCORR = 'LT+S'
      !>      OBSRVR = 'EARTH'
      !>
      !>      DO J=1, NLOOPS
      !>
      !>         WRITE(*,*) 'Relation condition: ', RELATE(J)
      !>
      !>C
      !>C        Perform the search. The SPICE window RESULT contains
      !>C        the set of times when the condition is met.
      !>C
      !>         CALL GFPA (  TARGET,    ILLMN,  ABCORR, OBSRVR,
      !>     .                RELATE(J), REFVAL, ADJUST, STEP,
      !>     .                CNFINE,    MAXWIN, NWPA,   WORK,
      !>     .                RESULT )
      !>
      !>C
      !>C        Display the results.
      !>C
      !>         IF ( WNCARD(RESULT) .EQ. 0 ) THEN
      !>
      !>            WRITE (*, '(A)') 'Result window is empty.'
      !>
      !>         ELSE
      !>
      !>            DO I = 1, WNCARD(RESULT)
      !>C
      !>C              Fetch the endpoints of the Ith interval
      !>C              of the result window.
      !>C
      !>               CALL WNFETD ( RESULT, I, START, FINISH )
      !>
      !>               PHASE = PHASEQ( START, TARGET, ILLMN, OBSRVR,
      !>     .                         ABCORR )
      !>               CALL TIMOUT ( START,
      !>     .                       'YYYY-MON-DD HR:MN:SC.###',
      !>     .                       TIMSTR                          )
      !>
      !>               WRITE (*, '(A,F16.9)') 'Start time = '//TIMSTR,
      !>     .                                                  PHASE
      !>
      !>               PHASE = PHASEQ( FINISH, TARGET, ILLMN, OBSRVR,
      !>     .                         ABCORR )
      !>               CALL TIMOUT ( FINISH,
      !>     .                       'YYYY-MON-DD HR:MN:SC.###',
      !>     .                       TIMSTR                          )
      !>
      !>               WRITE (*, '(A,F16.9)') 'Stop time  = '//TIMSTR,
      !>     .                                                  PHASE
      !>
      !>            END DO
      !>
      !>         END IF
      !>
      !>         WRITE(*,*) ' '
      !>
      !>      END DO
      !>
      !>      END
      !>```
      !>
      !>        When this program was executed on a Mac/Intel/gfortran/64-bit
      !>        platform, the output was:
      !>
      !>         Relation condition: =
      !>        Start time = 2006-DEC-02 13:31:34.414       0.575988450
      !>        Stop time  = 2006-DEC-02 13:31:34.414       0.575988450
      !>        Start time = 2006-DEC-07 14:07:55.470       0.575988450
      !>        Stop time  = 2006-DEC-07 14:07:55.470       0.575988450
      !>        Start time = 2006-DEC-31 23:59:59.997       0.575988450
      !>        Stop time  = 2006-DEC-31 23:59:59.997       0.575988450
      !>        Start time = 2007-JAN-06 08:16:25.512       0.575988450
      !>        Stop time  = 2007-JAN-06 08:16:25.512       0.575988450
      !>        Start time = 2007-JAN-30 11:41:32.557       0.575988450
      !>        Stop time  = 2007-JAN-30 11:41:32.557       0.575988450
      !>
      !>         Relation condition: <
      !>        Start time = 2006-DEC-02 13:31:34.414       0.575988450
      !>        Stop time  = 2006-DEC-07 14:07:55.470       0.575988450
      !>        Start time = 2006-DEC-31 23:59:59.997       0.575988450
      !>        Stop time  = 2007-JAN-06 08:16:25.512       0.575988450
      !>        Start time = 2007-JAN-30 11:41:32.557       0.575988450
      !>        Stop time  = 2007-JAN-31 00:00:00.000       0.468279091
      !>
      !>         Relation condition: >
      !>        Start time = 2006-DEC-01 00:00:00.000       0.940714974
      !>        Stop time  = 2006-DEC-02 13:31:34.414       0.575988450
      !>        Start time = 2006-DEC-07 14:07:55.470       0.575988450
      !>        Stop time  = 2006-DEC-31 23:59:59.997       0.575988450
      !>        Start time = 2007-JAN-06 08:16:25.512       0.575988450
      !>        Stop time  = 2007-JAN-30 11:41:32.557       0.575988450
      !>
      !>         Relation condition: LOCMIN
      !>        Start time = 2006-DEC-05 00:16:50.317       0.086121423
      !>        Stop time  = 2006-DEC-05 00:16:50.317       0.086121423
      !>        Start time = 2007-JAN-03 14:18:31.977       0.079899769
      !>        Stop time  = 2007-JAN-03 14:18:31.977       0.079899769
      !>
      !>         Relation condition: ABSMIN
      !>        Start time = 2007-JAN-03 14:18:31.977       0.079899769
      !>        Stop time  = 2007-JAN-03 14:18:31.977       0.079899769
      !>
      !>         Relation condition: LOCMAX
      !>        Start time = 2006-DEC-20 14:09:10.392       3.055062862
      !>        Stop time  = 2006-DEC-20 14:09:10.392       3.055062862
      !>        Start time = 2007-JAN-19 04:27:54.600       3.074603891
      !>        Stop time  = 2007-JAN-19 04:27:54.600       3.074603891
      !>
      !>         Relation condition: ABSMAX
      !>        Start time = 2007-JAN-19 04:27:54.600       3.074603891
      !>        Stop time  = 2007-JAN-19 04:27:54.600       3.074603891
      !>
      !>## Restrictions
      !>
      !>     1)  The kernel files to be used by this routine must be loaded
      !>         (normally using the SPICELIB routine FURNSH) before this
      !>         routine is called.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     E.D. Wright        (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.1, 27-OCT-2021 (JDR) (NJB)
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>        Updated description of RELATE, REFVAL, WORK and RESULT
      !>        arguments in $Brief_I/O, $Detailed_Input and $Detailed_Output.
      !>
      !>        Added SAVE statements for CNFINE, WORK and RESULT variables in
      !>        code example.
      !>
      !>        Replaced entry #9 by new entries #9 and #10, and added entry
      !>        #14 in $Exceptions.
      !>
      !>        Updated header to describe use of expanded confinement window.
      !>
      !>-    SPICELIB Version 1.0.0, 15-JUL-2014 (EDW) (NJB)
      module subroutine gfpa ( ctx, target, illmn, abcorr, obsrvr, relate, refval, adjust, step, cnfine, mw, nw, work, result )
      use pepper_kinds, only: ip, wp
      use pepper_math, only: odd
      use pepper_inc_gf
      use pepper_inc_zzholdd
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), parameter :: lbcell = -5
      character(*), intent(in) :: target  !! Name of the target body.
      character(*), intent(in) :: illmn  !! Name of the illuminating body.
      character(*), intent(in) :: abcorr  !! Aberration correction flag.
      character(*), intent(in) :: obsrvr  !! Name of the observing body.
      character(*), intent(in) :: relate  !! Relational operator.
      real(wp), intent(in) :: refval  !! Reference value.
      real(wp), intent(in) :: adjust  !! Adjustment value for absolute extrema searches.
      real(wp), intent(in) :: step  !! Step size used for locating extrema and roots.
      real(wp), intent(in) :: cnfine ( lbcell : * )  !! SPICE window to which the search is confined.
      integer(ip), intent(in) :: mw  !! Workspace window size.
      integer(ip), intent(in) :: nw  !! The number of workspace windows needed for the search.
      real(wp), intent(inout) :: work   ( lbcell : mw, nw )  !! Array of workspace windows.
      real(wp), intent(inout) :: result ( lbcell : * )  !! SPICE window containing results.


      integer(ip), parameter :: qnpars = 4



      real(wp) :: tol
      logical :: ok

!
!     Quantity definition parameter arrays:
!
      character(lnsize) :: qcpars ( qnpars )
      character(lnsize) :: qpnams ( qnpars )

      real(wp) :: qdpars ( qnpars )

      integer(ip) :: qipars ( qnpars )

      logical :: qlpars ( qnpars )

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Check into the error subsystem.
!

!
!     Confirm minimum window sizes.
!
      if ( (mw < 2) .or. odd(mw) ) then

         call ctx%setmsg ( 'Workspace window size was #; size must be ' &
         //            'at least 2 and an even value.'            )
         call ctx%errint ( '#',  mw                                   )
         call ctx%sigerr ( 'SPICE(INVALIDDIMENSION)'                  )
         return

      end if

      if ( nw < nwpa ) then

         call ctx%setmsg ( 'Workspace window count was #; count must be ' &
         //            'at least #.'                                )
         call ctx%errint ( '#',  nw                                     )
         call ctx%errint ( '#',  nwpa                                   )
         call ctx%sigerr ( 'SPICE(INVALIDDIMENSION)'                    )
         return

      end if

!
!     Check the result window size.
!
      if ( (sized( ctx,result) < 2) .or. odd( sized( ctx,result) ) ) then

         call ctx%setmsg ( 'Result window size was #; size must be ' &
         //            'at least 2 and an even value.'             )
         call ctx%errint ( '#', sized( ctx,result)                          )
         call ctx%sigerr ( 'SPICE(INVALIDDIMENSION)'                   )
         return

      end if

!
!     Set up a call to GFEVNT specific to the phase angle search.
!
      qpnams(1) = 'TARGET'
      qcpars(1) =  target

      qpnams(2) = 'OBSERVER'
      qcpars(2) =  obsrvr

      qpnams(3) = 'ABCORR'
      qcpars(3) =  abcorr

      qpnams(4) = 'ILLUM'
      qcpars(4) =  illmn

!
!     Set the step size.
!
      call gfsstp ( ctx,step)

!
!     Retrieve the convergence tolerance, if set.
!
      call zzholdd ( ctx, zzget, gf_tol, ok, tol )

!
!     Use the default value CNVTOL if no stored tolerance value.
!
      if ( .not. ok ) then

         tol = cnvtol

      end if

!
!     Initialize the RESULT window to empty.
!
      call scardd ( ctx, 0, result)

!
!     Look for solutions.
!
!     Progress report and interrupt options are set to .FALSE.
!
      call gfevnt ( ctx, gfstep,   gfrefn,  'PHASE ANGLE', qnpars, &
                    qpnams,   qcpars,   qdpars,       qipars, &
                    qlpars,   relate,   refval,       tol, &
                    adjust,   cnfine,   norpt,        gfrepi, &
                    gfrepu,   gfrepf,   mw,           nwpa, &
                    work,     nobail,   gfbail,       result  )

      return

      end subroutine gfpa

      !> Determine time intervals for which a coordinate of an
      !> observer-target position vector satisfies a numerical constraint.
      !>
      !>## Detailed Input
      !>
      !>     TARGET   is the name of a target body. Optionally, you may supply
      !>              the integer ID code for the object as an integer string.
      !>              For example both 'MOON' and '301' are legitimate strings
      !>              that indicate the moon is the target body.
      !>
      !>              The target and observer define a position vector
      !>              that points from the observer to the target.
      !>
      !>     FRAME    is the name of the reference frame in which to perform
      !>              state look-ups and coordinate calculations.
      !>
      !>              The SPICE frame subsystem must recognize the FRAME
      !>              name.
      !>
      !>     ABCORR   is the description of the aberration corrections
      !>              to apply to the state evaluations to account for one-way
      !>              light time and stellar aberration.
      !>
      !>              This routine accepts the same aberration corrections as
      !>              does the SPICE routine SPKEZR. See the header of SPKEZR
      !>              for a detailed description of the aberration correction
      !>              options. For convenience, the options are listed below:
      !>
      !>                 'NONE'     Apply no correction. Returns the "true"
      !>                            geometric state.
      !>
      !>                 'LT'       "Reception" case: correct for
      !>                            one-way light time using a Newtonian
      !>                            formulation.
      !>
      !>                 'LT+S'     "Reception" case: correct for
      !>                            one-way light time and stellar
      !>                            aberration using a Newtonian
      !>                            formulation.
      !>
      !>                 'CN'       "Reception" case: converged
      !>                            Newtonian light time correction.
      !>
      !>                 'CN+S'     "Reception" case: converged
      !>                            Newtonian light time and stellar
      !>                            aberration corrections.
      !>
      !>                 'XLT'      "Transmission" case: correct for
      !>                            one-way light time using a Newtonian
      !>                            formulation.
      !>
      !>                 'XLT+S'    "Transmission" case: correct for
      !>                            one-way light time and stellar
      !>                            aberration using a Newtonian
      !>                            formulation.
      !>
      !>                 'XCN'      "Transmission" case: converged
      !>                            Newtonian light time correction.
      !>
      !>                 'XCN+S'    "Transmission" case: converged
      !>                            Newtonian light time and stellar
      !>                            aberration corrections.
      !>
      !>              The ABCORR string lacks sensitivity to case, leading
      !>              and trailing blanks.
      !>
      !>     OBSRVR   is the name of an observing body. Optionally, you may
      !>              supply the ID code of the object as an integer string.
      !>              For example, both 'EARTH' and '399' are legitimate
      !>              strings to indicate the observer is the Earth.
      !>
      !>     CRDSYS   is the name of the coordinate system for which the
      !>              coordinate of interest is a member.
      !>
      !>     COORD    is the string name of the coordinate of interest in
      !>              CRDSYS.
      !>
      !>              The supported coordinate systems and coordinate names:
      !>
      !>                 CRDSYS             COORD               Range
      !>                 ----------------   -----------------   ------------
      !>                 'RECTANGULAR'      'X'
      !>                                    'Y'
      !>                                    'Z'
      !>
      !>                 'LATITUDINAL'      'RADIUS'
      !>                                    'LONGITUDE'         (-Pi,Pi]
      !>                                    'LATITUDE'          [-Pi/2,Pi/2]
      !>
      !>                 'RA/DEC'           'RANGE'
      !>                                    'RIGHT ASCENSION'   [0,2Pi)
      !>                                    'DECLINATION'       [-Pi/2,Pi/2]
      !>
      !>                 'SPHERICAL'        'RADIUS'
      !>                                    'COLATITUDE'        [0,Pi]
      !>                                    'LONGITUDE'         (-Pi,Pi]
      !>
      !>                 'CYLINDRICAL'      'RADIUS'
      !>                                    'LONGITUDE'         [0,2Pi)
      !>                                    'Z'
      !>
      !>                 'GEODETIC'         'LONGITUDE'         (-Pi,Pi]
      !>                                    'LATITUDE'          [-Pi/2,Pi/2]
      !>                                    'ALTITUDE'
      !>
      !>                 'PLANETOGRAPHIC'   'LONGITUDE'         [0,2Pi)
      !>                                    'LATITUDE'          [-Pi/2,Pi/2]
      !>                                    'ALTITUDE'
      !>
      !>              The 'ALTITUDE' coordinates have a constant value of
      !>              zero +/- roundoff for ellipsoid targets.
      !>
      !>              Limit searches for coordinate events in the 'GEODETIC'
      !>              and 'PLANETOGRAPHIC' coordinate systems to TARGET bodies
      !>              with axial symmetry in the equatorial plane, i.e.
      !>              equality of the body X and Y radii (oblate or prolate
      !>              spheroids).
      !>
      !>              Searches on 'GEODETIC' or 'PLANETOGRAPHIC' coordinates
      !>              requires body shape data, and in the case of
      !>              'PLANETOGRAPHIC' coordinates, body rotation data.
      !>
      !>              The body associated with 'GEODETIC' or 'PLANETOGRAPHIC'
      !>              coordinates is the center of the frame FRAME.
      !>
      !>     RELATE   is the relational operator used to define a constraint on
      !>              the selected coordinate of the observer-target vector.
      !>              The result window found by this routine indicates the
      !>              time intervals where the constraint is satisfied.
      !>              Supported values of RELATE and corresponding meanings are
      !>              shown below:
      !>
      !>                 '>'        The coordinate value is greater than the
      !>                            reference value REFVAL.
      !>
      !>                 '='        The coordinate value is equal to the
      !>                            reference value REFVAL.
      !>
      !>                 '<'        The coordinate value is less than the
      !>                            reference value REFVAL.
      !>
      !>                 'ABSMAX'   The coordinate value is at an absolute
      !>                            maximum.
      !>
      !>                 'ABSMIN'   The coordinate value is at an absolute
      !>                            minimum.
      !>
      !>                 'LOCMAX'   The coordinate value is at a local
      !>                            maximum.
      !>
      !>                 'LOCMIN'   The coordinate value is at a local
      !>                            minimum.
      !>
      !>              RELATE may be used to specify an "adjusted" absolute
      !>              extremum constraint: this requires the quantity to be
      !>              within a specified offset relative to an absolute
      !>              extremum. The argument ADJUST (described below) is used
      !>              to specify this offset.
      !>
      !>              Local extrema are considered to exist only in the
      !>              interiors of the intervals comprising the confinement
      !>              window:  a local extremum cannot exist at a boundary
      !>              point of the confinement window.
      !>
      !>              The RELATE string lacks sensitivity to case, leading
      !>              and trailing blanks.
      !>
      !>     REFVAL   is the double precision reference value used together
      !>              with the argument RELATE to define an equality or
      !>              inequality to satisfy by the selected coordinate of the
      !>              observer- target vector. See the discussion of RELATE
      !>              above for further information.
      !>
      !>              The units of REFVAL correspond to the type as defined
      !>              by COORD, radians for angular measures, kilometers for
      !>              distance measures.
      !>
      !>     ADJUST   is a double precision value used to modify searches for
      !>              absolute extrema: when RELATE is set to 'ABSMAX' or
      !>              'ABSMIN' and ADJUST is set to a positive value, GFPOSC
      !>              finds times when the position vector coordinate is within
      !>              ADJUST radians/kilometers of the specified extreme value.
      !>
      !>              For RELATE set to 'ABSMAX', the RESULT window contains
      !>              time intervals when the position vector coordinate has
      !>              values between ABSMAX - ADJUST and ABSMAX.
      !>
      !>              For RELATE set to 'ABSMIN', the RESULT window contains
      !>              time intervals when the position vector coordinate has
      !>              values between ABSMIN and ABSMIN + ADJUST.
      !>
      !>              ADJUST is not used for searches for local extrema,
      !>              equality or inequality conditions.
      !>
      !>     STEP     is the double precision time step size to use in the
      !>              search.
      !>
      !>              STEP must be short enough to for a search using this step
      !>              size to locate the time intervals where coordinate
      !>              function of the position vector is monotone increasing or
      !>              decreasing. However, STEP must not be *too* short, or the
      !>              search will take an unreasonable amount of time.
      !>
      !>              For coordinates other than 'LONGITUDE' and 'RIGHT
      !>              ASCENSION', the step size must be shorter than the
      !>              shortest interval, within the confinement window, over
      !>              which the coordinate is monotone increasing or
      !>              decreasing.
      !>
      !>              For 'LONGITUDE' and 'RIGHT ASCENSION', the step size must
      !>              be shorter than the shortest interval, within the
      !>              confinement window, over which either the sine or cosine
      !>              of the coordinate is monotone increasing or decreasing.
      !>
      !>              The choice of STEP affects the completeness but not the
      !>              precision of solutions found by this routine; the
      !>              precision is controlled by the convergence tolerance. See
      !>              the discussion of the parameter CNVTOL for details.
      !>
      !>              STEP has units of seconds.
      !>
      !>     CNFINE   is a double precision SPICE window that confines the time
      !>              period over which the specified search is conducted.
      !>              CNFINE may consist of a single interval or a collection
      !>              of intervals.
      !>
      !>              In some cases the confinement window can be used to
      !>              greatly reduce the time period that must be searched
      !>              for the desired solution. See the $Particulars section
      !>              below for further discussion.
      !>
      !>              See the $Examples section below for a code example
      !>              that shows how to create a confinement window.
      !>
      !>              CNFINE must be initialized by the caller using the
      !>              SPICELIB routine SSIZED.
      !>
      !>              In some cases the observer's state may be computed at
      !>              times outside of CNFINE by as much as 2 seconds. See
      !>              $Particulars for details.
      !>
      !>     MW       is a parameter specifying the length of the SPICE
      !>              windows in the workspace array WORK (see description
      !>              below) used by this routine.
      !>
      !>              MW should be set to a number at least twice as large
      !>              as the maximum number of intervals required by any
      !>              workspace window. In many cases, it's not necessary to
      !>              compute an accurate estimate of how many intervals are
      !>              needed; rather, the user can pick a size considerably
      !>              larger than what's really required.
      !>
      !>              However, since excessively large arrays can prevent
      !>              applications from compiling, linking, or running
      !>              properly, sometimes MW must be set according to
      !>              the actual workspace requirement. A rule of thumb
      !>              for the number of intervals NINTVLS needed is
      !>
      !>                  NINTVLS  =  2*N  +  ( M / STEP )
      !>
      !>              where
      !>
      !>                  N     is the number of intervals in the confinement
      !>                        window
      !>
      !>                  M     is the measure of the confinement window, in
      !>                        units of seconds
      !>
      !>                  STEP  is the search step size in seconds
      !>
      !>              MW should then be set to
      !>
      !>                  2 * NINTVLS
      !>
      !>     NW       is a parameter specifying the number of SPICE windows
      !>              in the workspace array WORK (see description below)
      !>              used by this routine. NW should be set to the
      !>              parameter NWMAX; this parameter is declared in the
      !>              include file gf.inc. (The reason this dimension is
      !>              an input argument is that this allows run-time
      !>              error checking to be performed.)
      !>
      !>     RESULT   is a double precision SPICE window which will contain
      !>              the search results. RESULT must be declared and
      !>              initialized with sufficient size to capture the full
      !>              set of time intervals within the search region on which
      !>              the specified condition is satisfied.
      !>
      !>              RESULT must be initialized by the caller via the
      !>              SPICELIB routine SSIZED.
      !>
      !>              If RESULT is non-empty on input, its contents will be
      !>              discarded before GFPOSC conducts its search.
      !>
      !>## Detailed Output
      !>
      !>     WORK     is an array used to store workspace windows.
      !>
      !>              This array should be declared by the caller as shown:
      !>
      !>                 INCLUDE 'gf.inc'
      !>                    ...
      !>
      !>                 DOUBLE PRECISION    WORK ( LBCELL : MW, NWMAX )
      !>
      !>              where MW is a constant declared by the caller and
      !>              NWMAX is a constant defined in the SPICELIB INCLUDE
      !>              file gf.inc. See the discussion of MW above.
      !>
      !>              WORK need not be initialized by the caller.
      !>
      !>              WORK is modified by this routine. The caller should
      !>              re-initialize this array before attempting to use it for
      !>              any other purpose.
      !>
      !>     RESULT   is the SPICE window of intervals, contained within the
      !>              confinement window CNFINE, on which the specified
      !>              constraint is satisfied.
      !>
      !>              The endpoints of the time intervals comprising RESULT are
      !>              interpreted as seconds past J2000 TDB.
      !>
      !>              If the search is for local extrema, or for absolute
      !>              extrema with ADJUST set to zero, then normally each
      !>              interval of RESULT will be a singleton: the left and
      !>              right endpoints of each interval will be identical.
      !>
      !>              If no times within the confinement window satisfy the
      !>              search criteria, RESULT will be returned with a
      !>              cardinality of zero.
      !>
      !>## Parameters
      !>
      !>     LBCELL   is the integer value defining the lower bound for
      !>              SPICE Cell arrays (a SPICE window is a kind of cell).
      !>
      !>     CNVTOL   is the convergence tolerance used for finding
      !>              endpoints of the intervals comprising the result
      !>              window. CNVTOL is also used for finding intermediate
      !>              results; in particular, CNVTOL is used for finding the
      !>              windows on which the specified coordinate is increasing
      !>              or decreasing. CNVTOL is used to determine when binary
      !>              searches for roots should terminate: when a root is
      !>              bracketed within an interval of length CNVTOL; the
      !>              root is considered to have been found.
      !>
      !>              The accuracy, as opposed to precision, of roots found
      !>              by this routine depends on the accuracy of the input
      !>              data. In most cases, the accuracy of solutions will be
      !>              inferior to their precision.
      !>
      !>     See INCLUDE file gf.inc for declarations and descriptions of
      !>     parameters used throughout the GF system.
      !>
      !>## Exceptions
      !>
      !>     1)  In order for this routine to produce correct results,
      !>         the step size must be appropriate for the problem at hand.
      !>         Step sizes that are too large may cause this routine to miss
      !>         roots; step sizes that are too small may cause this routine
      !>         to run unacceptably slowly and in some cases, find spurious
      !>         roots.
      !>
      !>         This routine does not diagnose invalid step sizes, except
      !>         that if the step size is non-positive, an error is signaled
      !>         by a routine in the call tree of this routine.
      !>
      !>     2)  Due to numerical errors, in particular,
      !>
      !>            - truncation error in time values
      !>            - finite tolerance value
      !>            - errors in computed geometric quantities
      !>
      !>         it is *normal* for the condition of interest to not always be
      !>         satisfied near the endpoints of the intervals comprising the
      !>         RESULT window. One technique to handle such a situation,
      !>         slightly contract RESULT using the window routine WNCOND.
      !>
      !>     3)  If the window size MW is less than 2 or not an even value,
      !>         the error SPICE(INVALIDDIMENSION) is signaled.
      !>
      !>     4)  If the window size of RESULT is less than 2, the error
      !>         SPICE(INVALIDDIMENSION) is signaled.
      !>
      !>     5)  If the output SPICE window RESULT has insufficient capacity
      !>         to contain the number of intervals on which the specified
      !>         distance condition is met, an error is signaled
      !>         by a routine in the call tree of this routine.
      !>
      !>     6)  If an error (typically cell overflow) occurs during
      !>         window arithmetic, the error is signaled by a routine
      !>         in the call tree of this routine.
      !>
      !>     7)  If the relational operator RELATE is not recognized, an
      !>         error is signaled by a routine in the call tree of this
      !>         routine.
      !>
      !>     8)  If the size of the workspace WORK is too small, an error is
      !>         signaled by a routine in the call tree of this routine.
      !>
      !>     9)  If the aberration correction specifier contains an
      !>         unrecognized value, an error is signaled by a routine in the
      !>         call tree of this routine.
      !>
      !>     10) If ADJUST is negative, an error is signaled by a routine in
      !>         the call tree of this routine.
      !>
      !>     11) If either of the input body names do not map to NAIF ID
      !>         codes, an error is signaled by a routine in the call tree of
      !>         this routine.
      !>
      !>     12) If required ephemerides or other kernel data are not
      !>         available, an error is signaled by a routine in the call tree
      !>         of this routine.
      !>
      !>     13) If the search uses GEODETIC or PLANETOGRAPHIC coordinates, and
      !>         the center body of the reference frame has unequal equatorial
      !>         radii, an error is signaled by a routine in the call tree of
      !>         this routine.
      !>
      !>## Files
      !>
      !>     Appropriate SPK and PCK kernels must be loaded by the calling
      !>     program before this routine is called.
      !>
      !>     The following data are required:
      !>
      !>     -  SPK data: the calling application must load ephemeris data
      !>        for the targets, observer, and any intermediate objects in
      !>        a chain connecting the targets and observer that cover the
      !>        time period specified by the window CNFINE. If aberration
      !>        corrections are used, the states of target and observer
      !>        relative to the solar system barycenter must be calculable
      !>        from the available ephemeris data. Typically ephemeris data
      !>        are made available by loading one or more SPK files using
      !>        FURNSH.
      !>
      !>     -  If non-inertial reference frames are used, then PCK
      !>        files, frame kernels, C-kernels, and SCLK kernels may be
      !>        needed.
      !>
      !>     -  In some cases the observer's state may be computed at times
      !>        outside of CNFINE by as much as 2 seconds; data required to
      !>        compute this state must be provided by loaded kernels. See
      !>        $Particulars for details.
      !>
      !>     Such kernel data are normally loaded once per program
      !>     run, NOT every time this routine is called.
      !>
      !>## Particulars
      !>
      !>     This routine provides a simpler, but less flexible interface
      !>     than does the routine GFEVNT for conducting searches for
      !>     observer-target position vector coordinate value events.
      !>     Applications that require support for progress reporting,
      !>     interrupt handling, non-default step or refinement functions,
      !>     or non-default convergence tolerance should call GFEVNT rather
      !>     than this routine.
      !>
      !>     This routine determines a set of one or more time intervals
      !>     within the confinement window when the selected coordinate of
      !>     the observer-target position vector satisfies a caller-specified
      !>     constraint. The resulting set of intervals is returned as a SPICE
      !>     window.
      !>
      !>     Below we discuss in greater detail aspects of this routine's
      !>     solution process that are relevant to correct and efficient
      !>     use of this routine in user applications.
      !>
      !>     The Search Process
      !>     ==================
      !>
      !>     Regardless of the type of constraint selected by the caller, this
      !>     routine starts the search for solutions by determining the time
      !>     periods, within the confinement window, over which the specified
      !>     coordinate function is monotone increasing and monotone
      !>     decreasing. Each of these time periods is represented by a SPICE
      !>     window. Having found these windows, all of the coordinate
      !>     function's local extrema within the confinement window are known.
      !>     Absolute extrema then can be found very easily.
      !>
      !>     Within any interval of these "monotone" windows, there will be at
      !>     most one solution of any equality constraint. Since the boundary
      !>     of the solution set for any inequality constraint is contained in
      !>     the union of
      !>
      !>     -  the set of points where an equality constraint is met
      !>
      !>     -  the boundary points of the confinement window
      !>
      !>     the solutions of both equality and inequality constraints can be
      !>     found easily once the monotone windows have been found.
      !>
      !>     Step Size
      !>     =========
      !>
      !>     The monotone windows (described above) are found using a two-step
      !>     search process. Each interval of the confinement window is
      !>     searched as follows: first, the input step size is used to
      !>     determine the time separation at which the sign of the rate of
      !>     change of coordinate will be sampled. Starting at
      !>     the left endpoint of an interval, samples will be taken at each
      !>     step. If a change of sign is found, a root has been bracketed; at
      !>     that point, the time at which the time derivative of the
      !>     coordinate is zero can be found by a refinement process, for
      !>     example, using a binary search.
      !>
      !>     Note that the optimal choice of step size depends on the lengths
      !>     of the intervals over which the coordinate function is monotone:
      !>     the step size should be shorter than the shortest of these
      !>     intervals (within the confinement window).
      !>
      !>     The optimal step size is *not* necessarily related to the lengths
      !>     of the intervals comprising the result window. For example, if
      !>     the shortest monotone interval has length 10 days, and if the
      !>     shortest result window interval has length 5 minutes, a step size
      !>     of 9.9 days is still adequate to find all of the intervals in the
      !>     result window. In situations like this, the technique of using
      !>     monotone windows yields a dramatic efficiency improvement over a
      !>     state-based search that simply tests at each step whether the
      !>     specified constraint is satisfied. The latter type of search can
      !>     miss solution intervals if the step size is longer than the
      !>     shortest solution interval.
      !>
      !>     Having some knowledge of the relative geometry of the target and
      !>     observer can be a valuable aid in picking a reasonable step size.
      !>     In general, the user can compensate for lack of such knowledge by
      !>     picking a very short step size; the cost is increased computation
      !>     time.
      !>
      !>     Note that the step size is not related to the precision with which
      !>     the endpoints of the intervals of the result window are computed.
      !>     That precision level is controlled by the convergence tolerance.
      !>
      !>     Convergence Tolerance
      !>     =====================
      !>
      !>     As described above, the root-finding process used by this routine
      !>     involves first bracketing roots and then using a search process
      !>     to locate them. "Roots" are both times when local extrema are
      !>     attained and times when the coordinate function is equal to a
      !>     reference value. All endpoints of the intervals comprising the
      !>     result window are either endpoints of intervals of the
      !>     confinement window or roots.
      !>
      !>     Once a root has been bracketed, a refinement process is used to
      !>     narrow down the time interval within which the root must lie.
      !>     This refinement process terminates when the location of the root
      !>     has been determined to within an error margin called the
      !>     "convergence tolerance." The default convergence tolerance
      !>     used by this routine is set by the parameter CNVTOL (defined
      !>     in gf.inc).
      !>
      !>     The value of CNVTOL is set to a "tight" value so that the
      !>     tolerance doesn't become the limiting factor in the accuracy of
      !>     solutions found by this routine. In general the accuracy of input
      !>     data will be the limiting factor.
      !>
      !>     The user may change the convergence tolerance from the default
      !>     CNVTOL value by calling the routine GFSTOL, e.g.
      !>
      !>        CALL GFSTOL( tolerance value )
      !>
      !>     Call GFSTOL prior to calling this routine. All subsequent
      !>     searches will use the updated tolerance value.
      !>
      !>     Setting the tolerance tighter than CNVTOL is unlikely to be
      !>     useful, since the results are unlikely to be more accurate.
      !>     Making the tolerance looser will speed up searches somewhat,
      !>     since a few convergence steps will be omitted. However, in most
      !>     cases, the step size is likely to have a much greater effect
      !>     on processing time than would the convergence tolerance.
      !>
      !>     The Confinement Window
      !>     ======================
      !>
      !>     The simplest use of the confinement window is to specify a time
      !>     interval within which a solution is sought. However, the
      !>     confinement window can, in some cases, be used to make searches
      !>     more efficient. Sometimes it's possible to do an efficient search
      !>     to reduce the size of the time period over which a relatively
      !>     slow search of interest must be performed.
      !>
      !>     Practical use of the coordinate search capability would likely
      !>     consist of searches over multiple coordinate constraints to find
      !>     time intervals that satisfies the constraints. An
      !>     effective technique to accomplish such a search is
      !>     to use the result window from one search as the confinement window
      !>     of the next.
      !>
      !>     Certain types of searches require the state of the observer,
      !>     relative to the solar system barycenter, to be computed at times
      !>     slightly outside the confinement window CNFINE. The time window
      !>     that is actually used is the result of "expanding" CNFINE by a
      !>     specified amount "T": each time interval of CNFINE is expanded by
      !>     shifting the interval's left endpoint to the left and the right
      !>     endpoint to the right by T seconds. Any overlapping intervals are
      !>     merged. (The input argument CNFINE is not modified.)
      !>
      !>     The window expansions listed below are additive: if both
      !>     conditions apply, the window expansion amount is the sum of the
      !>     individual amounts.
      !>
      !>     -  If a search uses an equality constraint, the time window
      !>        over which the state of the observer is computed is expanded
      !>        by 1 second at both ends of all of the time intervals
      !>        comprising the window over which the search is conducted.
      !>
      !>     -  If a search uses stellar aberration corrections, the time
      !>        window over which the state of the observer is computed is
      !>        expanded as described above.
      !>
      !>     When light time corrections are used, expansion of the search
      !>     window also affects the set of times at which the light time-
      !>     corrected state of the target is computed.
      !>
      !>     In addition to the possible 2 second expansion of the search
      !>     window that occurs when both an equality constraint and stellar
      !>     aberration corrections are used, round-off error should be taken
      !>     into account when the need for data availability is analyzed.
      !>
      !>     Longitude and Right Ascension
      !>     =============================
      !>
      !>     The cyclic nature of the longitude and right ascension coordinates
      !>     produces branch cuts at +/- 180 degrees longitude and 0-360
      !>     right ascension. Round-off error may cause solutions near these
      !>     branches to cross the branch. Use of the SPICE routine WNCOND
      !>     will contract solution windows by some epsilon, reducing the
      !>     measure of the windows and eliminating the branch crossing. A
      !>     one millisecond contraction will in most cases eliminate
      !>     numerical round-off caused branch crossings.
      !>
      !>## Examples
      !>
      !>     The numerical results shown for these examples may differ across
      !>     platforms. The results depend on the SPICE kernels used as
      !>     input, the compiler and supporting libraries, and the machine
      !>     specific arithmetic implementation.
      !>
      !>     1) Find the time during 2007 for which the latitude of the
      !>        Earth-Sun vector in IAU_EARTH frame has the maximum value,
      !>        i.e. the latitude of the Tropic of Cancer.
      !>
      !>        Use the meta-kernel shown below to load the required SPICE
      !>        kernels.
      !>
      !>           KPL/MK
      !>
      !>           File name: gfposc_ex1.tm
      !>
      !>           This meta-kernel is intended to support operation of SPICE
      !>           example programs. The kernels shown here should not be
      !>           assumed to contain adequate or correct versions of data
      !>           required by SPICE-based user applications.
      !>
      !>           In order for an application to use this meta-kernel, the
      !>           kernels referenced here must be present in the user's
      !>           current working directory.
      !>
      !>           The names and contents of the kernels referenced
      !>           by this meta-kernel are as follows:
      !>
      !>              File name                     Contents
      !>              ---------                     --------
      !>              de421.bsp                     Planetary ephemeris
      !>              pck00009.tpc                  Planet orientation and
      !>                                            radii
      !>              naif0009.tls                  Leapseconds
      !>
      !>           \begindata
      !>
      !>              KERNELS_TO_LOAD = ( 'de421.bsp',
      !>                                  'pck00009.tpc',
      !>                                  'naif0009.tls'  )
      !>
      !>           \begintext
      !>
      !>           End of meta-kernel
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM GFPOSC_EX1
      !>      IMPLICIT NONE
      !>
      !>C
      !>C     Include GF parameter declarations:
      !>C
      !>      INCLUDE 'gf.inc'
      !>
      !>C
      !>C     SPICELIB functions
      !>C
      !>      DOUBLE PRECISION      SPD
      !>      DOUBLE PRECISION      RPD
      !>      INTEGER               WNCARD
      !>
      !>C
      !>C     Local parameters
      !>C
      !>      INTEGER               LBCELL
      !>      PARAMETER           ( LBCELL = -5 )
      !>
      !>C
      !>C     Use the parameter MAXWIN for both
      !>C     the result window size and the workspace
      !>C     size.
      !>C
      !>      INTEGER               MAXWIN
      !>      PARAMETER           ( MAXWIN = 750 )
      !>
      !>C
      !>C     String length.
      !>C
      !>      INTEGER               STRLEN
      !>      PARAMETER           ( STRLEN = 64 )
      !>
      !>C
      !>C     Local variables
      !>C
      !>      CHARACTER*(STRLEN)    TIMSTR
      !>      CHARACTER*(STRLEN)    TIMFIN
      !>      CHARACTER*(STRLEN)    RELATE
      !>      CHARACTER*(STRLEN)    CRDSYS
      !>      CHARACTER*(STRLEN)    COORD
      !>      CHARACTER*(STRLEN)    ABCORR
      !>      CHARACTER*(STRLEN)    TARG
      !>      CHARACTER*(STRLEN)    OBSRVR
      !>      CHARACTER*(STRLEN)    FRAME
      !>      CHARACTER*(STRLEN)   TIMFMT
      !>
      !>      DOUBLE PRECISION      ADJUST
      !>      DOUBLE PRECISION      CNFINE ( LBCELL : 2 )
      !>      DOUBLE PRECISION      ET0
      !>      DOUBLE PRECISION      ET1
      !>      DOUBLE PRECISION      FINISH
      !>      DOUBLE PRECISION      REFVAL
      !>      DOUBLE PRECISION      RESULT ( LBCELL : MAXWIN )
      !>      DOUBLE PRECISION      START
      !>      DOUBLE PRECISION      STEP
      !>      DOUBLE PRECISION      WORK   ( LBCELL : MAXWIN, NWMAX )
      !>
      !>      INTEGER               I
      !>
      !>C
      !>C     Saved variables
      !>C
      !>C     The confinement, workspace and result windows CNFINE,
      !>C     WORK and RESULT are saved because this practice helps to
      !>C     prevent stack overflow.
      !>C
      !>      SAVE                  CNFINE
      !>      SAVE                  RESULT
      !>      SAVE                  WORK
      !>
      !>C
      !>C     Load kernels.
      !>C
      !>      CALL FURNSH ( 'gfposc_ex1.tm' )
      !>
      !>C
      !>C     Initialize windows.
      !>C
      !>      CALL SSIZED ( MAXWIN, RESULT )
      !>      CALL SSIZED ( 2,      CNFINE )
      !>
      !>      TIMFMT = 'YYYY-MON-DD HR:MN:SC.###### (TDB) ::TDB ::RND'
      !>
      !>C
      !>C     Store the time bounds of our search interval in
      !>C     the confinement window.
      !>C
      !>
      !>      CALL STR2ET ( '2007 JAN 1', ET0 )
      !>      CALL STR2ET ( '2008 JAN 1', ET1 )
      !>
      !>      CALL WNINSD ( ET0, ET1, CNFINE )
      !>
      !>C
      !>C     The latitude varies relatively slowly, ~46 degrees
      !>C     during the year. The extrema occur approximately every
      !>C     six months. Search using a step size less than half
      !>C     that value (180 days). For this example use ninety days
      !>C     (in units of seconds).
      !>C
      !>      STEP   = SPD() * 90.D0
      !>      ADJUST = 0.D0
      !>      REFVAL = 0.D0
      !>
      !>C
      !>C     Search for the date on which the CRDSYS system
      !>C     coordinate COORD satisfies the RELATE constraint.
      !>C
      !>      RELATE = 'ABSMAX'
      !>      CRDSYS = 'LATITUDINAL'
      !>      COORD  = 'LATITUDE'
      !>      TARG   = 'SUN'
      !>      OBSRVR = 'EARTH'
      !>      FRAME  = 'IAU_EARTH'
      !>      ABCORR = 'NONE'
      !>
      !>C
      !>C     Perform this search using the geometric position
      !>C     of the bodies; set the aberration correction to 'NONE'.
      !>C
      !>      CALL GFPOSC ( TARG,   FRAME, ABCORR,
      !>     .              OBSRVR, CRDSYS, COORD,
      !>     .              RELATE, REFVAL, ADJUST,
      !>     .              STEP,   CNFINE,  MAXWIN,
      !>     .              NWMAX,  WORK,   RESULT )
      !>
      !>C
      !>C     Display the results.
      !>C
      !>      IF ( WNCARD(RESULT) .EQ. 0 ) THEN
      !>
      !>         WRITE (*,*) 'Result window is empty.'
      !>
      !>      ELSE
      !>
      !>         DO I = 1, WNCARD(RESULT)
      !>
      !>C
      !>C           Fetch the endpoints of the Ith interval
      !>C           of the result window.
      !>C
      !>            CALL WNFETD ( RESULT, I, START, FINISH )
      !>
      !>            IF( START .EQ. FINISH ) THEN
      !>
      !>C
      !>C              The result window contains singleton
      !>C              intervals, so we need display only the
      !>C              start times.
      !>C
      !>               CALL TIMOUT ( START, TIMFMT, TIMSTR )
      !>               WRITE (*, *) 'Event time: ', TIMSTR
      !>
      !>            ELSE
      !>
      !>               CALL TIMOUT ( START,  TIMFMT, TIMSTR )
      !>               CALL TIMOUT ( FINISH, TIMFMT, TIMFIN )
      !>
      !>               WRITE(*, *) 'From : ', TIMSTR
      !>               WRITE(*, *) 'To   : ', TIMFIN
      !>               WRITE(*, *) ' '
      !>
      !>            END IF
      !>
      !>         END DO
      !>
      !>      END IF
      !>
      !>      END
      !>```
      !>
      !>        When this program was executed on a Mac/Intel/gfortran/64-bit
      !>        platform, the output was:
      !>
      !>         Event time: 2007-JUN-21 17:54:13.172475 (TDB)
      !>
      !>     2) A minor modification of the program listed in Example 1; find
      !>        the time during 2007 for which the latitude of the Earth-Sun
      !>        vector in IAU_EARTH frame has the minimum value, i.e. the
      !>        latitude of the Tropic of Capricorn.
      !>
      !>        Use the meta-kernel from the first example.
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM GFPOSC_EX2
      !>      IMPLICIT NONE
      !>
      !>C
      !>C     Include GF parameter declarations:
      !>C
      !>      INCLUDE 'gf.inc'
      !>
      !>C
      !>C     SPICELIB functions
      !>C
      !>      DOUBLE PRECISION      SPD
      !>      DOUBLE PRECISION      RPD
      !>      INTEGER               WNCARD
      !>
      !>C
      !>C     Local parameters
      !>C
      !>      INTEGER               LBCELL
      !>      PARAMETER           ( LBCELL = -5 )
      !>
      !>C
      !>C     Use the parameter MAXWIN for both
      !>C     the result window size and the workspace
      !>C     size.
      !>C
      !>      INTEGER               MAXWIN
      !>      PARAMETER           ( MAXWIN = 750 )
      !>
      !>C
      !>C     String length.
      !>C
      !>      INTEGER               STRLEN
      !>      PARAMETER           ( STRLEN = 64 )
      !>
      !>C
      !>C     Local variables
      !>C
      !>      CHARACTER*(STRLEN)    TIMSTR
      !>      CHARACTER*(STRLEN)    TIMFIN
      !>      CHARACTER*(STRLEN)    RELATE
      !>      CHARACTER*(STRLEN)    CRDSYS
      !>      CHARACTER*(STRLEN)    COORD
      !>      CHARACTER*(STRLEN)    ABCORR
      !>      CHARACTER*(STRLEN)    TARG
      !>      CHARACTER*(STRLEN)    OBSRVR
      !>      CHARACTER*(STRLEN)    FRAME
      !>      CHARACTER*(STRLEN)   TIMFMT
      !>
      !>      DOUBLE PRECISION      ADJUST
      !>      DOUBLE PRECISION      CNFINE ( LBCELL : 2 )
      !>      DOUBLE PRECISION      ET0
      !>      DOUBLE PRECISION      ET1
      !>      DOUBLE PRECISION      FINISH
      !>      DOUBLE PRECISION      REFVAL
      !>      DOUBLE PRECISION      RESULT ( LBCELL : MAXWIN )
      !>      DOUBLE PRECISION      START
      !>      DOUBLE PRECISION      STEP
      !>      DOUBLE PRECISION      WORK   ( LBCELL : MAXWIN, NWMAX )
      !>
      !>      INTEGER               I
      !>
      !>C
      !>C     Saved variables
      !>C
      !>C     The confinement, workspace and result windows CNFINE,
      !>C     WORK and RESULT are saved because this practice helps to
      !>C     prevent stack overflow.
      !>C
      !>      SAVE                  CNFINE
      !>      SAVE                  RESULT
      !>      SAVE                  WORK
      !>
      !>C
      !>C     Load kernels.
      !>C
      !>      CALL FURNSH ( 'gfposc_ex1.tm' )
      !>
