      !>-    SPICELIB Version 1.2.0, 27-OCT-2021 (JDR) (NJB)
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>        Added initialization of QCPARS(10) to pacify Valgrind.
      !>
      !>        Modified code example's output to comply with maximum line
      !>        length of header comments. Added SAVE statements for CNFINE,
      !>        WORK, RESULT1, RESULT2, RESULT3 and RESULT4 variables in code
      !>        example.
      !>
      !>        Added entries #5 and #9 in $Exceptions section.
      !>
      !>        Updated description of WORK and RESULT arguments in $Brief_I/O,
      !>        $Detailed_Input and $Detailed_Output. Extended description of
      !>        COORD argument.
      !>
      !>        Updated header to describe use of expanded confinement window.
      !>
      !>-    SPICELIB Version 1.1.0, 05-SEP-2012 (EDW)
      !>
      !>        Edit to comments to correct search description.
      !>
      !>        Implemented use of ZZHOLDD to allow user to alter convergence
      !>        tolerance.
      !>
      !>        Removed the STEP > 0 error check. The GFSSTP call includes
      !>        the check.
      !>
      !>-    SPICELIB Version 1.0.1, 22-AUG-2009 (EDW)
      !>
      !>        Edited argument descriptions.
      !>
      !>        Edit to Example description, replaced "intercept" with
      !>        "sub-observer point."
      !>
      !>-    SPICELIB Version 1.0.0, 17-FEB-2009 (NJB) (EDW)
      module subroutine gfsubc ( ctx, target, fixref, method, abcorr, obsrvr, crdsys, coord, relate, refval, adjust, step, cnfine, mw, nw, work, result )
      use pepper_kinds, only: ip, wp
      use pepper_inc_gf
      use pepper_inc_zzgf
      use pepper_inc_zzabcorr
      use pepper_inc_zzholdd
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), parameter :: lbcell = -5
      character(*), intent(in) :: target  !! Name of the target body.
      character(*), intent(in) :: fixref  !! Body fixed frame associated with TARGET.
      character(*), intent(in) :: method  !! Name of method type for subpoint calculation.
      character(*), intent(in) :: abcorr  !! Aberration correction flag.
      character(*), intent(in) :: obsrvr  !! Name of the observing body.
      character(*), intent(in) :: crdsys  !! Name of the coordinate system containing COORD.
      character(*), intent(in) :: coord  !! Name of the coordinate of interest.
      character(*), intent(in) :: relate  !! Relational operator.
      real(wp), intent(in) :: refval  !! Reference value.
      real(wp), intent(in) :: adjust  !! Adjustment value for absolute extrema searches.
      real(wp), intent(in) :: step  !! Step size used for locating extrema and roots.
      real(wp), intent(in) :: cnfine ( lbcell : * )  !! SPICE window to which the search is confined.
      integer(ip), intent(in) :: mw  !! Workspace window size.
      integer(ip), intent(in) :: nw  !! The number of workspace windows needed for the search.
      real(wp), intent(inout) :: work   ( lbcell : mw, nw )  !! Array of workspace windows.
      real(wp), intent(inout) :: result ( lbcell : * )  !! SPICE window containing results.


      real(wp) :: tol
      logical :: ok

!
!     Quantity definition parameter arrays:
!
      character(lnsize) :: qcpars ( qnpars )
      character(lnsize) :: qpnams ( qnpars )
      character(lnsize), parameter :: dref = ' '

      real(wp) :: qdpars ( qnpars )
      real(wp), parameter :: dvec   ( 3 ) = &
         [ 0.0_wp, 0.0_wp, 0.0_wp ]

      integer(ip) :: qipars ( qnpars )

      logical :: qlpars ( qnpars )

!
!     Define no-use values for DVEC and DREF
!

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Check into the error subsystem.
!

!
!     Confirm minimum window sizes.
!
      if ( mw < 2 .or. .not. (mod(mw, 2) == 0) ) then

         call ctx%setmsg ( 'Workspace window size was #; size must be ' &
         //            'at least 2 and an even value.'            )
         call ctx%errint ( '#',  mw                                    )
         call ctx%sigerr ( 'SPICE(INVALIDDIMENSION)'                   )
         return

      end if

      if ( sized( ctx,result) < 2 ) then

         call ctx%setmsg ( 'Result window size was #; size must be ' &
         //            'at least 2.'                               )
         call ctx%errint ( '#', sized( ctx,result)                          )
         call ctx%sigerr ( 'SPICE(INVALIDDIMENSION)'                   )
         return

      end if

!
!     Set up a call to GFEVNT specific to the subpoint coordinate
!     search.
!
      qpnams(1) = 'TARGET'
      qcpars(1) =  target

      qpnams(2) = 'OBSERVER'
      qcpars(2) =  obsrvr

      qpnams(3) = 'ABCORR'
      qcpars(3) =  abcorr

      qpnams(4) = 'COORDINATE SYSTEM'
      qcpars(4) =  crdsys

      qpnams(5) = 'COORDINATE'
      qcpars(5) =  coord

      qpnams(6) = 'REFERENCE FRAME'
      qcpars(6) =  fixref

      qpnams(7) = 'VECTOR DEFINITION'
      qcpars(7) =  sobdef

      qpnams(8) = 'METHOD'
      qcpars(8) =  method

      qpnams(9) = 'DREF'
      qcpars(9) =  dref

      qpnams(10) = 'DVEC'
      qdpars(1)  = dvec(1)
      qdpars(2)  = dvec(2)
      qdpars(3)  = dvec(3)

!
!     Initialize QCPARS(10) since GFEVNT will try to
!     left-justify it and convert it to upper case.
!
      qcpars(10) = ' '

!
!     Set the step size.
!
      call gfsstp ( ctx,step)

!
!     Retrieve the convergence tolerance, if set.
!
      call zzholdd ( ctx, zzget, gf_tol, ok, tol )

!
!     Use the default value CNVTOL if no stored tolerance value.
!
      if ( .not. ok ) then

         tol = cnvtol

      end if

!
!     Initialize the RESULT window to empty.
!
      call scardd ( ctx, 0, result)

!
!     Look for solutions.
!
!     Progress report and interrupt options are set to .FALSE.
!
      call gfevnt ( ctx, gfstep,   gfrefn,  'COORDINATE', &
                    qnpars,   qpnams,   qcpars, &
                    qdpars,   qipars,   qlpars, &
                    relate,   refval,   tol, &
                    adjust,   cnfine,   norpt, &
                    gfrepi,   gfrepu,   gfrepf, &
                    mw,       nw,       work, &
                    nobail,  gfbail,    result )

      return

      end subroutine gfsubc

      !> The cells of a GF search with windows as arrays (PEPPER): the
      !> confinement window as a cell, and a result cell and work windows
      !> of a size that the search cannot exceed. The GF solver finds at
      !> most one transition per STEP in each confinement interval, so no
      !> window holds more than B = sum (ceiling(length/STEP) + 2) intervals;
      !> the cells have room for 2B. Signals SPICE(INSUFFICIENTMEMORY) if
      !> they cannot be allocated.
      module subroutine gf_cells ( ctx, cnfine, step, cnf, res, mw, work )
      use, intrinsic :: iso_fortran_env, only: int64
      use pepper_kinds, only: ip, wp
      use pepper_windows, only: window_to_cell
      use pepper_inc_gf, only: nwmax
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      real(wp), intent(in) :: cnfine(:,:)  !! the confinement window, shape (2, n)
      real(wp), intent(in) :: step  !! the search step
      real(wp), allocatable, intent(out) :: cnf(:)  !! the confinement window as a cell
      real(wp), allocatable, intent(out) :: res(:)  !! an empty result cell of size MW
      integer(ip), intent(out) :: mw  !! the size of the result cell and of the work windows
      real(wp), allocatable, intent(out), optional :: work(:,:)  !! NWMAX empty work windows of size MW
      integer(int64) :: b
      integer(int64) :: words
      integer(ip) :: i
      integer :: stat
      real(wp) :: bound
      real(wp) :: span
      mw = 0
      call window_to_cell ( cnfine, cnf )
!
!     The bound on the number of intervals in any window of the search.
!     A step that is not positive is left for the search to reject.
!
      bound = 8.0_wp
      do i = 1, size ( cnfine, 2, ip )
         bound = bound + 2.0_wp
         span  = cnfine(2,i) - cnfine(1,i)
         if ( step > 0.0_wp .and. span > 0.0_wp ) then
            bound = bound + min ( span / step, 1.0e15_wp ) + 1.0_wp
         end if
      end do
      b = int ( min ( bound, 1.0e16_wp ), int64 )
      words = 4 * b
      if ( words > int ( huge(mw), int64 ) - 8 ) then
         stat = 1
      else
         mw = int ( words, ip )
         allocate ( res(-5:mw), stat=stat )
         if ( stat == 0 .and. present ( work ) ) allocate ( work(-5:mw, nwmax), stat=stat )
      end if
      if ( stat /= 0 ) then
         call ctx%setmsg ( 'The windows of a GF search over # intervals ' // &
                           'with a step of # s would hold up to # ' // &
                           'intervals each; they could not be allocated.' )
         call ctx%errint ( '#', size ( cnfine, 2, ip ) )
         call ctx%errdp  ( '#', step )
         call ctx%errdp  ( '#', real ( 2*b, wp ) )
         call ctx%sigerr ( 'SPICE(INSUFFICIENTMEMORY)' )
         return
      end if
      call ssized ( ctx, mw, res )
      if ( present ( work ) ) then
         do i = 1, nwmax
            call ssized ( ctx, mw, work(:,i) )
         end do
      end if
      end subroutine gf_cells

      !> A GF search on the observer-target distance (PEPPER; [[gfdist]] with the confinement
      !> and result windows as arrays, and without workspace).
      !>
      !> The windows that the search needs are sized from the confinement
      !> window and the step: the solver finds at most one transition per
      !> step. The errors are those of [[gfdist]], without
      !> SPICE(WINDOWEXCESS) and the checks of MW and NW; a size too large to
      !> allocate signals SPICE(INSUFFICIENTMEMORY).
      module subroutine gf_distance ( ctx, target, abcorr, obsrvr, relate, refval, adjust, step, cnfine, result )
      use pepper_kinds, only: ip, wp
      use pepper_windows, only: cell_to_window
      use pepper_inc_gf, only: nwmax
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      character(*), intent(in) :: target  !! Name of the target body.
      character(*), intent(in) :: abcorr  !! Aberration correction flag.
      character(*), intent(in) :: obsrvr  !! Name of the observing body.
      character(*), intent(in) :: relate  !! Relational operator.
      real(wp), intent(in) :: refval  !! Reference value.
      real(wp), intent(in) :: adjust  !! Adjustment value for absolute extrema searches.
      real(wp), intent(in) :: step  !! Step size used for locating extrema and roots.
      real(wp), intent(in) :: cnfine(:,:)  !! the confinement window, shape (2, n): intervals [start, stop], sorted and disjoint
      real(wp), allocatable, intent(out) :: result(:,:)  !! the result window, shape (2, n) (n = 0 after an error)
      real(wp), allocatable :: cnf(:)
      real(wp), allocatable :: res(:)
      real(wp), allocatable :: work(:,:)
      integer(ip) :: mw
      allocate ( result(2,0) )
      if ( ctx%failed() ) return
      call gf_cells ( ctx, cnfine, step, cnf, res, mw, work )
      if ( ctx%failed() ) return
      call gfdist ( ctx, target, abcorr, obsrvr, relate, refval, adjust, step, cnf, mw, nwmax, &
                    work, res )
      if ( ctx%failed() ) return
      call cell_to_window ( res, result )
      end subroutine gf_distance

      !> A GF search on a coordinate of a position vector (PEPPER; [[gfposc]] with the confinement
      !> and result windows as arrays, and without workspace).
      !>
      !> The windows that the search needs are sized from the confinement
      !> window and the step: the solver finds at most one transition per
      !> step. The errors are those of [[gfposc]], without
      !> SPICE(WINDOWEXCESS) and the checks of MW and NW; a size too large to
      !> allocate signals SPICE(INSUFFICIENTMEMORY).
      module subroutine gf_position ( ctx, target, frame, abcorr, obsrvr, crdsys, coord, relate, refval, adjust, step, cnfine, result )
      use pepper_kinds, only: ip, wp
      use pepper_windows, only: cell_to_window
      use pepper_inc_gf, only: nwmax
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      character(*), intent(in) :: target  !! Name of the target body.
      character(*), intent(in) :: frame  !! Name of the reference frame for coordinate calculations.
      character(*), intent(in) :: abcorr  !! Aberration correction flag.
      character(*), intent(in) :: obsrvr  !! Name of the observing body.
      character(*), intent(in) :: crdsys  !! Name of the coordinate system containing COORD.
      character(*), intent(in) :: coord  !! Name of the coordinate of interest.
      character(*), intent(in) :: relate  !! Relational operator.
      real(wp), intent(in) :: refval  !! Reference value.
      real(wp), intent(in) :: adjust  !! Adjustment value for absolute extrema searches.
      real(wp), intent(in) :: step  !! Step size used for locating extrema and roots.
      real(wp), intent(in) :: cnfine(:,:)  !! the confinement window, shape (2, n): intervals [start, stop], sorted and disjoint
      real(wp), allocatable, intent(out) :: result(:,:)  !! the result window, shape (2, n) (n = 0 after an error)
      real(wp), allocatable :: cnf(:)
      real(wp), allocatable :: res(:)
      real(wp), allocatable :: work(:,:)
      integer(ip) :: mw
      allocate ( result(2,0) )
      if ( ctx%failed() ) return
      call gf_cells ( ctx, cnfine, step, cnf, res, mw, work )
      if ( ctx%failed() ) return
      call gfposc ( ctx, target, frame, abcorr, obsrvr, crdsys, coord, relate, refval, adjust, &
                    step, cnf, mw, nwmax, work, res )
      if ( ctx%failed() ) return
      call cell_to_window ( res, result )
      end subroutine gf_position

      !> A GF search on a coordinate of a sub-observer point (PEPPER; [[gfsubc]] with the confinement
      !> and result windows as arrays, and without workspace).
      !>
      !> The windows that the search needs are sized from the confinement
      !> window and the step: the solver finds at most one transition per
      !> step. The errors are those of [[gfsubc]], without
